local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = "ผู้พิทักษ์ คุณได้ยินหรือยัง? นิทรรศการศิลปะที่ห่างไกลในชานเมืองกำลังจะปิดตัวลงในวันเกิดของผม\nนิทรรศการนั้นเป็นสิ่งผิดปกติในวงการศิลปะ แบ่งเป็นสองส่วน หนึ่งส่วนเป็นผลิตภัณฑ์การทดลองอนาคตที่ตื้นเขิน อีกหนึ่งส่วนเป็นขยะโบราณจากสองศตวรรษที่แล้ว ในท้องที่แคบของมันเต็มไปด้วยของแปลกที่ไม่ใครกล้าแตะต้องในบ้านประมูล: ภาพบุคคลที่พูดคำหยาบน่ารังเกียจ นกกลไกที่บินไม่หยุด สลักเสลาทะเลที่ทำให้คนเห็นรู้สึกคลื่นไส้ รูปปั้นที่ทำจากน้ำตา เขียนหนังสือผีที่เขียนเองอย่างต่อเนื่อง กะโหลกร้องเพลงกล่อมเด็กเมื่อถูกจูบ...\nยากมากที่จะบรรยายว่าผมรักนิทรรศการนี้แค่ไหน! เมื่อห้าสิบปีก่อน มันเกิดขึ้นในมุมที่ไม่มีใครสนใจ วันนี้มันกำลังจะหายไปในมุมนั้น\nตั้งแต่เด็ก เริ่มมีคนบอกผมว่าวันนี้คือคำสาป เหมือนกับตัวผม ผมคิดว่าชะตากรรมอาจถูกกำหนดไว้อยู่แล้ว แต่ถ้าชะตากรรมถูกกำหนดแล้วจะทำไม! นิทรรศการนั้นสร้างโลกที่ไม่มีใครเหมือน นั่นคือความคิดสร้างสรรค์เจ้าแรกในโลกที่แปลกประหลาด ทั้งหมดนี้เกิดขึ้นในพื้นที่เล็กๆ ช่องว่างที่สวยงามนี้! ตั้งแต่วันเกิด มันก็สร้างโดยใช้ผลงานของมัน ในวันสิ้นสุดของมัน เพื่อนสนิทและมิตรเก่าของมันจะมอบการอำลาครั้งสุดท้าย\nผู้พิทักษ์ คุณเห็นโลกในตาของผมจากลิงค์ ผมคิดว่าคุณก็น่าจะตั้งตารอที่จะไปดูนิทรรศการแปลก ๆ นี้กับผมใช่ไหม?!\n\nพิคแมนนี่"
