  Mail_116602_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「รัตติกาลของกลางวันอมตะ」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「การถวายเครื่องบูชา」,     「การสารภาพพิธีบูชา」,     「ความภักดีในการถวายเครื่องบูชา」ที่เหลืออยู่ของผู้พิทักษ์ในอัตรา 40 คูปองกุหลาบทองต่อหนึ่งชิ้น โปรดจำไว้และตรวจสอบให้ดี."
