  Mail_117308_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ：\n        ขอบคุณสำหรับการสนับสนุนและการยอมรับใน「คืนแห่งการลืมเลือน」เพื่อให้ผู้พิทักษ์ที่มหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดียิ่งขึ้น เราจึงขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัลให้คุณ เมื่อกรอกแบบสอบถามเสร็จสิ้นก็สามารถรับได้ แบบสอบถามจะสิ้นสุดในวันที่ 10 พฤศจิกายน เวลา 09:00 กรุณาอย่าลืมกรอกให้ทันเวลา.\n        <SurveyLink:「คลิกที่นี่เพื่อกรอก」>\n        เราจะรับฟังข้อเสนอแนะจากผู้พิทักษ์ทุกคนอย่างจริงจัง และความคิดเห็นของคุณจะช่วยให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ！\n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
