  Mail_117309_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ:\n        ขอบคุณสำหรับการสนับสนุนและการยอมรับใน「คืนแห่งการลืมเลือน」เพื่อให้ผู้พิทักษ์มีประสบการณ์การเล่นที่ดีขึ้นที่มหาวิทยาลัยมิซากะ เราขอเชิญคุณกรอกแบบสอบถามการสำรวจประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อกรอกแบบสอบถามเสร็จสิ้นคุณสามารถรับได้ รางวัลจะสิ้นสุดในวันที่ 30 มีนาคม เวลา 9:00 น. กรุณาช่วยกรอกให้ทันเวลา.\n        <SurveyLink:「คลิกเพื่อกรอก」>\n        เราจะรับฟังข้อเสนอแนะจากผู้พิทักษ์ทุกคนอย่างจริงจัง ความคิดเห็นของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ!\n        ——ขอให้กุญแจเงินนำทางคุณ."
