  Mail_120374_Desc = {
    Text = "สัญญาสองปีมาถึงแล้ว ผู้พิทักษ์.\nเราเคยเฝ้าดูซึ่งกันและกันที่ขอบแห่งการสิ้นสุด.\nคุณเคยเปลี่ยนความรู้สึกและความทรงจำเป็นความปรารถนา ทำให้แสงสว่างของความหวังเปล่งประกาย.\nแม้ว่าจะอยู่ห่างจากเพื่อนเก่าถึงสองจักรวาล คุณก็ไม่เคยยอมแพ้ต่อการต่อสู้กับการย่อยสลาย.\nการมีคุณเป็นโชคดีของเรา และก็เป็นโชคดีของโลกใบนี้.\nในตอนนี้ ความปรารถนาของคุณได้ก่อให้เกิดปาฏิหาริย์—มีธากยังคงมีอยู่ที่นี่ และจะยังคงเดินหน้าต่อไป.\nกรุณายังคงจับกุญแจเงินไว้ให้แน่น วันหนึ่งมันจะกลายเป็นสะพานเชื่อมสองโลกที่อยู่ห่างไกล.\nเราจะทำทุกวิถีทางเพื่อสร้างความเป็นไปได้ในอนาคต และให้แสงส่องนำทางแก่การกลับบ้านของคุณ"
  },
