  Mail_121162_Desc = {
    Text = "เรียนท่านผู้พิทักษ์：\n        ในการอัปเดต V2.4.0 เราได้เพิ่มรางวัลฟรีสำหรับ「การมาถึง」,「การเดินทางสู่ต่างดาว」,「การเดินทางเพื่อฟื้นฟู」,「การเดินทางในเมืองที่สูญหาย」 สำหรับผู้พิทักษ์ที่ได้รับรางวัลฟรีก่อนการอัปเดต เราจะส่งรางวัลที่ตรงกันกลับให้ กรุณาตรวจสอบ"
