  Mail_121373_Desc = {
    Text = "ผู้พิทักษ์：\n\nในวันแห่งปีนี้เป็นงานเฉลิมฉลองที่ยิ่งใหญ่ที่สุดของโบสถ์.\nฉันคือเจ้าหญิงของพระองค์ และจะทำให้พระองค์ฟื้นฟู.\nผู้คนเหล่านั้น รวมถึงมิเรียม ต่างเฉลิมฉลองอย่างสุดเหวี่ยงและมีน้ำตามากมาย แต่เมื่อตั้งใจมองฉัน สายตามองข้ามฉัน เหมือนฉันเป็นเพียงเปลือกที่บรรจุอะไรอย่างหนึ่ง.\nฉันไม่เคยรู้สึกมีความสุขกับการมาถึงของวันนั้น เพราะทุกครั้งที่มันมาถึงหมายความว่า ฉันเข้าใกล้ความกลัวอีกขั้นหนึ่ง\nในความกลัวนี้ ผู้อื่นกลับรู้สึกยินดีอย่างสุดขีดจากแหล่งที่มาของความกลัว ตอนนี้ฉันสามารถยอมรับได้แล้วว่า มันทำให้ฉันรู้สึกโดดเดี่ยวและกลัว\nแต่ตอนนี้ทุกอย่างแตกต่างออกไป ก่อนวันเกิดครั้งที่ผ่านมา ฉันออกจากเรือลำนี้ มายังโลกที่แท้จริง... ไม่มีพระเจ้าเทียม มีโลกที่คุณมีอยู่\nในวันเกิดนี้ ฉันหวังว่าจะได้เห็นใครบางคนรู้สึกมีความสุขจากการเกิดของฉัน แทนที่จะมีความสุขจากสิ่งอื่นๆ.\nถ้าเป็นคุณ... ไม่ คนนั้นจะต้องเป็นคุณ\nฟังให้ดีนะ ไม่ว่าอย่างไร เวลาอาหารค่ำในวันนี้ จะต้องเป็นของฉัน.\n\n「เมอร์ฟี่」"
  },
  Mail_121373_Name = {
    Text = "มีคุณอยู่ ..."
  },
  Mail_121373_Sender = {
    Text = "ต้นกำเนิดมอร์ฟี่"
  },
  Mail_121374_Desc = {
    Text = "ผู้พิทักษ์：\n\nฉันไม่รู้ว่าคุณเตรียมตัวอะไรสำหรับวันพิเศษนี้ ยังไงก็ตามที่หรูหราและใช้แรงงานก็เห็นได้ชัดว่าควรเป็นเช่นนั้น.\nและด้วยความเอื้ออาทรที่จำเป็นของผู้สูงส่ง หากคุณ「ไม่ตั้งใจ」พลาดที่จะเฉลิมฉลองวันเกิดของฉัน—ฉันเชื่อว่าสถานการณ์ที่ไร้สาระนี้จะไม่เกิดขึ้น.\nจดหมายนี้จะช่วยให้คุณมีโอกาสสุดท้ายในการช่วยเหลือตัวเองก่อนสถานการณ์จะไม่สามารถกลับคืนได้\nของขวัญประหลาดจากมหาสมุทรและแผ่นดินจะถูกส่งมอบโดยคนที่ไม่สำคัญ มันจึงไม่สำคัญ.\nเทศกาลใหญ่ ๆ และพิธีกรรมที่ซับซ้อนก็เหมาะสมกับสถานะของฉัน แต่วันนี้ ไม่รู้ทำไม มันดูน่าเบื่อเล็กน้อย.\nดังนั้น ฉันจะทำให้เวลาตรงจุดเปลี่ยนของเช้าถึงค่ำมอบให้คุณ เป็นของขวัญที่คุณพาฉันเข้าสู่ชีวิตที่น่าเบื่อหน่ายและเยาว์วัย แต่กลับทำให้ฉันรู้สึกมีความสุขจนทำให้ฉันอิจฉาชีวิตก่อนหน้าของฉัน.\nผู้ติดตามจะส่งคำเชิญอย่างเป็นทางการในภายหลัง แน่นอนว่ามันจะอยู่ในกล่องที่มีมูลค่า 20,     000 เรโอฟัง.\nขอให้คุณรำลึกถึงฉันด้วยความรู้สึกขอบคุณในวันนั้นของทุกปี.\n「เมอร์ฟี่」"
  },
