  Mail_121651_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ：\nในสัปดาห์ที่แล้ว ใน「ดำน้ำภาพลวงตา」คุณได้รับตำแหน่งเป็น「{s1}」.\nในสัปดาห์ที่แล้ว ใน「โหมดเตรียมทีม」คุณได้รับตำแหน่งเป็น「{s2}」,     ชนะการต่อสู้ได้：{s3} ครั้ง.\nในสัปดาห์ที่แล้ว ใน「โหมดเลือกสรร」คุณได้รับตำแหน่งเป็น「{s4}」,     ชนะการต่อสู้ได้：{s5} ครั้ง.\nจากผลการแข่งขันทั้งหมดข้างต้น คุณจะได้รับรางวัลเพิ่มเติมต่อไปนี้,     กรุณาจดจำที่จะตรวจสอบ."
