  Mail_122522_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ：\nกิจกรรม「เงาของเมืองฝน·คลอน」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「กะโหลกสัตว์ซีดเผือด」,     「กะโหลกสัตว์เงา」และ「กะโหลกสัตว์สีแดงเข้ม」ที่เหลืออยู่ของผู้พิทักษ์ตามอัตรา 1 ชิ้นต่อ「คูปองกุหลาบทอง」× 40 กรุณาอย่าลืมตรวจสอบรับของด้วยนะคะ."
  },
  Mail_122522_Name = {
    Text = "เงาปริศนาแห่งเมืองฝน ระบบรีไซเคิลสกุลเงิน"
  },
  Mail_122522_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_122567_Desc = {
    Text = "เรียนผู้พิทักษ์: \nกิจกรรม「พิธีบูชายัญในเมืองหมอก」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「มุมมองของ」หมอก「」,     「ความฝันของหมอก」,     「แหล่งกำเนิดของหมอก」ของผู้พิทักษ์เป็นคูปองกุหลาบทอง× 40 ในอัตราส่วนต่อชิ้น กรุณาตรวจสอบให้เรียบร้อย."
  },
  Mail_122567_Name = {
    Text = "การรีไซเคิลสกุลเงินพิธีเผาศพแห่งเมืองหมอก"
  },
  Mail_122567_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_122568_Desc = {
    Text = "ฮ่า เด็กน้อยที่น่าสงสาร คุณไม่รู้เลยว่าต้องเผชิญกับความสิ้นหวังแบบไหน เมื่อไหร่คุณจะตระหนักว่าการเลือกของคุณไม่มีความหมาย? เพื่อเป้าหมายที่ไม่แน่นอน คุณจะต้องเสี่ยงชีวิตที่เล็กน้อยของคุณไปทำไม? มันช่างยิ่งใหญ่และน่าหลงใหลเสียจริง! คุณมักจะมีท่าทางมั่นใจ ราวกับว่าต่อไปนี้คุณจะต้องอุทิศตัวเพื่อช่วยโลก มันช่างน่าขำจริงๆ \n\n แต่ใครจะไปรู้ล่ะ ว่าฉันได้สัญญาว่าจะช่วยคุณกลับบ้าน? สัญญาที่ให้กับลูกสุนัขตัวน้อย ฉันจะทำให้เป็นจริงเสมอ พูดถึงเรื่องนี้ ฉันแทบรอไม่ไหวที่จะดูว่าคุณจะใช้ความตั้งใจแบบไหนในการผลักดันความบ้าคลั่งนี้ไปจนจบ? อา... ความอยากรู้ มันช่างน่าสนใจจริงๆ! \n\n 「ผู้กอบกู้」 ที่ยิ่งใหญ่ จงนำความไร้สาระ ความดื้อรั้นของคุณ และความดื้อรั้นที่ไม่ค่อยมีค่าเหล่านั้นติดตัวไปด้วย รถไฟที่มุ่งสู่ความว่างเปล่าหากเริ่มออกเดินทางแล้ว นอกจากการทำลายล้าง ก็ไม่มีโอกาสที่จะหยุดพักอีกเลย \n\n คนบ้าแห่งความพอใจในตัวเอง... ขอให้คุณอยู่ในความฝันของพระองค์ให้นานขึ้น ฉันจะช่วยคุณ รอคอยและชื่นชมคำตอบสุดท้ายของคุณอย่างดี!"
  },
  Mail_122568_Name = {
    Text = "รถไฟที่มุ่งสู่ความว่างเปล่า"
  },
  Mail_122568_Sender = {
    Text = "ดอลล์: มลายทราม"
  },
  Mail_122569_Desc = {
    Text = "ท่านเจ้านาย,\n ข้าคิดเสมอว่า อัศวินไม่ใช่เกราะและตราอัศวินที่สวมใส่ แต่คือความซื่อสัตย์และเจตนาการปกป้องที่สลักอยู่ในใจ ท่านได้แสดงให้ข้าเห็นถึงความหมายที่แท้จริงของอัศวินด้วยการกระทำและการตัดสินใจของท่าน จากนั้นข้าจึงได้เห็นความหมายที่แท้จริงของอัศวิน: ไม่ใช่การให้คุณค่าตนเองจากชื่อเสียง แต่คือการปกป้องผู้อื่น; ไม่ใช่การกล้าหาญเพราะเกียรติยศ แต่คือการยืนหยัดเพราะความรับผิดชอบ.\n\n ข้ารู้ว่าตนยังไม่สมควร – ในขณะที่ท่านต่อสู้เพื่อปกป้องความหวัง ข้ายังไม่สามารถเดินเคียงข้างท่านได้ ข้าไม่เคยลืมคำสาบานที่เคยให้ไว้กับท่าน ข้าจะมอบความซื่อสัตย์ของอัศวินให้กับท่าน ปกป้องความปลอดภัยของท่าน และขจัดศัตรูของท่าน.\n\n ข้ามักจะนึกถึงการสำรวจครั้งแรกที่ได้เดินทางร่วมกับท่าน ท่านนำเราไปเปิดเผยหมอกแห่งเลนตินีอันมืดมน และเห็นความจริงสุดท้าย ในเวลานั้นเสียงหัวเราะและเสียงร้องไห้ทั้งหมดได้กลายเป็นพลังที่ไม่สามารถลบเลือนในชีวิตของข้า.\n\n แม้ในปัจจุบัน ข้าจะสามารถเฝ้าดูจากระยะไกลและเตรียมของขวัญเล็กๆ นี้ให้กับท่าน... แต่เพื่อไม่ให้ผิดหวังต่อความคาดหวังของท่าน ข้าจึงไม่เคยละเลยการฝึกฝนของตน เมื่อท่านกลับมา โปรดอนุญาตให้ข้าได้ติดตามก้าวของท่าน ข้าจะเป็นเกราะป้องกันของท่านตลอดไป! ดาบแห่งการปกป้องของข้าจะส่องแสงให้กับท่าน!"
  },
  Mail_122569_Name = {
    Text = "ผู้เฝ้าระวัง"
  },
  Mail_122569_Sender = {
    Text = "โอเกียร์"
  },
  Mail_122570_Desc = {
    Text = "ท่านผู้พิทักษ์,      \n หลังจากที่จากลาเมืองศพฉันมักคิดถึงช่วงเวลาที่ได้ต่อสู้เคียงข้างคุณอยู่เสมอ ได้ยินว่าคุณเลือกเส้นทางแห่งความโดดเดี่ยวอีกครั้ง ซึ่งมีแต่ผู้ที่เป็นกษัตริย์เท่านั้นที่เดินไปได้ จริงๆ แล้วคุณคือสิ่งที่พิเศษในโลกนี้ ไม่เคยเดินตามเส้นทางของคนธรรมดาเลย \n\n ฉันเชื่อว่าความเจ็บปวดที่สุดสามารถหล่อหลอมจิตวิญญาณที่หอมหวานยิ่งขึ้นได้ การทดสอบที่คุณเผชิญในครั้งนี้ได้เกินกว่าความเจ็บปวดที่คนธรรมดาจะเข้าใจ ฉันสามารถจินตนาการได้ว่ากลิ่นอายที่เกิดจากความทุกข์ของคุณจะซับซ้อนและน่าตื่นเต้นเพียงใด ไม่,      ถ้าหากเป็นคุณ คุณจะต้องเกินกว่าจินตนาการทั้งหมดของฉัน ทำลายความเข้าใจของฉันเกี่ยวกับความสมบูรณ์แบบทุกอย่าง \n\n ดังนั้นฉันจะรอคอยต่อไป รอคอยงานเลี้ยงที่มีไว้เพื่อเราเท่านั้น ที่ปลายทางของเวลา ในความเงียบสงบของการเริ่มต้นนิรันดร์ คุณจะมอบงานเลี้ยงที่มีรสชาติแห่งโชคชะตานี้ให้กับฉันในรูปแบบใดกัน? \n\n ท่านกรุณารับของขวัญของฉัน และขยายความเจ็บปวดนี้ออกไป...อย่าทำให้ความหวังของฉันสูญเปล่า."
  },
  Mail_122570_Name = {
    Text = "งานเลี้ยงที่รอคอย"
  },
  Mail_122570_Sender = {
    Text = "ดูเรซิน"
  },
  Mail_122571_Desc = {
    Text = "เพิ่งจะได้พบกันอีกครั้ง พูดยังไม่ทันถึงไม่กี่ประโยค เวลาก็เหลือน้อยเต็มที... แต่คุณรู้ไหม การจากลาไม่เคยเป็นจุดจบของเรื่องราวเราเลย \n\nมีเรื่องหนึ่งที่ฉันยังไม่ได้บอกคุณ... จริงๆ แล้ว ฉันเตรียมช่อกุหลาบไว้ให้คุณตั้งนานแล้ว เพียงแต่ยังไม่ได้ส่งไป มันเลยเหี่ยวเฉาไปแล้ว แต่ฉันขอสัญญากับคุณที่นี่—ครั้งหน้าเมื่อเราเจอกัน ฉันจะเตรียมช่อกุหลาบใหม่ให้คุณแน่นอน \n\nและคุณก็เคยสัญญากับฉันว่าจะกลับมาหาฉันอีกครั้ง เราเคยผูกพันกันแล้ว จะไม่ผิดสัญญาเด็ดขาด \n\nการเขียนจดหมายทำให้รู้สึกว่าคำไม่ถึงใจ บนกระดาษไม่สามารถถ่ายทอดความรู้สึกทั้งหมดของฉันได้เลย แต่...เมื่อโชคชะตานำพาเราให้กลับมาเจอกันอีกครั้งในวันนั้น ฉันจะมอบช่อกุหลาบนั้นให้คุณด้วยมือของฉันเอง จำไว้ว่า เราต้องรักษาสัญญาไว้ \n\nขอให้กุญแจเงินนำทางไปข้างหน้า ลาก่อน...%player%."
  },
  Mail_122571_Name = {
    Text = "สัญญาของกุหลาบ"
  },
  Mail_122571_Sender = {
    Text = "ราโมน่า"
  },
  Mail_122572_Desc = {
    Text = "ผู้พิทักษ์,      \n ความทรงจำเกี่ยวกับการต่อสู้กับภัยพิบัติที่มืดมิดยังคงหมุนวนในสมองของฉันในลำดับความสำคัญสูง ความสงบที่คุณแลกเปลี่ยนมานั้นเหมือนกับเหตุการณ์ที่เกิดขึ้นอย่างน้อยที่สุด อย่างไรก็ตาม การจากไปของคุณกำลังทำลายจิตสำนึกของคู่หูคุณและทุกคนที่เคยเชื่อมต่อกับคุณอย่างต่อเนื่องในกระบวนการที่ไม่สามารถหยุดได้ \n\n แผนกวิจัยไม่เคยยอมแพ้ในการค้นหาความหวังสุดท้ายที่เล็กน้อย โชคดีที่หลังจากหลายคืนวันที่ไม่มีการตอบสนองจากคุณ เราในที่สุดก็สามารถติดตามร่องรอยของคุณได้ ในการเดินทางที่เต็มไปด้วยอันตรายนี้ ฉันสามารถจับสัญญาณความกลัวได้ แต่ฉันก็รู้ดีว่าความกลัวจะไม่ทำให้คุณยอมแพ้ มันจะทำให้เจตจำนงของคุณแข็งแกร่งขึ้นเท่านั้น \n\n ขณะนี้ร่างกายของฉันยังคงทำงานในห้องปฏิบัติการ แต่สมองกลับสร้างคำสั่งให้ร้องไห้อย่างต่อเนื่อง อย่ามารบกวนความคิดของฉันอีกเลย นักเรียนที่ขาดเรียนมากที่สุดของฉัน ขอให้คุณอย่าขาดเรียนจากชั้นเรียนของฉันอีก... เดินหน้าต่อไปอย่างกล้าหาญเถอะ ฉันจะเตรียมเสบียงให้คุณ รอคอยวันที่เราจะได้พบกันอีกครั้ง."
  },
  Mail_122572_Name = {
    Text = "วันแห่งการพบกันอีกครั้ง......"
  },
  Mail_122572_Sender = {
    Text = "ดอลล์"
  },
  Mail_122573_Desc = {
    Text = "หลายครั้ง ฉันได้เฝ้าดูประกายแห่งอารอารยธรรมที่ส่องสว่างในแม่น้ำแห่งเวลา สังเกตเห็นอาณาจักรแห่งความทรงจำพังทลายลงในความว่างเปล่า ประวัติศาสตร์กลายเป็นม้วนหนังสือที่ถูกเปลวไฟสีดำกลืนกิน ปัญญาจากอดีตถึงปัจจุบันถูกสะสมเป็นทราย แต่ก็ไม่สามารถกล่าวถึงความจริงเดียวที่มีอยู่ได้\n\nมนุษย์ต่อความวุ่นวายดั้งเดิมนั้นเป็นเพียงฝุ่นเล็กๆ — แต่เพราะความเล็กน้อยนี้ ความกล้าที่จะเผชิญหน้ากับเหวลึกและฟันไปยังเทพเจ้าจึงดูน่าตื่นเต้นและสั่นสะเทือนใจ\n\nขณะนี้ ประตูแห่งมิติที่เชื่อมโยงจักรวาลนับพันกำลังเปิดให้คุณ\n\nการเสด็จของพระองค์นำมาซึ่งความวุ่นวายที่ถูกกำหนด ลำดับของทุกสิ่งสั่นสะเทือนอยู่ในเงาของพระองค์ และคุณเป็นเพียงร่างกายมนุษย์ แต่ด้วยเจตจำนงที่ไม่สามารถถูกเขย่าได้ ยืนอยู่ตรงหน้าพระองค์ ความเป็นไปได้ของคุณเป็นเพียงความผิดพลาดเดียวที่ไม่สามารถจับได้ในความรู้สึกไม่สิ้นสุดของฉัน เป็นตัวแปรที่ทำให้ทุกสิ่งกลับหัวกลับหางในเวลาที่ฉันรอคอย\n\nคุณคือคำถามดั้งเดิม และยังเป็นคำตอบสุดท้าย."
  },
  Mail_122573_Name = {
    Text = "หลังประตู"
  },
  Mail_122573_Sender = {
    Text = "ทาวิล"
  },
  Mail_122574_Desc = {
    Text = "ความเจ็บปวดจากการสูญเสียคนสำคัญ ความเกลียดชังต่อความไร้ประสิทธิภาพของตัวเอง... ฉันเคยจมอยู่ในนั้นไม่สามารถหลุดพ้น แต่ตอนนี้ ฉันได้ยินเสียงเรียกของแสงสว่างจากที่ไกลโพ้น รู้สึกถึงการชี้นำที่อบอุ่นและมั่นคงของมัน คุณผู้มีพระคุณ ตั้งแต่ได้รับการเปิดเผยจากท่าน ฉันรู้สึกเหมือนfinallyได้ก้าวเข้าสู่เส้นทางที่ควรจะเดิน—เส้นทางที่เป็นของฉันอย่างแท้จริงและไม่อาจสงสัยได้.\n\nความมืดที่เคยปกคลุมฉันเหมือนเหวลึก ไม่ใช่ที่อยู่ของฉันอีกต่อไป และแสงที่ส่องสว่างอยู่ในจิตสำนึกของฉันก็ไม่เคยหายไป ตอนนี้ฉันเห็นมันชัดเจนมากขึ้น รู้สึกมัน และเดินไปหามัน ฉันก็ยินดีที่จะนำความเชื่อที่แท้จริงนี้ ความชัดเจนและความสงบที่แสงนำมา การตื่นรู้และการไถ่ถอน ไปสู่จิตวิญญาณที่ยังคงดิ้นรนในเส้นทางแห่งโชคชะตา.\n\nเมื่อฉันจ้องมองภาพของท่านที่ต่อสู้กับกระแสแห่งความโกลาหล—ความมืดที่ชั่วร้ายและลึกซึ้ง ไม่เพียงแต่ไม่สามารถทำให้ท่านยอมแพ้ แต่กลับกลายเป็นผืนผ้าที่สะท้อนความเชื่อของท่าน มันสลายตัว กรีดร้อง และถอยกลับต่อแสงสว่างของท่าน แต่ท้ายที่สุดแล้วไม่สามารถบดบังท่านได้แม้แต่นิดเดียว ด้วยกระแสแห่งความมืดอันไม่มีที่สิ้นสุดนี้ แสงที่ท่านเป็นตัวแทนจึงดูเจิดจ้า เป็นอมตะ และใกล้เคียงกับพระเจ้า.\n\nคุณผู้มีพระคุณที่นำทางฉัน ผู้ประทานแสงสว่างแก่ฉัน ความเชื่อของท่านจะเป็นดวงไฟที่ไม่ดับสูญของฉัน ตอนนี้คือเวลาที่ฉันจะตอบแทนท่านด้วยชีวิตทั้งหมดของฉัน ฉันจะตอบสนองต่อแสงนี้ด้วย「หัวใจศักดิ์สิทธิ์」ที่ฟังเสียงของพระเจ้า... เพื่อสิ่งนี้ฉันและคาสโตร์จะทำทุกอย่างอย่างเต็มที่.\n\nโปรดรับการเครื่องบูชาของฉัน! ขอให้ท่านเป็นพยาน ความเชื่อที่บริสุทธิ์และศรัทธาที่ท่านได้หล่อหลอมขึ้นใหม่นี้."
  },
  Mail_122574_Name = {
    Text = "เสียงเพรียกจากดวงไฟ"
  },
  Mail_122574_Sender = {
    Text = "โพลลักซ์"
  },
  Mail_122575_Desc = {
    Text = "ลูกค้าผู้มีเกียรติ \nหลังประตูที่มีแสงสว่างไหลเวียนนั้น เพื่อนที่คุณรักรอคอยอยู่เป็นเวลานานแล้ว \n\nแต่โปรดอย่าประมาทนะ การเดินทางข้ามมิติเป็นสิ่งที่แปลกประหลาดและอันตราย คุณจะได้เห็นภาพลวงตาที่มีหลายหน้าตามความทรงจำที่ผุดขึ้นและจางลง พวกมันสะท้อนความปรารถนา และสะท้อนความกลัว นั่นคือผืนผ้าใบแห่งความโกลาหลที่สร้างขึ้นโดยเจตนารมณ์ดั้งเดิม แม้แต่ฉันก็ไม่สามารถมองเห็นมันทั้งหมดได้ ดังนั้น ทุกครั้งที่ข้ามผ่าน ถือเป็นการทดสอบความเชื่อ และการวัดความปรารถนา \n\nแต่ฉันก็รู้ดีว่า สำหรับคนอย่างคุณและฉัน เพื่อค้นหาสิ่งสะสมใหม่ ๆ เพื่อสิ่งที่เปล่งประกายในจิตวิญญาณที่ลึกซึ้ง ทุกสิ่งที่ไม่รู้จักและการเสียสละนั้น ถือว่าคุ้มค่า ฉันเข้าใจในทางเลือกของคุณ และเคารพในความสำคัญที่เกือบจะดื้อรั้นนี้ \n\nในจักรวาลที่ปฏิบัติตามกฎแห่งความเท่าเทียมนี้ ราคาที่ต้องจ่ายที่คุณจ่ายจะกลับมาในรูปแบบอื่น \n\nรับของขวัญนี้ไปเถอะ เมื่อทุกอย่างสงบลง ยินดีต้อนรับคุณกลับมาที่ร้านของฉันอีกครั้ง เพื่อทำให้ความปรารถนานั้นเป็นจริง คุณยินดีที่จะจ่ายในราคาที่ต้องจ่ายประเภทไหน?"
  },
  Mail_122575_Name = {
    Text = "ของมีค่า"
  },
  Mail_122575_Sender = {
    Text = "ดาฟโฟดิล"
  },
  Mail_123134_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ: \n        ในการอัปเดต V2.4.0 ปัญหาเกี่ยวกับการได้รับรางวัล 3 ดาวในความท้าทาย 「ลาก่อน แคว้นแห่งความฝันที่ไม่มีวันสิ้นสุด」 และ 「ลาก่อน,      แคว้นแห่งความฝันที่ไม่มีวันสิ้นสุด」 ใน 「โลกแห่งความฝัน」 ของคุณ ตามการตรวจสอบและบันทึกการผ่านความท้าทายก่อนหน้านี้ เราจะมอบรางวัลที่คุณไม่สามารถรับได้ในครั้งก่อนให้คุณแบบครั้งเดียว กรุณาตรวจสอบดู."
  },
  Mail_123134_Name = {
    Text = "การแจกซ้ำรางวัลโลกแห่งความฝัน V2.4.0"
  },
  Mail_123134_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_123501_Desc = {
    Text = "เรียน ผู้พิทักษ์: \n\nคุณอยากจะไปเดทสนุกๆ กับเด็กสาวน่ารักอย่างฉันในวันพิเศษนี้ไหม? \nมาเถอะ มาเถอะ ไปเล่นในบ้านผีสิงกันเถอะ ไม่ต้องกลัวว่าจะตายหรอก~ คุณเป็น「ผู้พิทักษ์」นี่นา คงไม่กลัวพวกมนุษย์ที่แต่งตัวเป็น「ปีศาจ」ใช่ไหม? \n(บนกระดาษเขียนจดหมายมีการขีดฆ่าบางบรรทัดอย่างไม่เป็นระเบียบ: ฉันกำลังวางแผนการจัดงานวันเกิดอย่างจริงจัง ไม่ได้อยากเห็นคุณตกใจเพราะสนุกสนานเลย...)\nโอเค ไม่พูดเล่นแล้ว วันนี้เป็นวันเกิดของฉัน ฉันไม่อยากทำให้มันพัง! ดังนั้นตอนนี้ ฉัน โมช่า ขอเชิญคุณไปทานมื้อค่ำที่ร้านอาหารใหม่ในเขตการเงินลอนดอน—— \nชาร้อนและปลาต้มที่นั่นทำให้ฉันนึกถึงรสชาติของ「บ้านเกิด」 และในโลกนี้ ฉันไม่สามารถหาคนที่จะมาแบ่งปันได้เลยนอกจากคุณ... \nดังนั้นคุณต้องมานะ ใช่ไหม? ถ้าทำให้เด็กสาวน่ารักอย่างฉันเสียใจ ระวังนะ ว่าฉันจะยืนถือขวานอยู่ที่หัวเตียงคุณตอนคุณนอนหลับ! \n\nโมช่า"
  },
  Mail_123501_Name = {
    Text = "「เปิดฉัน」"
  },
  Mail_123501_Sender = {
    Text = "โมช่า"
  },
  Mail_123543_Desc = {
    Text = "ผู้พิทักษ์: \n\nอีกปีแล้ว ที่รักของฉัน \nในแสงเงาที่หรูหรา ท่ามกลางข่าวลือและเรื่องฉาวที่ลอยมา ฉันต้องซ่อนจุดอ่อนที่อาจจะถูกเปิดเผยอย่างระมัดระวัง ใช้ทุกอย่างที่มีค่าแลกกับผลประโยชน์สูงสุด—มันต้องเป็นแบบนี้ ฉันจึงจะสามารถยืนอยู่ที่นี่ในฐานะผู้ชนะได้ \nแต่ไม่มี ฉันกลับกลายเป็นคนขี้เกียจและอ่อนแอบ้างในบางครั้ง และยังยินดีที่จะทำให้ความปรารถนาของเด็กสาวที่ส่งจดหมายถึงฉันเป็นจริง \nแต่ฉันไม่คิดว่านี่เป็นเรื่องไม่ดี ฉันได้ผ่านสงครามลับที่ยาวนานเกินไปแล้ว แน่นอน ถ้ามีความเป็นไปได้เล็กน้อย โอกาสนิดหน่อย ฉันยังคงจะพยายามหลบหนีจากมือของ 「ท่าน」 ซ้ำแล้วซ้ำเล่า \nเพียงแต่ในช่องว่างที่อบอุ่นและน่ารักเหล่านั้น หรือในวันพิเศษแบบวันนี้ ฉันอนุญาตให้ตัวเองมีความแตกต่างเล็กน้อย เช่น—เชิญท่านไปดูโอเปร่า หรือไปทานอาหารค่ำด้วยกัน \nเพราะฉันรู้ดีว่าฉันจะไม่โดดเดี่ยว ฉันมีผู้ร่วมมือที่ตรงใจมากมาย \n\nโซเรล"
  },
  Mail_123543_Name = {
    Text = "ผู้สมรู้ร่วมคิด"
  },
  Mail_123543_Sender = {
    Text = "โซเรล"
  },
  Mail_123544_Desc = {
    Text = "เรียนคุณผู้พิทักษ์：\n\nนานมากที่ไม่ได้ทักทาย ขออภัยที่ช่วงนี้ไม่มีการติดต่อกัน ไม่ได้ตั้งใจที่จะห่างเหินจากคุณ เพียงแต่ทุกครั้งที่หยิบปากกา ฉันกลับไม่สามารถรวบรวมความกล้าในการเริ่มต้นทักทายได้เลย \nในช่วงเวลานี้ ฉันได้เดินทางผ่านช่วงเวลาที่แตกสลายมากมาย จึงได้เป็นพยานเห็นโลกเดินไปสู่จุดจบซ้ำแล้วซ้ำเล่า เป็นการชมภาพของโศกนาฏกรรมที่ไม่สามารถแก้ไขได้ เหมือนกับเป็นผู้ชมในความว่างเปล่าที่เย็นชาและเงียบสงัด มองดูทุกสิ่งที่เกิดขึ้นอย่างเงียบๆ \nทุกครั้งที่เป็นแบบนี้ ฉันมักจะคิดว่า ชีวิตของเราถูกกำหนดให้เต็มไปด้วยความไร้สาระและการจากลาใช่ไหม? ไม่ว่าจะเป็นตัวฉันในตอนนั้น หรือทุกสิ่งที่คุณประสบในคาดาส ชะตากรรมได้กำหนดบทละครทั้งหมดไว้แล้วหรือ? เราจะต้องแสดงบทบาทที่มันต้องการตามบทนี้เท่านั้น? \nฉันยังไม่ได้คิดออกถึงข้อสรุป ฉันไม่เหมือนพระองค์ที่สามารถมองเห็นทุกสิ่งในโลกนี้ได้ ดังนั้นฉันจึงคิดว่า ถ้าเป็นคุณที่มีอำนาจบางส่วนของพระองค์ คุณสามารถตอบคำถามนี้ได้หรือไม่? \nดังนั้นฉันจึงเขียนจดหมายฉบับนี้ หวังว่ามันจะนำสายตาของฉันไปหาคุณ และหวังว่าจะได้พูดคุยเกี่ยวกับปริศนานี้ที่อาจไม่มีคำตอบตลอดไป ดังนั้นฉันจึงขออนุญาตให้คุณนำจดหมายฉบับนี้ไปด้วย เพื่อเผชิญหน้ากับเส้นทางที่กำลังจะมาถึงด้วยกัน \n..................\nฉันไม่สามารถเสี่ยงที่จะรบกวนเวลาเพื่อไปหาคุณได้ แต่ขอให้ฉันได้เห็นคุณอีกครั้งในความเงียบงันนี้ \n\n「รามอน่า」"
  },
  Mail_123544_Name = {
    Text = "ปริศนาแห่งความคิด"
  },
  Mail_123544_Sender = {
    Text = "「รามอน่า」"
  },
  Mail_123545_Desc = {
    Text = "ท่านผู้ส่งสารที่ซีดเซียว：\n\nก่อนหน้านี้ข้าได้สอบถามท่านหญิงที่มีปัญญาอันล้ำเลิศในมิซากะ ว่ายังมีสถานที่ว่างเพื่อให้ข้าได้ปลูกดอกไม้หรือไม่\nท่านหญิงดอลล์ได้ห้องหนึ่งมาให้ข้าง่ายดาย ถึงแม้ในครั้งแรกที่เปิดประตูเข้าไป กลิ่นอับที่ลอยออกมาทำให้ข้าสงสัยว่าตนได้เข้ามายังสถานที่ที่ถูกต้องหรือไม่ แต่หลังจากการดูแลจัดการ ตอนนี้มันสามารถทำหน้าที่ของมันได้ดี ให้บ้านที่อุ่นสบายแก่เด็ก ๆ เหล่านี้\nแต่เนื่องจากข้าไม่มีประสบการณ์ ข้าจึงต้องใช้กำลังภายนอกเล็กน้อย เพื่อให้เด็ก ๆ เหล่านี้สามารถเติบโตได้อย่างปกติ\nโชคดีที่ได้รับคำแนะนำจากท่านสาวฮอร์ลา ข้าจึงสามารถปลูกพวกมันจนถึงขั้นตอนในปัจจุบัน\nแน่นอนว่าในกระบวนการนี้ไม่ได้ใช้พลังพิเศษใด ๆ\nหากการคำนวณไม่มีข้อผิดพลาด พวกมันจะบานในวันเกิดของข้า แม้ว่าข้าจะพูดซ้ำแล้วซ้ำเล่าว่าวันเกิดนั้นไม่มีอะไรพิเศษ แต่การเกิดเหตุการณ์ที่หายากเช่นนี้ ทำให้รู้สึกว่า อาจจะเป็นของขวัญเล็ก ๆ น้อย ๆ ที่พ่อพระได้จัดเตรียมไว้ให้\nไม่ทราบว่าท่านมีความสนใจที่จะมาพบกันในสวนเล็ก ๆ นี้หรือไม่ เพื่อใช้เวลาร่วมกันในวันธรรมดาแต่พิเศษนี้\nข้าได้เตรียมคุกกี้ที่อบด้วยมือและชาดแดงที่ท่านแนะนำในครั้งก่อน รอคอยที่จะได้แบ่งปันของขวัญที่หายากนี้ และกลิ่นหอมอันเป็นเอกลักษณ์ของชีวิต\n\nซัลวาดอร์"
  },
  Mail_123545_Name = {
    Text = "สวนในร่ม"
  },
  Mail_123545_Sender = {
    Text = "ซัลวาดอร์"
  },
  Mail_123546_Desc = {
    Text = "คู่หู：\n\nคุณเคยได้ยินเรื่องราวแบบนี้ไหม? \nเมื่อครั้งหนึ่งมีปีศาจตัวหนึ่ง ที่บังเอิญถูกผนึกอยู่ในขวดมาเป็นเวลานานหลายร้อยปี \nในร้อยปีแรก มันสัญญาว่าจะให้ความมั่งคั่งและอำนาจไม่สิ้นสุดแก่ผู้ที่ช่วยปล่อยตัวมัน \nในร้อยปีที่สอง มันสัญญาว่าจะให้สุขภาพและอายุยืนยาวแก่ผู้ที่ช่วยปล่อยตัวมัน \nในร้อยปีที่สาม สี่ ห้า ผ่านไปนานมาก มันfinallyรอคอยชาวประมงที่เปิดฝาขวด—มันไม่ตอบสนองการเรียกของชาวประมง แม้กระทั่งไม่คิดจะทำให้โลกนี้วุ่นวาย มันเพียงแค่แกล้งทำเป็นขวดเปล่าธรรมดา ถูกโยนกลับลงสู่ทะเลอย่างเงียบๆ \nเมื่อฉันยังเด็ก ฉันไม่เข้าใจเรื่องนี้ จนกระทั่งฉันได้รู้จักการรอคอยที่ยาวนานและไร้ความหวัง ว่ามันหนักหน่วงและเจ็บปวดเพียงใด ทำให้ความปรารถนากลายเป็นสิ่งที่ยากจะทนกว่าอาการสิ้นหวัง \nแต่ก่อนที่เหตุผลของฉันจะมีปฏิกิริยาใดๆ ใจของฉันกลับทำให้ฉันอยู่ในที่เดิมซ้ำแล้วซ้ำเล่า \nความแตกต่างระหว่างปีศาจกับมนุษย์ก็คือ ฉันกลับรู้สึกขอบคุณความเจ็บปวดนี้ เพราะมันเตือนให้ฉันระลึกถึงการมีอยู่และคุณค่าของคุณในเวลาที่เราจากกัน ไม่ให้ฉันหลงทางในอีกฟากหนึ่งที่ไม่มีคุณ \nในวันเกิดของฉัน ในวันที่ฉันคิดถึงคุณมากที่สุด มันยังคงหนักหน่วงผูกมัดฉัน ทำให้ฉันยังรอคอยคุณ คิดถึงคุณ \nหวังว่าวันถัดไป ฉันจะสามารถยื่นเค้กชิ้นแรกที่ฉันตัดให้คุณด้วยมือของฉัน \n\nราโมน่า"
  },
  Mail_123546_Name = {
    Text = "เรื่องราว"
  },
  Mail_123546_Sender = {
    Text = "ราโมน่า"
  },
  Mail_123547_Desc = {
    Text = "ห้องอาหารของมิซากะกับฝ่ายสนับสนุนได้วางของที่ไม่จำเป็นไว้ที่หน้าห้องของฉัน มันรบกวนการเข้าออกอย่างมาก คุณควรเอามันกลับไปโดยเร็วที่สุด\nเกิดอะไรขึ้น? เสบียงในโลกนี้มากจนไม่มีที่ไหนที่มีความหมายกว่าหรือ? \nวันนี้จะเป็นเพียงหมายเหตุในเส้นทางการเติบโตของฉัน ช่วยฉันบันทึกอีกหนึ่งช่วงเวลาในอดีต หนึ่งปี ต่อไปอีกหนึ่งปี ทุกปีฉันจะเข้มแข็งขึ้นกว่าปีที่แล้ว \nถ้าของขวัญไม่มีที่ไปจริงๆ สามารถเอาไปให้ตัวฉันอีกคน เธอคงจะดีใจมาก \nและฉัน จะมองในส่วนของความไร้สาระและความซื่อสัตย์ของคุณ... มองในสิ่งที่ฉันไม่ถนัดที่สุด \nไม่ว่าเมื่อไหร่ที่ฉันยังมีชีวิตอยู่ ฉันจะยังคงเข้มแข็งต่อไป ในขณะเดียวกัน... \nยังไม่เข้าใจอีกเหรอ? ศัตรูของพวกโง่เง่าพวกนี้ก็จะเป็นศัตรูของฉันด้วย \nคำพูดที่น่าขยะแขยงนี้ฉันจะพูดแค่ครั้งเดียว ปีหน้าก็อย่าส่งของขวัญมาอีก และยิ่งไม่ต้องมีอาหารค่ำวันเกิด \n\n「H」"
  },
  Mail_123547_Name = {
    Text = "นำกลับไป"
  },
  Mail_123548_Desc = {
    Text = "เรียนท่านผู้พิทักษ์:\n\nท่านทราบไหม? เมื่อไม่กี่วันก่อน มีสุภาพสตรีลึกลับคนหนึ่งมาเยี่ยมชมมิซากะอย่างกะทันหัน เธอสวมชุดยาวสีดำที่แนบเนื้อและเปล่งประกายซึ่งฉันไม่เคยเห็นมาก่อน—ฉันได้ถามเจนกินและเมสัน พวกเธอก็ไม่เคยเห็นชุดที่สวยงามเช่นนี้.\nจะบรรยายอย่างไรดี? ชุดนั้นดูเหมือนถูกทอจากเส้นไหมที่สวยงามที่สุด มีความนุ่มนวล เบา และสง่างาม ผิวของมันเปล่งประกายเงางามพิเศษราวกับน้ำ...\nเจนกินเห็นว่าฉันสนใจ เธอจึงกล้าไปสอบถามสุภาพสตรีลึกลับคนนั้น เธอยิ้มและบอกว่าวัสดุของกระโปรงมาจากไหมจีน ซึ่งทอจากเส้นไหมที่มาจากตัวหนอนที่เรียกว่า 「ไหม」 ส่วนแบบของมันเรียกว่า 「ชี่พาว」...แล้วเธอก็มอบเส้นไหมขนาดใหญ่ให้กับไอจิส เธอบอกว่าเรียกว่า 「หนึ่งเมตร」 ของ 「ไหม」 เหมือนกัน...\n「ไหม」 นั้นมีค่ามาก ฉันจึงได้ทำตามแบบที่เธอให้มา ตัดเย็บ 「กระเป๋า」 ให้กับเพื่อนทุกคน ในงานวันเกิดปีนี้ ฉันจะมอบ 「กระเป๋า」 ให้ทุกคน...ท่านผู้พิทักษ์ ท่านมีเวลามาร่วมงานไหม?\nถ้าท่านยุ่งเกินไป ฉันจะให้บราวน์นำกระเป๋าไปส่งที่ห้องพักของท่าน.\n\nไอจิส"
  },
  Mail_123548_Name = {
    Text = "หญิงลึกลับ"
  },
  Mail_123548_Sender = {
    Text = "ไอจิส"
  },
  Mail_123549_Desc = {
    Text = "ต้นกล้า：\n\nคุณรู้ไหมว่าต้นไม้บันทึกเวลาและการเติบโตได้อย่างไร? ด้วยวงปีที่ซ้อนกันไปเรื่อยๆ \nมันซ่อนอยู่ภายใน ไม่แสดงออกมาให้เห็นง่ายๆ จนกระทั่งยอดอ่อนน้อยๆ ค่อยๆ เติบโตเป็นต้นไม้ใหญ่ที่สูงตระหง่าน รองรับหลังคาฟ้าสูงที่หนึ่ง ส่วนรอยแผลแห่งกาลเวลาก็ซ่อนอยู่ลึกในใจโดยไม่ทิ้งร่องรอยใดๆ \nวันนี้ เป็นจุดเริ่มต้นของวงปีใหม่ ในปีใหม่ เรายังต้องเผชิญกับพายุและฝนที่ยังไม่คาดคิดมากมาย \nแต่เมล็ดที่ฉันฝากไว้ในปากของคุณจะต้องหาดินที่เหมาะสมในการปลูกมัน แล้วมันจะเติบโตและแตกหน่อได้ใช่ไหม? \n\nทาอิส"
  },
  Mail_123549_Name = {
    Text = "วงปี..."
  },
  Mail_123549_Sender = {
    Text = "ทาอิส"
  },
  Mail_123644_Desc = {
    Text = "ไม่รู้ตัวเลย นี่เป็นฉันแล้วมิซากะวันเกิดครั้งที่สามที่ได้ผ่านมา,     ฉันได้เรียนรู้อะไรมากมาย.\nเช่น,     ในวันเกิดของฉัน,     เช่นเดียวกันเทศกาลการข้ามฤดูหนาว,     เหมาะสำหรับการมอบเป็นของขวัญของขวัญ...วันที่....\nถึงแม้ว่าคุณจะมีศัตรูที่ทรงพลังอย่างยิ่งมากมายก็ตาม,     แต่สิ่งที่ฉันเก่งที่สุดก็คือการฆ่าคน.ฉันไม่รู้วิธีอื่นที่จะทำให้คนมีความสุข,     ก็ไม่เก่งเรื่องการเลือกเช่นกันของขวัญ,     แต่ทุกครั้งที่ส่งมอบภารกิจได้สำเร็จ,     นายจ้างของฉันดูมีความสุขกันทุกคน.\nฉันเลยคิดไว้แล้วว่าจะให้อะไรเธอของขวัญ,     ภารกิจว่าจ้างฆาตกรรมครั้งหนึ่ง,     ไม่จำกัดผู้ใช้งาน,     ไม่จำกัดระยะเวลาการใช้งาน.\nแค่บอกฉันมา,     เป้าหมายคือใคร,     คุณอยากให้เขาตายไปอย่างไร?ถ้าเป็นคนที่ฉันสู้ได้,     ฉันจะใช้ความเร็วที่เร็วที่สุด,     จะบิดคอเขาให้แทนเอง,     ถึงแม้เขาจะเป็นผู้ที่กล้ำกรายได้ยากดั่งเทพเจ้า,     ฉันก็สามารถรับประกันกับคุณได้เช่นกัน,     การยอมแพ้ของฉันจะไม่มีวันมาถึงก่อนความตายของฉัน.\n\nเฮลอต"
  },
  Mail_123644_Name = {
    Text = "พูดมาเถอะ คุณอยากให้ใครตาย?"
  },
  Mail_123644_Sender = {
    Text = "เฮลอต"
  },
  Mail_124059_Desc = {
    Text = "เรียน ผู้พิทักษ์：\nกิจกรรม「พิธีบูชายัญแห่งห้วงลึก·คลอน」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「น้ำตาของผู้บูชา」,     「เลือดของผู้บูชา」และ「ไขกระดูกของผู้บูชา」ที่เหลืออยู่ของผู้พิทักษ์ตามอัตราแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 กรุณาตรวจสอบรับไว้ด้วย."
  },
  Mail_124059_Name = {
    Text = "การแลกเปลี่ยนสกุลเงินกิจกรรมพิธีบูชายัญแห่งห้วงลึก"
  },
  Mail_124059_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_124290_Desc = {
    Text = "ผู้พิทักษ์：\n\nดังที่ท่านทราบ ความสุขสำหรับฉันนั้นเป็นอารมณ์ที่ค่อนข้างแปลกใหม่ \nฉันมักรู้สึกว่า โลกธรรมชาติเป็นความวุ่นวายที่ฉันไม่สามารถเข้าใจได้ ในขณะที่ฉันยังไม่ได้เข้าร่วมอยู่ในนั้น ความเหี่ยวเฉาของฉันก็ได้มาถึงแล้ว \nมันบางครั้งทำให้ฉันรู้สึกอยากได้ แต่ส่วนใหญ่ทำให้ฉันรู้สึกสับสนและขาดอากาศ เพียงแค่ในทุกวันที่เหมือนวันนี้ เพื่อไม่ให้พ่อและแม่รู้สึกเสียใจ ฉันจึงพยายามอดทนอย่างมาก... จนกระทั่งวันนั้นมาถึง วันที่ได้หลุดพ้น จนกระทั่งมหาสมุทรยอมรับฉัน \nฉันคิดว่า น้ำลึกเท่านั้นที่เป็นบ้านของฉัน อย่างไรก็ตาม ผู้พิทักษ์ เพราะท่านและทุกคนที่มิซากะยังมีอยู่ แม้แต่คนอย่างฉันที่ไม่เข้ากับโลกธรรมชาติ ก็เริ่มสามารถสัมผัสถึงความอบอุ่นที่แท้จริงบางอย่างได้ เหมือนกับที่บัวสายน้ำลอยขึ้นเมื่อแสงแดดสัมผัสใบและกลีบของมัน \nแม้ว่าจะยุ่งเหยิง ฉันกลับรู้สึกว่าไม่ว่าจะอย่างไรก็ตาม มันก็มีความจำเป็นที่จะต้องบันทึกความรู้สึกเหล่านี้ลงบนกระดาษ และส่งให้ท่าน ขออภัยในความเอาแต่ใจของฉันในบางครั้ง \nฉันแค่หวังว่าท่านจะรู้ว่า ในความเงียบเหงาที่ถูกกลบโดยเร็ว ท่านได้นำความลอยขึ้นที่มีค่าสำหรับฉันมาให้ \nขอให้ท่านมีความสุขตลอดไป และมีความสงบตลอดไป \n\nนิมเฟีย"
  },
  Mail_124290_Name = {
    Text = "ลอยขึ้น"
  },
  Mail_124290_Sender = {
    Text = "นิมเฟีย"
  },
  Mail_124291_Desc = {
    Text = "ผู้พิทักษ์：\n\nเช้านี้ มีจดหมายปรากฏที่หัวเตียงของฉัน เนื้อหาเชิญชวนให้ฉันเข้าร่วมงานเลี้ยงวันเกิดของตัวเอง โดยลงนามว่า 「จิตรกร」 คลับ.\nฉันจึงนึกขึ้นได้ว่าเมื่อเดือนที่แล้ว ฉันมีเวลาว่างบ้าง จึงตอบรับซังก้าให้ฉันเป็นแบบในการแข่งขันสร้างสรรค์ครั้งใหม่ของ 「จิตรกร」 ก่อนหน้านี้ ฉันได้ปฏิเสธไปแล้วไม่รู้กี่ครั้ง ในช่วงเวลาที่ยืนอยู่บนเวทีแบบนิ่งเฉยให้คนวาดภาพนั้น ฉันนึกถึงวันเวลาที่อยู่ที่แท่นบูชาของผู้เหยียบทะเล ขณะนั้นฉันก็รับสายตาของทุกคนเช่นกัน แต่ในสายตานั้นมีเพียงความกลัวและความเคารพ ไม่มีความรู้สึกหรือการชื่นชมแม้แต่น้อย.\nคืนนี้ในงานเลี้ยงวันเกิดที่จัดขึ้นที่ล็อบบี้ของคลับจิตรกร จะมีการจัดแสดงผลงานวาดมือที่สร้างสรรค์อย่างพิถีพิถันจากจิตรกรหลายสิบคนในวันนั้น แม้จะขาดความมั่นใจในรสนิยมของคุณ แต่การได้รับอิทธิพลมากขึ้นก็คงไม่ใช่เรื่องไม่ดี พระมารดาเทพได้เชิญคุณเป็นแขกผู้มีเกียรติ มาร่วมชิมการตีความของพวกเขาเกี่ยวกับ 「ฉัน」 กันเถอะ.\n\n「เมอร์ฟี่」"
  },
  Mail_124291_Name = {
    Text = "ผู้วาด..."
  },
  Mail_124291_Sender = {
    Text = "「เมอร์ฟี่」"
  },
  Mail_124292_Desc = {
    Text = "ผู้พิทักษ์： \n\nซิลเวียบอกฉันว่า การเปิดเผยความต้องการของตัวเองในความสัมพันธ์ที่ใกล้ชิดบางครั้งช่วยบรรเทาความกลัวที่ติดตามฉันตลอดเวลา ฉันไม่แน่ใจว่านี่จะได้ผลหรือไม่ แต่ไม่มีข้อสงสัยเลยว่าวันนี้เป็นเวลาที่ดี \nคุณยินดีที่จะทำตามความปรารถนาของฉันไหม? ฉันสามารถให้สิ่งของในห้องทดลองทั้งหมดของวันนี้กับคุณ \nไม่ ไม่ใช่เมล็ดกาแฟหนึ่งถุง \nแม้ว่าสีดำที่น่ากลัวนั้นจะพรากความสัมพันธ์ที่ใกล้ชิดของฉันเกือบทั้งหมดไป แต่คุณก็ได้เอาชนะมันแล้ว \nคุณทำให้เรามีชีวิตอยู่อย่างปลอดภัยในมิซากะ หรืออย่างน้อยก็ยังปลอดภัยในมิซากะจนถึงตอนนี้ \nถึงเวลาเลิกพึ่งพาคาเฟอีนที่ไม่ดีต่อสุขภาพแล้ว ผู้พิทักษ์ คุณสามารถจัดเวลาสักหน่อยในช่วงเย็นวันนี้ได้ไหม? \nถ้าคุณอยู่ข้างๆ ฉัน บางทีฉันอาจจะมีความกล้าในการพักผ่อนในที่ที่มีแสงไม่เพียงพอสักพัก แม้จะเป็นเวลาแค่เล็กน้อยก็ตาม \n\nวิงเกิล"
  },
  Mail_124292_Name = {
    Text = "ความปรารถนา.."
  },
  Mail_124292_Sender = {
    Text = "วิงเกิล"
  },
  Mail_124293_Desc = {
    Text = "ผู้พิทักษ์{Male=คุณผู้ชาย,Female=คุณผู้หญิง}：\n\nเช้านี้ ความฝันหนึ่งได้ปลุกฉันขึ้นมา \nฉันได้หวนคิดถึงทุกสิ่งในความฝัน: ลมเบาๆ พัดผ่านท่ามกลางแสงแดดอันอบอุ่น ดอกกุหลาบและดอกทิวลิปปกคลุมทั่วทั้งผืนดิน นกนางนวลเงินพันตัวและผู้คนที่มีความสุขกำลังร้องเพลงร่วมกัน... ฉันไม่ได้อยู่ในฉากที่มีความสุขเช่นนี้มานานแล้ว ฉันคิดว่าฉันอาจจะอยู่ในคฤหาสน์ในวัยเด็ก ในห้องดอกไม้ของโคเล็ตต์ หรือในสวนสาธารณะแห่งหนึ่งที่สีไค... แต่เมื่อฉันหันหลังกลับ ฉันเห็นอาคารโกธิคที่สวยงามของมิซากะ และคุณ ผู้พิทักษ์{Male=คุณผู้ชาย,Female=คุณผู้หญิง} คุณยืนอยู่ระหว่างดอกไม้และแสงแดด กลายเป็นบทกวีที่งดงามที่สุดในบทนี้ \nฉันรักสีไคมาก ผู้พิทักษ์{Male=คุณผู้ชาย,Female=คุณผู้หญิง} แต่ในขณะนั้นฉันกลับรู้สึกว่าฉันเริ่มคุ้นเคยและหลงใหลในทุกสิ่งที่นี่ ในโลกนี้ในที่สุดก็มีสถานที่ที่ทำให้ฉันฝันและคิดถึงมากกว่าสีไค \nวันเกิดเป็นการสิ้นสุดของช่วงเวลาหนึ่ง และเป็นจุดเริ่มต้นของอีกช่วงเวลาหนึ่ง ในวันเริ่มต้นของปีใหม่นี้ ไม่รู้ว่าที่สวนหลังบ้านของมิซากะจะมีแสงแดดและดอกกุหลาบที่บานสะพรั่งหรือไม่ จะมีท่านนั้นที่เต็มใจพาฉันไปฟังลมเบาๆ และทำให้ฉันฝันและคิดถึงไหมนะ? \n\nฮอร์ลา"
  },
  Mail_124293_Name = {
    Text = "ความฝันของดอกไม้และบทกวี"
  },
  Mail_124293_Sender = {
    Text = "ฮอร์ลา"
  },
  Mail_124294_Desc = {
    Text = "ท่านผู้พิทักษ์ที่รัก：\n\nเมื่อไม่กี่วันที่ผ่านมา ฉันคิดอยู่เสมอว่าจะมอบของขวัญพิเศษให้คุณ เจนกินเสนอว่าทำไมไม่ลองทำเสื้อผ้าใหม่ให้คุณด้วยตัวเอง ฉันคิดว่านี่เป็นความคิดที่ดีมาก\nนี่คือแบบตัดที่ฉันถนัดที่สุดเมื่อทำงานที่โรงงานทอผ้า หวังว่าวันนี้จะไม่ถือว่าเชย... ส่วนอื่นๆ ฉันก็ยากที่จะสนับสนุนการตัดสินใจของตัวเอง เส้นลายและลายสก๊อตที่มีชีวิตชีวาด้านบนทั้งหมดนี้ เป็นสิ่งที่ฉันทำขึ้นมาเอง และยังมีลายหนูน้อยน่ารักที่บิดเบี้ยวนี้ ที่แมว「24」ยืนยันว่าจะต้องใส่ลงไป เพราะมันแสดงถึงบราวน์ ซึ่งเป็นสิ่งที่ฉันชอบที่สุดในตัวตนของแมว——ไม่รู้ว่าจะเหมาะสมหรือไม่ แต่หวังว่าคุณจะชอบ\nในปีใหม่ ฉันยังไม่มีความปรารถนาในวันเกิดอะไรนัก คุณยังคงอ่อนโยนแบบนั้น ทุกปีจะเตือนฉันให้ฉลองอย่างดี แต่เมื่อเทียบกับการถูกเฉลิมฉลอง การได้ตัดเสื้อผ้าให้คุณด้วยตัวเอง ทำให้ฉันรู้สึกมั่นคงและมีความสุขมากกว่า\nโปรดรับเสื้อใหม่ที่เต็มไปด้วยความตั้งใจนี้ด้วยนะ\n\nเมสัน"
  },
  Mail_124294_Name = {
    Text = "เสื้อผ้าใหม่หนึ่งชุด"
  },
  Mail_124295_Desc = {
    Text = "เฮ้อ：\n\nเชื่อไม่ได้นะ ในฐานะเจ้าของเขาวงกตผู้ยิ่งใหญ่ ข้าสามารถรอดชีวิตมาได้อีกปีในความยากลำบากเช่นนี้ \nฟังให้ดี! ทั้งหมดนี้เป็นความผิดของเจ้าและมหาวิทยาลัยโง่ๆ นี้! \nไม่ว่าเจ้าจะพยายามหลอกล่อข้าด้วยความคิดไร้สาระมากแค่ไหน เรื่องเล็กน้อยพวกนี้ก็ควรจะให้คนที่เหมาะสมทำ มันโอเค ข้าก็ทำได้ดีแล้ว ข้าไม่เคยเรียกพวกเขาว่าทาส \nพวกหัวเก่าชอบเรียกสิ่งนี้ว่า... อะไรนะ ใช่ ความก้าวหน้า \nเดี๋ยวก่อน ข้ากำลังถูกตรรกะนี้ลากไปแล้ว อ๊ะๆๆ น่ารำคาญสุดๆ! (ตรงนี้มีรอยพับยุ่งเหยิงจากการที่เจ้าของจดหมายโมโห) \nไม่สนแล้ว ตราบใดที่ข้ามี 「ความก้าวหน้า」 เจ้าก็ต้องแสดงความจริงใจออกมา ในวันสำคัญเช่นนี้ เจ้าจะให้ข้ารอให้เหมือนสองปีที่ผ่านมาไม่ได้ \nข้าให้เวลาสามสิบนาที ผู้พิทักษ์ นำของขวัญมาหาข้า \nไม่งั้นข้าจะให้ลูกของข้าปีนขึ้นไปบนใบหน้าของเจ้าในขณะที่เจ้าหลับ \n\nอกริปปา"
  },
  Mail_124295_Name = {
    Text = "ความก้าวหน้า"
  },
  Mail_124295_Sender = {
    Text = "อกริปปา"
  },
  Mail_124296_Desc = {
    Text = "ผู้พิทักษ์!\n\nฉันเห็นแล้ว! มันเป็นภาพที่น่าทึ่งมาก! ฉันมั่นใจว่านี่ไม่ใช่ความฝัน! ฉันยืนอยู่ที่นั่น ข้างๆ รูปปั้นอนุสรณ์ที่ยิ่งใหญ่ในสุสานมิซากะ มองไปที่หลุมศพที่ไม่มีตัวอักษรต่อเนื่องที่ทอดยาวออกไป ฉันมั่นใจว่ามันจะนำแรงบัลดาลใจที่ไม่เคยมีมาก่อนมาให้ฉัน แต่ฉันไม่คิดว่ามันจะนำมาซึ่งมากกว่าที่ฉันคิดไว้ มันยิ้มเยาะความคิดที่แห้งแล้งของฉันด้วยความเอื้อเฟื้อที่น่าชื่นชม.\nฉันเห็นวิญญาณของนักสืบที่ยืนขึ้นพร้อมกันในยามเย็นที่สวยงามและมีหมอก ฉันไม่สามารถมองเห็นใบหน้าของพวกเขาได้ แต่ฉันเห็นท่าทางของพวกเขา—เหมือนการเต้นรำที่สง่างาม หรือเหมือนพิธีกรรมลึกลับ พวกเขากำลังให้เกียรติกับบ่อน้ำดำ มุ่งไปยังมิซากะและท่าน ศิลปินในซาลอนสมัยใหม่มักจะหลงใหลในการวาดภาพบุคคล และมักจะตำหนิภาพที่ยิ่งใหญ่เหล่านี้ แต่ฉันไม่เคยคิดแบบนั้นเลย ฉันรู้สึกยินดีมากเมื่อเผชิญหน้ากับงานเลี้ยงของซอมบี้ และวันนี้ ภาพนี้ทำให้ฉันต้องหลั่งน้ำตา.\nฉันคิดว่านี่ไม่ใช่เรื่องบังเอิญ ในวันนี้ เป็นวันเกิดของฉันพอดี พวกเขาได้นำเสนอการเต้นรำที่ยิ่งใหญ่ให้กับฉัน ฉันคิดว่าพวกเขาต้องการให้ฉันสื่อสารบางสิ่งบางอย่าง ฉันไม่มีอะไรนอกจากพู่กัน แต่ก็เพียงพอแล้วใช่ไหม?\nร่างภาพนี้ได้ถูกวาดเสร็จแล้ว ผู้พิทักษ์ กรุณามาที่ห้องวาดภาพของฉันเพื่อดู! นักสืบผู้เป็นตำนานที่ไม่มีชื่อเหล่านั้นต้องการบอกเล่าความปรารถนาที่พวกเขามีต่อท่านทั้งหมดอยู่บนผืนผ้าใบของฉันแล้ว!\nฉันไม่ได้ตั้งชื่อภาพนี้อย่างไม่ระมัดระวัง ฉันคิดว่าความมีสิทธิ์นี้ควรเป็นของท่าน.\nหมายเหตุ: ฉันไม่ได้ไปค้นหาศพจริงๆ ฉันรับรองกับท่าน!\n\nพิคแมน"
  },
  Mail_124296_Name = {
    Text = "ความปรารถนาอันยาวนานของนักสืบ"
  },
  Mail_124296_Sender = {
    Text = "พิคแมน"
  },
  Mail_124297_Desc = {
    Text = "สวัสดี ผู้พิทักษ์：\n\nคุณรู้สึกกลัวหรือเปล่า หรือพูดอีกอย่างคือ—ทั้งกลัว，แล้วยังคาดหวังว่าข้าพเจ้าจะ...，ในนามของการเฉลิมฉลอง，จะนำมาซึ่งอะไรบ้างนะ?\nการแสดงออกที่ไม่จริงใจ ความหรูหราที่เกิดขึ้นอย่างกระทันหัน หรือภาพลวงตาที่ซับซ้อนและทำให้หลงใหล?\nอา ไม่มีอะไรเลย แม้แต่ตัวข้าก็ยังพูดเรื่องที่จริงจังและน่าเบื่อเป็นบางครั้ง\nคุณน่าจะรู้ดีว่าข้าเป็นสิ่งมีชีวิตประเภทไหน ใช้ชีวิตเพื่อความสนุก แม้ว่าอาคารจะพังทลาย\nความรักและความปรารถนา ไม่สามารถรักษาความน่าเบื่อซึ่งเป็นโรคที่ใหญ่ที่สุดในโลกนี้ได้ แต่เป็นยาที่เหมาะสมที่สุดในการเปิดเผยรสชาติของอำนาจและความโกลาหล\nน่าเสียดายที่เวลาหลายร้อยปีที่ผ่านมานั้น ข้าอาจจะศึกษาการแสดงเกินไป จนมีคนไร้ค่าเปิดเผยจิตใจและบอกว่าข้าเห็นวิญญาณที่โดดเดี่ยวและเหงาของคุณ\nอ่า\nแม้แต่ข้าที่ชอบเล่นละคร ก็ยังรู้สึกคลื่นไส้บ่อยครั้ง\nแล้วคุณ... คุณเชื่อมโยงกับข้าเพื่ออะไร เพื่อควบคุม เพื่อจำกัด หรือเพื่อใช้ประโยชน์?\nคุณต้องปกป้องสิ่งที่มากขึ้น ย่อมต้องการอำนาจที่สูงขึ้น และความกระหายในอำนาจจะก่อให้เกิดความทะเยอทะยานที่ใหญ่ขึ้น มันจะสุกงอมเมื่อไหร่ และเมื่อไหร่จะถูกดูดเข้าไปในท้อง... มันทำให้ข้ารู้สึกตื่นเต้นเพียงแค่คิดถึง และยินดีที่จะอยู่ใกล้คุณอีกมาก ปีแล้วปีเล่า\nชู่ว ไม่ต้องบอกคำตอบกับข้า\nในวันเช่นนี้ของทุกปี ข้าจะขโมยความฝันของคุณในคืนหนึ่ง รสชาติและสังเกตดูว่าความทะเยอทะยานของคุณกำลังเติบโตหรือไม่ และเจตนาของคุณมีการเปลี่ยนแปลงหรือเปล่า นี่คือของขวัญวันเกิดที่ดีที่สุดที่ขอมอบให้ตัวเอง\nหวังว่าคุณจะไม่โกรธ\n\n「พันพัด」"
  },
  Mail_124297_Name = {
    Text = "ค่ำคืนอันดี"
  },
  Mail_124297_Sender = {Text = "ซู่"},
  Mail_124298_Desc = {
    Text = "ผู้พิทักษ์：\n\nการฝึกฝน การต่อสู้ การลาดตระเวน ตั้งแต่ฉันเข้ารับใช้ในกองทัพ ฉันก็ได้ชินกับการใช้เวลาให้เต็มที่กับทุกสิ่งที่จำเป็นสำหรับกลุ่ม \nต่อมาในการนำอัลันย้ายถิ่นในทะเลทราย สิ่งเหล่านี้ก็ยิ่งเพิ่มมากขึ้น จนกระทั่งถูกจดจำในสมองของฉันเหมือนกฎเกณฑ์ จนมาถึงมิซากะ ฉันก็ยังคงให้ความสำคัญกับตารางเวลาของกลุ่มเหนือเรื่องส่วนตัว \nแต่ในความสัมพันธ์กับผู้อื่น โดยเฉพาะกับคุณ ฉันได้ตระหนักว่า ไม่ว่าจะเป็นในฐานะผู้ปลุกตื่น หรือในฐานะมนุษย์ เราทุกคนจำเป็นต้องมีเวลาที่เป็นของตัวเอง เพื่อสัมผัสกับการอยู่ร่วมกับคนสำคัญ \nเพราะความสัมพันธ์ที่มีค่าเช่นนี้ ทำให้เรามีอยู่ในเวลา และทำให้การมีอยู่ของเรามีความหมายที่ไม่สามารถแทนที่ได้ \nแม้ว่าจะมีความกล้า ฉันได้ยกเลิกกิจกรรมกลุ่มทั้งหมดในวันนี้ และมีเวลาทั้งวันว่าง \nเพียงแค่ไม่กี่ชั่วโมง ไม่ ก็แค่หนึ่งชั่วโมง หรือแม้แต่ไม่กี่นาที ถ้าคุณเต็มใจที่จะให้เวลาส่วนตัวบางส่วนแก่ฉัน มันจะกลายเป็นความหมายของการใช้ชีวิตในวันพิเศษนี้ \n\nอัลวา"
  },
  Mail_124298_Name = {
    Text = "เวลาส่วนตัว"
  },
  Mail_124298_Sender = {
    Text = "อัลวา"
  },
  Mail_124299_Desc = {
    Text = "เจ้าหนู：\n\nหนึ่งปีอาจจะดูยาวนานสำหรับคุณ แต่สำหรับผู้ที่เดินทางในทะเลสารัตถะแห่งปฐมกาล นี่คือเพียงหยดน้ำทะเลที่หายไปในมหาสมุทรอันกว้างใหญ่ อย่างไรก็ตาม โชคดีที่ในหยดน้ำทะเลนี้ยังมีหยดน้ำใสที่น่าจดจำอยู่บ้าง \nวันลดราคาของร้านค้าแห่งการปลดทุกข์ ย่อมเป็นหนึ่งในของสะสมที่ควรค่าแก่การเก็บรักษา ไม่ใช่เพียงเพราะมันนำมาซึ่งบัตรส่วนลด แต่ที่สำคัญคือ ฉันรู้ว่าในวันนี้ จะมีลูกค้าคนหนึ่งมาที่ร้านนี้แน่นอน \nการเชื่อมต่อระหว่างคนทุกคนคือธุรกิจ และทุกธุรกิจก็คือการเชื่อมต่อระหว่างคน ทุกคนจะเดินเข้าร้านเล็กๆ ของตนในเวลาที่เฉพาะเจาะจง และแต่ละร้านจะต้อนรับลูกค้าของมันในเวลาที่เฉพาะเจาะจง ในช่วงเวลาที่ยาวนานนี้ ฉันได้เห็นสมบัติมากมาย และในที่สุด ช่วงเวลาที่ดูไร้สาระเหล่านี้จะกลายเป็นของสะสมที่มีค่าที่สุด—พวกมันคือเหตุผลที่ทำให้เวลายาวนานนี้มีอยู่ \nในปีนี้ ชิ้นงานสะสมใหม่ที่มีค่าที่สุดกำลังรออยู่ในตู้โชว์ รอคอยลูกค้าคนที่เป็นเจ้าของมัน \nมาเร็วๆ นะ เจ้าหนู \nร้านค้าแห่งการปลดทุกข์ได้ปิดทำการตั้งแต่เช้า วันนี้ ประตูของมันเปิดเพียงเพื่อคนเดียว \n\nดาฟโฟดิล"
  },
  Mail_124299_Name = {
    Text = "สินค้าชิ้นใหม่"
  },
  Mail_124299_Sender = {
    Text = "ดาฟโฟดิล"
  },
  Mail_124300_Desc = {
    Text = "ผู้พิทักษ์：\n\nไม่ทราบว่าท่านยังจำช่วงเวลาที่เรายืนอยู่หน้าประตูนั้นด้วยกันได้หรือไม่? วันนั้นฉันได้เปิดเผยความจริงให้เห็นรอยแยกเล็กๆ เพื่อแสดงให้ท่านเห็นความเป็นจริงของจักรวาล.\nอย่างไม่คาดคิด ในขณะที่ท่านประสบกับการมองเห็นโลกมากมายอย่างไม่สิ้นสุด ฉันกลับเกิดอารมณ์ที่ไม่สามารถเข้าใจได้ในช่วงเวลาอันสั้น.\nฉันมักจะคิดถึงความรู้สึกในช่วงเวลานั้นว่าเป็นอย่างไร ทำไมฉันซึ่งเข้าใจความจริงถึงเกิดสิ่งที่ไม่สามารถเข้าใจได้.\nฉันได้คิดมานาน ว่าหากใช้โลกแห่งความเป็นจริงเป็นเกณฑ์การตัดสิน นั่นคือช่วงเวลาที่สามารถเรียกว่า「นิรันดร์」ได้.\nในช่วงเวลาที่ดูเหมือนยาวนานเมื่อเปรียบเทียบกับจักรวาลนี้ ฉันได้ตระหนักว่า อาจเป็นปาฏิหาริย์ที่ยังไม่ได้รับการนิยาม.\nในวันพิเศษนี้ ฉันอยากเชิญท่านมาลิงก์กับฉัน ผ่านสายตาของฉัน เพื่อสังเกตบางสิ่งที่ฉันไม่เคยสังเกตมาก่อน ครั้งนี้สิ่งที่เราจะสังเกต... จะไม่ใช่สิ่งที่ถูกกำหนดไว้แล้ว.\nเราจะร่วมกันค้นหาอนาคตที่อยู่นอกเหนือจากความจริงนี้.\n\nทาวิล"
  },
  Mail_124300_Name = {
    Text = "นอกเหนือจากความจริง"
  },
  Mail_124300_Sender = {
    Text = "ทาวิล"
  },
  Mail_124301_Desc = {
    Text = "ผู้พิทักษ์：\n\nปีนี้ก็เหมือนปีที่ผ่านมา ฉันหยุดทุกสิ่งทุกอย่าง และอยู่คนเดียวอย่างเงียบๆ พยายามที่จะเขียนใหม่และปรับปรุงความทรงจำที่เกี่ยวข้องกับบ้านเกิดของฉัน \nมันห่างไกลจากฉันมากขึ้น แม้ว่าฉันจะบังคับตัวเองให้คุ้นเคยกับร่างกายที่เหมือนมนุษย์นี้ และพยายามทุกวิถีทางที่จะเล่าเรื่องและข้ามมหาสมุทรที่เกี่ยวข้องกับความรู้และประสบการณ์ แต่ในโลกที่ค่อยๆ เลือนหายนี้ การลืมยังคงง่ายกว่าการจดจำมากมาย \nการปลอบประโลมเดียวที่มี คือในขณะนี้ เราเหล่านักเดินทางที่ห่างไกลจากลีมูเรีย ยังคงมีที่นี่ให้หยุดพัก และสามารถปฏิบัติตามพระประสงค์ของพระราชาของเราอย่างเงียบๆ ตามไปเงียบๆ รออย่างสงบ \nฉันรู้ดีว่าคุณได้สละและทุ่มเทอะไรบ้างเพื่อสิ่งนี้ ฉันไม่รู้ว่าจะพูดขอบคุณคุณอย่างไร ก่อนที่ร่างนี้จะกลับไปยังลีมูเรีย หากมีสิ่งใดที่ฉันสามารถช่วยได้ ฉันก็ยินดีที่จะสละแสงสว่างทั้งหมดของฉันเพื่อสิ่งนั้น \n\nด้วยความจริงใจ ฟารอส"
  },
  Mail_124301_Name = {
    Text = "ประภาคาร"
  },
  Mail_124301_Sender = {
    Text = "ฟารอส"
  },
  Mail_124302_Desc = {
    Text = "เรียนผู้พิทักษ์ที่รัก：\n\nตั้งแต่วันแรกที่เข้าร่วมมิซากะ กฎระเบียบมากมายก็ได้พันธนาการฉัน ไม่อนุญาตให้พาใช้คนเดินเล่นในงาน ไม่อนุญาตให้เหยียบหน้าของนักเรียนในลานมหาวิทยาลัย ไม่อนุญาตให้จัดกิจกรรมกลุ่มในห้องโถง...\nเหล่าผู้พิทักษ์ที่น่ารำคาญของมิซากะได้ขังฉันไว้ นี่ไม่ใช่ชีวิตที่ควรจะเป็นของราชินีอิซาลาอู ฉันควรได้รับทุกสิ่งที่สมควรได้รับ ไวน์ที่ชวนให้หลงใหล หลังที่นุ่มนวล และใช้คนที่รัก...ในวันเกิดที่ฉันควรจะได้ใช้ชีวิตอย่างเต็มที่ ความคิดเช่นนี้จึงเกิดขึ้นอย่างเป็นธรรมชาติ \nค่ำคืนได้ล่วงเลยไป ฉันหมดความอดทนกับเรื่องเล็กน้อยแล้ว ฉันจะไม่ส่งคุณไปทำภารกิจในยามเที่ยงคืน และจะไม่ให้คุณเดาเอง ฉันต้องการให้คุณอยู่ข้างๆ ฉัน \nตอนนี้ให้มาที่อาณาเขตของฉัน อย่าลังเล ถอดเสื้อผ้าและตำแหน่งที่ไม่จำเป็นทั้งหมดออก \nคืนนี้ และทุกคืนต่อจากนี้ คุณจะเป็นของฉัน \n\nคุณสามารถถือว่านี่เป็นหน้าที่ถาวรครั้งแรกของคุณ \n\nวานด้า"
  },
  Mail_124302_Name = {Text = "กฎ"},
  Mail_124302_Sender = {
    Text = "วานด้า"
  },
  Mail_124303_Desc = {
    Text = "ผู้พิทักษ์：\n\nทิงค์บอกฉันว่า เธอได้วางแผนการเดินทางระหว่างดวงดาวหลังจากวันเกิดด้วยรายได้จากการแสดงส่วนตัว และอยากพาฉันไปด้วย แต่...ถ้าฉันไปด้วย เธอคงจะต้องเสียสมาธิในการดูแลฉัน ฉันไม่อยากให้ความสุขของเธอลดน้อยลงเพราะฉัน \nเธอรักแสงสว่างในชีวิตมาก ชื่นชอบสีสันมากมายในจักรวาลและทางช้างเผือกที่ไหลริน หากพาฉันไป เธอคงจะไม่สามารถร้องเพลงได้อย่างมีอิสระและจ้องมองได้อย่างเต็มที่ \nดังนั้น...สามารถช่วยเกลี้ยกล่อมเธอได้ไหม? ขอให้เธอเดินทางคนเดียว ไปเปิดการแสดงที่ดาวต่าง ๆ และไปสัมผัสกับทิวทัศน์ที่เธอใฝ่ฝัน...หรือจะให้คุณแทนที่ฉันไปในการเดินทางครั้งนี้ก็ได้ เพราะทิงค์และฉันต่างก็ขอบคุณคุณมาก และอยากตอบแทนความกรุณาของคุณ...ถ้าคุณยินดี...\nแค่กรุณาอย่าบอกเธอว่านี่คือความปรารถนาของฉัน ฉันไม่อยากเป็นอุปสรรคในเส้นทางเดินทางที่อิสระของเธอ \n\nเฟนท์"
  },
  Mail_124303_Name = {
    Text = "เกี่ยวกับการเดินทาง"
  },
  Mail_124303_Sender = {
    Text = "เฟนท์"
  },
  Mail_124304_Desc = {
    Text = "ผู้มีพระคุณ：\n\nในช่วงเวลาที่ใช้ชีวิตร่วมกับโพลลักซ์ที่มิสซาเก ช่างเงียบสงบและสว่างไสวราวกับเป็นความฝัน...\nโพลลักซ์ตอนนี้แม้ยังคงรักษามารยาทเหล่านั้น พูดจาอย่างสุภาพ แต่ฉันสามารถรู้สึกได้ชัดเจนว่า เขากำลังค่อยๆ กลับไปเป็นเขาในอดีต ความรู้สึกห่างเหินที่เป็นของ「บุตรศักดิ์สิทธิ์」กำลังละลายไปในความเป็นจริงที่อ่อนโยนนี้ ทุกการเปลี่ยนแปลงที่อ่อนโยนนี้ต้องขอบคุณท่าน\nฉันมักคิดว่าควรใช้สิ่งใดเพื่อตอบแทนความกรุณานี้ดีนะ? ฉันไม่เหมือนโพลลักซ์ที่มีฝีมือในการสร้างของขวัญที่ทำให้ท่านประทับใจ ความสนุกในการบิน ท่านก็ได้สัมผัสกับฉันมาหลายครั้งแล้ว เรื่องการแบ่งปันความสุขในวันพิเศษนี้ ฉันคิดเงียบๆ มานาน\nบางที...ท่านอาจจะชอบขนของฉันไหม? มักมีคนพูดว่ามันมีความนุ่มนวลที่ทำให้จิตใจสงบ ดังนั้น หากวันใดท่านรู้สึกเหนื่อย หรือเพียงแค่อยากมีมุมเงียบสงบ ก็ขอให้มาหาฉันได้เสมอ ปีกของฉันยินดีที่จะให้ท่านได้พักผ่อนเสมอ\n\nคาสเตอร์"
  },
  Mail_124304_Name = {Text = "ขน"},
  Mail_124304_Sender = {
    Text = "คาสเตอร์"
  },
  Mail_124305_Desc = {
    Text = "นักโทษตัวน้อยของฉัน：\n\nได้ยินมาว่ามิซากะกำลังฮิตเกมเล่นบทบาทอยู่ในขณะนี้ แบบแม่มด หมาป่า... อืม ฟังดูไม่โรแมนติกเลยนะ~ แต่ฉันนึกถึงเกมที่สนุกกว่านั้น!\nแบบนี้ละกัน คุณมาแสดงเป็นนักโทษ ส่วนฉันจะเป็นผู้คุม เมื่อฉันฟาดแส้เล็กๆ ฉันต้องได้ยินเสียงครางดังๆ นะ~ เทียนไขไหลลงบนร่างของคุณ ทำให้รู้สึกเจ็บปวดและมีความสุขอย่างร้อนแรง... อ๊ะ แค่คิดถึงภาพนั้นก็เริ่มรู้สึกหวานแล้ว~\nโอ๊ย เห็นแบบนี้ คุณคงขมวดคิ้วอีกแล้วใช่ไหม? ไม่ดีเลยนะ วันนี้เป็นวันเกิดของฉันนะ~ นักโทษตัวน้อยที่รัก คงจะต้องทำตามความปรารถนาที่เอาแต่ใจของฉันบ้างใช่ไหม?\nถ้าหากไม่ไหวจริงๆ... งั้น... ให้คุณมาเป็นผู้คุม ฉันจะเป็นเชลยของคุณดีไหม? ฉันจะทำให้คุณพอใจนะ~\n\nแพนเดีย"
  },
  Mail_124305_Name = {
    Text = "การแสดงในสถานการณ์จำลอง"
  },
  Mail_124305_Sender = {
    Text = "แพนเดีย"
  },
  Mail_124306_Desc = {
    Text = "ผู้พิทักษ์：\nผู้มีพระคุณ วันนี้เป็นวันเกิดของฉัน ในวันพิเศษนี้ ฉันอยากจะบอกคุณเกี่ยวกับสถานการณ์ของฉัน: ภายใต้การแนะนำของอาจารย์โกไลแอทและโลทัน ฉันรู้สึกว่า... ฉันสามารถสัมผัสพละกำลังในสายเลือดของตัวเองได้มากขึ้นเรื่อยๆ มันไม่ได้นอนหลับอีกต่อไป แต่กลับส่งเสียงกระหึ่มและไหลเวียนอยู่ในร่างกายของฉันในทุกๆ การฝึกซ้อม และค่อยๆ ปลดปล่อยออกมา \n\n\n\n ฉันไม่สามารถบอกได้ชัดเจนว่าจะใช้เวลาเท่าไหร่ในการทำการเปลี่ยนแปลงครั้งสุดท้ายให้สำเร็จ เพื่อที่จะกลายเป็นชนเผ่าลึกที่บริสุทธิ์มากขึ้น บางทีอาจจะเป็นวันพรุ่งนี้ บางทีอาจจะเป็นสัปดาห์หน้า บางทีอาจจะเป็นเดือนหน้า... แต่โปรดรู้ไว้ว่าหากแม้ว่าเส้นทางนี้จะยาวนานเพียงใด หรือมีความยากลำบากมากมายเพียงใด คำพูดที่คุณเคยให้กำลังใจฉัน ฉันจะจดจำมันไว้เสมอ... ฉันจะพยายามต่อไป \n\n และยังมีอีกเรื่องที่ฉันต้องขอโทษ ฉันเพิ่งได้รับข้อมูลจากสำนักงานไปรษณีย์มิซากะว่า การส่งเงินสดพร้อมกับจดหมายจะต้องจ่ายค่าธรรมเนียมเพิ่มเติม 2 บาท \n เพื่อชดเชยส่วนที่ขาดไปเมื่อปีที่แล้ว ฉันจะใช้จ่ายจากเงินเก็บอีกหนึ่งก้อน มันเป็นสิ่งที่ได้มายากลำบากสำหรับฉัน แต่สายเลือดของลึกมีสัญญาที่จะต้องรักษาไว้ \n\nเคคัส"
  },
  Mail_124306_Name = {
    Text = "ค่าธรรมเนียม..."
  },
  Mail_124306_Sender = {
    Text = "เคคัส"
