  Mail_124307_Desc = {
    Text = "ผู้พิทักษ์：\n\nฟังให้ดี คืนนี้ไม่ว่าอย่างไรก็ต้องไปที่「ร้านนั้น」กับฉัน\nเสื้อผ้าที่ใช้ในการปลอมตัวได้ส่งไปให้คุณแล้ว ต้องระวังให้ดี ห้ามให้คนอื่นรู้ว่าเราอยู่ที่ไหน!\nขนมหวานจำนวนจำกัดจาก「ร้านนั้น」เริ่มขายแล้ว คนที่ไม่รู้มาจากไหนนั่นต้องได้ซื้อลูกค้ามาเยอะ ต้องไม่ให้พวกเขารู้ว่าข้าน้อยอยู่ที่ไหน\nถึงแม้คนนั้นจะจองขนมเค้กจำนวนจำกัดจากทุกที่ในลอนดีเนี่ยนเพื่อไม่ให้ฉันได้ซื้อ แต่... เฮอะ\nข้าน้อยได้ซื้อใจเชฟของ「ร้านนั้น」ล่วงหน้าให้เขาเอาขนมที่อร่อยที่สุดออกจากเมนู\nเฮอะ ข้าน้อยจะให้คนนั้นรู้ว่า บางอย่างไม่ได้ขึ้นอยู่กับเงินอย่างเดียว\nตอนนั้นเราจะค่อยๆ แอบเข้าไปทางประตูหลัง เปิดกล่องเหล็กที่มีการเข้ารหัสสามชั้น แล้วจะได้ของที่เป็นรุ่นลิมิเต็ดในรุ่นลิมิเต็ด\nเป็นรางวัล ฉันจะให้เค้กชิ้นหนึ่ง (ขีดฆ่า) ครึ่งหนึ่งให้คุณ\nคืนนี้สิบเอ็ดโมง ฉันจะรอคุณอยู่ในห้อง คุณต้องมาให้ได้! เข้าใจไหม!\nต้องเก็บเป็นความลับ ไม่อย่างนั้นถ้าข่าวหลุดไปให้คนนั้นรู้ว่าพวกเราที่ไหน ทุกอย่างก็จะจบลง!\n\nเมอร์ฟี่"
  },
  Mail_124307_Name = {
    Text = "การแย่งเค้กครั้งใหญ่"
  },
  Mail_124307_Sender = {
    Text = "เมอร์ฟี่"
  },
  Mail_124308_Desc = {
    Text = "ผู้พิทักษ์：\n\nรู้สึกเสียใจที่ต้องแจ้งให้คุณทราบว่า โรงละครลอนดีเนี่ยนได้ยกเลิกการแสดงมายากลของปรมาจารย์คาเซียห์โดยสิ้นเชิง เหตุผลมีดังนี้: ราคาตั๋วสูงเกินไป, ทุกคนเห็นเหตุการณ์แปลกๆ มากเกินไปทำให้ขาดความสนใจในมายากล, มีผู้ชมหายไปติดต่อกันหลายการแสดงจนถึงปัจจุบันยังไม่กลับมา, ตำรวจมักจะมาหาเจ้าของโรงละครเพื่อขอให้ปรมาจารย์คาเซียห์หยุดการแสดงเพื่อไปให้ความร่วมมือในการสอบสวน เป็นต้น \nล่าสุดได้รับผลกระทบจากการเคลื่อนไหวที่แบล็คพูล การแสดงของฉันมีข้อผิดพลาดเล็กน้อยในบางครั้ง ซึ่งเป็นเรื่องเล็กน้อย แต่ข้อที่สองเป็นสิ่งที่ปรมาจารย์คาเซียห์ไม่สามารถทนได้! \nฉันได้คิดอย่างหนักในเรื่องนี้ จนในที่สุดก็คิดได้การแสดงใหม่ที่สมบูรณ์แบบ! การควบคุมศพ, การฟื้นคืนชีพของผู้ตาย, การข้ามมิติ, การติดเชื้อทางอารมณ์, หนวดขนาดใหญ่...ทั้งหมดนี้ไม่ใช่เรื่องใหญ่! ก่อนหน้านี้ได้รับผลกระทบจากสุนัขล่าอาณาเขตที่น่ารังเกียจ การควบคุมเวลาเป็นสิ่งต้องห้ามในวงการนี้ แต่หลังจากที่สุนัขตัวนั้นถูกผนึกแล้ว ธุรกิจมายากลของปรมาจารย์คาเซียห์จะขึ้นสู่ระดับใหม่! \nเวลาการแสดงกำหนดไว้ในคืนนี้ ฟรีอย่างสมบูรณ์ ที่นั่งแถวแรกกลางได้ถูกจองไว้สำหรับผู้พิทักษ์แล้ว ยังมีช่วงเวลาที่น่าประหลาดใจรอคุณอยู่! เพลิดเพลินกับเกียรติยศในการเป็นผู้ชมที่มีส่วนร่วมคนแรกในการแสดงมายากลที่ยิ่งใหญ่ที่สุดในยุคใหม่! \nเพื่อฟื้นฟูเกียรติยศของปรมาจารย์คาเซียห์! \n\nคาเซียห์"
  },
  Mail_124308_Name = {
    Text = "คาเซีย，ทำให้เวทมนตร์ยิ่งใหญ่อีกครั้ง!"
  },
  Mail_124308_Sender = {
    Text = "คาเซียห์"
  },
  Mail_124309_Desc = {
    Text = "เจ้านาย：\n\nซิลเวียพี่สาวเพิ่งมาบอกฉันว่า ในวันเกิดปีนี้ พวกเขาจะพาฉันไปนั่งชิงช้าสวรรค์.\nลิลลี่เคยอ่านในสมุดวาดรูปว่า ชิงช้าสวรรค์เป็นวงล้อที่ใหญ่โตมาก นั่งอยู่บนมันจะค่อยๆ หมุนขึ้นไปบนฟ้า ดูนกน้อยบินไปบินมา ฟังดูมีความสุขมาก.\nแต่ซิลเวียพี่สาวบอกว่า “จริงๆ แล้วมันมีความแตกต่างบางอย่าง” ลิลลี่ก็ไม่เข้าใจว่ามันคืออะไร.\nเธอยังบอกอีกว่า ที่ที่ชิงช้าสวรรค์จะไปนั้นสูงมาก ฉันควรจะมีผู้ดูแลไปด้วย.\nลิลลี่ไม่เข้าใจว่าผู้ดูแลหมายถึงอะไร แต่ลิลลี่อยากไปเที่ยวระหว่างเมฆากับเจ้านาย.\nหลังอาหารกลางวัน ฉันกับซิลเวียพี่สาวจะรอคุณที่หน้าหอพัก.\n\nลิลลี่"
  },
  Mail_124309_Name = {
    Text = "ชิงช้าสวรรค์"
  },
  Mail_124309_Sender = {
    Text = "ลิลลี่"
  },
  Mail_124310_Desc = {
    Text = "ผู้พิทักษ์ (ครั้งนี้ฉันเขียนถูกแล้ว! เจ๋งไหม!):\n\nถึงเวลาที่จะเขียนเรื่องน่าขายหน้าพวกนี้อีกแล้ว ฉันเริ่มชินแล้ว ในเวลานี้ ฉันและบราวน์กำลังคิดเรื่องว่าจะพาคุณไปกินอะไรดีในวันนี้!\nอาหารข้างถนนในตรอกซอกซอยเขตตะวันออกแน่นอนว่าอร่อย แต่วันนี้ฉันตั้งใจจะพาคุณและบราวน์ไปกินของดีๆ — ก็คือของที่พวกเขตตะวันตกชอบกินนั่นแหละ\nเช่นอาหารจานเด็ดที่เต็มไปด้วยซอสและเครื่องเทศ ปริมาณน้อย แต่จานใหญ่ แถมยังแพงเหลือเกิน เหมือนกับการปล้นเงินเลย คิดถึงตรงนี้แล้วรู้สึกเหมือนกระเป๋าสตางค์เริ่มรั่วแล้ว แน่นอนว่ามันคือเงินที่ออกไปทิ้งรอยไว้\nแต่คุณคือคนที่สำคัญที่สุดและที่ฉันชอบที่สุดนอกจากพี่สาวและบราวน์ คนเขตตะวันออกไม่เคยงกกับคนของตัวเอง ดังนั้นวันนี้ค่าใช้จ่ายทั้งหมดจะโดยฉันและบราวน์จ่าย\nอย่ามองข้ามพวกเรา เราก็ทำเงินได้ไม่น้อยจากการส่งนม ส่งหนังสือพิมพ์ และธุรกิจอื่นๆ คุณก็สบายใจได้เลย!\n\nเพื่อนที่ดีของคุณ เจนกิน และบราวน์"
  },
  Mail_124310_Name = {
    Text = "วันนี้ฉันกับบราวน์เช็คบิล!"
  },
  Mail_124310_Sender = {
    Text = "เจนกิน"
  },
  Mail_124311_Desc = {
    Text = "เรียน ผู้พิทักษ์：\n\nคุณคงได้ยินเรื่องที่ซิลเวียทำลายคาสิโนใต้ดินมิซากะจนสิ้นซากแล้วใช่ไหม? แต่วันนี้เป็นวันเกิดของฉัน ถ้าไม่มีกิจกรรมที่ทำให้ระดับอะดรีนาลีนพุ่งสูงขึ้น ก็จะถือว่าทำให้วันดีๆ ของปีสูญเปล่าไปไหม? \nหลังจากพิจารณาอย่างรอบคอบ ฉันจึงตัดสินใจเชิญคุณเป็นเพื่อนร่วมมือของฉัน เพื่อร่วมกันจับขโมยคืนที่มาจากสีไคและขโมยสมบัติจากพิพิธภัณฑ์ใหญ่ในช่วงนี้ \nขณะที่ฉันนั่งดื่มที่บาร์ 「อะพอลโล」 ข้างนอก ฉันบังเอิญได้ยินพวกเขาพูดคุยกันอย่างตื่นเต้นเกี่ยวกับการปล้นเครื่องประดับราคาแพง พนักงานบาร์ไม่ใส่ใจ แต่ฉันฟังออกว่า มรกต, ทับทิม, เพชร และของที่ถูกขโมยทั้งหมดตรงกัน เพื่อหลีกเลี่ยงการทำให้พวกเขาตกใจ ฉันจึงทำเครื่องหมายให้กับพวกเขาและเตรียมรอให้พวกเขากลับไปยังที่ซ่อน เพื่อจับกุมพวกเขาทั้งหมด \nคืนนี้เจ็ดโมง ที่จุดจอดรถไฟมิซากะหน้าประตูโรงเรียน เราไม่พบกันไม่ได้ \n\nไรเกอร์"
  },
  Mail_124311_Name = {
    Text = "แผนการล่า"
  },
  Mail_124311_Sender = {
    Text = "ไรเกอร์"
  },
  Mail_124312_Desc = {
    Text = "ผู้พิทักษ์：\n\nเวลาที่มิซากะหมุนเวียนดูเหมือนจะเบากว่าที่อื่น ๆ หลายครั้งที่มีเสียงปรบมือ หลายครั้งที่มีการแสดงจบ ปีหนึ่งก็ผ่านไปอีกครั้ง.\nในปีนี้ ฉันได้มีนิสัยใหม่ ๆ บางอย่าง เมื่อก่อนเวลาที่ฉันขึ้นไปบนเวที แม้จะเป็นโรงละครที่แน่นขนัดในสายตาของฉันก็ว่างเปล่า ฉันเต้นรำอยู่บนเวทีที่ว่างเปล่า ต่อหน้าห้องโถงที่ว่างเปล่า เสียงที่ก้องกังวานในโลกนี้มีเพียงเสียงรองเท้าเต้นเท่านั้น และตอนนี้ ทุกครั้งที่ม่านเปิดขึ้น ฉันจะเห็นคุณ เก้าอี้นับพันว่างเปล่า มีเพียงคุณคนเดียวที่มองมาที่ฉัน ในสายตาของคุณ การเต้นรำของฉันกลับมามีความหมายอีกครั้ง.\nปีผ่านไป ท่าทางการเต้นของคุณยังคงดูเก้งก้าง แต่แววตาที่กระตือรือร้นจากคนดูที่อยู่ด้านล่าง กลับสามารถก้าวข้ามท่าทางที่ธรรมดาของการเต้นบนเวทีได้อย่างง่ายดาย แววตาเหล่านั้นเป็นลำธารที่ชำระล้างท่าทางการเต้นที่เริ่มธรรมดาของฉัน ในการเต้นรำร่วมกันระหว่างนักเต้นและผู้ชม ฉันกำลังเข้าใกล้ห้องโถงที่ฉันตามหามาตลอด ฉันในที่สุดก็เข้าใจว่า สำหรับการเต้นรำ ผู้ชมและนักเต้นมีความสำคัญเท่าเทียมกัน.\nหลายเดือนที่ผ่านมา ฉันเตรียมตัวสำหรับการเต้นรำหนึ่งชุด มันได้รับการหล่อหลอมจากสายตาของคุณ และเกิดขึ้นในเงาของคุณ ตอนนี้ มันพร้อมแล้ว.\nฉันคิดว่ามันหวังว่าในคืนนี้ จะได้เห็นคุณเป็นคนแรกที่เป็นพยานมัน.\n\nลิซ"
  },
  Mail_124312_Name = {
    Text = "นักเต้นกับผู้ชม"
  },
  Mail_124312_Sender = {Text = "ลิซ"},
  Mail_124313_Desc = {
    Text = "ผู้พิทักษ์：\n\nด้วยการต้อนรับจากที่นี่ ในปีนี้ ฉันมีโอกาสพูดคุยกับพระราชาเป็นจำนวนมาก แม้การปรากฏตัวของประเทศเทพยังห่างไกล แต่เวลาของลีมูเรียดูเหมือนจะยังคงดำเนินต่อไปในมิซากะ \nคุณและพระราชาเคยบอกฉันว่า ความเชื่อไม่ควรเป็นทั้งหมดในชีวิตของฉัน ฉันเคยดื้อรั้น แต่สิ่งที่ฉันประสบในช่วงหลังดูเหมือนจะทำให้ทัศนคติของฉันเปลี่ยนแปลงไป การสวดอ้อนวอนบ่อยเกินไป อาจทำให้พระองค์รู้สึกรำคาญ นอกจากการรับใช้ด้วยใจจริง พระองค์อาจหวังว่าผู้ศรัทธาของพระองค์จะมีชีวิตที่เรียบง่ายในแบบของตนเอง \nเมื่อเข้าใจเรื่องนี้แล้ว ฉันจึงพยายามทำการเปลี่ยนแปลงเล็กน้อย ฉันได้ไปเยี่ยมชมช่างทำขนมชื่อดังทั้งหมดในลอนดีเนี่ยน และขอให้พวกเขาสอนวิธีการอบให้ฉัน พวกเขามีความลับบางอย่างที่ไม่เปิดเผย แต่ฉันก็ได้ให้พรจากพระองค์ทำให้พวกเขายอมเปิดปาก เมื่อวานนี้ ฉันได้ลองทำบางอย่างเป็นครั้งแรก ผู้ศรัทธาหลายคนบอกว่าพวกเขาคิดว่ารสชาติดีมาก แต่รสนิยมของพวกเขาก็น่าสงสัยเช่นเดียวกับความภักดี \nฉันอยากเชิญคุณมาที่สวนของฉันในวันนี้ เพื่อชิม ฉันเชื่อในรสนิยมของคุณ และเชื่อในความตรงไปตรงมาของคุณ หากมันไม่อร่อยหวังว่าคุณจะพูดตรงๆ ฉันจะปรับปรุงอย่างจริงจัง \nขอบคุณมาก \n\nมิเรียม"
  },
  Mail_124313_Name = {
    Text = "ความชำนาญอีกอย่าง"
  },
  Mail_124313_Sender = {
    Text = "มิเรียม"
  },
  Mail_124314_Desc = {
    Text = "ท่านผู้พิทักษ์：\n\nเกี่ยวกับความหมายของชีวิตและความตาย คงจะเบื่อหน่ายกับการได้ยินมันแล้วใช่ไหม? ในความทรงจำอันงดงามของอันเดดในเนครอโพลิส สิ่งที่ฉันเรียนรู้ได้สำคัญที่สุดคือ แทนที่จะค้นหาความหมายของการรับประทานอาหาร สิ่งที่สำคัญกว่าคืออาหารที่อยู่บนโต๊ะอาหารตรงหน้า\nในยุคโบราณของมนุษย์ บรรพบุรุษของเราได้ค้นพบทุกสิ่งเกี่ยวกับความหมายของการรับประทานอาหาร—ความหลงใหล, ความปรารถนา, การเพลิดเพลิน ไม่ใช่เพื่อมีชีวิตอยู่จึงรับประทานอาหาร แต่เพื่อรับประทานอาหารจึงมีชีวิตอยู่ น่าเสียดายที่ความปรารถนาอันบริสุทธิ์เหล่านั้นถูกลืมเลือนในระยะเวลาที่ยาวนาน กลุ่มคนนี้กลับกลายเป็นซับซ้อนมากขึ้นเรื่อยๆ\nดังนั้น ฉันจึงตั้งชื่อธีมของงานเลี้ยงวันนี้ว่า 「บริสุทธิ์」 ในวันที่เต็มไปด้วยพิธีกรรมนี้ ทุกเรื่องราวที่ซับซ้อนจะหายไปจากเรา บนโต๊ะอาหารนี้ จะมีเพียงความหลงใหลและความปรารถนาอันบริสุทธิ์และดั้งเดิม มีเพียงผู้ชิมและอาหาร มีเพียงคุณและฉัน\nโปรดรับคำเชิญที่จริงใจที่สุดจากฉัน คุณจะไม่ปฏิเสธฉันใช่ไหม? \n\nดูเรซิน"
  },
  Mail_124314_Name = {
    Text = "งานเลี้ยงมื้อค่ำบริสุทธิ์"
  },
  Mail_124314_Sender = {
    Text = "ดูเรซิน"
  },
  Mail_124315_Desc = {
    Text = "ท่านผู้พิทักษ์ที่รักที่สุด: \n\nหัวใจของฉันเหมือนกำลังเติบโต... ฉันรู้ว่ามันฟังดูแปลกสำหรับผู้ปลุกตื่น แต่แตกต่างจากก่อนหน้านี้ ฉันจะอธิบายให้ท่านฟังอย่างไรดี? \nไม่ว่าคนดีเหล่านั้นจะปฏิบัติกับฉันอย่างอ่อนโยนและเอาใจใส่เพียงใด พยายามให้อบอุ่น หลังจากพี่ชายจากไป อกของฉันก็ยังคงว่างเปล่า ฉันยิ่งเดินอยู่ใต้แสงอาทิตย์มากเท่าไร ก็ยิ่งถูกความอบอุ่นเหล่านั้นทำร้ายมากขึ้นเท่านั้น กลับกัน ความมืดและความชื้นกลับทำให้ฉันรู้สึกสบายใจ เหมือนว่าถ้าฉันอยู่ในที่เย็นชืดตลอดไป ความรักที่เข้มงวดและเจ็บปวดของพี่ชายจะยังคงอยู่กับฉัน \nแต่ตอนนี้ หลังจากปีที่ใกล้ชิดกับท่านมากขึ้นทุกที ทุกครั้งที่เห็นท่าน ทุกครั้งที่ความเจ็บปวดที่ท่านมอบให้ตกลงบนเนื้อของฉัน ส่งผ่านไปยังกระดูกของฉัน—อา อา ความสุขในอกของฉันเพิ่มขึ้นเรื่อยๆ เพียงแต่ท่านตีฉันอย่างไม่ปรานี ดูหมิ่นฉัน ข่มเหงฉัน ฉันก็รู้ว่าที่นี่มีที่ที่ฉันสามารถอยู่ได้จริงๆ \nความสุขนี้จะยั่งยืนไปจนถึงปีหน้าไหม ปีถัดไปล่ะ? ถ้าความปรารถนาที่อวยพรในวันเกิดเป็นจริง ความปรารถนาเดียวของฉันคือการถูกท่านมองด้วยสายตาเหยียดหยามตลอดไป และมีความเจ็บปวด... ความเจ็บปวดมากขึ้นเรื่อยๆ เมื่อท่านยกมือขึ้น สิ่งแรกที่ฉันจะรู้สึกคือกลิ่นอันคุ้นเคย โหดร้าย และมีความสุข \n\nลีห์ที่หวังจะถูกท่านตี"
  },
  Mail_124315_Name = {
    Text = "หัวใจของฉัน"
  },
  Mail_124315_Sender = {
    Text = "ลีห์"
  },
  Mail_124316_Desc = {
    Text = "ผู้พิทักษ์\n\nแม้ว่าฉันอยากรู้เกี่ยวกับการฝึกซ้อมของคุณในช่วงนี้ แต่โปรดมั่นใจว่า วันนี้ไม่ใช่วันที่ฉันจะมาคอยกดดันให้คุณฝึกซ้อมดนตรี\nเช้าวันนี้ ฉันได้ไปที่ห้องดนตรีตามปกติ แต่ฉันมาสายไปสามสิบห้านาที การฝึกซ้อมดนตรีในเวลาเจ็ดโมงเช้านั้นเป็นนิสัยที่ฉันรักษามาหลายสิบปี แต่วันนี้กลับถูกทำลายอย่างง่ายดาย สาเหตุคือเมื่อฉันเดินผ่านทางเดินของโรงเรียน ฉันได้ยินเสียงร้องของนกโรบิน\nการทำลายความเคยชินที่มีมานานไม่ใช่เรื่องง่ายที่จะยอมรับ โดยเฉพาะสำหรับฉัน อย่างไรก็ตาม แปลกที่ฉันไม่ได้รู้สึกผิดหวังและโกรธกับตัวเองอย่างที่คิดไว้ ตอนแรก ฉันรู้สึกตื่นตระหนก แต่ต่อมาฉันต้องยอมรับว่า ทำนองที่วนอยู่ในหัวของฉันนั้นช่างน่าพอใจ\nลอนดีเนี่ยนมักจะถูกปลุกตื่นด้วยเสียงนกโรบิน ซึ่งเสียงนี้ฉันสามารถได้ยินทุกวัน แต่แปลกที่ในหลายปีมานี้ นี่เป็นครั้งแรกที่ฉันสังเกตเห็นมัน ฉันยืนฟังเสียงเพลงของพวกมันในทางเดิน และในสามสิบนาทีนี้ ฉันรู้สึกว่าทำนองที่สูงส่งที่สุดในจักรวาลซ่อนอยู่ในลำคอเล็กๆ ของพวกมัน\nอาจจะเป็นเพราะชีวิตที่นี่ทำให้รู้สึกเฉื่อยชา หรืออาจจะเป็นบรรยากาศที่ทำให้คนอ่อนโยนขึ้น ไม่ว่าจะเป็นอย่างไรก็ตาม ฉันคิดว่ามันต้องเกี่ยวข้องกับคุณ\nใช้เวลาเพียงสิบ นาทีฉันก็ยอมรับการเปลี่ยนแปลงนี้อย่างมีความสุข ชีวิตเหมือนดนตรีมีจังหวะและการเปลี่ยนแปลงที่โบราณ วันเกิดอาจเป็นจุดที่การเปลี่ยนแปลงเหล่านี้ถูกกำหนดไว้ ฉันยังอยากขอบคุณคุณที่ทำให้ฉันมีโอกาสนี้ในการตั้งสติฟังสิ่งที่ฉันเคยมองข้าม ความสุข ใช่ ฉันคิดว่านี่จะเป็นจุดเริ่มต้นของบทเพลงใหม่ในชีวิตของฉัน\nเพราะฉะนั้น ฉันอยากเชิญคุณไปที่ป่าลึกข้างนอกโรงเรียนในช่วงเย็นวันนี้ เสียงธรรมชาติในช่วงเย็นจะแตกต่างจากตอนเช้า แต่ฉันคิดว่ามันจะเป็นแรงบันดาลใจใหม่ในชีวิตดนตรีของเรา\n\nฮาเมลน์"
  },
  Mail_124316_Name = {
    Text = "เสียงธรรมชาติ"
  },
  Mail_124316_Sender = {
    Text = "ฮาเมลน์"
  },
  Mail_124317_Desc = {
    Text = "ผู้มีอุปการคุณ：\n\nฉันเพิ่งเห็นอีเมลวันเกิดที่เฟนท์เขียนถึงคุณ... แน่นอนว่า พี่สาวของเธอมักจะคิดถึงคนอื่นเสมอ แค่ระหว่างพี่น้องก็ไม่มีใครเป็นหนี้ใคร และฉันก็ไม่เคยมองว่าเธอเป็นภาระ หากไม่มีการปกป้องของเธอ ฉันก็คงไม่มีโอกาสได้จัดคอนเสิร์ตทัวร์ในตอนนี้\nผู้มีอุปการคุณที่เคารพ คุณเป็นผู้ฟังที่สำคัญที่สุดสำหรับฉันเสมอ ดังนั้นครั้งนี้ ฉันจึงเตรียมตั๋วเรือให้คุณอย่างเงียบๆ—ขอเชิญคุณมาร่วมเดินทางในทริปข้ามจักรวาลครั้งนี้ หากมีคุณไปด้วย ฉันเชื่อว่าความรู้สึกหนักใจในใจของพี่สาวจะลดน้อยลงมาก\nนอกจากนี้โปรดสบายใจได้ ในระหว่างการเดินทางเราจะไม่รบกวนเวลาส่วนตัวของคุณ ฉันและพี่สาวหวังว่าคุณจะได้เพลิดเพลินกับการเดินทางนี้อย่างเต็มที่ และสัมผัสกับทุกเนบิวลาและการพบเจอที่ไม่รู้จักอย่างอิสระ\n\nทิงค์"
  },
  Mail_124317_Name = {
    Text = "คำเชิญเดินทาง"
  },
  Mail_124317_Sender = {
    Text = "ทิงค์"
  },
  Mail_124318_Desc = {
    Text = "ผู้พิทักษ์： \n\nวันเกิดใกล้เข้ามาแล้ว แต่ความคิดกลับลอยไปที่สีไคโดยไม่รู้ตัว โดยเฉพาะอย่างยิ่งคิดถึงประติมากรรมในนิทรรศการศิลปะเหล่านั้น ท่าทางที่เงียบสงบของพวกมันเคยเคาะประตูแรงบัลดาลใจของฉันนับครั้งไม่ถ้วน.\nในสตูดิโอที่อยู่กับประติมากรรมตลอดทั้งวัน ขาดการแลกเปลี่ยนทางศิลปะ มานานแล้ว ก็รู้สึกเบื่อหน่าย ปีที่แล้วในช่วงเวลาเดียวกัน เพื่อฉลองวันเกิดของตัวเอง ฉันได้สร้างเค้กประติมากรรมมากมาย ในตอนแรกรู้สึกสนุกสนาน แต่ตอนนี้กลับสู่ความสงบแล้ว.\nตอนนี้ขยับตัวไม่สะดวก การกลับไปที่สีไคกลายเป็นความปรารถนาอันหรูหรา หากคุณมีแผนการไปสำรวจ สามารถช่วยสังเกตงานใหม่ในนิทรรศการศิลปะให้ฉันได้ไหม? ฉันปรารถนาให้คุณได้มองเห็นความงดงามของศิลปะที่หลากหลายและเปิดกว้างอีกครั้ง.\nเพื่อเป็นการตอบแทน ฉันยินดีที่จะสร้างประติมากรรมให้คุณอีกชิ้นหนึ่ง ชื่อว่า«ผู้พิทักษ์ที่สีไค»เป็นยังไงบ้าง?\n\nซังก้า"
  },
  Mail_124318_Name = {
    Text = "ความคิดถึงเซียงได"
  },
  Mail_124318_Sender = {
    Text = "ซังก้า"
  },
  Mail_124770_Desc = {
    Text = "ผู้พิทักษ์：\n\nเนื่องจากทุกปีสิทธิ์ในการเข้าห้องทดลองของฉันจะถูกยกเลิก วันนั้นจึงกลายเป็นวันพิเศษในแบบที่ไม่พึงประสงค์ เพื่อไม่ให้เสียเวลาไปกับเรื่องที่ไม่มีประสิทธิภาพ ฉันจึงไปที่ห้องเก็บเอกสาร \nที่นั่นฉันพบสองสิ่ง หนึ่งในนั้นคือสมุดการบ้านที่เต็มไปด้วยช่องว่างที่ไม่มีค่า \nอีกเล่มก็เป็นสมุดการบ้านเช่นกัน ซึ่งทำให้ฉันรู้ว่าฉันประเมินค่าความรู้ในมหาสมุทรต่ำเกินไป เพราะกระบวนการอนุมานและข้อสรุปที่อยู่ในนั้นทำให้ฉันรู้ว่ามีสิ่งที่มีค่าต่ำกว่าการไม่มีอยู่จริงในโลกนี้ \nและสมุดการบ้านทั้งสองเล่มนี้เขียนชื่อเดียวกันว่า ผู้พิทักษ์มิซากะที่ยิ่งใหญ่ของเรา %player% \nเอริกา บอกฉันว่าคุณอยากรู้ว่าจะส่งของขวัญวันเกิดอะไรให้ฉัน \nคุณสามารถส่งคำตอบให้ฉันได้ \nฉันก็อยากรู้ ว่าคำตอบไหนที่จะทำให้ฉันตกใจมากกว่า มันเป็นเพียงความขี้เกียจและการทำงานที่ขาดความพยายาม หรือคุณได้เรียนรู้ตลอดทั้งปีและท้ายที่สุดก็ทิ้งขยะทางวิชาการเหล่านี้ไว้ในความสิ้นหวังที่ไร้ประโยชน์ \nถ้าเป็นอย่างแรก เพียงแค่มีเหตุผลที่เพียงพอและพิสูจน์ว่าคุณเข้าใจความรู้ที่สอนในชั้นเรียนทั้งหมด ฉันสามารถยื่นคำร้องขอยกเว้นการบ้านให้คุณกับวิทยาลัยได้ แน่นอนว่านี่ไม่ได้หมายความว่าฉันสนับสนุนความเกียจคร้านที่อาจทำให้คุณเลิกขยัน แต่ถ้าคุณสามารถผ่านการทดสอบของฉันได้เสมอ ฉันไม่ใช่คนหัวโบราณ และไม่รังเกียจที่จะให้สิทธิพิเศษกับนักเรียนของฉัน \nถ้าเป็นอย่างหลัง ในฐานะผู้ปกครองคนแรกของคุณ เชื่อฉันเถอะ ไม่ว่าคุณจะเป็นวัสดุที่ยากจะปรับรูปแบบแค่ไหน เราสามารถหาสิ่งหนึ่งในเทคโนโลยีที่ฉันควบคุมได้ เพื่อเพิ่มพูนความรู้ที่ขาดแคลนของคุณ และช่วยให้คุณหลุดพ้นจากความทุกข์ทรมานจากความไม่รู้ \nวันนี้บ่ายสี่โมง ฉันจะอยู่ที่ห้องเก็บเอกสาร เพื่อตรวจสอบความเข้าใจของคุณในความรู้ในชั้นเรียน อย่ามาสาย \n\nดอลล์"
  },
  Mail_124770_Name = {
    Text = "สิทธิพิเศษ"
  },
  Mail_124770_Sender = {
    Text = "ดอลล์"
  },
  Mail_124771_Desc = {
    Text = "ลูกหมาของมิซากะ：\n\nปีนี้คุณก็ยังติดอยู่ในวงจรประจำวันซ้ำซากนั้น ทำเรื่องยุ่งเหยิง ช่วยโลก ทำเพื่อน เรียนรู้สิ่งใหม่ ๆ และยังคงสร้างภาพลวงตาที่ทุกอย่างเป็นปกติให้กับโลกต่อไป \nที่แท้แม้จะเอาสมองของคุณออกจากร่างกาย และดึงลูมินิสจากมิติหนึ่งไปยังอีกมิติหนึ่ง ก็ไม่ได้ส่งผลกระทบต่อการวิ่งวุ่นวายและยุ่งเหยิงที่น่าหัวเราะของคุณเลย \nช่างยุ่งเหยิงและเสียงดังจริง ๆ ลูกสุนัขที่รัก \nคุณไม่เชื่อในความจริงเหล่านั้น คุณยังจะต้องทำให้พวกเขาเจ็บปวดต่อไป ทำให้กระบวนการล่มสลายยืดเยื้อออกไปอีกนิด เป้าหมายของคุณคืออะไร คุณกำลังแกล้งโง่หรือมนุษย์สามารถโง่ได้ขนาดนี้จริง ๆ? แม้ว่าฉันจะเคยเปิดเปลือกสมองของร่างกายคุณ แต่สิ่งเหล่านี้ยังคงเป็นปริศนาที่ไม่สามารถแก้ไขได้สำหรับฉัน \nยินดีด้วย คุณทำให้ฉันเริ่มมีความสั่นคลอน ฉันถึงกับเริ่มสงสัยว่าถ้าการสังเกตคุณทำให้ฉันมีความสุขมากขนาดนี้ ทุกอย่างยังสามารถพูดได้ว่าไร้ความหมายอยู่หรือไม่? \nจงอธิษฐานไปเถอะ ทำสิ่งที่คุณถนัดในแบบที่ไร้ความหมาย อธิษฐานให้ใครก็ไม่มีความสำคัญ \nอธิษฐานว่าคุณจะสามารถขังฉันไว้ตลอดไป ลูกสุนัข นั่นจะทำให้ฉันและคุณสามารถหาความสนุกในโลกที่ไร้ความหมายนี้ได้บ้าง \n\n「ดอร์」"
  },
  Mail_124771_Name = {
    Text = "สวดมนต์เถอะ"
  },
  Mail_124771_Sender = {
    Text = "ดอลล์: มลายทราม"
  },
  Mail_124772_Desc = {
    Text = "คู่หู：\n\nในวันเกิดของคุณในทุกปี การเขียนจดหมายให้คุณดูเหมือนจะกลายเป็นประเพณีไปโดยไม่รู้ตัว \nฉันยังจำได้ วันเกิดที่ฉันเขียนจดหมายให้คุณเป็นครั้งแรก，ก็เช่นกันครั้งแรกที่พ่ออนุญาตให้ฉันจัดการเรื่องวันเกิดเอง ฉันเชิญคุณออกไปข้างนอกกับฉัน และหลังจากนั้น เราได้ประสบการณ์ใหม่ๆ ร่วมกันมากมาย \nหลายสิ่งหลายอย่างหลังจากนั้นก็มีการเปลี่ยนแปลงมากมาย แต่เมื่อคิดให้ดีแล้ว มันก็เหมือนกับว่าไม่มีอะไรเปลี่ยนแปลง เรายังคงเดินอยู่บนเส้นทางที่เรากำหนดไว้ และเรายังคงมีแต่กันและกันอยู่ข้างๆ และคุณยังคงเป็นคู่หูที่สำคัญที่สุดสำหรับฉัน \nดังนั้น แม้ว่าพ่อเพิ่งส่งเค้กมาให้ และถามว่าฉันจะไปงานเลี้ยงที่เขาจัดให้ในคืนนี้หรือไม่ ฉันก็มีแผนอื่นในคืนนี้ \nลอนดีเนี่ยนได้ฉายภาพยนตร์ใหม่ซึ่งได้รับความนิยมอย่างผิดปกติ แต่สถาบันและสมาคมได้ยืนยันร่วมกันแล้วว่า ไม่มีการตอบสนองทางจิตวิญญาณใดๆ \nนี่หมายความว่ามันเป็นเพียงผลงานที่ 「ธรรมดา」 ที่ยอดเยี่ยมจริงๆ \nฉันมีตั๋วสองใบ คุณสามารถสมมติได้ว่าฉันไม่ได้ไปสร้างความลำบากให้คุณนายโซเรล เพราะตั๋วมันหายากมาก \nดังนั้น คู่หู คุณยินดีที่จะใช้เวลานี้กับฉันไหม? บางทีเราอาจจะหลีกหนีจากสถานการณ์ผิดปกติที่เราต้องจัดการทุกวัน และใช้เวลากับกันในคืนที่ 「ธรรมดา」 สักคืน \nในวันพรุ่งนี้เมื่อเราตื่นขึ้นมา ไม่ว่าโลกจะเกิดอะไรขึ้น ฉันจะเผชิญหน้ากับมันไปกับคุณ \n\nราโมน่า"
  },
  Mail_124772_Sender = {
    Text = "ราโมน่า"
  },
  Mail_124773_Desc = {
    Text = "ผู้พิทักษ์：\n\nขอบคุณความสัมพันธ์พิเศษระหว่างฉันกับตัวตนของฉัน รวมถึงลิงก์ระหว่างฉันกับคุณ แม้ว่าจะไม่ได้อยู่เคียงข้างคุณตลอดเวลา แต่ฉันก็มีความรู้เล็กน้อยเกี่ยวกับสิ่งที่เกิดขึ้นกับคุณในปีที่ผ่านมา \nคุณมีชีวิตอยู่ในโลกอีกใบ ดูเหมือนว่าคุณยังคงนำการเปลี่ยนแปลงที่ชื่อว่า「ความหวัง」มาสู่ที่นั่น แม้จะมองขึ้นไปในบ่อดำวันแล้ววันเล่า พลังงานที่เหมือนแสงนี้ก็ยังทำให้ฉันรู้สึกอบอุ่น \nฉันเริ่มกลับมาทำตารางเวลาที่เคยทำ แต่แตกต่างจากเมื่อก่อน ตอนนี้ฉันไม่ได้เผชิญหน้ากับการล้างผลาญที่กำหนดไว้ด้วยใจที่ดิ้นรนอย่างไร้ประโยชน์อีกต่อไป คุณสอนฉันสิ่งใหม่ ๆ ว่ากระบวนการที่แต่ละการดำรงอยู่พยายามอย่างเต็มที่เพื่อความต่อเนื่องก่อนถึงจุดสิ้นสุดที่กำหนด นั่นคือเหตุผลที่ทำให้วัฒนธรรม, จิตวิญญาณ, และเจตจำนงมีความหมาย \nไม่ว่าสำหรับโลกที่ฉันอยู่จะมีช่วงเวลานี้สั้นเพียงใด ฉันจะพยายามต่อไป แม้เพียงแค่เพื่อที่จะได้พบกับใบหน้าที่คุ้นเคยและพูดคุยกับพวกเขา การพยายามนี้ก็ไม่ใช่เรื่องที่ไร้ความหมาย \nจนกว่าคุณจะหยุด ฉันจะเดินต่อไปบนเส้นทางนี้ ขอให้ฉันได้เห็นมันเป็นวิธีการที่เห็นแก่ตัวในการเดินเคียงข้างคุณ เพื่อที่อาจจะทำให้คุณนึกถึงว่ามีฉันคนนี้ที่พยายามอย่างเต็มที่ทำในสิ่งที่เหมือนกับคุณ \n\n「รามอน่า」"
  },
  Mail_124773_Sender = {
    Text = "「รามอน่า」"
  },
  Mail_124774_Desc = {
    Text = "การฆ่าเป้าหมายนั้นง่าย แต่การจัดการหลังจากนั้นเป็นเรื่องยุ่งยาก.\nปีนี้ฉันตั้งใจจะทำตามประเพณีของปีที่แล้ว โดยการช่วยคุณฆ่าคนอีกคน.\nอย่างไรก็ตาม ฉันสังเกตว่าคุณยังไม่ได้ใช้ของขวัญชิ้นก่อนที่ฉันให้ไป หลังจากคิดอย่างรอบคอบ ถึงแม้จะไม่แน่ใจว่านี่เป็นสาเหตุหรือไม่ แต่ฉันก็พบข้อบกพร่องของตัวเอง.\nคุณสามารถวางใจได้ แม้ว่าในอดีต ฉันมักจะให้บริการเฉพาะการฆ่าศัตรูให้กับนายจ้าง แต่เพื่อหลีกเลี่ยงปัญหาต่างๆ ในการทำลายหลักฐาน ฉันก็มีประสบการณ์มาก.แม้ว่าเป้าหมายที่คุณต้องการฆ่าจะอยู่ภายใต้การป้องกันของกฎระเบียบและระเบียบที่ยุ่งยาก คุณก็ไม่จำเป็นต้องกังวลใจ ฉันจะจัดการทุกอย่างให้เรียบร้อย.\nฉันรับรองว่า จะไม่มีใครสามารถติดตามคุณได้.\nเมื่อคุณคิดชื่อคนที่ต้องการได้แล้ว ก็แค่บอกชื่อฉัน,     ไม่ว่าฉันจะอยู่ที่ไหน,     จะรีบไปช่วยคุณจัดการกับพระองค์ทันที.\nขอให้คุณมีความสุขในวันหยุดนี้,     และหวังว่าคุณจะรู้สึกมีความสุขในวันที่ฉันเกิดด้วยนะ,     ผู้พิทักษ์.\n\n\nเฮลอต"
  },
  Mail_124774_Name = {
    Text = "ผู้ที่ฆ่าคนบ่อยๆ มักจะรู้ว่า\n..."
  },
  Mail_124774_Sender = {
    Text = "เฮลอต"
  },
  Mail_124775_Desc = {
    Text = "ดีแล้ว ชัดเจนว่าพวกคุณไม่ได้เตรียมตัวหยุดพฤติกรรมนี้ ตามที่ฉันทราบ ฉันก็เคยชินกับประเพณี 「การมอบของขวัญ」 แล้ว \n แต่วันหนึ่งคุณจะเสียใจที่ทำดีแบบนี้ เชื่อฉันเถอะ \n ตอนนี้คิดดูแล้ว นั่นอาจเป็นสิ่งที่ฉันเสียใจที่สุด ช่างน่าเสียดาย ฉันไม่เคยคิดว่าฉันจะเสียใจเพราะการฆ่า \n ไม่มีใครรู้ดีไปกว่าฉัน ว่าความรู้สึกผิดไม่มีค่าอะไร แต่ก่อนที่จะถึงวันนั้น ฉันจะพยายามทำอะไรสักอย่างเพื่อชดเชย เพียงแค่เพราะฉันอยากทำ \n เมื่อคุณเกลียดฉันในอนาคตเพราะเรื่องนั้น ไม่ต้องรู้สึกเครียดเกี่ยวกับมัน \n ฉันจะยอมรับความโกรธของพวกคุณอย่างเต็มที่ \n\nH"
  },
  Mail_124775_Name = {
    Text = "คุณจะเสียใจ"
  },
  Mail_124775_Sender = {
    Text = "เฮลอต: ตรวนสีชาด"
  },
  Mail_124776_Desc = {
    Text = "ผู้พิทักษ์：\n\nอีกครั้งหนึ่งที่ถึงวันเกิด วันเฉลิมฉลองการมีชีวิตอยู่ โดยปกติแล้วเมื่อวันนี้มาถึง ฉันมักจะรู้สึกแปลกประหลาดอยู่เสมอ \nการเกิดของฉันดูเหมือนจะเป็นเพื่อไล่ตามความตาย เมื่อหลุดพ้นจากธีมของความตายแล้ว ชีวิต... หรือกล่าวอีกอย่างก็คือ สติยังคงดำเนินต่อไปในช่วงเวลาใดช่วงเวลาหนึ่ง มันหมายถึงอะไรสำหรับฉันกันแน่?\nในช่วงชีวิต ความเจ็บปวดและความรู้สึกผิดที่ดึงรั้งกัน ทำให้ชีวิตของฉันพันกันอย่างยากจะหลีกหนี จนกระทั่งความตายมาถึง ชีวิตจึงเริ่มเป็นของฉันอย่างแท้จริงเป็นครั้งแรก \nปีที่แล้ว ปีนี้ หรืออาจจะทุกปีในอนาคต ฉันมีเวลายาวนานเกือบจะไม่มีที่สิ้นสุดในการสัมผัส ทุกวันเหมือนกับวันก่อน แต่ก็ไม่เหมือนกัน ในเมื่อชีวิตไม่ถูกพันธนาการด้วยความเจ็บปวดและเป้าหมาย มันจะมีจุดสิ้นสุดเป็นอย่างไร หรือจุดสิ้นสุดที่กล่าวอาจจะมาถึงอีกครั้งไหม?\nหัวข้อนี้มันใหญ่เกินไป ฉันคิดไม่ออก \nแต่ความรู้สึกที่อยากจะบันทึกความคิดที่แปลกประหลาดเหล่านี้มันช่างจริงจัง ฉันรู้สึกว่าคำตอบเหมือนจะเปิดเผยอยู่แล้ว \nอย่างน้อยสำหรับฉัน มันคือช่วงเวลาที่ชัดเจนและมีค่า ไม่ว่าความคิดของฉันจะยุ่งเหยิงเพียงใด ไม่ว่าฉันจะหาที่มาของมันได้ยากเพียงใด ฉันรู้ชัดเจนว่ามันสามารถล่องลอยไปที่ไหน และถูกยอมรับที่ไหน และฉันก็อยากจะเปิดเผยมันให้คุณ \nอาจจะปีหน้าวันนี้ ฉันจะหาความหมายที่เป็นตัวเองมากกว่านี้ แต่ตอนนี้ ฉันหวังว่าจะสามารถเห็นแก่ตัวเก็บรักษาสิ่งเล็กน้อยเหล่านี้ไว้ ซึ่งมีเพียงคุณและฉันที่รู้จัก \nใช่ ผู้พิทักษ์ คุณและทุกคนในมิซากะ คือรากฐานที่ไม่มีใครรู้จักในใจของฉัน \nขอบคุณคุณเสมอมา ขอให้คุณมีความสุขตลอดไป และสงบสุขตลอดไป \n\nนิมเฟีย"
  },
  Mail_124776_Name = {
    Text = "ระบบราก"
  },
  Mail_124776_Sender = {
    Text = "นิมเฟีย"
  },
  Mail_124777_Desc = {
    Text = "เหลือเพิ่งประดิษฐ์วิธีการผ่อนคลายใหม่——ประเทศเทพพักกลางวัน.\nแตกต่างจากการพักกลางวันที่รวดเร็วและสั้นทั่วไป ในการพักกลางวันประเทศเทพนี้ ยู่จะออกจากบัลลังก์หินสีฟ้าที่นั่งนาน,     จะแขนสัมผัสสร้างเป็นทรงกลมที่ปิดเสียง,     ต่อมาเติมน้ำทะเลที่ปรุงพิเศษให้เต็มพื้นที่ทั้งหมด.\nน้ำทะเลเหล่านี้ไม่เพียงแต่สามารถปล่อยกลิ่นหอมที่ยู่ต้องการ เปลี่ยนเป็นทัศนียภาพที่ยู่ต้องการมองเห็น แต่ยังสามารถรองรับร่างกายของยู่จากทุกทิศทางด้วยความแรงที่เหมาะสม.\nดังนั้น ไม่ว่ายู่จะวางท่าทางใด ก็สามารถสัมผัสได้ถึงความรู้สึกอบอุ่นเหมือนอยู่ในเตียงนุ่นระดับสูงสุด.\nเมื่อถึงเวลานั้น ยู่สามารถผ่อนคลายจิตใจในกลิ่นหอมที่ชอบ เพลิดเพลินกับความเงียบสงบที่แยกตัวออกจากโลกภายนอก โดยหนุนศีรษะด้วยหมอนที่ยู่ชอบที่สุดและหลับอย่างสบาย.\nในฐานะที่เป็นข้าราชบริพารที่ยู่ชอบที่สุด ยู่คิดว่าวันเกิดของยู่เป็นวันที่เหมาะสมที่สุดที่จะแบ่งปันความสบายนี้กับเจ้า.ถ้าเจ้าสนใจ,     ได้มาที่สถานที่ลับที่ยู่เคยบอกเจ้า.ไม่ต้องกังวลเกี่ยวกับความปลอดภัยของเจ้า ยู่จะสร้างพื้นที่ที่เป็นเอกเทศให้กับเจ้า,     ให้เจ้าหลีกเลี่ยงผลกระทบจากความฝันที่ยู่ปล่อยออกมา.\nอย่าลืมนำหมอนที่สบายที่สุดของเจ้ามาด้วย.\n\nธูลู"
  },
  Mail_124777_Name = {
    Text = "พักกลางวัน"
  },
  Mail_124777_Sender = {
    Text = "ธูลู"
  },
  Mail_124778_Desc = {
    Text = "ดวงไฟของฉัน：\n\nฉันและคาสเตอร์ได้ปรับตัวเข้ากับชีวิตที่มิซากะแล้ว หลังจากหลบหนีจากการหลอกลวงและการฆ่าฟันของคริสตจักร ฉันรู้สึกว่าฉันกำลังค้นหาตัวตนในอดีตของตัวเองกลับมาอีกครั้ง\nแม้ว่าในชีวิตประจำวันยังหลีกเลี่ยงไม่ได้ที่จะมีเงาของ「บุตรศักดิ์สิทธิ์」ปะปนอยู่ แต่เชื่อว่าไม่นานฉันจะสามารถลบล้างความหยิ่งผยองและความห่างเหินนั้นออกไปได้ โดยเหลือเพียงความอ่อนน้อมต่อพระเจ้าและความมุ่งมั่นที่จะเดินตามทางที่ถูกต้อง\nเมื่อเร็วๆ นี้ฉันได้รับของขวัญที่ค่อนข้างเซอร์ไพรส์ เป็นหนังสือที่มีการจัดทำอย่างสวยงาม เล่าถึงเรื่องราวของผู้ที่จากบ้านเกิดกลับมาหาอดีตในวัยเด็กของตน พร้อมกับมันยังมีบันทึกที่เขียนไว้ว่า「ขอให้คุณค้นหาตัวตนในตอนแรกของคุณได้เร็วๆ」\nประโยคนี้ปรากฏต่อหน้าฉันในฉากแรก ความทรงจำในอดีตทั้งหลายก็ลอยขึ้นมาในใจ——ความห่วงใยของทุกคนที่มิซากะ การชี้นำของดวงไฟ และอ้อมกอดอันอบอุ่นจากพี่ชายของฉัน\nดังนั้นในวันเกิดปีนี้ ฉันจึงอยากเชิญทุกคนที่มิซากะมาร่วมงานเลี้ยงวันเกิดของฉันและพี่ชาย ไม่มีความช่วยเหลือจากทุกคน เราคงไม่มีทางกลับไปยังช่วงเวลาในตอนแรกได้\nฉันใช้เงินเก็บที่สะสมมาในระยะเวลาที่ผ่านมาเช่าที่ร้านอาหารแห่งหนึ่ง เชฟที่นั่นมีความรู้เกี่ยวกับอาหารจากทั่วทุกมุมโลก เชื่อว่าทุกคนจะสามารถลิ้มลองรสชาติที่คุ้นเคยที่สุดได้ที่นั่น\n\nโพลลักซ์"
  },
  Mail_124778_Name = {
    Text = "ค้นหาวัยเด็ก"
  },
  Mail_124778_Sender = {
    Text = "โพลลักซ์"
  },
  Mail_124779_Desc = {
    Text = "ฉันตัดสินใจรับคำเชิญจากสนามแข่งใต้ดินในชานเมือง เพื่อเข้าร่วมการแข่งขันที่ชีวิตและความตายไม่สำคัญ\nแม้วันเวลาที่คลับปลาเทราต์จะดี แต่ก็เรียบง่ายเกินไป ทุกวันไม่ใช่ฆ่าปลาก็ฆ่าปลา อาจจะพูดได้ว่าฉันได้พิชิตปลาเทราต์อย่างสมบูรณ์ แต่การพิชิตปลาเทราต์นั้นไม่ถือว่าเป็นการพิชิต!\nเลือดนักรบในร่างกายของฉันกำลังเดือดพล่าน พวกมันต้องการการต่อสู้ที่เต็มไปด้วยความตื่นเต้น และตอนนี้ โอกาสมาถึงแล้ว\nผู้ชายหัวล้านที่ติดต่อกับฉันบอกว่าเขาได้หามังกรนาฏยักษ์สามตัว หมีหน้าผีสองตัว จระเข้เซรีนาซอนสี่ตัว และสัตว์แปลกๆ อีกมากมายที่ฉันจำชื่อไม่ได้ เพียงพอให้ฉันได้ต่อสู้ตลอดทั้งคืน\nฉันตั้งใจให้พวกเขาจัดการแข่งขันในวันนี้ เพื่อที่จะได้แสดงให้คุณเห็นในวันเกิดของฉัน—ฉัน, อูฟฮาช, นักรบโรมันคนสุดท้าย ผู้พิชิตสัตว์ร้ายทุกชนิดในโลก!\nวันนี้จะไม่มีเศษปลาเทราต์ในสนามอีกต่อไป แต่จะเป็นเลือดและซากสัตว์ประหลาด!\n\nอูฟฮาช"
  },
  Mail_124779_Name = {
    Text = "พิชิตสัตว์ร้าย"
  },
  Mail_124779_Sender = {
    Text = "อูฟฮาช"
  },
  Mail_124780_Desc = {
    Text = "「อัศวินกุญแจเงิน」：\n\nผู้พิทักษ์! เมื่อกี้ฉันกำลังปรับแต่ง「เรือมายา」อยู่ มอสก็ส่งถุงชิ้นส่วนขนาดใหญ่ให้ฉัน บอกว่าเป็นของขวัญวันเกิดของฉัน ฉันถึงนึกขึ้นได้ว่าวันนี้เป็นวันเกิดของฉัน!\nดังนั้นฉันจึงรีบเขียนจดหมายถึงคุณ จริงๆ แล้ว ฉันทำไมถึงลืมวันนี้อีกแล้วนะ ทั้งที่ฉันเขียน...เขียนไปกี่ใบแล้วนะ?\nแต่ทั้งหมดนี้ไม่สำคัญ สิ่งที่สำคัญคือ ฉันนึกถึงสิ่งที่เคยบอกว่าจะทำในวันเกิดแล้ว——ฉันจะขึ้น「เรือมายา」พาคุณและมอสไปวนรอบลอนดีเนี่ยนหนึ่งร้อยรอบ!\nถึงมอสจะไม่เข้าใจเรื่องเครื่องจักรเลย แต่ถุงชิ้นส่วนนั้นมันมากเกินไป จนทำให้ฉันสามารถหาชิ้นส่วนที่ต้องการทั้งหมดได้ ตอนนี้「เรือมายา」ที่ปรับแต่งแล้ว ได้กลายเป็นเวอร์ชันต้นแบบที่มีความแข็งแกร่งมากขึ้น (ชั่วคราว)!\nฉันตั้งชื่อการผจญภัยนี้ว่า โนติลา กับผู้พิทักษ์และมอส กับ「มโนภาพ」การผจญภัย เป็นไงล่ะ ฟังดูตรงไปตรงมาดีไหม? แบบนี้ฉันจะไม่มีวันลืมการผจญภัยนี้แน่ๆ\nเฮ้ เฮ้ มันน่าตื่นเต้นจริงๆ รออีกสักครู่ ผู้พิทักษ์「อัศวินมายา」โนติลา และ「วังวนอัศวิน」มอสกำลังจะมาถึงแล้ว!\nทีมผจญภัย「มโนภาพ」 ออกเดินทาง!\n\nโนติลาที่กำลังเร่งเครื่องเข้ามา"
  },
  Mail_124780_Name = {
    Text = "「ภาพลวงตา」โจมตี!"
  },
  Mail_124780_Sender = {
    Text = "นอติลา"
  },
  Mail_124793_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพรักและยิ่งใหญ่<Del:น่ารัก> {Male=คุณผู้ชาย,Female=คุณผู้หญิง}：\n\nอา อา นานมากแล้วที่ไม่ได้ติดต่อกัน, ผู้พิทักษ์ที่รักของเราท่าน{Male=คุณผู้ชาย,Female=คุณผู้หญิง} คิดถึงฉันไหม~\nตอนนี้คุณเป็นคนดังของมิซากะแล้ว ทุกคนในโรงเรียนกำลังเรียนรู้เรื่องราวอันกล้าหาญของคุณ ทุกสิ่งที่เกี่ยวข้องกับคุณสามารถขายในตลาดมืดในราคาที่สูงลิบ!\nแต่ก็เป็นเรื่องปกติ เพราะใครจะไปลืมว่าคุณคือ「ตำนานที่มีชีวิต」ผู้พิทักษ์เพียงคนเดียวของมิซากะล่ะ?\nในปีนี้มิซากะเกิดเรื่องราวสนุกสนานมากมาย——ออริตาได้เป็นเพื่อนกับขนมขิงหลายตัว, ศาสตราจารย์ดอลล์ทำให้ห้องทดลองสิบเจ็ดห้องระเบิดเพื่อเปลี่ยนลุคของสมอง, คาสเตอร์ถูกอกริปปาหลอกให้ช่วยสอบของเธอ ผลคือมันเป็นวิชาความรู้ทั่วไป คะแนนสุดท้ายแย่กว่าที่เธอสอบเองเสียอีก!\nโอ้ ใช่แล้ว ยังมีหนูตัวน้อยที่น่ารังเกียจ มันขโมยฟิล์มที่มีค่าของฉันไป นั่นคือภาพแมวของ「24」ที่ฉันถ่ายได้อย่างยากลำบาก!\nนอกจากนี้ยังมีอีกมากมาย ฉันได้จัดเรียงมันไว้แล้ว ส่งเป็นฉบับพิเศษปีใหม่ของหนังสือพิมพ์โรงเรียนให้คุณแล้วนะ\nอะไรนะ? คุณสงสัยว่าฉันติดต่อคุณได้ยังไง? เฮเฮ นี่เป็นความลับนะ ฉันจะไม่บอกหรอกว่าฉันใช้ข้อมูลลับมากมายแลกกับคุณนายผู้ที่ดูเหมือนจะจัดการยากคนหนึ่ง!\nในปีใหม่ที่จะถึงนี้ ขอให้เราทำงานหนักร่วมกันนะ สุขสันต์วันปีใหม่, %player%!\n\nฮันนา พีสลี"
  },
  Mail_124793_Name = {
    Text = "ฉบับพิเศษปีใหม่"
  },
  Mail_124793_Sender = {
    Text = "ฮันนา พีสลี"
  },
  Mail_124794_Desc = {
    Text = "ผู้ส่งสารที่ซีดเซียว：\n\nราตรีน้ำค้างเงินกำลังจะมาถึง ขอให้ฉันได้แสดงความปรารถนาดีที่จริงใจที่สุดต่อท่านที่นี่ก่อน\n\nครั้งสุดท้ายที่ฉันไปเยี่ยมเด็ก ๆ ที่บ้านคนจนลิเลียน มีเด็กบางคนแอบถามฉันว่า「ผู้ส่งสารแห่งฤดูหนาวมีจริงไหม?」\nฉันรู้สึกสงสัยว่าทำไมเด็กเหล่านี้ถึงมีความคิดเช่นนี้ ถ้าฉันจำไม่ผิดเมื่อปีที่แล้วเด็กทุกคนควรได้รับของขวัญจาก「ผู้ส่งสารแห่งฤดูหนาว」\nแต่ผลก็คือเด็ก ๆ บอกฉันว่า——「ฉันเห็นผู้ชายหล่อ ๆ คนนั้นมอบของขวัญให้กับคุณแม่ใหญ่ไดอาน่า เขาดูไม่เหมือนผู้ส่งสารแห่งฤดูหนาวเลย!」\nคงเป็นเพราะลอร์ดท่านนั้นมอบของขวัญให้กับบ้านคนจนโดยบังเอิญถูกเด็ก ๆ พบเห็น จึงเกิดความสงสัยเล็กน้อยเหล่านี้ขึ้น\n\nดังนั้นในราตรีน้ำค้างเงินปีนี้ ฉันได้เตรียมชุดเสื้อผ้าผู้ส่งสารแห่งฤดูหนาวแบบดั้งเดิมสองชุด อยากเชิญผู้ส่งสารที่ซีดเซียวท่านมาร่วมแสดงบทบาทเป็นผู้ส่งสารแห่งฤดูหนาวเพื่อมอบของขวัญให้กับเด็ก ๆ\nฉันเชื่อว่าจะต้องมีเด็กคนหนึ่งในคืนที่มืดมิดลืมตาขึ้นมาแอบมองเรา จดจำภาพลักษณ์ในชุดแดงและหมวกแดงของเรา แล้วในเทศกาลการข้ามฤดูหนาวจะตื่นเต้นบอกทุกคนว่า——「ฉันเห็นผู้ส่งสารแห่งฤดูหนาวแล้ว!」\nในขณะเดียวกันฉันยังได้เตรียมของขวัญให้กับท่านโดยเฉพาะ หวังว่าท่านจะชอบ\nสุขสันต์เทศกาลการข้ามฤดูหนาว. \n\nซัลวาดอร์"
  },
  Mail_124794_Name = {
    Text = "ผู้ส่งสารแห่งฤดูหนาว"
