  Mail_124991_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรมทำซ้ำ「การรักษาหลายครั้ง·คลอน」สิ้นสุดแล้ว ขณะนี้จะทำการแลกเปลี่ยนสกุลเงินกิจกรรมที่เหลืออยู่「จิ๊กซอว์ความทรงจำ」ในอัตรา 40 คูปองกุหลาบทองต่อชิ้น กรุณาอย่าลืมตรวจสอบ."
