  Mail_125448_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「เรื่องเก่าแก่ของเมืองทะเล」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「น้ำตาลลูกแพร์」ที่เหลืออยู่ของผู้พิทักษ์ตามอัตราแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 ต่อชิ้น กรุณาอย่าลืมตรวจสอบด้วยนะคะ."
