  Mail_126321_Desc = {
    Text = "เรียน ผู้พิทักษ์:\nกิจกรรม「ผู้ถักทอพันธนาการตน」ได้สิ้นสุดลงแล้ว ขณะนี้「ตั๋วที่นั่งกำมะหยี่」ที่เหลืออยู่ของผู้พิทักษ์จะถูกแปลงในอัตราส่วนทุก 1 ชิ้นแลกเป็น「คูปองทองกุหลาบ」× 40 กรุณาตรวจสอบรับของด้วย"
