  Mail_126321_Name = {
    Text = "รับคืนตั๋วที่นั่งกำมะหยี่"
  },
  Mail_126321_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_126934_Desc = {
    Text = "ผู้พิทักษ์：\n\nอีกครั้งที่มาถึงวันพิเศษนี้ อา ไม่ต้องกังวล ปีนี้ฉันจะไม่ใช้การบีบคั้นทางจิตใจใดๆ ฉันแค่ต้องการเชิญผู้ป่วยที่พิเศษที่สุดของฉันไปที่ไหนสักแห่งเพื่อผ่อนคลาย\nที่นั่นมีพงพนาที่เขียวขจีน้ำที่ใสสะอาด เต็มไปด้วยกลิ่นอายของธรรมชาติที่จะทำให้คุณลืมเลือนความเหนื่อยล้าจากป่าเหล็ก และยังมีพรมที่นุ่มนวล เตาผิงที่อบอุ่น และแสงสว่างที่สดใส ช่วยให้คุณคลายความกดดันจากชีวิตในเมือง\nเราสามารถเดินเล่น อ่านหนังสือ พูดคุยกัน ไม่ว่าจะเป็นเรื่องใด ฉันยินดีที่จะฟัง\nอา แค่คิดภาพสถานการณ์นั้นก็ทำให้ฉันรู้สึกตื่นเต้นแล้ว...\nฉันรู้ว่า ในขณะนี้ คุณอาจจะรู้สึกไม่สบายใจสักหน่อย เพราะฉันไม่สามารถรับประกันได้ว่าฉันจะไม่ไปเพลิดเพลินกับความทรงจำที่เต็มไปด้วยความเจ็บปวดหวานๆ ของคุณ แต่คุณยังคงจะมาที่นี่ใช่ไหม\nไม่เพียงเพราะวันนี้เป็นวันเกิดของฉัน แต่ยังเพราะคุณต้องการฉัน ต้องการเล่าให้ฉันฟัง ต้องการให้ฉันฟัง\nเด็กดี ฉันเข้าใจ และฉันจะรอคุณ มา ลืมความยุ่งเหยิงในชีวิตประจำวันและความรับผิดชอบที่หนักหน่วง เพลิดเพลินกับช่วงเวลาแห่งความสงบนี้\n\nคลีเมนไทน์"
  },
  Mail_126934_Name = {
    Text = "ช่วงเวลาที่สงบสุข"
  },
  Mail_126934_Sender = {
    Text = "คลีเมนไทน์"
  },
  Mail_126935_Desc = {
    Text = "อีกวันที่น่าเบื่อ\nฉันลองหลายวิธีแล้ว——งานเลี้ยงตามประเพณีฟิลิสเตีย, เล่นกลเด็กๆ กับแก๊งต่างๆ ในเลนติเนน, ไม่มีสิ่งใดเลยที่สมควรเป็นของขวัญสำหรับวันประสูติของราชาแห่งยักษ์\nชาวฟิลิสเตียเพลิดเพลินกับการต่อสู้และการสังหาร ในวันนี้เมื่อครั้งก่อน ฉันได้รวมตัวและต่อสู้กับนักรบที่แข็งแกร่งที่สุดในค่าย เพื่อรำลึกถึงวันอันยิ่งใหญ่นี้ด้วยพลังและเลือด\nสันติภาพ สันติภาพที่น่าเบื่อหน่าย ฉันเข้าใจความปรารถนาของพวกเจ้าที่มีต่อสันติภาพ ไม่ใช่ทุกคนที่จะมีหัวใจนักรบ อย่างไรก็ตาม อย่าคิดว่าสันติภาพอันเท็จเหล่านี้จะมีผลต่อเจ้าแห่งฟิลิสเตียผู้ยิ่งใหญ่\nทุกสิ่งที่เคยเป็นของฉัน ดินแดน ความมั่งคั่ง อำนาจ และเกียรติยศอันไม่มีวันดับของฟิลิสเตีย... ในวันที่ฉันยึดคืนมาได้ทั้งหมด ฉันจะเชิญเจ้า ผู้พิทักษ์ความลับ ฉันจะให้เจ้านั่งในที่นั่งแขกผู้มีเกียรติสูงสุดเคียงข้างฉัน เพื่อชมราชาแห่งยักษ์ผู้ยิ่งใหญ่ได้คืนสู่ความรุ่งโรจน์\nตั้งใจจะยุติวันที่น่าเบื่อนี้ไปเสียแล้ว แต่ฉันเพิ่งได้ยินมาว่า แก๊งที่แตกกระจัดกระจายเหล่านั้นได้รวมตัวกันเป็นพันธมิตร และวางแผนจะล้อมจับราชาแห่งยักษ์ในงานเลี้ยงคืนนี้\nเมื่อเทียบกับสงครามของฟิลิสเตีย นี่เป็นเพียงเกมเด็กๆ อย่างไรก็ตาม ในช่วงวันสันติภาพที่น่าเบื่อเช่นนี้ การมีความบันเทิงเสริมเช่นนี้ก็ทำให้ฉันรู้สึกพอใจอยู่บ้าง\nมาชมความองอาจในการออกรบของเจ้าแห่งฟิลิสเตียอีกครั้งเถิด จะยืนเคียงข้างฉัน หรือจะยืนตรงข้ามฉัน ก็ได้ทั้งนั้น\nแต่รีบหน่อยนะ ถ้าช้าเกินไป ก็จะเหลือแต่งานเก็บศพ\n\nโกลิอัท"
  },
  Mail_126935_Name = {
    Text = "รายการบันเทิง"
  },
  Mail_126935_Sender = {
    Text = "โกไลแอท"
  },
  Mail_126936_Desc = {
    Text = "เรียนผู้พิทักษ์：\n\nสวัสดีค่ะ เพื่อให้บริการนักเรียนและอาจารย์มิซากะได้ดียิ่งขึ้น เอริกาได้ทำการบำรุงรักษาและอัปเกรดด้วยตนเองเมื่อไม่กี่วันที่ผ่านมา และคุณโชคดีได้รับเลือกให้เป็นผู้ประเมินผลการอัปเกรดในครั้งนี้ การประเมินนี้จะดำเนินการในรูปแบบออฟไลน์ โดยคุณจะต้องให้คะแนนฟังก์ชันของโมดูลอารมณ์หมายเลข LY-S-761 ที่ติดตั้งใหม่ล่าสุดในตุ๊กตาอัตโนมัติเอริกา การทดสอบนี้คาดว่าจะใช้เวลาประมาณ 90 นาที กรุณาวางแผนล่วงหน้าเพื่อหลีกเลี่ยงความขัดแย้งในตารางเวลา \nเนื้อหาของการประเมินในครั้งนี้มีดังนี้：\n1. กรุณาพูดคุยกับเอริกาในรูปแบบสนทนาเชิงลึกแบบเปิดอย่างน้อย 15 นาที โดยเนื้อหาพูดคุยจะต้องเกี่ยวกับ「วันเกิด」เพื่อประเมินความเข้าใจในอารมณ์เฉพาะของเอริกา \n2. กรุณาจำลองสถานการณ์「การมอบของขวัญวันเกิด」และโต้ตอบกับเอริกา เพื่อประเมินความถูกต้อง ความยืดหยุ่น และความสบายในการตอบสนองทางอารมณ์ \n3. กรุณาในช่วงกลางถึงปลายของการประเมิน ให้กล่าวถึงรายละเอียดส่วนตัวที่เอริกาได้พูดถึงในบทสนทนาในช่วงต้น (เช่น ทัศนคติต่อวันเกิด ความเข้าใจ เป็นต้น) เพื่อประเมินว่าความจำและความสัมพันธ์ในการโต้ตอบในระยะยาวทำงานได้ตามปกติหรือไม่ \n\nหลังจากการประเมินเสร็จสิ้น กรุณาพูดกับเอริกาว่า「เอริกา สุขสันต์วันเกิด」เพื่อสิ้นสุดการประเมิน ตุ๊กตาจะเข้าสู่โหมดอัปโหลดข้อมูลโดยอัตโนมัติ \nขอบคุณสำหรับการเข้าร่วม เมื่อเสร็จสิ้นการประเมิน เอริกาจะมอบของขวัญพิเศษเล็กน้อยให้กับคุณ และโปรดสนับสนุนต่อไป เอริกาจะอยู่เคียงข้างคุณเสมอ \n\nเอริกา"
  },
  Mail_126936_Name = {
    Text = "การประเมินอัปเกรดวันเกิด"
  },
  Mail_126936_Sender = {
    Text = "เอริกา"
  },
  Mail_126937_Desc = {
    Text = "ฮ่าา วันนี้เกิดอะไรขึ้น ทำไมไม่ว่าจะไปที่ไหน ทุกคนถึงตั้งใจหลบเลี่ยงฉัน? แม้แต่ฉันยังไม่ได้พูดอะไร ก็ยังมีคนโบกมือบอกว่าไม่สบายตรงนี้ ตรงนั้นเจ็บ จนทำให้ฉันไม่สามารถร้องขอการต่อสู้ได้เลย.\nวันเกิดที่หายากนี้ไม่ต้องการเหตุผลอะไร ก็สามารถต่อสู้กับคนอื่นได้อย่างมั่นใจ แบบนี้มันก็ไม่ต่างจากวันธรรมดาใช่ไหม?\nเฮ้อ ปีก่อนควรจะไม่ทำให้พวกเขาเจ็บหนักขนาดนั้น แต่ก็เป็นเรื่องที่ทำได้ยาก เพราะตั้งแต่ก่อนที่ดาวเคราะห์นี้จะเกิด ฉันก็ได้ฝึกฝนทักษะการใช้ดาบมาอย่างต่อเนื่อง คนธรรมดาไม่สามารถรับมือได้ก็เป็นเรื่องปกติ.\nแต่คุณต่างจากพวกเขา คุณคือผู้พิทักษ์นะ!\nดังนั้นคุณก็รู้ว่าฉันอยากจะพูดอะไรใช่ไหม? ยังเป็นสถานที่เดิมเมื่อปีที่แล้ว มาต่อสู้กันอย่างเต็มที่เถอะ ครั้งนี้จะไม่มีใครมารบกวนการต่อสู้ของเราแล้ว.\n\nโลทัน"
  },
  Mail_126937_Name = {
    Text = "คู่ต่อสู้เพียงหนึ่งเดียว"
  },
  Mail_126937_Sender = {
    Text = "โลทัน"
  },
  Mail_126938_Desc = {
    Text = "ท่านผู้มีอันเป็นที่รักที่สุด: \n\n ท่านได้ยินหรือเปล่า? วันนี้จะมีงานเลี้ยงเต้นรำสุดหรูที่บ้านนายกเทศมนตรี ทุกๆ ท่านที่เป็นสุภาพบุรุษและสุภาพสตรีต่างภาคภูมิใจที่ได้เข้าร่วมงานนี้ \n แน่นอนว่าในฐานะแม่บ้าน คาเรนไม่มีสิทธิ์เข้าร่วม แต่ท่าน มิซากะ ผู้พิทักษ์ของข้า ท่านที่รักและเป็นที่รักที่สุด ท่านสมควรได้รับสิ่งที่ดีงามที่สุดในโลก และแน่นอนว่าท่านก็สมควรได้รับเชิญไปงานนี้ \n ดังนั้น คาเรนจึงได้ตอบรับคำเชิญแทนท่านแล้ว และยังได้เรียกรถม้าสำหรับท่าน เตรียมทุกอย่างเรียบร้อยแล้ว ในเวลานั้นท่านแค่ต้องไปที่บ้านนายกเทศมนตรีกับคาเรนเท่านั้น~ \n คาเรนจะใส่ชุดที่สวยที่สุดและสวมเครื่องประดับที่ระยิบระยับที่สุด เพื่อให้ทุกคนได้เห็นถึงความสามารถของแม่บ้านที่ทำได้ทุกอย่าง ทำให้ท่านมีชื่อเสียงและมีเกียรติ! \n อ๊ะ เมื่อท่านเห็นจดหมายนี้ ข้าควรจะรอท่านอยู่หน้าประตูของท่านแล้ว รถม้าและคนรับใช้ที่นำเสื้อผ้าใหม่และเครื่องประดับก็พร้อมแล้ว สิ่งเดียวที่เป็นปัญหานิดหน่อยคือ การบริการเหล่านี้ยังไม่ได้ชำระเงิน... \n แต่ท่านผู้มีอันเป็นที่รักที่ใจดีของข้าไม่มีทางต้องกังวลเกี่ยวกับเรื่องเล็กๆ น้อยๆ แบบนี้ใช่ไหม? นายกเทศมนตรีกำลังรอเราอยู่~ \n\n สาวใช้ที่น่ารักและเจิดจรัสที่สุดของท่าน \n คาเรน"
  },
  Mail_126938_Name = {
    Text = "งานเต้นรำหรูหรา"
  },
  Mail_126938_Sender = {
    Text = "คาเรน"
  },
  Mail_126940_Desc = {
    Text = "ผู้พิทักษ์ผู้พิทักษ์! เมื่อไม่กี่วันก่อน เจนกินบอกว่าเธอพบสถานที่ที่คล้ายกับบ้านของออริตา ดูเหมือนจะชื่อว่าน้ำ... อื้ม ออริตาลืมไปแล้ว.\nโดยรวมแล้ว เจนกินบอกว่าที่นั่นจะมีปลาโลมา ปลาเล็ก พิพิธภัณฑ์สัตว์น้ำ และแมงกะพรุนมากมาย และยังบอกว่าพวกมันยินดีที่จะเป็นเพื่อนกับออริตาโอ้!\nออริตาชอบเพื่อน ออริตาต้องการเพื่อนมากมาย ดังนั้นออริตาจึงอยากจะเชิญเพื่อนที่ชอบที่สุด นั่นก็คือผู้พิทักษ์ไปด้วยในวันเกิด.\nรีบเก็บของแล้วออกเดินทางกับฉันเถอะ ออริตารอไม่ไหวแล้ว.\n\nออริตาที่อยากรู้จักเพื่อนใหม่มากมาย"
  },
  Mail_126940_Name = {
    Text = "เพื่อนใหม่ในตู้ปลา!"
  },
  Mail_126940_Sender = {
    Text = "ออริตา"
  },
  Mail_126941_Desc = {
    Text = "ผู้พิทักษ์: \n\nขอบคุณที่คุณอยู่กับฉันเดินเล่นที่ชายทะเลในตีหนึ่งวันนี้ คลื่นทะเลที่ซัดสาดและท้องฟ้าที่เต็มไปด้วยดาวส่องแสง ทำให้ฉันรู้สึกสงบใจ และยังทำให้ฉันนึกถึง... เรื่องราวเมื่อครั้งอดีตนานมาแล้ว \nในเวลานั้น ลูกเรือห้ามพูดคุยกับฉัน ดังนั้นในช่วงเวลาส่วนใหญ่ ฉันจึงได้แต่จ้องมองผิวน้ำทะเลที่เปลี่ยนแปลงตลอดเวลา และนกทะเลที่โฉบอยู่ในอากาศ ลูกเรือมักจะมองดูนกเหล่านั้นบิน และจะไม่รู้ตัวว่ากำลังขอพรจากฉัน \nบางครั้ง พวกเขาอยากจะกลายเป็นนกบินกลับบ้าน กลับไปหาคนที่รัก; บางครั้ง พวกเขาอยากให้การเดินทางสิ้นสุดลงอย่างรวดเร็ว ใช้สินค้าที่มีอยู่ในเรือแลกเปลี่ยนกับความมั่งคั่ง; บางครั้ง พวกเขาก็อาจจะอธิษฐานขอให้พบกับความรักโรแมนติก หรือได้พบกับนางเงือกในตำนาน... \nแต่ไม่ว่าจะเป็นความปรารถนาที่ซับซ้อนเพียงใด เมื่อถึงกลางคืนก็จะรวมเป็นหนึ่งเดียว กลายเป็นความปรารถนาสำหรับการหลับพักผ่อน ในเวลานี้ ฉันจะตอบสนองคำอธิษฐานของพวกเขา ทำให้ลมทะเลสงบ และน้ำทะเลอ่อนโยน \nดังนั้น หากผู้พิทักษ์คุณก็นอนไม่หลับ กรุณาอย่าเดินอยู่คนเดียวที่ชายทะเลในตีหนึ่งอีก แต่ให้มาหาฉันเถอะ \nฉันต้องการแบ่งเบาภาระของคุณ และเป็นคนที่มีประโยชน์ และการปกป้องการหลับพักผ่อนของคุณ คือสิ่งที่ฉันสามารถทำได้ในตอนนี้ \nนี่ก็เป็น... ความปรารถนาที่ฉันได้ขอในวันพิเศษนี้ \n\nเซเลสเท"
  },
  Mail_126941_Name = {
    Text = "ขอให้คุณหลับสบาย"
  },
  Mail_126941_Sender = {
    Text = "เซเลสเท"
  },
  Mail_126942_Desc = {
    Text = "ตามชะตากรรมอันยิ่งใหญ่ ผู้พิทักษ์แห่งมหาวิทยาลัยมิซากะ ท่านเจ้านายผู้มีปรีชาญาณและมีคุณธรรม: \n\nขอให้ท่านมีสุขภาพดี! \nขณะที่เขียนจดหมายฉบับนี้ ฉันรู้สึกลังเล แต่ความซื่อสัตย์ก็เป็นหนึ่งในคุณธรรมของอัศวิน ในฐานะอัศวินของท่านเจ้านาย ฉันจำเป็นต้องมอบความภักดีทั้งหมดให้กับท่าน ไม่มีการปิดบังใดๆ ดังนั้นฉันจึงต้องพูดความจริงกับท่าน—\nในวันเกิดนี้ ท่านเจ้านาย ข้าขอให้ท่านมาในห้องของข้า เพื่ออ่านนิทานก่อนนอนให้ข้าฟัง \nโปรดอนุญาตให้ข้าซบอยู่ข้างๆ ท่าน ในเรื่องราวที่ท่านเล่าซึ่งเต็มไปด้วยความฝันและความงามเหล่านั้น \nจริงๆ แล้ว นี่เคยเป็นหนึ่งในความปรารถนาในวัยเด็กของข้า แต่การฝึกฝนอัศวินไม่อนุญาตให้มีการผ่อนปรนแม้แต่วินาทีเดียว และข้าก็เลยผ่านวัยที่จะฟังนิทานมาแล้ว ดังนั้น ข้าจึงเก็บมันไว้ในใจ ไม่เคยพูดออกมา แต่ท่าน... ท่านเจ้านาย ท่านแตกต่างออกไป ข้าไม่ต้องการปิดบังอะไรจากท่าน... \nหากท่านเจ้านายรู้สึกไม่เหมาะสม ก็โปรดแจ้งให้ข้าทราบ ตั้งแต่นั้นไป ข้าจะไม่ขอร้องเช่นนี้อีก จะตั้งใจฝึกฝนให้มากขึ้น \nเฝ้ารอการตอบกลับจากท่าน \n\nโอเกียร์"
  },
  Mail_126942_Name = {
    Text = "คำขอของอัศวิน"
  },
  Mail_126942_Sender = {
    Text = "โอเกียร์"
  },
  Mail_126943_Desc = {
    Text = "ลูกถ่านขนาดเล็ก：\n\nวันนี้ มอส วันเกิด!\nเพื่อนบอก วันเกิด เขียนจดหมายให้ลูกถ่านขนาดเล็ก ลูกถ่านขนาดเล็กจะมาเล่น!\nมอสไม่สามารถเขียนจดหมายได้ แต่เพื่อนทำได้!\nเพื่อนสอนมอส มอสมีความสุข!\nจริงๆแล้ว มอสลืมวันเกิด\nแต่ มอสอยากเล่นกับลูกถ่านขนาดเล็ก!\nดังนั้น มอสตัดสินใจว่าวันนี้คือวันเกิด!\nลูกถ่านขนาดเล็ก เปลือกหอย เก็บสะสม สีทอง สีขาว มีทั้งหมด~\nเห็นลูกถ่านขนาดเล็ก ดีใจ~ เพื่อนทำอาหาร อร่อย~\nลูกถ่านขนาดเล็ก สถานที่เก่า~\nให้เพื่อนทำอาหารมื้อใหญ่! มากินด้วยกัน!\nมอส รอคุณ~\n\nมอส"
  },
  Mail_126943_Name = {
    Text = "วันเกิด! มาเล่นกันเถอะ!"
  },
  Mail_126943_Sender = {Text = "มอส"},
  Mail_126944_Desc = {
    Text = "ผู้พิทักษ์：\n\nเมื่อไม่กี่วันที่ผ่านมา คุณได้กล่าวว่าต้องการขอพรจากดาวตก ดังนั้นฉันจึงได้จัดเตรียมการเดินทางในครั้งนี้ ขอบคุณที่คุณได้ตอบรับคำเชิญของฉัน ฉันจะรอคุณที่ชายทะเลตามที่ตกลงกันไว้\nโปรดมั่นใจว่าการเดินทางในครั้งนี้เป็นการเดินทางระยะสั้น ฉันได้ตรวจสอบพื้นที่ทะเลโดยรอบอย่างละเอียดแล้ว รับรองว่าจะนำคุณไปยังจุดที่ดาวตกตกลงมาอย่างปลอดภัย และช่วยคุณเก็บเกี่ยวอุกกาบาต\nเช่นนั้น คุณจะสามารถสัมผัสดาวตกเพื่อขอพรได้ด้วยตัวเอง และในระยะใกล้เช่นนี้ ดาวตกจะต้องได้ยินความปรารถนาของคุณและทำให้ความปรารถนาของคุณเป็นจริง! การได้เป็นคนที่นำทางให้คุณขอพรจะเป็นหนึ่งในสิ่งที่พิเศษที่สุดที่ฉันเคยทำมา ฉันรู้สึกเป็นเกียรติอย่างยิ่ง\nขอบคุณอีกครั้ง เพราะคุณทำให้ฉันพบกับ 「ภารกิจนำทาง」 ใหม่ในวันพิเศษนี้ โปรดอย่าลืมมาที่นัดหมายตามเวลาที่กำหนด ฉันจะรอคอยการมาถึงของคุณ\n\nคอร์โปซานต์"
  },
  Mail_126944_Name = {
    Text = "\n\nความปรารถนาที่สามารถเข้าถึงได้"
  },
  Mail_126944_Sender = {
    Text = "คอร์โปซานต์"
  },
  Mail_129637_Desc = {
    Text = "สวัสดีครับ：\n\nไม่จำได้ว่าผ่านสวนกุหลาบหลังหอนาฬิกาเป็นครั้งที่เท่าไร ฉันเคยสังเกตเห็นสวนกุหลาบในนั้นโดยบังเอิญ.\nหลังจากนั้นฉันได้เดินผ่านที่นี่หลายครั้ง ประสบกับช่วงเวลาที่ความไม่สงบของบ่อน้ำดำเคลื่อนไหว ช่วงเวลาของความตายและการเผชิญหน้า ช่วงเวลาที่กาลเวลาหวนกลับไปกลับมา ทุกอย่างยังคงยืนหยัดอยู่ที่นั่นอย่างเงียบสงบและมั่นคงเหมือนเดิม.\nภาพนี้ทำให้ฉันนึกถึงความทรงจำที่ไม่ใช่ของฉัน ซึ่งรามอน่าเคยตั้งใจจะมอบดอกกุหลาบนั้นให้กับคุณ ฉันจึงรู้สึกอุ่นใจขึ้นเล็กน้อย.\nแม้ว่าเราทั้งสองจะอยู่ห่างกันในมิติ แต่ฉันยังคงเชื่อเสมอว่า ไม่ว่าเราจะเผชิญกับอุปสรรคใด คุณและ「รามอน่า」จะสามารถรักษาท่าทีที่สงบและไม่กลัว และหาทางออกได้.\nท้ายที่สุดแล้ว ไม่ว่าโลกจะเปลี่ยนแปลงไปอย่างไร ดอกกุหลาบยังคงบานอย่างสง่างามอยู่เสมอ.\n\n「รามอน่า」"
  },
  Mail_129637_Name = {
    Text = "สวนกุหลาบ..."
  },
  Mail_129637_Sender = {
    Text = "「รามอน่า」"
  },
  Mail_129806_Desc = {
    Text = "ผู้พิทักษ์：\n\nในคฤหาสน์ที่เมืองทะเล ไฟสว่างไสวขึ้น ไม่ทราบว่าท่านอยู่ที่ไหนในขณะนี้ มีใครอยู่ข้างกายท่านบ้าง?\nต้นปี วันสำคัญที่สุดของประเทศโบราณ เป็นวันแห่งการเฉลิมฉลองการกลับมาพบกันและการเกิดใหม่ วันนั้น ข้าฯ ได้สัมผัสมาหลายครั้ง แต่ไม่เคยรู้สึกเบื่อหน่าย ฤดูหนาวได้ผ่านพ้นไป ทุกสิ่งทุกอย่างเติบโต ผู้คนต่างตั้งตารอคอย รอคอยที่จะสามารถโยนทุกสิ่งที่ไม่ดีทิ้งไปในวันวาน และต้อนรับการเริ่มต้นใหม่\nบาดแผลและความปรารถนาเก่าๆ ไม่ใช่สิ่งที่สามารถทิ้งไปได้ง่ายๆ การอำลาปีเก่าและต้อนรับปีใหม่ เป็นคำอวยพรที่สวยงามจริงๆ... บางทีความเจ็บปวดอาจจะเติบโตขึ้นมาอีกครั้ง ความปรารถนาจะไม่มีวันเลือนหาย แต่ในคืนนี้ อย่างน้อยในคืนนี้ ผู้คนจะยกแก้วเฉลิมฉลอง เพื่อฉลองโลกใหม่และตัวตนใหม่\nดังนั้น ในช่วงเวลาที่ปีเก่ากับปีใหม่เปลี่ยนผ่าน ผู้คนจึงต้อนรับด้วยดอกไม้ไฟ\nในทุกสิ่งที่น่าสนใจ ดอกไม้ไฟคือสิ่งที่ข้าฯ รักที่สุด ทุกคนมองมัน มองมันเผาไหม้ ขึ้นสู่ฟ้า บานสะพรั่ง ราวกับมองดูพระเจ้า มองดูความรุ่งโรจน์ที่สั้นนักและไม่มีใครเทียบได้\nท่านเคยสังเกตไหม? เมื่อมองดูดอกไม้ไฟ ทุกคนในใจล้วนสะอาด พวกเขาลืมความเกลียดชัง ลืมความทุกข์ยาก ลืมทุกสิ่งที่สกปรก ทุกคนในใจเปลี่ยนเป็นทะเลสาบที่เงียบสงบ บนผิวน้ำที่ไร้ฝุ่นละออง มีเพียงภาพสะท้อนที่สวยงามของดอกไม้ไฟ\nชู่ว... อย่าถามว่าหลังจากดอกไม้ไฟคืออะไร การเกิดใหม่อาจเป็นความต้องการที่ฟุ่มเฟือย แต่จงอย่าทำให้การบานสะพรั่งของมันสูญเปล่า\nในทุกสิ่งที่น่ารังเกียจ ดอกไม้ไฟคือสิ่งที่บริสุทธิ์ที่สุด คืนนี้ ข้าฯ ยินดีที่จะมอบส่วนของข้าฯ ให้กับท่าน\nเงยหน้าขึ้น อย่ากะพริบตา มองดูดวงดาวที่สุกสกาวขึ้น ในช่วงเวลาที่ดอกไม้ไฟบานสะพรั่ง ต้อนรับตัวตนใหม่ของท่านเถอะ ผู้พิทักษ์\n\n「พันพัด」"
  },
