  Mail_129806_Sender = {Text = "ซู่"},
  Mail_130223_Desc = {
    Text = "เรียน ผู้พิทักษ์ที่เคารพ：\n กิจกรรม「อุบัติใหม่ในโลกที่บิดเบือน」สิ้นสุดแล้ว, ขณะนี้จะทำการแปลง「เกล็ดผีเสื้อสีขาวบริสุทธิ์」,「เกล็ดผีเสื้อสีแดง」,「เกล็ดผีเสื้อเรืองแสง」ที่เหลืออยู่ของผู้พิทักษ์ในอัตราการแลกเปลี่ยน คูปองกุหลาบทอง × 40 ต่อชิ้น, กรุณาอย่าลืมตรวจรับด้วยนะคะ."
