  Mail_131005_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「เสียงเพรียกของเมอร์สคัส」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「หอยสังข์หมายเลขหนึ่ง」,     「หอยสังข์หมายเลขสอง」,     「หอยสังข์หมายเลขสาม」ที่เหลืออยู่ตามอัตราแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 ต่อหนึ่งชิ้น กรุณาจำไว้และตรวจสอบการรับด้วยนะครับ."
