  Mail_131093_Desc = {
    Text = "เรียน ผู้พิทักษ์：\nกิจกรรม「งานฉลองไฟลุกไหม้·คลอน」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「กระดูกน่องต้น」,     「หอยแอมโมไนต์ใบกลม」และ「ซากปรักหักพังเกลียว」ที่เหลือของผู้พิทักษ์ตามอัตราการแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 กรุณาตรวจสอบให้ดี."
  },
  Mail_131093_Name = {
    Text = "การแลกเปลี่ยนสกุลเงินงานเลี้ยงเพลิง"
  },
  Mail_131093_Sender = {
