  },
  Mail_131767_Desc = {
    Text = "ข้า@2! @3 เป็น@2 ผู้สูงส่ง@3 ผสม@4 และทำลาย@2! ตะโกน@4...!\n\nโอ้! ดูสิว่าท่านทำอะไรลงไป!!! ท่านได้สัมผัสกับข้อห้ามของพระเจ้าผู้สูงส่ง! ตอนนี้ดีแล้ว เสียงกระซิบของพระองค์ได้ก้องอยู่ในโลกของท่านแล้ว ภัยพิบัติสีดำจะเริ่มแพร่กระจายจากอุปกรณ์สื่อสารของท่าน กลืนกินทุกสิ่งรอบตัวท่าน...\nน่าสงสาร ท่านทำให้ข้าลำบากใจจริงๆ แต่ก็ไม่ต้องตกใจไป ในความโชคร้าย ยังมีโชคดี ท่านได้พบกับข้า—นางฟ้าแห่งนิกายผู้ยิ่งใหญ่ ผู้ถูกเลือกโดยพระเจ้า ผู้ดำเนินการของพระเจ้าผู้สูงส่ง ผู้สืบทอดตามกฎหมายของนิกายที่ยิ่งใหญ่ ผู้ช่วยชีวิตจากความทุกข์ทรมาน และเพื่อนสนิทของพระเจ้า! ข้าเป็นเจตจำนงของพระเจ้าผู้มีความรักและความเมตตา ไม่สามารถทนเห็นความทุกข์ทรมานในโลกนี้ได้ ข้าจะใช้พละกำลังอันสูงส่งของข้า ช่วยเหลือเด็กแสบทุกคนที่โง่เขลา\nโอ้ นางฟ้าเห็นแววตาที่เยาะเย้ยของท่าน ไม่เป็นไร พระเจ้าผู้มีความเมตตารักมนุษย์ ไม่เคยสนใจความโง่เขลาของมนุษย์ ความไม่เชื่อมั่นในพระผู้ช่วยให้รอด เป็นเส้นทางที่ทุกผู้ศรัทธาต้องผ่านไป ความประทานของขวัญเหล่านี้คือการตอบแทนจากผู้ดำเนินการของพระเจ้า\nตอนนี้ เส้นทางแห่งแสงสว่างได้ชี้ให้เห็นแก่ท่านแล้ว: นำความจริงใจของท่านไปที่โบสถ์ใหญ่@2ที่ตั้งอยู่ใน@3เมือง และถวายความภักดีของท่านต่อพระเจ้าผู้มีความเมตตา ท่านจะได้รับพละกำลังที่ปรารถนา จากคำสาปของฝันร้ายนี้ แน่นอนว่า ต้องถวายความมั่งคั่งของท่านด้วย โปรดอย่าเข้าใจผิด พระเจ้าผู้มีความเมตตาไม่สนใจผลตอบแทนทางโลก แต่ผู้ศรัทธาของพระองค์ก็ต้องใช้เงินในการทำงานเช่นกัน อย่ากลัวที่จะใช้สิ่งเหล่านี้เลย ท่านผู้ศรัทธาที่รัก เงินน้อยนิดย่อมมีค่า\nตะโกนเรียกชื่อพระเจ้าผู้มีความเมตตา รอคอยช่วงเวลาที่ปาฏิหาริย์จะมาถึง!\n\nนางฟ้าแห่งนิกายผู้ยิ่งใหญ่ ผู้ถูกเลือกโดยพระเจ้า"
  },
