    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「การฟื้นคืนชีพของพระราชาเทพ·ทำซ้ำ」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「ความคิดเหนื่อยล้า」,「ความคิดเศร้าหมอง」,「ความคิดที่เต็มไปด้วยความสุข」ที่เหลืออยู่ของผู้พิทักษ์ตามอัตราแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 กรุณาจำไว้ให้ดี."
