  Mail_132458_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ:\n        ขอบคุณสำหรับการสนับสนุนและการรับรองใน《คืนแห่งการลืมเลือน》เพื่อให้ผู้พิทักษ์ที่มหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดียิ่งขึ้นเราขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณเรามี「เงินใจ」× 200 เป็นรางวัลเมื่อกรอกแบบสอบถามเสร็จสิ้นสามารถรับได้แบบสอบถามจะปิดในวันที่ 17 สิงหาคม เวลา 9:00 น. กรุณาให้ความสนใจในการกรอกให้ทันเวลา.\n        <SurveyLink:【คลิกเพื่อไปกรอก】>\n        เราจะฟังความคิดเห็นของผู้พิทักษ์ทุกคนอย่างจริงจังและข้อเสนอแนะของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อย ๆ !\n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
