  Mail_133704_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\nเวอร์ชัน{s1}ใกล้จะสิ้นสุดแล้ว กรุณาใช้「แกนแห่งมายา」ที่เหลืออยู่ให้ทันเวลา หลังจากหลักสูตรประจำเทอมในรอบนี้สิ้นสุดลง「แกนแห่งมายา」ที่เหลือจะถูกแปลงเป็น「แกนบริสุทธิ์」× 1 ในอัตราส่วน 1 ต่อ 1"
