  Mail_134024_Desc = {
    Text = "เรียน ผู้พิทักษ์:\n「การฝึกซ้อมรายวัน」ได้ถูกนำออกแล้ว ขณะนี้「บัตรรับรองตัวแทน」ที่เหลืออยู่ของผู้พิทักษ์จะถูกแปลงในอัตราส่วนทุก 1 ชิ้นแลกเป็น「คูปองทองกุหลาบ」× 10000 กรุณาตรวจสอบรับของด้วย"
  },
  Mail_134024_Name = {
