  },
  Mail_134067_Desc = {
    Text = "ผู้พิทักษ์ความลับ:\n\nวันนี้มีเรื่องพิเศษอยากปรึกษาด้วย\nฉันอยากเดินเล่นตามถนนเฉยๆ ดูของสนุกๆ ทั่วไปแบบธรรมดาๆ เดินไปเรื่อยตามใจชอบ ใช้เวลาสักวันแบบปกติ\n\nแล้วก็ ฉันไปถามฝ่ายวิชาการมา ปรากฏว่าเขาบอกว่า ด้วยเหตุผลด้านความปลอดภัย จะออกนอกโรงเรียนได้ก็ต่อเมื่อมีเธอไปด้วยเท่านั้น\nแถมยังบอกว่าอย่าไปทำให้คนอื่นตกใจ แล้วก็อย่าไปเอาอะไรใส่ปากมั่วๆ ข้างนอก ไม่สุภาพจริงๆ นะ\nก็ประมาณนี้แหละ สรุปคือออกไปเดินเล่นกันได้ไหม? ไปด้วยกันทุกคนนะ\n\n...ไม่รู้ทำไมถึงนึกขึ้นมาว่า เมล็ดแพงพวยน่ะ\nสักวันหนึ่งจะโบยบินไปตามสายลม ออกเดินทางสู่ดินแดนแห่งโชคชะตาของตัวเอง\nอาจจะเป็นพรุ่งนี้ หรืออาจจะเป็นอีกนานแสนนาน\nพอคิดไปคิดมา ก็รู้สึกว่าถ้าได้ทำอะไรหลายๆ อย่างกับทุกคนตอนนี้ ก็ดีเหมือนกันนะ\n\nสรุปก็คือ ฉันรออยู่หน้าหอพักนะ ฝากด้วยนะ!\n\nซายะ"
  },
  Mail_134067_Name = {
    Text = "เดินเล่น..."
  },
  Mail_134067_Sender = {
    Text = "ซายะ"
  },
  Mail_134068_Desc = {
    Text = "ผู้พิทักษ์:\n\nฉันรู้สึกว่า วันนี้เป็นวันที่พิเศษ แต่เค้าโครงของความทรงจำ ก็ยังคงเลือนลางอยู่เช่นเดิม\nมีเพียงชื่อ「ซายะ」เท่านั้น ที่พอจะยึดโยงฉันไว้กับสถานที่แห่งนี้\n\nความรู้สึกนั้นไม่ใช่ความเหงา ไม่ใช่ความเศร้า ไม่ใช่อารมณ์ที่ชัดเจนขนาดนั้น\nถ้าจะต้องตั้งชื่อให้กับความรู้สึกนี้สักชื่อ...คงจะเป็น「ความว่างเปล่า」สินะ\nไม่มีอะไรเลย ใสกระจ่างไม่มีที่สิ้นสุด ห้วงเวลาอันเงียบสงบ\n\nหากวันหนึ่ง เมล็ดแดนดิไลออนที่ล่องลอยไปตามสายลม\nร่วงหล่นลงอย่างขาวบริสุทธิ์ เงียบสงัด ในทุกมุมของโลกใบนี้...\nเมื่อนั้น ฉันอาจจะรู้สึกได้ในที่สุดว่า โลกใบนี้เป็นสิ่ง\"พิเศษ\"\n\nเมื่อนั้น หมอกสีเทาที่ปกคลุมลอนดิเนียม เมฆสีแดงเพลิงยามอาทิตย์อัสดง และท้องฟ้าที่เธอมักเงยหน้ามองจากลานโรงเรียน ทั้งหมดจะถูกปกคลุมด้วยดอกแดนดิไลออน กลายเป็นสีขาวบริสุทธิ์ กลายเป็นสีที่เป็นของฉัน\n\nดังนั้น...หากเธอยินดีจะมอบอะไรสักอย่างให้ฉัน\nไม่จำเป็นต้องเป็นของขวัญ เพียงแค่\"ความทรงจำ\"สักชิ้นก็พอ\n\nฉัน อยู่ในโลกสีขาวบริสุทธิ์ที่ดอกแดนดิไลออนบานสะพรั่ง\nเพียงแค่เงียบๆ รอคอยช่วงเวลานั้นมาถึง\n\nเมื่อวันหนึ่งเธอเงยหน้ามองท้องฟ้าที่จัตุรัสมิซาเกะอีกครั้ง\nได้โปรดให้ปุยขนสีขาวที่ลอยผ่านขอบสายตา\nซ้อนทับกับเงาร่างของฉันที่เคยพูดคุยกับเธอ สักเล็กน้อยเถอะนะ\n\nซายะ"
  },
  Mail_134068_Name = {
    Text = "คำสัญญาของดอกแดนดิไลออน..."
  },
  Mail_134068_Sender = {
    Text = "ซายะ"
  },
  Mail_139809_Desc = {
    Text = "ผู้พิทักษ์ความลับที่เคารพ:\n        ขอบคุณสำหรับการสนับสนุนและการยอมรับ《Forgotten Eve》ของคุณ เพื่อให้ผู้พิทักษ์ความลับมีประสบการณ์การเล่นเกมที่ดียิ่งขึ้นในมหาวิทยาลัยมิซาก เราขอเชิญคุณกรอกแบบสอบถามสำรวจประสบการณ์ต่อไปนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「Silver Core」× 200 เป็นรางวัล สามารถรับได้เมื่อกรอกแบบสอบถามเสร็จสิ้น กำหนดปิดรับแบบสอบถามวันที่ 16 พฤษภาคม เวลา 9:00 น. กรุณากรอกให้ทันเวลา\n        <SurveyLink:【คลิกเพื่อไปกรอก】>\n        เราจะรับฟังข้อเสนอแนะจากผู้พิทักษ์ความลับทุกคนอย่างจริงจัง และคำติชมของคุณจะทำให้มหาวิทยาลัยมิซากดีขึ้นเรื่อยๆ อย่างแน่นอน!\n        ——ขอให้กุญแจเงินนำทางสู่เส้นทางข้างหน้า"
  },
