    Text = "เรียน ผู้พิทักษ์：\nกิจกรรม「เมื่อภูเขาหิมะละลาย·คลอน」ได้สิ้นสุดแล้ว ขณะนี้จะทำการรีไซเคิลเงินกิจกรรมที่เหลืออยู่ของผู้พิทักษ์「บุปผาที่ถูกแช่แข็ง」「บัดดอกไม้เงินค้าง」และ「บุปผาแสงอาทิตย์」ตามอัตราแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 กรุณาจำไว้ว่าให้ตรวจสอบการรับด้วย."
