    Text = "ผู้พิทักษ์ที่เคารพ:\n「เอโปยานส์นิรันดร์」สิ้นสุดแล้ว,      ขณะนี้จะทำการแปลง「」เหยื่อ「สด」「」เหยื่อ「ใหญ่โต」「」เหยื่อ「โบราณ」ที่เหลืออยู่ของผู้พิทักษ์ในอัตราแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 ต่อชิ้น,      กรุณาอย่าลืมตรวจรับด้วยนะคะ."
