  },
  Mail_141470_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\n「นักโทษกระจก·คลอน」สิ้นสุดแล้ว, ขณะนี้จะทำการแปลง「หนังสือความรู้ทั่วไป」,「หนังสือคณิตศาสตร์」,「หนังสือวรรณกรรม」ที่เหลืออยู่ของผู้พิทักษ์ในอัตราแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 ต่อชิ้น, กรุณาอย่าลืมตรวจรับด้วยนะคะ."
  },
  Mail_141470_Name = {
    Text = "การแลกเปลี่ยนเงินผ่านจินตภาพ"
  },
  Mail_141470_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_141507_Desc = {
    Text = "ผู้พิทักษ์：\n\nวันเกิด สำหรับคุณ อาจเป็นวันสำคัญวันหนึ่งใช่ไหม? \nสำหรับฉัน น้ำหนักของแต่ละวันในใยแห่งชะตากรรมมีความเท่าเทียมกัน ทุกเรื่องราวอื่นๆ ทำให้วันนี้มีความหมายพิเศษ \nฉันเกิดในวันนี้ เข้าใจคำทำนายในวันนี้ ได้รับจักรที่ทอชะตากรรมในวันนี้ เห็นสายใยชะตาที่ซับซ้อนและฝันร้ายที่อยู่ปลายสายใย \nสำหรับผู้ทอชะตา วันนี้ไม่มีอะไรพิเศษ สำหรับนักแสดงบนเวที วันนี้ควรเฉลิมฉลอง และในทุกตัวตน ที่ทำให้ฉันมีความสุขที่สุดคือการเป็นตัวเองในฐานะนักแสดง \nผู้พิทักษ์ วันนี้ โรงละครชะตากรรมได้ดับไฟหมดแล้ว มีเพียงเวทีที่สว่างไสว คุณเคยกล่าวว่าอยากเห็นชะตาที่ฉันเคยประสบมาอีกมากมาย ตอนนี้ เวทีนี้จะนำเสนอเรื่องราวเกี่ยวกับตัวฉัน \nฉันไม่รู้มันจะนำเสนอเรื่องราวไหน ฉันจะนำความทรงจำขึ้นเวที เธอจะเลือกช่วงเวลาที่คุณคาดหวังที่สุดในคืนวันนี้ \nเรื่องราวนั้นอาจทำให้ฉันเจ็บปวด หรืออาจทำให้ฉันอับอาย แต่สิ่งเหล่านั้นไม่สำคัญใช่ไหม? ฉันคิดว่าบางครั้งให้จักรทอเอง และเป็นผู้ชมที่บริสุทธิ์ เป็นเรื่องที่น่ายินดี \nบัตรเข้าชมการแสดงใบเดียว ตอนนี้อยู่ในมือของคุณแล้ว นำจดหมายนี้มาที่นี่เถอะ ผู้พิทักษ์ คืนนี้ เรื่องราวที่ไม่มีใครรู้รอคอยการมาของคุณอยู่ \n\nอารัคเน"
  },
  Mail_141507_Name = {
    Text = "เรื่องราวที่ซ่อนเร้น"
  },
  Mail_141507_Sender = {
    Text = "อารัคเน"
  },
  Mail_141833_Desc = {
    Text = "ผู้รักษาความลับที่เคารพ：\n「จันทร์เสี้ยวและหิมะลึก」กิจกรรมสิ้นสุดแล้ว, ขณะนี้จะทำการแปลง「แอปเปิ้ลแดง」、「แอปเปิ้ลทอง」、「แอปเปิ้ลน้ำตาล」ที่เหลืออยู่ของผู้รักษาความลับในอัตราส่วน「คูปองกุหลาบทอง」× 40 ต่อชิ้น, กรุณาอย่าลืมตรวจรับด้วย."
