  Mail_141962_Sender = {
    Text = "มิซากะ ฝ่ายบริหารโรงเรียน"
  },
  Mail_142101_Desc = {
    Text = "นานมากแล้วที่ไม่ได้พบกัน, %player%:\n\nเมื่อคุณได้รับจดหมายฉบับนี้, ฉันน่าจะกำลังบินผ่านน่านฟ้าของยาโกร, ทุกปีในช่วงเดือนนี้, การเดินทางล่าของฉันมักจะไกลออกไปกว่าเดิมเสมอ.\nไม่มีอะไรเหมาะสมจะเป็นเพลงประกอบวันเกิดได้มากกว่าเสียงกรีดร้องและโหยหวนของศัตรูอีกแล้ว, ยิ่งกว่านั้น ฉันได้เตรียมกรงขังไว้เพียงพอแล้ว, ตราบใดที่ยังมีคนโง่เขลากล้าศรัทธาในเทพเจ็บปวดเหล่านั้นที่ไม่นำมาซึ่งสิ่งใดนอกจากความทุกข์ทรมาน, ไม่ว่าจะอยู่ที่ไหนในโลก, ฉันจะทำให้พวกเขาตระหนักถึงความผิดพลาดของตนเอง.\nบางครั้ง, เมื่อมังกรคืนบินทะลุชั้นเมฆและมองเห็นจันทรา, ความคิดที่ไร้สาระบางอย่างก็แว่บผ่านในหัวของฉัน.\nเช่น ช่วงเวลาเช่นนี้จะถูกบังคับให้หยุดลงอย่างกะทันหันและหลีกเลี่ยงไม่ได้เมื่อไหร่, เหมือนกับที่ชีวิตเคยดิ่งลงโดยไม่มีสัญญาณเตือนล่วงหน้า.\nแต่แล้วฉันก็ขำตัวเองขึ้นมา, ในวันที่ฉันก้าวเข้าสู่เส้นทางนี้, ฉันก็อยู่บนเส้นทางที่ไม่มีทางถอยหลังแล้ว, ฉันเชื่อว่าคุณต้องเข้าใจความหมายของฉันอย่างแน่นอน, เด็กน้อย. ในโลกนี้, ไม่มีใครอยู่ในสถานการณ์ที่เหมือนกับคุณและฉันมากกว่านี้อีกแล้ว.\nเราต่างเลือกทางเลือกที่ไม่มีทางเลือก, ข่าวดีคือ เราต่างก็สนุกกับทางเลือกของตัวเอง.\nปีใหม่นี้, ตราบใดที่เป่านกหวีดล่าสัตว์ที่ฉันให้ไว้, ฉันยังคงจะปรากฏตัวอยู่เคียงข้างคุณได้ทุกเมื่อ.\nแน่นอน, หากไม่มีเหตุการณ์ไม่คาดฝัน, ขอให้ฉันได้เพลิดเพลินกับการเดินทางครั้งนี้อย่างเต็มที่ก่อนนะ, เดือนหน้า, ฉันจะนำของที่ระลึกและเรื่องราวที่พบเห็นใหม่ๆ มาฝากคุณ.\nขอให้ทุกอย่างราบรื่น, ขอให้มีความสุข.\n\n「ลุง」ผู้เป็นที่รักของคุณ"
  },
  Mail_142101_Name = {
    Text = "เรื่องราวที่พบเห็น"
  },
  Mail_142101_Sender = {
    Text = "「ลุง」ผู้เป็นที่รักของคุณ"
  },
  Mail_143935_Desc = {
    Text = "เรียน ผู้พิทักษ์：\nกิจกรรม「ข้อความชั่วคราว」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「ข้อความชั่วคราว」,     「ข้อความชั่วคราว」,     「ข้อความชั่วคราว」ที่เหลืออยู่ของผู้พิทักษ์ในอัตรา 40 ตั๋วทองกุหลาบต่อชิ้น กรุณาจำไว้ให้ดี."
