  Mail_147081_Desc = {
    Text = "ปฏิทินเป็นสิ่งประดิษฐ์ที่น่าเบื่อ. ทุกวันไม่มีความแตกต่างกัน รวมถึงวันนี้ด้วย.\nตามปฏิทินของพวกคุณ วันนี้คือวันที่ฉันถือกำเนิด. คำว่าถือกำเนิดนั้นไม่ค่อยถูกต้องนักสำหรับฉัน. ฉันคือเศษซากที่ถูกฉีกออกมาจากเคออส เป็นใบมีดที่ถูกขัดเกลาจากการต่อสู้นับครั้งไม่ถ้วน. สิ่งที่หล่อหลอมฉันไม่ใช่แม่ แต่คือคู่ต่อสู้ทุกคนที่เคยปะทะกับฉัน. และคุณ คือหนึ่งท่านที่สำคัญยิ่งในหมู่พวกเขา.\nพวกคุณให้ความสำคัญกับวันแบบนี้มาก. งานเลี้ยง ของขวัญ คำอวยพร—ฉันไม่ต้องการสิ่งเหล่านั้น.\nฉันต้องการเพียงการต่อสู้หนึ่งครั้ง.\nช่วงเวลาที่ผ่านมา คุณได้ทำสิ่งที่น่าอัศจรรย์มากมาย. แต่ฉันรู้ว่าสิ่งที่คุณแสดงออกมานั้น ยังห่างไกลจากขีดจำกัดของคุณมากนัก.\nพลบค่ำวันนี้ ที่สนามฝึก. พาอาวุธของคุณมา ฉันจะรอคุณอยู่ที่นั่น. ไม่ต้องสนใจแพ้ชนะ ไม่ต้องกังวลเรื่องบาดเจ็บ. ขณะที่ใบมีดปะทะกันโดยไม่เก็บรักษาอะไรไว้ คือของขวัญแสดงความยินดีเดียวที่ฉันคาดหวัง. ให้ฉันดูว่า เศษชิ้นส่วนของ@4นั้น สามารถทำอะไรได้บ้าง.\nฉันคิดว่า คุณจะทำให้ฉันประหลาดใจได้ 「คู่ต่อสู้」ของฉัน."
