  Mail_147798_Desc = {
    Text = "ผู้รักษาความลับที่เคารพ：\n        ในการอัปเดต V2.6.0, เราได้แก้ไขปัญหารางวัลที่ซ่อนอยู่ที่หายไปของการสอบสวนดำเนินการบทลืม H7-6. เนื่องจากคุณได้ผ่านด่าน H7-6 ก่อนการแก้ไข, เราจะส่งรางวัลที่ซ่อนอยู่ที่หายไปให้คุณโดยตรง. กรุณาตรวจรับ."
