  Mail_148478_Desc = {
    Text = "ผู้รักษาความลับที่เคารพ：\n        รางวัลที่ได้รับใน「หัวข้อภาคการศึกษา-หัวข้อขั้นสูง」ภาคการศึกษาที่ {s1} ยังไม่ได้รับ, ขณะนี้จะส่งรางวัลที่ยังไม่ได้รับให้คุณผ่านไฟล์แนบในอีเมล, กรุณาจัดการกระเป๋าให้เรียบร้อยก่อนรับรางวัล."
