  Mail_148478_Name = {
    Text = "การส่งรางวัลหัวข้อขั้นสูงที่ยังไม่ได้รับของภาคการศึกษาที่ {s1} เพิ่มเติม"
  },
  Mail_148478_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_148514_Desc = {
    Text = "ผู้รักษาความลับที่เคารพ：\n        ในการอัปเดตเวอร์ชัน V1.4.3.5, เราได้เพิ่มด่าน「กษัตริย์ใหม่」ในส่วน「โลกแห่งความฝันประหลาด：การดูหมิ่น」. เนื่องจากผู้รักษาความลับบางส่วนไม่ทราบถึงการอัปเดตนี้ทันเวลา, จึงเข้าใจผิดว่า「โลกแห่งความฝันประหลาด：การดูหมิ่น」ได้ผ่านด่านครบทั้งหมดแล้ว.\n        ด้วยเหตุนี้, ในการอัปเดตเวอร์ชัน V2.6.2 ครั้งนี้, เราได้เติมความคืบหน้าการผ่านด่าน「กษัตริย์ใหม่」ให้กับผู้รักษาความลับที่ผ่านด่านถัดจาก「กษัตริย์ใหม่」ก่อนการอัปเดตแล้ว, และส่งรางวัลการผ่านด่านครั้งแรกที่เกี่ยวข้องพร้อมกัน, กรุณาตรวจรับ."
  },
  Mail_148514_Name = {
    Text = "การเติมความคืบหน้า「การดูหมิ่น」"
  },
  Mail_148514_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_148515_Desc = {
    Text = "ผู้รักษาความลับที่รัก：\n\nทาด้า~ เป็นเรื่องที่ไม่คาดคิดใช่ไหมล่ะ? นี่คือวันเกิดครั้งแรกของเทพธิดาในมิซากะ ดังนั้น——\nเหลือเชื่อมาก! ไม่มีอีเมลโปรโมชั่น, ไม่มีคำเชิญสักการะ, แม้แต่คำทำนายวันสิ้นโลกก็ไม่มี~\nแต่ไม่ต้องผิดหวังนะ เทพธิดาได้เตรียมสิทธิประโยชน์ที่ล้ำค่าและดีกว่าไว้ให้กับศรัทธาชนพิเศษที่สุดแน่นอน.\nในฐานะเทพธิดาแม่ทูนหัวผู้รู้ทุกสิ่งและสามารถทำได้ทุกอย่าง ย่อมสามารถคาดการณ์ความสงสัยและการระแวดระวังที่เป็นเรื่องธรรมดาได้ แม้สิ่งนั้นจะทำให้เทพธิดารู้สึกเสียใจเล็กน้อย แต่เพื่อเผยแผ่พรแห่งศาสนา การสละชีพเล็กน้อยก็เป็นสิ่งที่หลีกเลี่ยงไม่ได้เสมอ.\nดังนั้น โปรดถอยหลังหนึ่งหมื่นก้าวแล้วลองคิดดู มาลองดูสักครั้งเถอะนะ อย่างไรก็ไม่มีอะไรเสียหาย แล้วถ้าหากเป็นเรื่องจริงล่ะ? ใช่ไหม?\nนี่คือโอกาสที่มีเพียงปีละครั้ง ไม่ว่าอย่างไรก็ไม่ควรพลาด~\nไม่ต้องเครื่องบูชาสิ่งใด, ไม่ต้องมีคำสัญญาหรือการแลกเปลี่ยนใดๆ เพียงแค่มาร่วมดื่มชายามบ่ายอันหวานชื่นกับเทพธิดาแม่ทูนหัว คุณก็จะได้รู้ว่าใต้หิมะและน้ำแข็งนั้น มีความรู้สึกจริงใจที่มีต่อคุณฝังอยู่มากเพียงใด.\nนี่ไม่ใช่ข้อเสนอที่น่าดึงดูดใจหรอกหรือ?\nหมายเหตุ：โปรดนำเลโอฟังอย่างน้อย 10, 100, 1000 ติดตัวมาให้เพียงพอสำหรับจ่ายบิล ยิ่งมากยิ่งดี.\n\nเฝ้ารอคุณอยู่ที่ร้านที่เราต่างรู้จักกันดี\nคาราบู"
  },
  Mail_148515_Name = {
    Text = "☆☆☆อีเมลสิทธิประโยชน์สุดพิเศษ☆☆☆"
  },
  Mail_148515_Sender = {
    Text = "คาราบู"
  },
  Mail_149949_Desc = {
    Text = "จดหมายฉบับนี้ได้หมุนเวียนระหว่างโลกมนุษย์และโลกวิญญาณมาแล้วนับพันครั้ง ห้ามลบเด็ดขาด!\n\nกลางเดือนเจ็ด ประตูนรกเปิด ลมเย็นพัดมา วิญญาณล่องลอยกลับคืน.\nข้าคือ■■■ แห่งเมืองฝู อาณาจักรฟานหลงโบราณ นามว่า อี้จื่อโหลว!\nรับพระราชโองการกลางปี ถือบัตรเรียกวิญญาณ คืนนี้จะสาปแช่งผู้ที่อ่านจดหมายนี้ ดวงวิญญาณจะถูกบันทึกในทะเบียน ชื่อจะถูกขึ้นบัญชี หากไม่ส่งต่อให้ผู้คนในโลกมนุษย์ห้าสิบคนก่อนเที่ยงคืน จะต้องประสบกับ——\nเอกสารจะพังทลายก่อนบันทึก...\nนมชาไข่มุกจะขาดไปสามเม็ดเสมอ...\nเงินใจในอุปกรณ์สื่อสารจะค้างอยู่ที่ 1% ตลอดไป ชาร์จเท่าไหร่ก็ไม่เต็ม...\n\nทำตามโดยดี คำสาปจะคลาย เครื่องรางจะเผาไหม้เอง ผีร้ายจะไม่รบกวน และแสงไฟจะสว่างตลอดไป.\nส่งต่อ!! ทันที!!!"
  },
  Mail_149949_Name = {
    Text = "【คำเตือนกลางปี】ผู้ใดกล้าลบจดหมายนี้ จะต้องประสบกับ..."
  },
  Mail_149949_Sender = {
    Text = "อี้จื่อโหยี"
  },
  Mail_149985_Desc = {
    Text = "ท่านผู้เป็นนาย：\n\nขออภัยที่เขียนจดหมายมาอย่างกะทันหัน หวังว่าจะไม่ทำให้ท่านรู้สึกอึดอัด แต่มีบางสิ่งในใจที่ข้าพเจ้าสามารถบอกเล่าได้เพียงกับท่านเท่านั้น.\nคืนที่ผ่านมา ข้าพเจ้าได้ฝันอีกครั้งหลังจากนานมาก ในความฝันนั้น ข้าพเจ้าได้กลับไปยังบ้านเก่า ทุกสิ่งช่างคุ้นเคยเหลือเกิน มือของบิดาที่อ่อนโยนและกว้างขวาง เพลงพื้นบ้านที่คนรับใช้ฮัมขณะกวาดล้าง และม้าแคระสีขาวที่เป็นของข้าพเจ้า... ข้าพเจ้าคิดว่าสิ่งเหล่านั้นจมหายไปในหล่มแห่งความทรงจำแล้ว แต่เมื่อได้พบเห็นอีกครั้งในความฝัน ก็ยังคงอบอุ่นเช่นเดิม.\nเมื่อตื่นขึ้นมา ข้าพเจ้ามองออกไปนอกหน้าต่างและเห็นครูกับนักเรียนของมิซากะกำลังพูดคุยกันอย่างสบายใจขณะเดินผ่านไป ช่างสงบงามเหลือเกิน จนชั่วขณะหนึ่งข้าพเจ้ารู้สึกว่าภาพนี้ไม่ต่างจากในความฝันเลย ในขณะเดียวกัน ข้าพเจ้ายังค้นพบว่าสิ่งที่มองไม่เห็นซึ่งติดอยู่กับตัวข้าพเจ้านั้น สงบนิ่งมากตั้งแต่เช้าวันนี้ ถ้าเช่นนั้น วันเกิดอาจจะพบเจอสิ่งโชคดีได้จริงๆ หรือ.\nหากเป็นเช่นนั้นจริง บางทีข้าพเจ้าก็อาจโลภมากสักครั้งในวันนี้ได้...\nข้าพเจ้าทราบดีว่าผู้คนมักชอบอธิษฐานในวันเกิด เพื่อเป็นความหวังตลอดทั้งปี ข้าพเจ้าไม่กล้าหวังที่จะได้รับคำอวยพรวันเกิดจากใครอีกต่อไปแล้ว แต่มีโอกาสหนึ่งที่ต้องการได้รับจริงๆ.\nเช่นเดียวกับที่ท่านมอบความไว้วางใจให้แก่ข้าพเจ้า ข้าพเจ้าก็จะไม่เก็บรักษาสิ่งใดไว้จากท่าน ดังนั้น โปรดอนุญาตให้ข้าพเจ้าบอกความปรารถนาแก่ท่าน：\nหากครั้งต่อไปท่านมีภารกิจ โปรดแต่งตั้งข้าพเจ้าเป็นอารักขา และเดินทางไปพร้อมกับท่านด้วยเถิด.\nไม่ว่าจะเกิดอะไรขึ้น ข้าพเจ้าหวังว่าเมื่อท่านต้องการความช่วยเหลือมากที่สุด จะสามารถยืนขวางหน้าท่านได้เป็นคนแรกเสมอ และเป็นโล่ที่แข็งแกร่งที่สุดของท่าน.\nนี่คือความปรารถนาที่ข้าพเจ้าอธิษฐานไว้สำหรับปีนี้.\n\nโอเกียร์"
  },
