  Mail_18019_Desc = {
    Text = "ผู้พิทักษ์ที่รัก：\nระบบตรวจพบว่าบัญชีปัจจุบันได้ทำการคืนเงินครั้งหนึ่ง ทีมงานได้ดำเนินการหักส่วนของสกุลเงินเสมือนที่เกี่ยวข้องกับคำสั่งคืนเงินของคุณแล้วเมื่อ{s1} หากสกุลเงินที่ถูกหักกลายเป็นติดลบ จะต้องปรับกลับเป็นบวกก่อนจึงจะสามารถใช้งานได้ตามปกติ \nหากมีข้อสงสัยโปรดติดต่อฝ่ายบริการลูกค้า"
