  },
  Mail_18034_Desc = {
    Text = "สวัสดี ผู้พิทักษ์ คุณยังไม่ได้รับรางวัลคะแนนสะสมจากกิจกรรมฝันลึก ตอนนี้เราได้ส่งรางวัลให้คุณทางอีเมลเป็นไฟล์แนบแล้ว."
  },
  Mail_18034_Name = {
    Text = "ยังไม่ได้รับรางวัลสะสมจากความฝันลึกซึ้ง"
  },
  Mail_18034_Sender = {
