  },
  Mail_18035_Desc = {
    Text = "ผู้พิทักษ์ที่รัก：\n\nหนทางข้างหน้ายังยาวไกลและเต็มไปด้วยอุปสรรค ในช่วงเวลาที่ยากลำบากนี้ เราต้องร่วมมือกันและก้าวไปข้างหน้าพร้อมกัน\nจดหมายฉบับนี้ได้แนบของพิเศษ \"ลิงฟีไท\" มาให้ กรุณาโปรดรับไว้\nขอให้กุญแจเงินนำทางสว่างสู่อนาคต\nนอกจากนี้: ของพิเศษสำหรับคุณเหลืออีก {s1} วัน กรุณาจัดการเวลาสอบสวนให้เหมาะสม\n\nฝ่ายสนับสนุนด้านการจัดการของคณะกรรมการโรงเรียนมิซากะ"
  },
  Mail_18035_Name = {
