  },
  Mail_20231_Desc = {
    Text = "ผู้พิทักษ์ที่รัก การเล่นหมากรุกเฟสฤดูกาลใหม่ได้เริ่มต้นขึ้นแล้ว ระดับของคุณถูกรีเซ็ตจาก {s1} เป็น {s2} รางวัลระดับฤดูกาลใหม่ได้ถูกรีเซ็ตแล้ว คุณสามารถเพิ่มระดับเพื่อรับเกียรติและรางวัลมากยิ่งขึ้น! {s3}\n{s4}"
  },
  Mail_20231_Name = {
    Text = "การเล่นหมากรุกเฟสเมลประจำฤดูกาล"
  },
  Mail_20231_Sender = {
    Text = "คณะกรรมการมิซากะ"
  },
  Mail_21453_Desc = {
    Text = "ผู้พิทักษ์ที่รัก:\n\nขอโทษที่รบกวนคุณแบบไม่ทันตั้งตัว ไม่ทราบว่าคุณสบายดีไหมในช่วงนี้?\nขอโทษจริงๆ ที่มาขัดจังหวะคุณในขณะที่คุณยุ่ง เจนกินและคนอื่นๆ เตรียมงานเลี้ยงวันเกิดเล็กๆ ให้ฉัน ฉันคิดอยู่นานมาก แต่สุดท้ายก็ตัดสินใจส่งคำเชิญนี้ด้วยตัวเอง\nเด็กกำพร้าส่วนใหญ่ที่ฟังรับไว้ดูแลจำวันเกิดของตัวเองไม่ได้ คุณซาร่าเลยกำหนดวันที่พวกเขาปรากฏตัวที่สถานเลี้ยงเด็กกำพร้าเป็นวันเกิดของพวกเขา แต่สำหรับฉันมันแตกต่างออกไป คุณซาร่าบอกว่า ฉันถูกทิ้งไว้หน้าประตูสถานสงเคราะห์ในคืนฤดูหนาวที่หนาวเหน็บ และเธออยากให้ชีวิตของฉันไม่เย็นชาและไร้ชีวิต จึงเลือกวันที่อบอุ่นวันหนึ่งเป็นวันเกิดของฉัน ดังนั้น นี่คือวันของฉัน เป็นวันที่เต็มไปด้วยความห่วงใยและรัก นี่เป็นวันสำคัญสำหรับฉัน และฉันหวังว่าผู้พิทักษ์จะมาเฉลิมฉลองกับฉันด้วย นี่คือความปรารถนาเล็กๆ ของฉัน แน่นอนว่าถ้าไม่สามารถทำได้ก็ไม่เป็นไร เพราะผู้พิทักษ์มีเรื่องมากมายที่ต้องจัดการ ไอจิสรู้ดี\nหากคำเชิญนี้สร้างความลำบากให้กับคุณ กรุณาบอกฉันด้วยนะคะ และโปรดยอมรับคำขอโทษอย่างจริงใจจากฉัน แต่ถ้า สมมุติว่า คุณสามารถหาเวลาว่างได้ คุณจะได้รับการต้อนรับอย่างอบอุ่นมากๆ เลยค่ะ บางทีอาจสนุกมากๆ ก็ได้นะคะ เพราะเป็นเจนกินที่เตรียมไว้\n\nไอจิส"
  },
  Mail_21453_Name = {
    Text = "ขอโทษที่รบกวนในขณะที่คุณยุ่ง.."
  },
  Mail_21453_Sender = {
    Text = "ไอจิส"
  },
  Mail_21454_Desc = {
    Text = "เฮ้：\nฉันไม่เคยเข้าใจเลย วันเกิดมีอะไรดีที่ควรค่าแก่การเฉลิมฉลอง? คุ้มค่าที่ทุกคนต้องลงทุนแรงขนาดนี้?\nปีที่แล้ววันนี้ มีนักเรียนมาถามวันเกิดของฉัน ขำจริงๆ! ตอนฉันเกิดยังไม่มี concept เรื่องเวลาบนดาวเคราะห์ดวงนี้เลย ไหนจะเรื่องวันเกิดอีก แต่เธอบังคับถามจนฉันทำไม่ได้เลยบอกไปว่า 「ตอนที่กลางวันกับกลางคืนแบ่งครึ่งกันพอดี」 ไม่รู้เธอเข้าใจยังไงนะ\nเขียนจดหมายนี้เพื่อเตือนให้คุณจำไว้ว่า หลังเที่ยงคืนวันนี้อย่าลืมเอาดอกไม้หน้าห้องฉันออก กลิ่นแรงจนแสบจมูก!\n\nโรแทน"
  },
  Mail_21454_Name = {
    Text = "ดอกไม้เหล่านั้น.."
  },
  Mail_21454_Sender = {
    Text = "โลทัน"
  },
  Mail_21455_Desc = {
    Text = "เอริกาส่งกาแฟมาให้เป็นของขวัญวันเกิดของฉัน บอกว่าเป็นเสบียงสำหรับทั้งปีของคุณ<Del:แต่ คุณเต็มใจไหม ถ้าไม่>\n ถ้าเป็นดอร์หรือใครก็ตามที่เล่นตลกกับคุณ แม้ว่าฉันจะเสียดายมาก แต่ฉันก็ยังสามารถ...คืนให้คุณได้ อย่างไรก็ตามนั่นคือกาแฟ! แค่ดื่มน้อยลงสองแก้วฉันก็หลับไม่ได้แล้ว ไม่ดื่มตลอดทั้งปี? คุณอาจจะนอนหลับเหมือนตูรูแน่ๆ ไม่ใช่ว่าเขาไม่ดีนะ เพียงแต่ว่า สิ่งที่เป็นสีดำจะปรากฏในตอนกลางคืน...เอาล่ะ หากคุณต้องการ คุณสามารถนำกาแฟกลับไปได้ทุกเมื่อ แน่นอนว่าหากคุณทิ้งกาแฟไว้ที่นี่ <Del:ฉันก็ เอาล่ะ>ฉันคิดว่าฉันจะดีใจมาก แบบนั้นฉันจะได้ทดลองสิ่งที่อยากทำ: สกัดและเข้มข้นคาเฟอีนให้สามารถดูดซึมผ่านผิวหนังได้ แปะไว้บนตัวเพื่อให้ตื่นตัวตลอดเวลา ตลอดเวลา...\n\n\nเวินเค่อที่อยากทำการทดลองนี้มาก"
  },
  Mail_21455_Name = {
    Text = "กาแฟ.."
  },
  Mail_21455_Sender = {
    Text = "วิงเกิล"
  },
  Mail_21456_Desc = {
    Text = "วันเกิด? \nถ้าจะให้พูดนะ วันเกิดของฉันไม่ใช่วันที่ดีอะไร อีกหลายร้อยหลายพันชีวิตที่บริสุทธิ์ต้องตายในวันนั้น เพื่อที่จะทำให้ฉัน 「เกิด」 และหลังจากนั้นก็ไปฆ่าคนอื่นเพิ่มอีก \nดังนั้น วันนั้นก็ไม่มีอะไรให้เฉลิมฉลองหรอก แต่ฉันเข้าใจว่าพวกมนุษย์อย่างพวกคุณเป็นสิ่งมีชีวิตที่ให้ความสำคัญกับ 「ความรู้สึกพิเศษของพิธีการ」 มาก พอดีตอนนี้ฉันมีเงินอยู่ก้อนหนึ่ง — วางใจได้เลย นี่คือเงินที่ฉันทำงานหนักหาเลี้ยงชีพด้วยหยาดเหงื่อที่สโมสรปลาเทราต์ ไม่ใช่รายได้ผิดกฎหมายอะไร \nรับเงินนี้ไปเถอะ แล้วเอาไปซื้อของขวัญให้ตัวเองละกัน ถือซะว่าเป็นการเฉลิมฉลองวันเกิดของฉันแล้วกัน \n\nยูวฮะชิ"
  },
  Mail_21456_Name = {
    Text = "วันเกิด.."
  },
  Mail_21456_Sender = {
    Text = "อูฟฮาช"
  },
  Mail_21457_Desc = {
    Text = "ผู้พิทักษ์：\n\nในเขตมิซากะ มีประเพณีเฉลิมฉลองวันเกิดหรือไม่?\nประเทศบ้านเกิดที่อยู่ในความทรงจำของข้า...ทุกปีจะมีพิธีเฉลิมฉลองครั้งใหญ่เพื่อเป็นเกียรติแก่วันประสูติของพระราชา\nเมื่อเวลาผ่านไป ความหมายพิเศษของ「วันเกิด」ก็ได้ถูกมอบให้กับทุกคน\nในอดีตกาลที่ไกลโพ้น ในวันเกิดนั้น เพื่อนร่วมงานและมิตรสหายจะเดินทางจากที่ไกลโพ้นมาหาข้า\nความรู้สึกที่ได้รับการโอบล้อมด้วยคนที่รัก...ความอบอุ่นเหมือนแสงอาทิตย์ที่โอบกอดเราไว้...อาจเป็นเหตุผลที่ข้าไม่อาจละทิ้งอดีตได้\nอา...ข้าพูดออกนอกเรื่องไปแล้ว ข้ารบกวนการทำงานของท่านหรือเปล่า?\nข้าเตรียมขนมและของว่างที่เคยใช้ประจำไว้บ้าง อยากจะแบ่งปันกับท่าน\nหากท่านยินดีโปรดมาพบข้าหลังอาหารเย็น\n\nฟาร์โรส"
  },
  Mail_21457_Name = {
    Text = "แสงที่ไม่เคยดับ.."
  },
  Mail_21457_Sender = {
    Text = "ฟารอส"
  },
  Mail_21458_Desc = {
    Text = "วันนี้เป็นวันที่ควรค่าแก่การจดจำอย่างแท้จริง: ในวันนี้ การปรากฏตัวของพระเจ้าแห่งโกลิอัทผู้ยิ่งใหญ่ กษัตริย์แห่งยักษ์ได้บังเกิดขึ้นในโลก；ในวันนี้ มหาสมุทรต้องสั่นสะเทือน และดวงดาวต้องหมองคล้ำ.\nได้ยินมาว่าในโรงเรียนไม่อนุญาตให้ฟุ่มเฟือย ก็จัดงานเลี้ยงฉลองวันเกิดของข้าตามขนาดปกติเพียงหนึ่งในสิบก็แล้วกัน—หมูหันสิบตัว ปลาหมึกย่างร้อยไม้ และวงดนตรีที่สามารถบรรเลงเพลงพื้นบ้านของโกลิอัท ใช่แล้ว ขอให้หาหญิงระบำมาสักโหล...\nอะไรนะ? สิ่งเหล่านี้ไม่ได้รับอนุญาตหรือ?\nงั้นขอแค่หญิงระบำก็พอ...ไม่ต้องหนึ่งโหล สักสี่ห้าคนก็พอ.\nอะไรนะ? แบบนี้ก็ไม่อนุญาตด้วยหรือ?!\nมาตรฐานที่ยากจนเช่นนี้ไม่สมกับฐานะของข้าเลย ตอนนี้ข้าประกาศว่า แผนงานเลี้ยงยกเลิก!\n\nโกลิอัท"
  },
  Mail_21458_Name = {
    Text = "แผนงานเลี้ยงอาหารค่ำ.."
  },
  Mail_21458_Sender = {
    Text = "โกไลแอท"
  },
  Mail_21459_Desc = {
    Text = "ผู้พิทักษ์——\n\nวันนี้ตอนที่ทำการฝึกความจำที่คุณเซลเวีย，เธอถามถึงวันเกิดของฉัน คุณก็น่าจะรู้แล้วว่าฉันเพิ่งวางประแจลงไปแล้วหันกลับไปก็ลืมได้เลย วันเกิดจะจำได้อย่างไร! ที่หนักกว่านั้นคือ นี่เป็นสิ่งที่มีแค่ฉันที่รู้ ฉัน! วันเกิดนี้ถือว่าไม่มีแล้วกัน.\n\nแต่คุณซัลวาดอร์บอกว่าวันที่เฉพาะเจาะจงไม่สำคัญ สิ่งที่สำคัญคือฉันเฉลิมฉลองอะไรทุกวัน ดังนั้นฉันจึงตัดสินใจว่า วันนี้คือวันเกิดของฉัน! ฉันได้ตกลงกับคนหนึ่ง (ฉันลืมไปแล้วว่าใคร คงไม่ใช่คุณหรอกนะ ผู้พิทักษ์?) ว่าจะจัดงานปาร์ตี้ที่หน้าห้องอาหาร คุณต้องมาให้ได้เลยนะ!\n\n\n\nแน่นอนว่าจะจำวันเกิดนี้ได้แน่นอน โนตี้ล่าร์\n\n\n\nกระดาษแผ่นหนึ่งที่ส่งมาพร้อมกับจดหมาย:\n\nเด็กคนนั้นเขียนจดหมายเสร็จก็รีบวิ่งออกไป ลืมทั้งจดหมายและของขวัญที่บอกว่าจะให้คุณไว้ที่โต๊ะ\nของทุกอย่างฉันได้ใส่ไว้ในซองจดหมายแล้ว รอคอยที่จะได้พบคุณที่งานปาร์ตี้ในคืนนี้ สบายใจได้ ฉันจะเตือนเธอให้มาที่งานในคืนนี้\n\n——เซลเวีย"
  },
  Mail_21459_Name = {
    Text = "วันเกิดที่ฉันตัดสินใจ!"
  },
  Mail_21459_Sender = {
    Text = "นอติลา"
  },
  Mail_21460_Desc = {
    Text = "หนูน้อย: \n\nในทะเลแห่งปฐมธาตุไม่มีดวงดาว ดวงอาทิตย์ ดวงจันทร์ และไม่มีสี่ฤดูหมุนเวียน ดังนั้น วันเกิดของฉันควรถูกบันทึกว่า【ไม่ทราบ】\nแต่วันนี้เป็นวันสำคัญจริงๆ เพราะรูปลักษณ์นี้สืบทอดมาจากมนุษย์คนหนึ่งที่มี「ความปรารถนา」 เธอชอบความคึกคัก จึงเปิดร้านเล็กๆ แห่งนี้ แต่เพราะต้องออกสืบสวนไปทั่ว วันเกิดของเธอมักมีแค่ฉันคนเดียวเป็นเพื่อน เพื่อเติมเต็มความปรารถนาของเธอก่อนจากไป ร้านคลายทุกข์จะจัดงานเลี้ยงแสงเทียนในวันนี้ ขอเชิญลูกค้าผู้ซื่อสัตย์ทุกท่านมาร่วมงาน\nแน่นอนว่า ร้านคลายทุกข์จะมอบส่วนลดเล็กๆ ให้กับทุกท่านที่มาร่วมงานด้วย หนูน้อยอย่าพลาดล่ะ\n\nดาฟเดล"
  },
  Mail_21460_Name = {
    Text = "ความปรารถนาของมนุษย์.."
  },
  Mail_21460_Sender = {
    Text = "ดาฟโฟดิล"
  },
  Mail_21461_Desc = {
    Text = "ในวันที่ถูกพรากจากครอบครัว แม่เลี้ยง...พระมเหสีของผู้ปกครองได้ทุบชิ้นดินเผาที่เขียนวันเกิดของข้าจนแหลกละเอียด ทำลายอดีตที่ข้าเคยเป็นชาวเตโลสให้สิ้นซาก วันเกิดที่แท้จริงนั้น ไม่มีทางรู้ได้อีกแล้ว \nหลังจากแยกทางกับไลอ์ ข้าก็ได้ครุ่นคิด...หากข้าจะถือเอาคืนที่ข้าหลบหนีจากกรงขังและเริ่มการแก้แค้นเป็น「วันเกิด」ของข้า ท่านคิดว่าอย่างไร? \nแม้ว่าตอนนี้จะไม่มีความจำเป็นต้องเฉลิมฉลองการเพิ่มอายุอีกต่อไป แต่ในฐานะเครื่องเตือนใจถึงการเปลี่ยนผ่านของเวลา ก็ดูเหมือนจะไม่เลวนัก"
  },
  Mail_21461_Name = {
    Text = "วันเกิด"
  },
  Mail_21461_Sender = {
    Text = "เฮลอต"
  },
  Mail_21462_Desc = {
    Text = "ทดสอบ ทดสอบ \nผู้พิทักษ์ที่เคารพ สวัสดี หากท่านได้รับจดหมายฉบับนี้ แสดงว่าความคิดเห็นของท่านมีความสำคัญอย่างยิ่งต่อเอริกา และท่านได้ถูกเลือกให้เข้าร่วมแผนการประเมินและซ่อมบำรุงโมดูลภาษาประจำปีของหุ่นยนต์อัตโนมัติเอริกา การประเมินครั้งนี้จะอยู่ในรูปแบบคำถามคำตอบสั้น โดยขอให้ท่านประเมินฟังก์ชันของโมดูลภาษาหมายเลข EA-L-1033 ที่ติดตั้งล่าสุดของหุ่นยนต์อัตโนมัติเอริกา จะไม่ใช้เวลามากของท่าน กรุณาอย่ากังวลหรือตื่นตกใจ \nคำถามคำตอบสั้น: \nกรุณาตอบว่าท่านเข้าใจเนื้อหาโดยรวมของจดหมายฉบับนี้หรือไม่? \n\nกรุณากรอกคำตอบไว้ใต้คำถามคำตอบสั้น และใส่จดหมายกลับลงซอง \nขอบคุณสำหรับการเข้าร่วม \n\nเอริกา"
  },
  Mail_21462_Name = {
    Text = "ทดสอบ ทดสอบ.."
  },
  Mail_21462_Sender = {
    Text = "เอริกา"
  },
  Mail_21463_Desc = {
    Text = "ผู้พิทักษ์：\n\nเธอเป็นคนที่หายากมากในโรงเรียนนี้ที่ยังคงมีสติ สายตาของเธอสามารถมองทะลุร่างที่บกพร่องนี้และเห็นตัวตนที่แท้จริงของฉัน \nคนอย่างเธอ ต้องสามารถอธิบายให้เด็กๆ เหล่านั้นเข้าใจได้แน่ว่า ฉันไม่ใช่เงือก ร่างนี้จะก้าวข้ามทะเลและข้ามภูเขา เพื่อสร้างร่างที่สมบูรณ์แบบ \n...ช่างเถอะ ฉันไม่อยากทำให้เธอลำบาก แต่อย่างน้อยวันนี้ อย่าให้พวกเขาเล่นกับหางของฉันเลย \nวันนี้เป็นวันพิเศษ หากเธอมีเวลา ฉันมีบางอย่างที่อยากพูดกับเธอเอง \n\nเคคอส"
  },
  Mail_21463_Name = {
    Text = "ร่างกายที่สมบูรณ์แบบ.."
  },
  Mail_21463_Sender = {
    Text = "เคคัส"
  },
  Mail_21464_Desc = {
    Text = "ผู้พิทักษ์: \n\nวันเกิดในความหมายของโลกมนุษย์ของฉัน คือวันที่พ่อรับฉันมาเลี้ยงเมื่อนานมาแล้ว \nในอดีตเขาให้ความสำคัญกับวันนี้เป็นพิเศษทุกปี มักจะจัดงานเต้นรำใหญ่โตเสมอ — การเต้นรำในชุดคอร์เซ็ตนั้นเหนื่อยกว่าการฟันดาบสามพันครั้งเสียอีก \nแต่นั่นคือความตั้งใจของเขาในฐานะพ่อ ฉันไม่อยากทำให้ความรักที่ได้มาอย่างยากลำบากนี้ต้องผิดหวัง \nอย่างไรก็ตาม ในปีนี้ เขายอมให้ฉันจัดการเรื่องวันเกิดเองได้แล้ว บางทีในสายตาของพ่อ ฉันอาจไม่ใช่เด็กที่ต้องดูแลใกล้ชิดอีกต่อไปแล้ว \nคุณสามารถไปที่ยอดหอคอยกับฉันได้ไหม? พูดคุยกัน รับลมสักหน่อย \nได้ยินมาว่า คืนนี้จะเป็นคืนพระจันทร์เต็มดวง \n\nรามอน่า"
  },
  Mail_21464_Name = {
    Text = "พระจันทร์เต็มดวง.."
  },
  Mail_21464_Sender = {
    Text = "ราโมน่า"
  },
  Mail_21465_Desc = {
    Text = "ท่านเจ้านายที่รักและเป็นที่สุดในความรัก:\nใช่แล้วค่ะ วันนี้เป็นวันเกิดครบรอบ@1ปีของคาเรน(อายุของผู้หญิงต้องเป็นความลับนะคะ)!\nคาเรนได้เตรียมงานเลี้ยงฉลองสุดพิเศษ และเชิญเพื่อนๆ ทุกคนที่สามารถเชิญได้~! ถึงแม้ว่าจะมีแค่ออรีตา,      โอกีล และลิลลี่ที่ตอบรับมา...\nแต่ไม่เป็นไรค่ะ ที่ไหนมีคน ที่นั่นก็มีปาร์ตี้ และที่ไหนมีปาร์ตี้ ที่นั่นก็ต้องมีคาเรน! คาเรนยังได้เตรียม 「เวอร์ชันปรับปรุง」 ซุปกบ,      ทากโคลนกระเทียม และซุปค้างคาวผัดเครื่องเทศไว้ให้ท่านเจ้านายลองชิมดูนะคะ~\n\nขอถามนิดนึงค่ะ ท่านเจ้านายต้องเตรียมของขวัญให้คาเรนแน่ๆ ใช่ไหมคะ? อย่าลืมนะ ต้องเป็นของที่ระยิบระยับด้วยนะคะ!\n\nสาวใช้ผู้ถ่อมตนของท่านเสมอ\nคาเรน"
  },
  Mail_21465_Name = {
    Text = "ของขวัญ.."
  },
  Mail_21465_Sender = {
    Text = "คาเรน"
  },
  Mail_21466_Desc = {
    Text = "<Del:ผู้พิทักษ์>พี่เขตตะวันตก:\nนี่คือจดหมาย<Del:เชิญชวร ขอเชิญชวน เชิญชวร เชิญชวน>พูดง่ายๆ ก็คือเชิญมากินเค้กฟรี แล้วก็ฉลองวันเกิดของฉันด้วย! จริงๆ แล้วก็เพื่อขอบคุณที่ก่อนหน้านี้ช่วยฉันตามหาพี่สาว แล้วยังพาฉันมาที่นี่ ให้ฉันกับบราวน์มีที่อยู่อย่างสบายใจ\n(ข้างบนนั้นเอจิสบังคับให้ฉันเขียน เขินจะตายไป ระหว่างเรามันไม่ต้องพูดแบบนี้ก็ได้ ใช่มั้ยล่ะ ผู้พิทักษ์?)\nสรุปก็คือ คืนนี้ที่ลานหลังหอพักของนาย ฉัน บราวน์ กับเอจิสเตรียมของดีๆ ไว้ด้วยมือของพวกเราเอง รอนายมาแบ่งปันด้วยกัน! แน่นอนว่าจริงๆ แล้วส่วนใหญ่เอจิสเป็นคนทำ เธอทำอาหารอร่อยมากเลยนะ คุณป้าๆ ในครัวยังชมว่าเธอมีพรสวรรค์เลย ถ้านายไม่มา รับรองว่าเสียใจแน่\n\nเพื่อนเก่าของนาย เจนกินกับบราวน์"
  },
  Mail_21466_Name = {
    Text = "ท่านชาวนิคมฝั่งตะวันตกที่รัก.."
  },
  Mail_21466_Sender = {
    Text = "เจนกิน"
  },
  Mail_21467_Desc = {
    Text = "ผู้พิทักษ์：\n\nเมื่อผู้คนยังอาศัยอยู่ในอาณาจักรของเทพเจ้า เราก็เริ่มใช้การเต้นรำเพื่อแสดงออกถึงความรู้สึกของตนเอง—การหมุนเต้นที่เบิกบาน ก้าวเต้นที่โศกเศร้า...มีคนว่าประวัติของการเต้นรำยาวนานเท่าประวัติศาสตร์ของมนุษย์ มันเป็นพยานต่อความรุ่งเรืองและการลดลงของเรา\n\nฉันเคยบอกว่าฉันจะไม่เต้นอีก แต่...ท้ายที่สุดแล้ว ฉันก็เกิดมาเพื่อเต้นรำ ดังนั้น แค่วันนี้ คุณยินดีมาเต้นกับฉันไหม? ร่วมดื่มด่ำในสิ่งนี้ และสัมผัสการขยับลึกในร่างกายกันเถอะ\n\nฉันจะรอคุณในห้องเต้น\n\n\n\nลิซ"
  },
  Mail_21467_Name = {
    Text = "คำเชิญให้เต้นด้วยกัน"
  },
  Mail_21467_Sender = {Text = "ลิซ"},
  Mail_21468_Desc = {
    Text = "เรียน ผู้พิทักษ์ที่เคารพ：\n\nก่อนที่ฉันจะเป็นผู้ปลุกเสก วันเกิดของฉันอยู่กับเพื่อนร่วมรบที่เอาเหล้ามาจากนอกค่ายทหาร ฉลองกันในเต๊นท์ที่เก็บคลังสินค้า ฉลองกันกับขนมปังดำที่เบิกเพิ่ม จากนั้นก่อนที่หัวหน้าจะค้นพบ เราก็โยนขวดลงไปในพุ่มนอก\n\nแต่มีธากไม่ใช่กองทัพ ที่นี่เราสามารถปลดปล่อยอิสระเต็มที่ ไม่ทราบว่าคุณจะร่วมสนุกกับฉันในการเปิดขวดไวน์ฉลองกับวันเกิดของฉันหรือไม่? ถ้าคุณยินดี ในคืนนี้เมื่อตะวันข้ามหลอดไฟขึ้นปีน โปรดมาที่ดาดฟ้าในที่พัก รู้ไหมว่าที่นั่นมีทิวทัศน์ที่ดีที่สุดในมีธาก\n\n\n\nแอลวา"
  },
  Mail_21468_Name = {
    Text = "แบ่งปันเครื่องดื่มชั้นเลิศ.."
  },
  Mail_21468_Sender = {
    Text = "อัลวา"
  },
  Mail_21469_Desc = {
    Text = "ชายหาดชายหาดชายหาดชายหาด!\nเอ๊ะ? ต้องเขียนชื่อผู้รับที่ขึ้นต้นจดหมาย——ลำบากจริงๆ! ทั้งที่ผู้พิทักษ์แปะโน้ตไว้บนตู้เย็นโดยไม่เขียนชื่อผู้รับเลย!\nวันนี้เป็นวันเกิดของออรีตา... เอ่อ... อายุเท่าไหร่กันนะ? แต่ยังไงก็ตาม มันคือวันเกิดของออรีตา!\nพวกนี้คือสมบัติของเธอ! ให้เธอด้วยนะ! พาเธอไปเล่นที่ชายหาดเถอะนะ ขอร้องล่ะ นะ~\nถือว่าเป็นของขวัญวันเกิดให้ออรีตาได้มั้ย นะ~\n\nออรีตา"
  },
  Mail_21469_Name = {
    Text = "ชายหาด!"
  },
  Mail_21469_Sender = {
    Text = "ออริตา"
  },
  Mail_21470_Desc = {
    Text = "ผู้มีพระคุณ：\n\nในอดีตตอนที่ฉันอยู่กับพี่สาวบนดาวร้าง เรามักจะกอดกันและดูดซับพลังจากต้นไม้เดียวกัน เพื่อเป็นการระลึกถึงการกำเนิดของเรา \nแม้ว่าวันเหล่านั้นจะขมขื่น แต่เมื่อคิดถึงตอนนี้ ก็อดไม่ได้ที่จะรู้สึกยินดีและอบอุ่น \nวันนี้เป็นอีกวันหนึ่งที่เราเฉลิมฉลองการกำเนิดของเรา หากเป็นไปได้ ฉันสามารถแลกเปลี่ยนเพลงหนึ่งกับกิ่งไม้หนึ่งได้ไหม? \nกิ่งไม้ที่หวานชื่น สามารถแทนความทรงจำระหว่างฉันกับพี่สาวของฉัน และแทนอนาคตระหว่างฉันกับคุณ...\n\nทิงค์เทต"
  },
  Mail_21470_Name = {
    Text = "เพลงวันเกิด"
  },
  Mail_21470_Sender = {
    Text = "ทิงค์"
  },
  Mail_21471_Desc = {
    Text = "ผู้พิทักษ์แห่งมหาวิทยาลัยมิซากะ ผู้เปี่ยมไปด้วยปัญญาและคุณธรรมอันสูงส่ง เจ้านายผู้ทรงคุณค่า:\nสวัสดี!\nเมื่อไม่กี่วันก่อน ข้าพเจ้าเห็นรถบรรทุกเข้าออกโรงม้าของโรงเรียน พบว่าได้นำม้าสายเลือดอบอุ่นมาส่งหนึ่งตัว ข้าพเจ้านึกถึงครั้งที่ได้ปฏิบัติภารกิจสอบสวนร่วมกับท่าน เคยได้ยินท่านกล่าวไว้ว่าท่านไม่เคยมีประสบการณ์ในการควบม้ามาก่อน ม้าสายเลือดอบอุ่นเพศเมียอายุน้อยนั้นเชื่องที่สุด เหมาะสมอย่างยิ่งสำหรับผู้เริ่มต้นฝึกฝนการขี่ม้า \nการขี่ม้า ไล่ล่าดวงอาทิตย์ขึ้นและตก นั่นคือช่วงเวลาที่แสนสบายที่สุดในความทรงจำของข้าพเจ้า หากท่านโปรดปราน ข้าพเจ้าอยากแบ่งปันความรู้สึกนี้ให้กับท่าน และขอเชิญชวนท่านร่วมขี่ม้าไปพร้อมกัน\n\nโอกีล"
  },
  Mail_21471_Name = {
    Text = "ม้าเลือดอุ่น.."
  },
  Mail_21471_Sender = {
    Text = "โอเกียร์"
  },
  Mail_21472_Desc = {
    Text = "ปฏิทินของอาณาจักรเก่านั้นแตกต่างจากที่ใช้ในเลนติเนียนปัจจุบันอย่างมาก\nข้าเกิดในวันพระจันทร์เต็มดวงที่ห้าของเดือนฤดูร้อนที่สอง การเลือกวันนี้เพื่อเฉลิมฉลองนั้นเป็นผลจากการคำนวณของหัวหน้าห้องปฏิบัติการ\nเมื่อครั้งอาณาจักรเก่ายังคงอยู่ มหาปุโรหิตจะเป็นผู้จัดการทุกอย่าง หลังจากพิธีบวงสรวงใหญ่แล้ว ก็จะเป็นการเฉลิมฉลองทั่วทั้งแผ่นดิน เข้าสู่วันหยุดยาวถึงเจ็ดวัน\nแม้มิใช่สิ่งที่ข้าปรารถนา แต่ข้าก็ไม่มีเหตุผลที่จะขัดขวางการแพร่กระจายของความสุข\nวันนี้ไม่ใช่วันหยุดราชการของมิซาเกอร์ และหน้าที่ของผู้พิทักษ์ก็กำหนดไว้แล้วว่าเจ้าจะไม่มีวันหยุดที่แน่นอน\nแต่ หากอ้างเหตุผลว่าเพื่อฉลองวันเกิดให้ข้าแล้วยื่นขอวันหยุด คิดว่าฝ่ายบริหารก็คงไม่กล้าว่าอะไร\nจงใช้เวลาบ่ายอันเงียบสงบสักวันเถิด\n\nทูรู"
  },
  Mail_21472_Name = {
    Text = "วันเกิด.."
  },
  Mail_21472_Sender = {
    Text = "ธูลู"
  },
  Mail_21473_Desc = {
    Text = "ผู้พิทักษ์：\n\nออรีตาบอกว่า คนที่เกิดวันนี้ต้องขอพรเสมอ \nแต่ผมกลับเป็นคนที่ไม่เคยขอพรเลย \nเพราะสิ่งที่ผมคิดมักจะเป็นจริงเสมอ นี่ไม่ใช่โชคดี แต่มันเหมือนกับบางอย่าง... การชี้นำจากโชคชะตา? \nเหมือนครั้งที่แล้วตอนที่ผมออกไปทะเลกับฮิลีย์สเตอร์ ผมก็ 「บังเอิญ」 เจอฟอสซิลที่สวยงามชิ้นหนึ่ง \nชาวบ้านแถวนั้นเรียกมันว่า 「ดอกลิลลี่ทะเล」 แขนของมันเหมือนกังหันลมที่หันเข้าหากระแสน้ำ กำลังเพลิดเพลินกับแสงแดดในบ่ายฤดูร้อนอย่างเกียจคร้าน \nเปราะบาง สวยงาม เมื่อเห็นมัน ภาพของคุณก็ปรากฏขึ้นในความคิดของผมอย่างเป็นธรรมชาติ \nครั้งนี้ผมก็ยังไม่ได้ขอพร— \nคุณต้องชอบแน่ๆ ใช่ไหม? \n\nซาน"
  },
  Mail_21473_Name = {
    Text = "ดอกไม้ทะเล.."
  },
  Mail_21473_Sender = {
    Text = "ซังก้า"
  },
  Mail_21475_Desc = {
    Text = "ผู้พิทักษ์：\n\nในอดีตตอนที่แล่นเรือกับเอลตัน เขาจะทำอาหารเต็มโต๊ะในวันนี้ของทุกปี และอยากให้ฉัน「ขอพร」\nก่อนที่จะมาที่นี่ ฉันไม่เข้าใจว่า「ความปรารถนา」คืออะไร ตอนนี้ ฉันไม่รู้ว่าฉันจะมี「ความปรารถนา」อะไรได้บ้าง...\nบางที การหา「ความปรารถนา」อาจเป็น「ความปรารถนา」ได้หรือเปล่า?\n\nฮิลีย์สเตอร์"
  },
  Mail_21475_Name = {
    Text = "ความปรารถนา.."
  },
  Mail_21475_Sender = {
    Text = "เซเลสเท"
  },
  Mail_21476_Desc = {
    Text = "ผู้พิทักษ์：\n\nออรีตาบอกฉันว่า เธอจะทำให้ทุกคำอธิษฐานในวันเกิดเป็นจริงใช่ไหม?\nคงจะไม่ใช่เรื่องจริงหรอกใช่ไหม? ถ้าต้องทำให้คำอธิษฐานของทุกคนเป็นจริง ก็คงลำบากเธอมากเลย\nแต่ว่า ถ้าขอได้... ฉันอยากให้ทิงค์เทตมีเวทีที่กว้างขึ้น\nจะยากเกินไปไหมนะ? อืม... นั่น นั่นขอเป็น 「ภายในหนึ่งปีข้างหน้า บนโต๊ะอาหารของฉันจะไม่มีขึ้นมาอีก」ได้ไหม?\n\nฟีนต์"
  },
  Mail_21476_Name = {
    Text = "ความปรารถนา.."
  },
  Mail_21476_Sender = {
    Text = "เฟนท์"
  },
  Mail_21477_Desc = {
    Text = "ผู้พิทักษ์ที่รัก：\n\nขอแบ่งปันความลับกับคุณ：วันเกิดนี้ไม่ใช่ของจริง แต่วันเดือนปีเกิดที่แท้จริงของฉัน...ก็ปล่อยให้มันลอยไปกับสายลมเถอะ\nหลังจากที่ฉันป่วย พี่ชายมักจะให้คนดูแลแอบเตรียมเค้กเล็กๆ ให้ฉันในวันเกิดเสมอ\nไม่มีเพลงวันเกิด ไม่มีคำอวยพร เหมือนการเฉลิมฉลองวันเกิดเป็นเรื่องน่าละอาย\nแต่ตอนนี้ทุกอย่างเปลี่ยนไปแล้ว ฉันสามารถเดินท่ามกลางแสงแดด ร้องเพลงดังๆ และเฉลิมฉลองวันเกิดได้\nแม้สิ่งเหล่านี้จะเป็นเพียงความสุขเล็กๆ น้อยๆ แต่ก็ทำให้ฉันรู้สึกคิดถึง\nขอบคุณมากนะคะ ผู้พิทักษ์\n\n(แน่นอน หากคุณและทุกคนสามารถปฏิบัติต่อฉันอย่างแข็งกร้าวกว่านี้...ก็คงจะสมบูรณ์แบบ)\n\nเรย่า"
  },
  Mail_21477_Name = {
    Text = "ความลับ.."
  },
  Mail_21477_Sender = {
    Text = "ลีห์"
  },
  Mail_21478_Desc = {
    Text = "นักโทษตัวน้อยของฉัน: \n\nมันนานมากแล้วที่ฉันไม่ได้ใช้แส้——\nติดอยู่ในโรงเรียนที่น่าเบื่อนี้ ติดอยู่ในชุดนักเรียน พันเดียรู้สึกคันยิบๆ ในใจ เหมือนมีลูกแมวซุกซนกำลังข่วน แต่ไม่เพียงแค่ไม่มีใครเข้าใจฉัน พวกพนักงานยังพยายามหยุดฉันจากการ 「หาความสนุก」 อีกด้วย——มันเกินไปจริงๆ!\nโอ้ว วันนี้เป็นวันพิเศษนะ เหมาะมากที่จะให้แส้ของฉันสัมผัสกับผิวที่อ่อนนุ่ม และได้ยินเสียงแห่งความเจ็บปวด... ถ้าวันนี้คุณว่าง ก็มาคุยกับฉันหน่อยดีไหม~?\n\nพันเดีย"
  },
  Mail_21478_Name = {
    Text = "เสียงของแส้.."
  },
  Mail_21478_Sender = {
    Text = "แพนเดีย"
  },
  Mail_21479_Desc = {
    Text = "<Big:การแสดงครบรอบปีของคาเซียจอมเวท จัดขึ้นเฉพาะวันนี้เท่านั้น!>\n\nเพื่อเป็นการขอบคุณผู้ชมทุกท่านสำหรับการสนับสนุนและให้กำลังใจมาโดยตลอด และเพื่อตอบแทนความสุขที่ทุกคนมอบให้ในอดีตที่ผ่านมา คาเซียจอมเวทจึงได้ตัดสินใจจัดการแสดงพิเศษครบรอบปีขึ้นในเวลา 20:00 น. ของคืนนี้ ณ ลานกลางมหาวิทยาลัยมิซากะ (ข้างรูปปั้นฟิลลิปส์) คืนนี้ คุณจะได้พบกับเวทีที่งดงามยิ่งกว่าที่เคย การแสดงที่เร้าใจยิ่งขึ้น และที่สำคัญที่สุด —— คือเวทมนตร์ที่น่าทึ่งจนคุณไม่อยากเชื่อสายตาตัวเอง! แม้กระทั่ง \"สมองแห่งมิซากะ\" จะต้องประทับใจกับเวทมนตร์ที่เหนือจินตนาการนี้ นี่คือคำรับรองจากคาเซียจอมเวท!\n\nโอกาสนี้หาได้ยาก จัดขึ้นเฉพาะคืนนี้เท่านั้น และไม่มีค่าใช้จ่ายใด ๆ! คาเซียจอมเวทรอนคุณอยู่ อย่าพลาดเด็ดขาด!\n\n<Small:PS: หากเกิดอาการจิตใจอ่อนล้า อารมณ์ซึมเศร้าระหว่างหรือหลังการแสดง คาเซียจอมเวทจะไม่รับผิดชอบใด ๆ ทั้งสิ้น>\n<Small:PPS: การโฆษณาใด ๆ ที่เกี่ยวข้องกับสมองแห่งมิซากะ จะขึ้นอยู่กับสถานการณ์จริงในขณะนั้น คาเซียจอมเวทขอสงวนสิทธิ์ในการตีความผลและรายละเอียดของรายการ>"
  },
  Mail_21479_Name = {
    Text = "การแสดงครบรอบของคาเซีย ปรมาจารย์แห่งเวทมนตร์！"
  },
  Mail_21479_Sender = {
    Text = "คาเซียห์"
  },
  Mail_21480_Desc = {
    Text = "เฮ้ วันนี้เป็นวันเกิดของฉัน ของขวัญล่ะ?\nอะไรนะ เธอลืมเตรียม...? ฮึ ก็อย่างที่ฉันคิดไว้เลย\nนี่ เอาปฏิทินเล่มนี้ไป มันเขียนวันเกิดของฉัน วันครบรอบวันสุดท้ายของฉัน วันแรกที่มาถึงมิซากะ และวันเทศกาลม้า วันขอบคุณพระเจ้า... วันทั้งหมดพวกนี้เราต้องเฉลิมฉลองด้วยกัน สรุปคือคราวหน้าห้ามลืมเด็ดขาด!\n\nถ้าเธอลืมอีกล่ะก็... ฉันก็คงทำอะไรเธอไม่ได้หรอก ฮึ แต่ยังไงก็ห้ามลืมเด็ดขาด\n\nอักกริปปา"
  },
  Mail_21480_Name = {
    Text = "เฮ้.."
  },
  Mail_21480_Sender = {
    Text = "อกริปปา"
  },
  Mail_21481_Desc = {
    Text = "ผู้พิทักษ์：\n\nฉันไม่อยากเขียนจดหมายฉบับนี้ แต่เอริกาดูเหมือนมีปัญหา ก่อนที่ฉันจะเขียนจบ เสียงเตือนของเธอดังไม่หยุด \nวันเกิดสำหรับฉันเป็นแค่วันที่ไร้ความหมาย โอกาสความสำเร็จของการทดลองไม่ได้สูงกว่าวันอื่น และดัชนีนอร์สของฉันก็ไม่เปลี่ยนแปลงในวันนี้ แต่รามอน่าดันยืนยันให้วันนี้เป็น 「วันพัก」 ของฉัน และจำกัดสิทธิ์เข้าห้องทดลองของฉัน \nฉันไม่มีที่ไป ดังนั้นวันนี้ฉันจะตรวจสอบรายงานที่คุณเคยส่งมาอย่างละเอียด \nโปรดมาที่ห้องเอกสารหลังอาหารเย็น ระวังอย่าพยายามนำเค้กเข้ามาในห้องเอกสาร เอกสารกระดาษนั้นเปราะบางมาก \n\nดอร์"
  },
  Mail_21481_Name = {
    Text = "หลังมื้อเย็น.."
  },
  Mail_21481_Sender = {
    Text = "ดอลล์"
  },
  Mail_22435_Desc = {
    Text = "ผู้พิทักษ์ที่รัก：\nตอนแรกที่เลือกอ่านบทกวีในช่วงเช้าที่แสงแดดเริ่มส่องในโรงเรียน เพราะคิดว่าช่วงเวลานี้คนเดินผ่านน้อยกว่า ทำให้สามารถดื่มด่ำกับโลกแห่งบทกวีได้ง่ายขึ้น ต่อมา ฉันก็ค่อยๆ หลงรักท้องฟ้าที่เริ่มสว่างในยามเช้า หยดน้ำค้างใสราวกับผลึก และเสียงนกร้องที่ไพเราะสดใส \nสิ่งที่ฉันไม่คาดคิดก็คือ มีคุณครูและนักเรียนหลายคนแอบติดตามฉัน และรวมกลุ่มเป็นชมรมคนรักบทกวีอย่างลับๆ วันนี้เป็นวันเกิดของฉัน พอดีกับดอก narcissus ในชมรมกำลังจะบาน พวกเขาจึงเตรียมจัดงานชื่นชมบทกวี โดยจะอ่านบทกวีพร้อมกับชมทิวทัศน์ในโรงเรียนร่วมกัน \nในสถานการณ์เช่นนี้ หวังว่าคุณจะมาชื่นชมด้วยกันนะคะ \n\nหนิงเฟย่า"
  },
  Mail_22435_Name = {
    Text = "การเชิญชวนไปงานอ่านบทกวี"
  },
  Mail_22435_Sender = {
    Text = "นิมเฟีย"
  },
  Mail_23897_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\n        ในอัปเดตเวอร์ชัน V1.0.21 เราได้ปรับเปลี่ยนรางวัลครั้งแรกสำหรับระดับความยาก「การสอบสวนดำเนินการ」ระดับยาก,     「การล่องเรือในจิตสำนึก」ระดับการต่อสู้ทั่วไปและยาก และ「ดินแดนไร้แสง」ช่องว่างการหมุนเวียน Ⅰ-Ⅳ ของแต่ละขอบเขต รายละเอียดของการปรับเปลี่ยนสามารถดูได้ใน「ประกาศการบำรุงรักษาออนไลน์ V1.0.21」\n        จากบันทึกการสอบสวนและการผ่านด่านก่อนหน้าของคุณ เราจะมอบรางวัลที่คุณไม่ได้รับก่อนหน้านี้ให้แบบครั้งเดียวเต็มจำนวนตามรางวัลที่ปรับเปลี่ยนแล้ว กรุณาตรวจสอบในเอกสารแนบ"
  },
  Mail_23897_Name = {
