  },
  Mail_24199_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพนับถือ：\n        ในอัปเดตเวอร์ชัน V1.0.24 เราได้เปิดใหม่สำหรับบทที่ห้าของ「การสอบสวนดำเนินการ」ที่เคยปิดชั่วคราวในเวอร์ชัน V1.0.16 ตามหลักการที่ยุติธรรม เราจะแจกค่าตอบแทนที่เหมาะสมตามการเปลี่ยนแปลงของรางวัลก่อนและหลังการปรับปรุง รวมถึงบันทึกการสอบสวนของผู้พิทักษ์แต่ละท่าน ตามบันทึกการสอบสวนของคุณ ค่าตอบแทนของคุณได้ถูกส่งไปยังไฟล์แนบแล้ว."
  },
  Mail_24199_Name = {
    Text = "V1.0.24 รางวัลชดเชยการเปิดใหม่ของบทที่ห้า"
