  },
  Mail_24200_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ: \n        ในอัปเดตเวอร์ชัน V1.0.24 เราได้เปิดใช้งาน「การสอบสวนดำเนินการ」บทที่ห้าอีกครั้ง ซึ่งถูกปิดชั่วคราวในเวอร์ชัน V1.0.16 โดยหลักการที่ยุติธรรม เราจะแจกจ่ายค่าชดเชยที่เหมาะสมตามการเปลี่ยนแปลงของรางวัลก่อนและหลังการปรับปรุง รวมถึงบันทึกการสอบสวนของผู้พิทักษ์แต่ละท่าน จากรายงานการสอบสวนของคุณ คุณไม่จำเป็นต้องได้รับค่าชดเชยในครั้งนี้"
