  },
  Mail_24202_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ:\n        ขอบคุณสำหรับการสนับสนุนและการรับรองเกม「คืนแห่งการลืมเลือน」เพื่อให้ผู้พิทักษ์ในมหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดีขึ้น เราขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อกรอกแบบสอบถามเสร็จสิ้นสามารถรับรางวัลได้.\n        <SurveyLink:「คลิกเพื่อกรอก」>\n        เราจะฟังข้อเสนอแนะจากผู้พิทักษ์ทุกคนอย่างจริงจัง ความคิดเห็นของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ!\n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
