  Mail_24280_Desc = {
    Text = "สวัสดี ผู้พิทักษ์：\nในการจัดอันดับการสอบสวนในความฝันลึกซึ้งเมื่อวานนี้ คุณได้อันดับที่ {s2} ใน 「{s1} อันดับ」 โดยมีหัวข้อการสอบสวนคือ 「{s3}」 ด้านล่างนี้เป็นรางวัลจากการจัดอันดับ กรุณารับรางวัลของคุณ"
