  Mail_24877_Desc = {
    Text = "ผู้พิทักษ์：\n\nวันเกิดของฉันทุกปี มักจะเป็นงานเลี้ยงสุดหรู แขกผู้มีเกียรติมากมาย ทุกคนสนุกสนาน\nแต่ครั้งนี้ ฉันกลับมีความคิดอื่นอยู่บ้าง——\nนั่งตำแหน่งเจ้าภาพมานาน บางทีก็อยากลองเป็นแขกดูบ้าง\nจะเป็นงานเลี้ยงสุดหรูอีกครั้ง หรือมื้ออาหารเย็นธรรมดา ก็ขึ้นอยู่กับเธอแล้ว ไงล่ะ?\nแต่ถ้าเลือกจัดงานเลี้ยงหรูอีกครั้ง อย่าเชิญพวกชนชั้นสูงเหล่านั้นนะ\nวันดีๆ แบบนี้ ฉันไม่อยากฝืนยิ้มให้ใคร\n\n<Del:หญิงชุดแดง>โซเรล"
