  Mail_24878_Desc = {
    Text = "เจ้านาย: \n\nวันนี้เป็นวันเกิดของลิลี่ อากริปปาบอกว่าจะ「ปาร์ตี้กันสุดเหวี่ยง」\nแต่ก่อนตอนที่แม่กับลิลี่ฉลองวันเกิดไม่ได้เป็นแบบนี้นะคะ แม่จะสวมหมวกแหลมให้ แล้วก็ปรบมือเป่าเทียนด้วยกัน\nลิลี่ไม่รู้ว่าทำแบบไหนถึงจะถูกต้อง ขอให้เจ้านายสั่งด้วยค่ะ \n\nลิลี่"
