  Mail_25148_Desc = {
    Text = "เรียน ผู้พิทักษ์ที่เคารพ:\n        ในการอัปเดต V1.1.0 รางวัลประจำสัปดาห์ของการเล่นหมากรุกเฟส(เบต้า) จะถูกถอดออก และแทนที่ด้วยการทดลองประจำสัปดาห์ ซึ่งจะมีความก้าวหน้าและรางวัลเดียวกับการทดลองประจำสัปดาห์ของความฝันลึกซึ้ง โดยยึดหลักการความเป็นธรรม เราจะชดเชยให้กับผู้พิทักษ์ที่ได้ปลดล็อคการเล่นหมากรุกเฟส(เบต้า) แต่ยังไม่เสร็จสิ้นหรือยังไม่ได้รับรางวัลประจำสัปดาห์นี้ และได้เข้าสู่เกมก่อนเวลา 5:00 น.(UTC+8) ของวันที่ 15 มกราคม โดยจะมอบไข่มุกหลอมละลาย ×1000 กรุณาตรวจสอบ."
  },
  Mail_25148_Name = {
    Text = "V1.1.0 การเล่นหมากรุกเฟส ของรางวัลชดเชยรายสัปดาห์"
