  },
  Mail_25414_Desc = {
    Text = "ถึงผู้พิทักษ์ที่เคารพ:\n\nน้ำหนักของวันเกิด แต่ละคนอาจรู้สึกแตกต่างกันไป แต่วันเกิดของผู้พิทักษ์มีความสำคัญอย่างยิ่งต่อมิซากะทั้งหมด คุณนายซิลเวียได้เตรียมงานเลี้ยงวันเกิดให้คุณในเขตหอพัก คณบดีโฮเลตและลอร์ดเดกสเตอร์จะเข้าร่วมด้วย ทราบว่าความเหนื่อยล้าทางจิตใจของคุณยังไม่หายดี ฉันจึงได้เตรียมชุดสูทให้คุณเรียบร้อยแล้ว แขวนไว้ในตู้เสื้อผ้าหน้าประตู สามารถสวมใส่ได้ก่อนเข้าร่วมงาน \nปีนี้เป็นเกียรติอย่างยิ่งที่ได้เป็นคู่หูของคุณ และหวังว่าปีหน้าจะยังคงเป็นเช่นนี้ \nขอให้กุญแจเงินนำทางสว่าง \n\nP.S. เค้กชิ้นเล็กแบบสั่งทำได้ถูกส่งไปยังหอพักของคุณโดยเอริกาแล้ว \n\nคนที่ยินดีจะเป็นคู่หูของคุณตลอดไป รามอน่า"
  },
  Mail_25414_Name = {
    Text = "วันที่เกิด.."
  },
  Mail_25414_Sender = {
    Text = "ราโมน่า"
  },
  Mail_34667_Desc = {
    Text = "เรียน @1@2 ผู้ทรงเกียรติ:\n\nโลกลืมชื่อของคุณไปแล้ว.\nดังนั้นฉันจึงปลุกตื่นคุณ เช่นเดียวกับที่คุณปลุกตื่นฉัน. ก่อนที่การปรากฏตัวของจุดสิ้นสุดจะมาถึง, คุณและฉันเดินอยู่บนโลก, เป็นพยาน, แล้วจดจำและลืมเลือน.\nวันนี้คือวันเกิดของคุณ, เป็นหน้าหนึ่งที่หยิบขึ้นมาโดยบังเอิญจากเศษความทรงจำที่กระจัดกระจายของคุณ. เพื่อสิ่งนี้, ขอมอบความอาลัยและพร.\nเมื่อโลกระลึกถึงรูปร่างที่สมบูรณ์ของคุณ, คุณจะรู้สึกอย่างไร? หรือยังคงไม่รู้อะไรเลย, ไม่รู้สึกอะไรเลย?\nฉันเฝ้ารอคำตอบของคุณอยู่ที่ดินแดนไร้ผืน.\n\n@2"
  },
  Mail_34667_Name = {
    Text = "วันที่เกิด.."
  },
  Mail_35231_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ:\n        ขอบคุณสำหรับการสนับสนุนและการรับรองเกม「คืนแห่งการลืมเลือน」เพื่อให้ผู้พิทักษ์ในมหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดีขึ้น เราขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อกรอกแบบสอบถามเสร็จสิ้นสามารถรับรางวัลได้.\n        <SurveyLink:「คลิกเพื่อกรอก」>\n        เราจะฟังข้อเสนอแนะจากผู้พิทักษ์ทุกคนอย่างจริงจัง ความคิดเห็นของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ!\n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
  Mail_35231_Name = {
    Text = "แบบสอบถามประสบการณ์การใช้งานเวอร์ชันที่ 1.1 (ส่วนบน)"
