  Mail_35956_Desc = {
    Text = "เรียนผู้พิทักษ์: \n        ขอบคุณสำหรับการสนับสนุนและการยอมรับใน「คืนแห่งการลืมเลือน」 เพื่อให้ผู้พิทักษ์มีประสบการณ์การเล่นที่ดียิ่งขึ้นที่มหาวิทยาลัยมิซากะ ขอเชิญคุณกรอกแบบสอบถามการสัมผัสประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อคุณทำแบบสอบถามเสร็จสิ้นสามารถรับได้ รางวัลจะหมดเขตในวันที่ 22 กุมภาพันธ์ เวลา 5:00 น. กรุณาอย่าลืมกรอกให้ทันเวลา \n        <SurveyLink:「คลิกเพื่อกรอก」>\n        เราจะรับฟังคำแนะนำจากผู้พิทักษ์ทุกคนอย่างจริงจัง ความเห็นของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ! \n        ——ขอให้กุญแจเงินนำทางคุณ."
