  Mail_36234_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ:\n        ขอบคุณสำหรับการสนับสนุนและการยอมรับใน「คืนแห่งการลืมเลือน」เพื่อให้ผู้พิทักษ์ที่มหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดีขึ้น เราขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อกรอกแบบสอบถามเสร็จสิ้นสามารถรับได้ แบบสอบถามจะปิดรับในเวลา 5:00 น. ของวันที่ 14 มีนาคม กรุณาอย่าลืมกรอกให้ทันเวลา.\n        <SurveyLink:「คลิกที่นี่เพื่อกรอก」>\n        เราจะรับฟังข้อเสนอแนะจากผู้พิทักษ์ทุกท่านอย่างจริงจัง ความคิดเห็นของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ!\n        ——ขอให้กุญแจเงินนำทางคุณ."
