  Mail_39548_Desc = {
    Text = "ผู้พิทักษ์ที่รัก：\n\nสำหรับชีวิตนิรันดร์ การเฉลิมฉลองวันเกิดอาจดูไม่จำเป็นนัก เมื่อเทียบกับแม่น้ำเวลาอันไม่มีที่สิ้นสุด ความทรงจำที่มนุษย์เรียกว่าน่าจดจำหรือยอดเยี่ยมของพวกคุณก็ดู...เล็กน้อยไปเสียหน่อย\nแต่พวกคุณกลับสร้างเทศกาลและงานเฉลิมฉลองมากมาย เพื่อรำลึกถึงสิ่งเหล่านี้ที่เรียกว่า「เล็กน้อย」— และแน่นอน นี่คือหนึ่งในเหตุผลที่ทำให้ฉันสนใจมนุษย์ พวกคุณช่างน่าเอ็นดูจริงๆ\nอย่างไรก็ตาม การพบกันระหว่างเรากับคุณไม่อาจนับรวมอยู่ในช่วงเวลา「เล็กน้อย」เหล่านั้นได้ เพราะคุณแตกต่างจากพวกเขา...และฉันเองก็เฝ้ารอที่จะเห็นว่าความ「แตกต่าง」นี้จะก่อให้เกิดพายุเช่นใดในอนาคต\nเอาล่ะ โปรดอภัยในความพูดมากของฉัน...เนื่องจากวันนี้เป็นวันเกิดของฉัน ฉันขอใช้สิทธิพิเศษของคนที่มีวันเกิดหน่อย\nส่วนสิ่งที่ฉันอยากให้คุณทำ ชู่...อย่าเพิ่งใจร้อน คำตอบอยู่ในห้องนอนของฉัน กรุณาไปคนเดียวในคืนนี้ตอนเที่ยงคืน\n\nวันดา"
