  Mail_39549_Desc = {
    Text = "วันนี้เป็นวันเกิดของคุณมอร์ฟี่——วันเกิดก็ควรจะมีงานเลี้ยงและงานเฉลิมฉลองสิ! \nพวกเจ้าหน้าที่ฝ่ายจัดการด้านหลังทำได้ดีอยู่นะ แต่พวกเขาไม่ค่อยเก่งเรื่องการแสดงละครเลยแถมยังปิดบังอะไรบางอย่างอยู่——ข้าเห็นพวกเขาแอบเอาเครื่องตกแต่งเค้กเข้าไปในคลังของระบบปลุกตั้งนานแล้ว ฮึ... เจ้าจะไม่ลงโทษพวกเจ้าหน้าที่พวกนั้นใช่ไหม? พวกเขาทำได้ดีจริงๆ เพียงแค่ไม่เก่งเรื่องซ่อนเซอร์ไพรส์เท่านั้นเอง... \nถึงตรงนี้ก่อนละกัน เหมือนจะมีใครบางคนกำลังตามหาข้าอยู่——หวังว่าพวกเขาจะไม่เอากระดาษสีมาป้ายใส่ตัวข้าจนเต็มนะ \nอ้อ แล้วตอนตัดเค้ก เจ้าจะอยู่ด้วยใช่ไหม? \n\nมอร์ฟี่"
