  Mail_44836_Desc = {
    Text = "เรียน ผู้พิทักษ์: \n        ในการอัปเดต V1.3.0 เราได้เพิ่มรางวัลสำหรับการชนะ 1 ครั้งและ 3 ครั้งในการทดสอบประจำสัปดาห์ของ「ความฝันลึกซึ้ง」เป็น: 「ใบรับรองตัวแทน」×1 สำหรับผู้พิทักษ์ที่ได้รับรางวัลข้างต้นก่อนการอัปเดต เราจะส่งใบรับรองตัวแทนในจำนวนที่เหมาะสมให้คุณ กรุณาตรวจสอบด้วย."
