  Mail_44837_Desc = {
    Text = "ผู้ส่งสารแห่งความซีดที่น่านับถือ:\n\nเด็กๆ หลายคนนำดอกไม้และขนมมาให้ฉันในวันนี้ ทำให้ฉันนึกขึ้นได้ว่า ก่อนยุคปฏิทินโบราณกว่าร้อยปี ฉันได้รับพรจากพระบิดา และได้รับชีวิตมาสู่โลกมนุษย์ในวันนี้ นั่นเป็นอดีตที่ไกลโพ้นมากแล้ว ความทรงจำในวัยเด็กของฉันเลือนลางไปเกือบหมด เหลือเพียงกลิ่นหอมของธูปในโบสถ์บอนโดซาที่ยังคงอยู่ในความคิดของฉัน ไม่จางหายไป แม้ว่าโบสถ์จะยังคงอยู่ แต่สูตรของธูปก็คงไม่ใช่สูตรเดิมอีกแล้ว\n\nขอโทษนะ การคร่ำครวญถึงฤดูใบไม้ผลิและความเศร้าในฤดูใบไม้ร่วงไม่ใช่จุดประสงค์ของการเขียนจดหมายของฉัน ฉันเตรียมงานชาร์จพักด้วยขนมที่เด็กๆ นำมา หวังว่าคุณจะมาแบ่งปันกับฉัน — ไม่ใช่เพื่อเฉลิมฉลองวันเกิดของฉัน แต่เพื่อเฉลิมฉลองทุกวันที่ชีวิตดำรงอยู่ และทุกวันที่ความหวังดำรงอยู่\n\nไม่ทราบว่าวันเกิดของคุณคือเมื่อไหร่? กรุณาบอกฉันหลังจากดื่มชาหนึ่งแก้วแล้ว\n\n\n\nเอลซัลวาดอร์"
