  Mail_44843_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\n        ในการอัปเดต V1.3.0 เราได้ถอดสิทธิพิเศษของ「หลักสูตรหลัก」ออก ได้แก่: ค่าประสบการณ์ผู้พิทักษ์ที่ได้รับใน「ดำดิ่งฝันมายา」และ「การประลองเฟส (beta)」เพิ่มเป็นสองเท่า เพื่อแสดงความเสียใจ เราจะมอบ「ค่าประสบการณ์ผู้พิทักษ์」× 240 ต่อวันเป็นค่าชดเชยให้แก่ผู้พิทักษ์ที่ซื้อ「หลักสูตรหลัก」ในรอบนี้ โดยจะให้ต่อเนื่องจนกว่าหลักสูตรประจำเทอมในรอบนี้จะสิ้นสุด กรุณาตรวจสอบรับของด้วย"
