  Mail_47305_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\nในการฝันลึกซึ้งเมื่อวานนี้ คุณได้ผ่านด่านระดับความยากสูงสุดที่「{s1}」.\nในการเล่นหมากรุกเฟสเมื่อวานนี้ คุณได้รับตำแหน่ง「{s2}」 แต่ยังไม่มีชัยชนะจากการเล่น.\nจากผลการท้าทายข้างต้น คุณจะได้รับรางวัลไข่มุกการหลอมกร่อน กรุณาตรวจสอบให้เรียบร้อย."
