  },
  Mail_47306_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\nในการดำดิ่งสู่ความฝันลึกซึ้งเมื่อวานนี้ คุณได้รับตำแหน่ง「{s1}」.\nในการเล่นหมากรุกเฟสเมื่อวานนี้ คุณได้รับตำแหน่ง「{s2}」 โดยไม่มีชัยชนะในการเล่นหมากรุกเฟส.\nจากผลการท้าทายข้างต้น คุณจะได้รับรางวัลเพิ่มเติมดังต่อไปนี้ กรุณาตรวจสอบให้แน่ใจ."
