  Mail_47307_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\nในการดำดิ่งสู่ความฝันลึกซึ้งเมื่อวานนี้ คุณได้รับตำแหน่ง「{s1}」.\nในการเล่นหมากรุกเฟสเมื่อวานนี้ คุณได้รับตำแหน่ง「{s2}」 และมีชัยชนะในการเล่น.\nจากผลลัพธ์ของการท้าทายเหล่านี้ คุณจะได้รับรางวัลเพิ่มเติมดังต่อไปนี้ กรุณาตรวจสอบ."
