    Text = "ผู้พิทักษ์ที่เคารพ:\nในการฝันลึกซึ้งเมื่อวานนี้ คุณได้ผ่านด่านระดับความยากสูงสุดคือ「{s1}」.\nในการเล่นหมากรุกเฟสเมื่อวานนี้ คุณได้รับตำแหน่ง「{s2}」 และมีชัยชนะ.\nจากผลลัพธ์ของความท้าทายดังกล่าว คุณจะได้รับรางวัลไข่มุกหลอมละลาย กรุณาตรวจสอบ."
