  Mail_48005_Desc = {
    Text = "ถึงผู้พิทักษ์ที่รัก:\n\n ขออภัยที่รบกวน หวังว่าเขียนของฉันจะไม่ทำลายอารมณ์ดีของคุณ ฉันไม่ค่อยเก่งในการเขียนนัก...\nเขียนจดหมายนี้เพื่อบอกคุณว่าดูเหมือนว่าวันเกิดของฉันใกล้เข้ามาแล้ว เพื่อสิ่งนี้ ฉันทำคุกกี้เล็ก ๆ บางชิ้น หวังว่าคุณจะได้ลองชิมดู.\nพูดตรง ๆ ฉันไม่แน่ใจว่าวันที่นี้ถูกต้องหรือไม่ หลังจากการติดเชื้อการย่อยสลาย ร่องรอยที่เกี่ยวกับการมีอยู่ของฉันค่อยๆ หายไป.\nคุณหนูตุ๊กตาถามฉันว่า รู้สึกอย่างไรเมื่อมองเห็นตัวเองถูกผู้คนลืมเลือน?\nมันยากที่จะบรรยาย... เหมือนยืนอยู่ในความมืดมิด ขอบแม่น้ำที่เปล่งประกาย ผู้คนต่างพูดคุยกันอยู่ฝั่งตรงข้ามของแม่น้ำ ในขณะที่พวกเขารีบร้อนเดินผ่านหน้าฉัน ฉันได้แต่เฝ้ามองพวกเขา แต่ไม่สามารถส่งเสียงใด ๆ ออกมาได้.\nมันเป็นความรู้สึกที่เหงาอย่างยิ่ง โชคดีที่คนเหล่านั้นไม่ได้รวมคุณอยู่ด้วย.\nอย่างน้อย คุณยังจำเรื่องราวของฉันได้ อยู่หรือเปล่า?\n\nเพิ่มเติม คุกกี้ 12 ชิ้นได้แนบมากับจดหมายนี้.\n\nเมสัน"
  },
  Mail_48005_Name = {
    Text = "ขออภัยที่รบกวน.."
