  Mail_48145_Desc = {
    Text = "เรียนผู้พิทักษ์:\nกิจกรรม「การรักษาหลายด้าน」ได้สิ้นสุดลงแล้ว ขณะนี้ระบบจะทำการรีไซเคิล「จิ๊กซอว์แห่งความทรงจำ」ที่เหลืออยู่ของคุณตามอัตราส่วนการแลกเปลี่ยนแบบไม่จำกัดของ「การวิเคราะห์บุคลิกภาพ」โปรดตรวจสอบให้แน่ใจว่าคุณได้รับของรางวัลเรียบร้อยแล้ว"
