  Mail_48157_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\nในการฝันลึกซึ้งเมื่อวานนี้ คุณได้ผ่านด่านความยากสูงสุดที่「{s1}」.\nในการเล่นหมากรุกเฟสเมื่อวานนี้ คุณไม่มีชัยชนะจากการเล่น.\nจากผลการท้าทายข้างต้น คุณจะได้รับรางวัลไข่มุกการหลอมกร่อนดังต่อไปนี้ กรุณาตรวจสอบให้แน่ใจว่าได้รับแล้ว."
