  Mail_48914_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ:\n        ขอบคุณสำหรับการสนับสนุนและการยอมรับต่อ「คืนแห่งการลืมเลือน」 เพื่อให้ผู้พิทักษ์ได้มีประสบการณ์การเล่นที่ดียิ่งขึ้นที่มหาวิทยาลัยมิซากะ เราขอเชิญคุณกรอกแบบสอบถามการสัมผัสประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณที่คุณให้ความร่วมมือ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล หากกรอกแบบสอบถามเสร็จสิ้นก็สามารถรับได้ แบบสอบถามจะสิ้นสุดในวันที่ 28 ตุลาคม เวลา 9:00 น. กรุณาอย่าลืมกรอกให้ทันเวลา.\n        <SurveyLink:「คลิกเพื่อกรอก」>\n        เราจะรับฟังข้อเสนอแนะจากผู้พิทักษ์ทุกคนอย่างจริงจัง ความคิดเห็นของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ!\n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
  Mail_48914_Name = {
    Text = "แบบสอบถามประสบการณ์การใช้งาน V1.6.3"
  },
  Mail_48914_Sender = {
    Text = "มิซากะ ฝ่ายบริหารโรงเรียน"
  },
  Mail_48915_Desc = {
    Text = "เรียนผู้พิทักษ์: \n        ขอบคุณสำหรับการสนับสนุนและการยอมรับใน「คืนแห่งการลืมเลือน」 เพื่อให้ผู้พิทักษ์ที่มหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดียิ่งขึ้น เราขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อคุณกรอกแบบสอบถามเสร็จสิ้นสามารถรับได้ ร่วมตอบแบบสอบถามก่อนเวลาปิดรับ 30 กันยายน เวลา 9:00 น. กรุณาอย่าลืมกรอกให้ทัน \n        <SurveyLink:「คลิกเพื่อกรอก」>\n        เราจะฟังความคิดเห็นจากผู้พิทักษ์ทุกคนอย่างตั้งใจ ข้อเสนอแนะของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ! \n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
