  Mail_50344_Desc = {
    Text = "ต้นกล้าน้อย:\n\nสายลมพัดพากลิ่นอายของเธอมา หอมหวานกว่าตอนที่เราเพิ่งรู้จักกันเสียอีก\nเธอเติบโตขึ้นในความรักของฉัน ได้รับการหล่อเลี้ยงจนสุกงอม...เหมือนผึ้งกับน้ำผึ้งเลยล่ะ\nวันนี้เป็นวันพิเศษ มาพบกับฉันได้ไหม?\nฉันทำตามที่เธอขอ รอคอยอย่างว่าง่ายมานานแล้วนะ...ถึงเวลาที่ควรจะให้รางวัลฉันบ้างแล้ว เธอว่าจริงไหม?\n\nไทอิส"
  },
