  Mail_53149_Desc = {
    Text = "ข้าได้ตัดสินใจแล้วว่าจะมอบชีวิตที่เหลือของแต่ละวันให้กับคนๆ นั้น... เพื่อเป็นการไถ่โทษสำหรับการกระทำอันโง่เขลาของข้า \nร่างกายที่ตื้นเขินนี้ 「วันเกิด」ไม่มีความหมายใดๆ ไม่คู่ควรแก่การเอ่ยถึง \nวันนี้ไม่แตกต่างจากวันใดในอดีตหรืออนาคต ข้าจะเดินทางไปยังโบสถ์เช่นเคย \nแต่ หากท่านต้องการให้ข้าออกจากโบสถ์ในวันนี้ ในฐานะแขกของมิซากะ ข้าจะไม่ขัดต่อความประสงค์ของท่านแน่นอน \nหากท่านอยากเห็นการสวดมนต์ของข้า ก็ยินดีต้อนรับท่านมา... ด้วยความเคารพอย่างสูงสุด ยินดีต้อนรับเสมอ \n\nมิลียาห์ม"
  },
