  Mail_54803_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ：\n        ในการอัปเดต V1.5.1 เราได้เพิ่มรางวัล「เงินใจ」สำหรับระดับผู้พิทักษ์ 21-80 ใน「บันทึกการเติบโต」 และได้เพิ่มรางวัล「เข็มกลัดสอบสวน」× 1000 สำหรับการทำภารกิจในขั้นตอนความชำนาญดินแดนⅠ~Ⅴ สำหรับผู้พิทักษ์ที่ได้รับรางวัลข้างต้นครบถ้วนก่อนการอัปเดต เราจะส่งรางวัล「เงินใจ」หรือ「เข็มกลัดสอบสวน」ที่เกี่ยวข้องให้แก่ท่าน กรุณาตรวจสอบด้วย."
