  Mail_55168_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「ก่อนที่ฤดูใบไม้ผลิจะเหี่ยวเฉา」สิ้นสุดแล้ว ในขณะนี้จะทำการแปลง「บทกวีที่เต็มไปด้วยความสุข」,     「บทกวีที่เศร้าสร้อย」และ「บทกวีแห่งความเสียใจ」ที่เหลืออยู่ของผู้พิทักษ์ตามอัตรา 200 ชิ้นต่อ「คูปองกุหลาบทอง」× 5000 กรุณาตรวจสอบด้วยค่ะ."
