  },
  Mail_56101_Desc = {
    Text = "ผู้พิทักษ์{Male=คุณ,Female=คุณ}：\n\nในช่วงเช้ามืดของวันนี้ ดอกกุหลาบหนึ่งได้บานอย่างสวยงามท่ามกลางเสียงนกร้องในฤดูใบไม้ผลิแรก \nมันควรจะเป็นกิ่งไม้ที่ยังตูม แต่มันกลับบานในวันวาเลนไทน์ ในวันที่ฉันเกิด และในฤดูกาลที่ไม่ใช่ของมัน \nฉันระลึกถึงสีไค ทุกปีในวันเกิดนี้ ถนนในสีไคมักจะเต็มไปด้วยความคึกคัก ฉันได้ยินเสียงดอกไม้บาน ได้ยินคำพูดรักที่ทำให้คนหน้าแดง แต่ฉันไม่ได้มีโอกาสสัมผัสพวกมันมานานแล้ว...จนกระทั่งวันนี้ \nคุณเชื่อเรื่องความบังเอิญไหม ผู้พิทักษ์? ฉันคิดว่าความบังเอิญเป็นภาษาหนึ่ง และดอกกุหลาบคือการเล่นสำนวน วันนี้ ในสวนที่หลากหลายของมิซากะ ดอกกุหลาบนี้ได้บานสะพรั่ง กลีบดอกของมันแผ่กว้างอย่างสง่างาม เปรียบเสมือนบทกวีที่ทำให้ใจสั่นไหว \nดังนั้น วันนี้ ผู้พิทักษ์...คุณยินดีที่จะมาชมการบานของดอกกุหลาบนี้กับฉันหรือไม่? \nทั้งฉันและดอกไม้ ต่างก็รอคอยการมาถึงของคุณ \n\nออร์ล่า"
  },
