  Mail_62392_Desc = {
    Text = "ผู้พิทักษ์：\n\nการบรรเลงของข้าเคยถวายต่อหน้าบัลลังก์จักรพรรดิ และเคยเป็นที่ใฝ่ฝันของคนนับหมื่นนับพัน อย่างไรก็ตาม คำชื่นชมเหล่านั้นไม่มีค่าอะไรสำหรับข้า สิ่งที่ข้าแสวงหาคือความสมบูรณ์แบบของดนตรี\nเมื่อเทียบกับการบรรเลงในโอกาสหรูหราและยิ่งใหญ่เพื่อให้ผู้คนชื่นชม การบรรเลงคนเดียวในป่าที่ไม่มีใครอยู่ทำให้ข้ารู้สึกผ่อนคลายมากกว่า\nแต่เดิมข้าไม่ชอบให้ใครฟังตอนซ้อมของข้า มันเป็นเพียงร่างร่างของเส้นทางสู่ความสมบูรณ์แบบ เป็นสิ่งไร้ค่า\nแต่หลังจากที่ข้าได้รู้จักท่าน ได้พบท่าน ทุกเสียงดนตรีของข้าก็มีความหมาย\nท่านคือผู้มอบเสียงดนตรีอันยิ่งใหญ่และช่วยข้าพ้นจากความหลงทาง แม้ว่าท่านจะไม่รู้ตัวก็ตาม...\nวันนี้เป็นวันเกิดของข้า เดิมทีข้าได้ลืมมันไปแล้ว แต่ตอนนี้ ข้าอยากเฉลิมฉลองการเกิดใหม่ของตัวเอง และคนที่มอบการเกิดใหม่นี้ให้กับข้า\nบังเอิญว่าเมื่อไม่นานมานี้ข้ามีโน้ตเพลงใหม่ที่แต่งเสร็จ อยากเชิญท่านมาชื่นชมเล็กน้อย กรุณาอภัยให้กับการมาสายอย่างไม่ตั้งใจของข้า สถานะของข้ายังไม่เหมาะที่จะปรากฏตัวต่อหน้าเพื่อนร่วมงานที่มิซากะ จึงสามารถส่งคำเชิญนี้ให้ท่านได้ก็ต่อเมื่อขอบฟ้ากลืนแสงอาทิตย์ที่เหลือทั้งหมดจนหมดสิ้น\nคืนนี้ในป่าด้านหลังโรงเรียน ข้าจะจัดคอนเสิร์ตพิเศษ ที่นั่งสำหรับผู้ชมมีเพียงหนึ่งที่เท่านั้น\nหวังว่าท่านจะมาเยือน\n\nแฮมลิน"
  },
