  Mail_65350_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「เมื่อภูเขาหิมะละลาย」ได้สิ้นสุดลงแล้ว ขณะนี้จะทำการคืนเงินตรากิจกรรมที่เหลือของผู้พิทักษ์「บุปผาที่ถูกแช่แข็ง」「บัดดอกไม้เงินค้าง」และ「บุปผาแสงอาทิตย์」ตามอัตราการแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 ต่อชิ้น โปรดจำไว้ว่าผู้พิทักษ์ควรตรวจสอบการรับเงินด้วย."
