  Mail_65442_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「ประตูวันเซียง」สิ้นสุดแล้ว ปัจจุบันจะทำการคืนเงินสกุลเงินกิจกรรมที่เหลืออยู่「Poin Akhir」ในอัตรา 40 คูปองกุหลาบต่อการแลกเปลี่ยน โปรดจำไว้ให้ดีนะครับ/ค่ะ."
