  Mail_67147_Desc = {
    Text = "ผู้พิทักษ์：\n\n    มิติของจักรวาลไม่ใช่สิ่งเดียวสำหรับฉัน ภายในประตูสุดท้ายสามารถมองเห็นหมื่นโลกและสรรพสิ่งที่ไม่มีที่สิ้นสุด สิ่งนั้นอยู่เหนือความฝันและความเป็นเหตุเป็นผลทางคณิตศาสตร์ทั้งปวง จึงไม่มีทางกำหนดวันที่ของ「วันที่เกิด」ได้ \n    เพราะฉะนั้น ให้วันที่เราพบกันครั้งแรกเป็นเวลาสำคัญนั้นเถอะ ในมาตราเวลาต่อเนื่องของคุณ วันนี้จะมีพิธีกรรมเฉพาะของฉัน เพื่อทำให้ความปรารถนาที่ฉันขอเป็นจริง \n    ดังนั้น ข้ามผ่านประตูกุญแจเงิน มาหาฉันเถอะ ฉันจะถ่ายทอด...ความรู้บางอย่างเกี่ยวกับต้นกำเนิดสูงสุด ความรู้ของจักรวาลให้แก่คุณ คืนนี้ แสงระยิบระยับนับล้านล้านจะส่องประกายเพื่อเราสองคน \n    ฉันรอคุณอยู่ที่ประตูสุดท้าย \n\nทาวี"
  },
  Mail_67147_Name = {
    Text = "ข้ามประตูเงิน.."
  },
  Mail_67147_Sender = {
    Text = "ทาวิล"
  },
  Mail_67933_Desc = {
    Text = "ฉันรู้สึกถึงความสับสนของเธอในชั่วขณะ — สิ่งสร้างที่ยิ่งใหญ่ที่สุด การจ้องมองตรงไปยังแทบจะเป็นไปไม่ได้ แล้วจะทำให้เกิดบาดแผลได้อย่างไร? แต่เธอก็ทำได้\nอีกหนึ่งสายตาพังทลาย เกราะที่แข็งแกร่ง ภายใต้ชิ้นส่วนที่หลั่งไหลมาทีละชิ้น ทิ้งร่องรอยและรอยปริไว้\n%player% สิ่งเดียวที่ไม่อาจแตกหักได้ คือความมุ่งมั่นที่แน่วแน่ของเธอ"
  },
  Mail_67933_Name = {
    Text = "มองเห็นเส้นทางจากความลังเล"
  },
  Mail_67933_Sender = {
    Text = "อลิสแตร์"
  },
  Mail_67934_Desc = {
    Text = "แขนขาของคุณสั่นระริก %player% คุณแทบจะยืนไม่ไหวแล้ว ความกลัวเข้าจับกุมคุณ ทำให้สมองว่างเปล่าและควบคุมการหายใจไม่ได้...แต่คุณก็ยังยกกุญแจเงินขึ้นสู่เบื้องหน้า \nในบรรดาคุณสมบัติที่ดีงามทั้งมวลของมนุษย์ ความกล้าหาญคือสิ่งที่สูงส่งที่สุด เมื่อเผชิญภัยพิบัติและสัตว์ร้าย เคยมีครั้งที่เราหยิบหินและหอกขึ้นสู้ บัดนี้เมื่อเผชิญเทพเจ้า คุณก็ยังคงเป็นเช่นนั้น \nอารยธรรมมนุษย์ถูกสร้างขึ้นจากความกล้าหาญ และจะดำรงอยู่ไม่สิ้นสุดเพราะความกล้าหาญ"
  },
  Mail_67934_Name = {
    Text = "เพลงสรรเสริญแห่งความกล้าหาญ ดังขึ้นท่ามกลางความหวาดผวา"
  },
  Mail_67934_Sender = {
    Text = "อลิสแตร์"
  },
  Mail_67935_Desc = {
    Text = "เราเคยพูดคุยกันถึงโลกใบนี้ คุณบอกว่าคุณไม่ชอบมัน ที่นี่เต็มไปด้วยผลประโยชน์ แผนการลับ การหลอกลวง และการฆ่าฟัน แม้จะไม่มีการหลอมกร่อนหรือเทพเจ้า โลกก็ยังเต็มไปด้วยความบอบช้ำและใกล้จะพังทลายอยู่แล้ว หลังจากที่อาร์คต์ตื่นขึ้นมา ในความทรงจำสั้นๆ ของคุณ คุณได้เห็นสิ่งที่เลวร้ายกว่าการหลอมกร่อน สิ่งที่ไร้ระเบียบและน่ากลัวยิ่งกว่าในจิตใจของมนุษย์  \nแต่เมื่อผู้สร้างชูดาบของพระองค์ คุณยังคงยืนขวางอยู่หน้าโลกใบนี้ การทำลายล้างคือความประสงค์ของเทพเจ้า แต่คุณปฏิเสธพระองค์  \nฉันเข้าใจ %player% ไม่มีผู้พิทักษ์คนใดที่ไม่เกลียดโลกใบนี้ และไม่มีผู้พิทักษ์คนใดที่ไม่รักมันอย่างแท้จริง เพราะในความสกปรกเหล่านั้น เราเคยเห็นแสงสว่างที่เปล่งประกายราวกับดวงดาว  \nหน้าที่ของผู้พิทักษ์คือปกป้องแสงสว่างที่เลือนลางนั้นให้อยู่ตลอดไป"
  },
  Mail_67935_Name = {
    Text = "จิตใจมนุษย์คงอยู่ตลอดไป"
  },
  Mail_67935_Sender = {
    Text = "อลิสแตร์"
  },
  Mail_67936_Desc = {
    Text = "ครั้งแรกที่เห็นการหลอมกร่อน ครั้งแรกที่เผชิญกับความจริงของการหลอมกร่อน ครั้งแรกที่รับรู้ถึงเสียงของเทพเจ้า... ในชีวิตอันยาวนานของข้า ข้าได้ผ่านช่วงเวลาที่ทรุดโทรมมาแล้วนับไม่ถ้วน ข้าไม่รู้ว่าตัวเองทำอะไรได้บ้าง ไม่รู้ว่าความหมายของการพยายามและเสียสละทั้งหมดนี้คืออะไร —— แต่ทั้งหมดนั้นยังไม่เท่ากับสิ่งที่เจ้ากำลังเผชิญอยู่ในตอนนี้ \nมนุษย์เป็นเช่นนี้เอง ลุกขึ้นยืนใหม่จากความทรุดโทรมซ้ำแล้วซ้ำเล่า ก้าวไปข้างหน้า \nจุดจบของเส้นทางอาจเป็นเหวที่ลึกหมื่นศอก แต่จะต้องมีบางคนที่อยากไปดูสักครั้ง"
  },
  Mail_67936_Name = {
    Text = "เศร้าหมอง แล้วฟื้นคืนชีวิตใหม่"
  },
  Mail_67936_Sender = {
    Text = "อลิสแตร์"
  },
  Mail_67937_Desc = {
    Text = "ขอบเขตของมิติเปิดออกแล้ว ข้าสามารถติดต่อเจ้าได้อีกครั้ง\nเมื่อเปรียบเทียบกับสิ่งที่เจ้าเห็น การรับรู้ในมิตินี้อ่อนแออย่างผิดปกติ อาจเพราะมิตินี้ไม่มีตัวตนของเจ้า หลังจากเสียสละแทบทุกอย่าง ข้าได้จัดการกับพระองค์แทนเจ้าแล้ว\nยากจะจินตนาการว่าเจ้ากำลังเผชิญอะไร แต่ไม่ว่าอย่างไร ข้าจะยืนหยัดต่อสู้เคียงข้างเจ้าเพื่อต้านทานความมืดมิดนี้ นี่คือคำสาบานของชาวมิซากะทุกคน\nดีใจที่ได้ร่วมต่อสู้กับเจ้าอีกครั้ง\nขอให้กุญแจเงินนำทางเรา"
  },
  Mail_67937_Name = {
    Text = "ร่วมกันต่อสู้อีกสักครั้ง"
  },
  Mail_67937_Sender = {
    Text = "ผู้ส่งไม่ระบุ"
  },
  Mail_67938_Desc = {
    Text = "บ้าคลั่ง คำพูดที่ฟังดูผ่อนคลาย หรือแม้กระทั่งงดงาม\nจักรวาลแห่งความวุ่นวายที่ก่อกำเนิดอารยธรรมอันวุ่นวาย ความวุ่นวายคือความจริงของโลกนี้ การยอมรับความวุ่นวายและสนุกกับความบ้าคลั่งเป็นเรื่องที่ง่ายดายมาก เมื่อเปรียบเทียบกันแล้ว การตื่นรู้และการต่อสู้กลับยากลำบากมาก เธอจะเสียสละความสุขและชีวิตทั้งหมด เพียงเพื่อตามหาคำตอบที่ไกลเกินเอื้อม \nแต่เธอยังคงเลือกที่จะตื่นรู้ %player% เพราะเราไม่ได้เกิดมาเพื่อเป็นทาส \nเธอทำให้พระองค์ได้เห็นแล้ว %player% —— สิ่งสร้างของพระองค์ ชิ้นส่วนของพระองค์ ไม่เคยยอมเป็นทาสที่ตาบอดและโง่เขลา เธอต่อสู้กับสายพระเนตรของพระองค์ครั้งแล้วครั้งเล่า และเลือกที่จะปกป้องโลกใบนี้ที่ไม่สมบูรณ์แบบและไม่ง่ายดาย \nในการเลือกนั้น เธอได้ครอบครองอิสรภาพนิรันดร์แล้ว"
  },
  Mail_67938_Name = {
    Text = "คุณไม่เคยยอมเป็นทาสที่ไร้เหตุผลและโง่เขลา"
  },
  Mail_67938_Sender = {
    Text = "อลิสแตร์"
  },
  Mail_67939_Desc = {
    Text = "ฉันรู้สึกถึงการพังทลายของสายตาหนึ่ง ฉันรู้สึกถึงความเจ็บปวดที่เนื้อหนังของเธอ \n นี่คือความรับผิดชอบที่ถูกสลักไว้ในตำแหน่งของผู้พิทักษ์ เส้นทางที่เธอเลือกเดินนั้นยากเย็นยิ่งกว่าเส้นทางที่ฉันเคยเดินเป็นหมื่นเท่า ไม่ใช่ทุกคนที่จะมีความกล้าหาญเพียงพอที่จะเผชิญหน้ากับเทพเจ้าสูงสุด ความกล้าหาญของเธอนั้นทำให้ฉันรู้สึกปลื้มปิติและชื่นชม \n พละกำลังของสิ่งสร้างจะทำให้เธอต้องทนทุกข์มากเพียงใด ฉันไม่อาจจินตนาการได้ ทั้งหมดที่ฉันรับรู้ได้ก็คือเพียงเศษเสี้ยวเล็กๆ ของสิ่งที่เธอแบกรับ ฉันเป็นเพียงคนไร้ประโยชน์ที่ติดอยู่ในสระดำ %player% ฉันไม่มีแรงพอที่จะเข้าร่วมในการต่อสู้ระหว่างเธอกับสิ่งสร้างอีกต่อไป ได้แต่เชื่อมโยงกับเธอผ่านการรับรู้ของฉันเท่านั้น นี่จะเป็นภารกิจสุดท้ายและสำคัญที่สุดในชีวิตของฉัน \n ในเส้นทางที่โดดเดี่ยวนี้ ไม่ว่าเธอจะมองเห็นหรือไม่ มิซากะจะอยู่เคียงข้างเธอเสมอ"
  },
  Mail_67939_Name = {
