  Mail_67940_Desc = {
    Text = "ข้าได้ยินเสียงกระซิบของเจตจำนงสูงสุด——อารยธรรมอันยิ่งใหญ่ ความสุขและทุกข์ของมนุษย์ ผู้คนนับไม่ถ้วนที่รายล้อมและห่างไกลจากท่าน ทุกสิ่งไม่เคยมีอยู่จริง \n ในคืนและวันอันนับไม่ถ้วนในสระดำ ภาพนี้ทำให้ข้ารู้สึกหวาดกลัว ต้นไม้หยั่งรากลงดิน จากนั้นเติบโตขึ้นเพื่อรับแสงอาทิตย์——ความทรงจำ ความทรงจำคือดินแดนของเรา เป็นที่ที่เราเติบโต ยืนหยัด และในที่สุดจะกลับไปยังจุดนั้น ข้าหวาดกลัวการสูญเสียผืนดินและลอยอยู่ในความว่างเปล่า โดยไม่มีจุดเริ่มต้นหรือจุดจบ \n ขอบคุณท่าน %player% ข้าคิดว่าข้าได้เป็นพยานในการต่อสู้ครั้งยิ่งใหญ่ นี่คือการต่อสู้ระหว่างมนุษย์กับเทพเจ้า นี่คือการต่อสู้ระหว่างการปกป้องและการทำลาย \n นี่คือการต่อสู้ระหว่างการจดจำและการลืมเลือน \n ท่านทำสำเร็จแล้ว %player% ท่านได้ทำในสิ่งที่ไม่มีใครกล้าจินตนาการ ท่านได้รับพละกำลังที่ไม่มีใครเทียบได้จากการจดจำ ท่านใช้พละกำลังนี้เพื่อต่อสู้เพื่อการจดจำ \n ท่านได้พบดวงอาทิตย์ของท่านเองในดินแดนโบราณนี้แล้ว"
