  Mail_68825_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「การฟื้นคืนชีพของพระราชาเทพ」สิ้นสุดแล้ว ขณะนี้จะทำการแปลงสกุลเงินกิจกรรมที่เหลืออยู่ของผู้พิทักษ์「ความคิดเหนื่อยล้า」,     「ความคิดเศร้าหมอง」และ「ความคิดที่เต็มไปด้วยความสุข」ตามอัตราแลกเปลี่ยนแต่ละรายการเป็น「คูปองกุหลาบทอง」× 40 กรุณาจำไว้และตรวจสอบให้ดี."
