  Mail_68898_Desc = {
    Text = "ที่รักของข้าพเจ้าที่สุดแสนจะที่สุด: \n\nในฐานะแม่บ้านมัลติฟังก์ชั่น คาเรนสามารถจำวันสำคัญต่างๆ ของผู้ใหญ่ได้มากมาย ตั้งแต่วันเลี้ยงฉลอง วันเกิด วันครบรอบ ไปจนถึงวันที่ซื้อสัตว์เลี้ยงครั้งแรก โดยไม่มีทางผิดพลาดแน่นอน แต่สำหรับคาเรนเอง วันพิเศษที่ควรจดจำมีเพียงวันนี้วันเดียวเท่านั้น \nเมื่อนานมาแล้ว คาเรนเคยเป็นสาวใช้อยู่ในพระราชวัง ตอนที่ขอเชฟให้เหลือขนมหวานที่คนชั้นสูงกินไม่หมดมาเป็นเค้กวันเกิดครั้งแรก กลับโดนดุอย่างหนัก เชฟคนนั้นโยนเค้กใส่หน้าของข้าพเจ้า ตอนนั้นข้าพเจ้าคิดว่า เค้กนี่อร่อยจริงๆ ข้าพเจ้าต้องหาเจ้านายที่ดีกับข้าพเจ้าให้เจอ เพื่อที่จะได้กินเค้กทุกวันเกิด \nตอนนี้ข้าพเจ้ามีคุณนายโซเรลที่สง่างามและใจดี และท่านเจ้านายที่แสนดีอย่างท่าน ความปรารถนาในอดีตก็ได้เป็นจริงแล้ว! แต่คนเรามักจะโลภมากขึ้น... ไม่สิ ต้องเรียกว่าเจริญเติบโตขึ้น ตอนนี้ความปรารถนาของข้าพเจ้าคือ ทุกวันเกิดอยากอยู่ข้างๆ ท่านเจ้านาย และถ้าได้ของขวัญที่ระยิบระยับทุกปีก็คงจะดีไม่น้อย \nหลังจากฟังมาขนาดนี้ ท่านคงจะเตรียมไว้ให้ข้าพเจ้าแล้วใช่ไหมคะ ใช่ไหมคะ? \n\nสาวใช้ของท่านที่ถ่อมตนตลอดกาล \nคาเรน"
  },
  Mail_68898_Name = {
    Text = "ทุกปีก็แบบนี้.."
