  Mail_68898_Sender = {
    Text = "คาเรน"
  },
  Mail_68899_Desc = {
    Text = "ต้นกล้า: \n\nการได้เห็นคุณเติบโตมาโดยตลอด ทำให้ฉันมั่นใจมากขึ้นว่า การเลือกคุณและช่วยเหลือคุณเป็นสิ่งที่ถูกต้องที่สุดที่ฉันเคยทำ \nฉันรู้สึกถึงความยินดีของการเก็บเกี่ยว ความไว้วางใจและความรักที่หล่อเลี้ยงทุกอย่างได้มอบผลตอบแทนที่หอมหวานแก่ฉัน คุณมอบให้ฉันความหวังและอนาคต \nตอนนี้ฉันสามารถปล่อยวางความยึดมั่นในเรื่องการสืบพันธุ์ และหันไปเพลิดเพลินกับผลไม้แห่งความรักที่อยู่นอกเหนือจากนั้น \nโลกใบนี้อาจไม่ต้องการราชินีอาลันอีกแล้ว แต่บางทีอาจจะมีที่ว่างสำหรับความปรารถนาของผู้หญิงธรรมดาคนหนึ่งที่อยากมีคู่รักเคียงข้างในวันเกิดของเธอ \nเหมือนกับคู่รักทั่วไป ที่ไปซื้อวัตถุดิบร่วมกัน ทำอาหารอร่อยๆ ด้วยกัน และอาจมีสิ่งอื่นที่ฉันยังไม่เคยลอง ดังนั้นที่รัก คุณจะช่วยฉัน เพื่อให้วันเกิดนี้เป็นวันเกิดที่อบอุ่นและเรียบง่ายได้ไหม? \n\nไทอีส"
  },
  Mail_68899_Name = {
    Text = "ชีวิตที่เรียบง่าย.."
  },
  Mail_68899_Sender = {
    Text = "ทาอิส"
  },
  Mail_68900_Desc = {
    Text = "ผู้พิทักษ์：\n\nคาเซียคือปรมาจารย์ด้านการแสดงที่ยอดเยี่ยมที่สุดในโลก สามารถเลียนแบบสีหน้าได้อย่างสมบูรณ์แบบทุกอารมณ์ แต่อารมณ์ของมนุษย์นั้นเป็นปริศนาของโลกที่ไม่ว่าจะพยายามแค่ไหนก็ไม่มีวันเข้าใจได้เลย \nฉันถามผู้คนมากมาย แต่ไม่มีใครสามารถอธิบายหลักการของอารมณ์ได้ จนกระทั่งฉันถามดอร์ เธอบอกฉันว่ามีวิชาหนึ่งเรียกว่าจิตวิทยา แม้จะไม่อาจเข้าใจอารมณ์ได้โดยตรง แต่ถ้าเรียนจิตวิทยาให้ดี ก็จะสามารถเข้าใจทฤษฎีของอารมณ์ทั้งหมดได้ \nนี่มัน... น่าสนใจจริงๆ! หรือว่าปัญหาที่คาเซียสงสัยมานานจะได้รับการคลี่คลายเสียที? \nเอ้อ กลับมาเรื่องเดิม ฉันมาบอกคุณว่า สัปดาห์นี้ฉันจะเข้าร่วมชั้นเรียนจิตวิทยากับห้องของคุณ คาเซียตัดสินใจเป็นเพื่อนร่วมโต๊ะของคุณแล้วนะ เนื้อหาที่ฉันขาดไปก่อนหน้านี้ คุณต้องช่วยฉันทบทวนด้วยล่ะ เพื่อนร่วมโต๊ะ~ \nอ้อ ใช่แล้ว เผลอลืมบอกไป วันนี้เป็นวันเกิดของฉัน ตรงนี้ฉันควรจะดีใจ และคุณก็ควรจะดีใจด้วยใช่ไหม? \nถ้าเป็นเรื่องที่น่ายินดีมากๆ มาสนุกกันให้เต็มที่ในโรงเรียนเถอะ ฉันจะทำให้โรงเรียนกลายเป็นสถานที่สวยงามเหมือนความฝันเลย! \n\nคาเซีย"
  },
  Mail_68900_Name = {
    Text = "จิตวิทยา.."
  },
  Mail_68900_Sender = {
    Text = "คาเซียห์"
  },
  Mail_68901_Desc = {
    Text = "ผู้ส่งสารสีซีดที่น่านับถือ：\n\nขอบคุณสำหรับความช่วยเหลือและการสนับสนุนของคุณตลอดปีที่ผ่านมา ความจริงใจของคุณต่อผู้อื่นนั้นสูงส่งตามคำสอนของพระบิดา แม้โอกาสพบกันไม่บ่อย แต่ทุกครั้งที่ได้เจอคุณ มันทำให้ฉันรู้สึกเหมือนได้พบเพื่อนเก่าที่รู้จักมานาน ทำให้ฉันรู้สึกอบอุ่นใจ\nวันเกิดนี้อาจไม่มีอะไรพิเศษ แต่เป็นเหตุผลที่ดีในการพบปะในฐานะเพื่อน และนอกเหนือจากคุณแล้ว ฉันไม่สามารถคิดถึงใครคนอื่นที่จะใช้เวลาร่วมกันในวันนี้ได้\nถ้าคุณสนใจ ฉันอยากเชิญคุณลองสัมผัสกับงานอดิเรกใหม่ล่าสุดของฉัน — การตกปลา แน่นอนว่าไม่ใช่เพื่อการทำอาหารและรับประทาน แต่เพียงเพื่อเพลิดเพลินกับการรอคอยอย่างสงบของขวัญที่โชคชะตาจะมอบให้ ฉันอยากแบ่งปันความรู้สึกสงบแบบนี้กับคุณ ในธรรมชาติ นั่งเงียบๆ ริมทะเลสาบ\nเพื่อนเก่าหนึ่งคน คันเบ็ดสองอัน วันนี้คงจะยอดเยี่ยมที่สุดแล้ว\n\nเอลซัลวาดอร์"
  },
  Mail_68901_Name = {
    Text = "ตกปลาใหม่..."
  },
  Mail_68901_Sender = {
    Text = "ซัลวาดอร์"
  },
  Mail_68902_Desc = {
    Text = "เจ้าของ：\n\nในวันเกิดปีนี้ ไอจิสและเจนกินได้ให้กระดิ่งลมแก้วที่หน้าตาคล้ายออรีตาแก่ฉัน\nฉันแขวนมันไว้ที่หน้าต่างในห้อง เมื่อลมพัดผ่าน มันจะส่งเสียงที่ไพเราะ ทำให้ฉันนึกถึงตอนที่แม่เคยโอบอุ้มฉันไว้ข้างหน้าต่าง และเล่าเรื่องราวให้ฟังอย่างอบอุ่น\nไม่ต้องเป็นห่วงหรอกเจ้าของ แม้ว่าฉันจะคิดถึงแม่ทุกวัน แต่เพราะมีเจ้าของและทุกคนอยู่เป็นเพื่อน ลิลลี่จึงไม่รู้สึกเหงา\nตอนนี้ลิลลี่เรียนรู้ที่จะอ่านเรื่องราวเองแล้ว ในยามเย็นเมื่อแสงแดดสีส้มอ่อนๆ สาดส่องเข้ามาในบ้าน ส่องลงบนกระดิ่งลม และสร้างเงาสะท้อนเป็นลวดลายเคลื่อนไหวที่ละมุนละไมบนหน้าหนังสือ ทำให้ห้องอบอวลไปด้วยความอบอุ่น\nลิลลี่ชอบมากที่จะนั่งเหม่อในช่วงเวลานี้ มองดูเมฆและกระดิ่งลมใต้แสงอาทิตย์ยามเย็น รู้สึกว่ามันงดงามเหลือเกิน\nหากเจ้าของมีเวลาวันนี้ ก็ลองมาเหม่อลอยพร้อมกับลิลลี่ดูนะ\n\nลิลลี่"
  },
  Mail_68902_Name = {
    Text = "กระดิ่งแก้ว.."
  },
  Mail_68902_Sender = {
    Text = "ลิลลี่"
  },
  Mail_68903_Desc = {
    Text = "เจ้าหนู:\n\nแม้ว่าวันพิเศษนี้จะถูกกำหนดขึ้นเพื่อเป็นเกียรติแก่มนุษย์คนนั้น แต่ฉันต้องยอมรับว่า วันลดราคาเป็นกลยุทธ์การขายที่มีความน่าสนใจอย่างมากสำหรับลูกค้าและผู้ค้า \nครั้งสุดท้ายที่เป็นวันเกิดของฉัน ยอดสั่งซื้อในร้านค้าเล็กๆ ของฉันเกือบเทียบได้กับยอดขายครึ่งปีในช่วงปกติ โดยเฉพาะสินค้าลดราคาพิเศษที่ฉันนำมาใช้ในการเฉลิมฉลองถูกแย่งซื้อจนหมด ควรจะบอกว่าลูกค้าในมิซากะดูแลกิจการของฉันดีเกินไป หรือแม้แต่นักสืบที่รอบคอบและระมัดระวังก็ไม่อาจต้านทานแรงจูงใจจากส่วนลดได้ \nอย่างไรก็ตาม เพื่อให้ความสุขแบบ win-win ดำเนินต่อไป ในปีนี้งานเลี้ยงวันเกิดของฉันจะยังคงมีกิจกรรมลดราคา ซึ่งมีเพียงปีละครั้ง โปรโมชั่นใหญ่มาก รีบมาจับจองก่อนหมดนะ! จำไว้ว่าให้ช่วยฉันโปรโมตเรื่องนี้ในมิซากะด้วย สำหรับการจดจำที่ง่าย ให้เรียกวันนี้ว่าวัน Double Ten ก็แล้วกัน \nนอกจากนี้ ฉันได้แอบเก็บของสนุกๆ ไว้ให้คุณบ้าง ต้องมาพบฉันเร็วๆ นะ \n\nดาฟเดล"
  },
  Mail_68903_Name = {
    Text = "วันลดราคา.."
  },
  Mail_68903_Sender = {
    Text = "ดาฟโฟดิล"
  },
  Mail_68904_Desc = {
    Text = "ด้วยพรแห่งโชคชะตา ข้าพเจ้าผู้พิทักษ์แห่งมหาวิทยาลัยมิซากะ เจ้านายผู้ทรงปัญญาและคุณธรรม: \nขอให้ท่านโชคดี! \nหากกล่าวว่าความปรารถนาสูงสุดของอัศวินทุกคนคือการติดตามเจ้านายผู้ยิ่งใหญ่แล้ว ชีวิตอัศวินของข้าพเจ้าก็ไม่มีอะไรต้องเสียใจอีกต่อไป \nในชีวิตของข้าพเจ้า นอกจากโชคชะตาที่ดีแล้ว ก็ยังเต็มไปด้วยโศกนาฏกรรมและความเศร้าโศกจากการต่อสู้อย่างทรหด ข้าพเจ้าทราบว่าหลายคนในมิซากะเคยแสดงความเห็นใจต่อข้าพเจ้า \nยังไม่ต้องเอ่ยถึงเพียงแค่การเปรียบเทียบความทุกข์ยาก ในมิซากะก็มีผู้โชคร้ายมากมายอยู่แล้ว ในโลกที่เต็มไปด้วยความทุกข์นี้ การเสียเลือดเนื้อเพื่อปกป้องไม่ใช่เรื่องที่ควรเศร้าเสียใจ ตรงกันข้าม ไม่ว่าในอดีตหรือปัจจุบัน ข้าพเจ้ารู้สึกภาคภูมิใจและพร้อมเสมอที่จะเสียสละชีวิตนี้ \nแต่ท่านลอร์ดโรแทนบอกว่าข้าพเจ้าดูเคร่งเครียดกังวลจนดูเหนื่อยเกินไป ให้ข้าพเจ้าเล่นสนุกๆ ในวันเกิดนี้ และได้เรียกเจนกินมาสอนข้าพเจ้าเล่นเกม โดยบอกว่าต้องการให้ข้าพเจ้าหวนคืนวัยเด็ก \nต้องยอมรับว่าเมื่อยังเยาว์ ข้าพเจ้าหมกมุ่นกับการฝึกฝน แทบไม่มีโอกาสได้เล่นอะไรแบบนี้ เกมที่ว่ากันว่าเด็กอายุห้าขวบสามารถเชี่ยวชาญได้นั้นกลับยากมากสำหรับข้าพเจ้า ดูเหมือนว่านอกเหนือจากวิถีแห่งอัศวินแล้ว ยังมีสิ่งอื่นอีกมากมายที่ข้าพเจ้าต้องเรียนรู้ \nหากท่านเจ้านายว่างในวันนี้ ไม่ทราบว่าท่านจะมาเล่นกับพวกเรากันไหม ข้าพเจ้าเห็นว่าเจนกินเริ่มเบื่อหลังจากชนะติดต่อกันสิบเกมแล้ว หากท่านเจ้านายอยู่ที่นี่ คงจะสร้างการแข่งขันที่น่าตื่นเต้นได้อย่างแน่นอน \n\nโอกีล"
  },
  Mail_68904_Name = {
    Text = "เกมที่ยาก.."
