  Mail_68904_Sender = {
    Text = "โอเกียร์"
  },
  Mail_68905_Desc = {
    Text = "เฮ้：\n\nได้ปฏิทินเล่มนั้นมาแล้ว ปีนี้คุณคงไม่ลืมวันเกิดของท่านเจ้าแห่งเขาวงกตผู้สูงศักดิ์แน่ \nข้าอนุญาตให้คุณเข้ามาในห้องของข้าเพื่อมอบของขวัญ และในวันนี้จงปรนนิบัติข้าอย่างสุดใจ \nเช่น การแปรงฟัน ล้างหน้า เปลี่ยนเสื้อผ้า รับประทานอาหาร และการทำความสะอาดห้อง เปลี่ยนผ้าปูที่นอน พวกคุณเรียกสิ่งนั้นว่าอะไรนะ งานทำความสะอาดใหญ่! \nใช่ งานทำความสะอาดใหญ่นี้มอบให้คุณทำทั้งหมดเลย ข้าเบื่อหน่ายกับงานบ้านพวกนี้เต็มที วันนี้ไม่ว่าอย่างไรก็ตาม ข้าจะกลับไปสู่ช่วงเวลาที่เคยอยู่ในกรุงโรม ใช้ชีวิตสบายๆ โดยไม่ต้องลงมือทำอะไรเอง \nวันนี้ไม่ว่าใครก็ตามอย่าหวังจะให้ข้าทำงานเองแม้แต่น้อย อย่าหวังเลย! \n\nอักกริปปา"
  },
  Mail_68905_Name = {
    Text = "ย้อนกลับไปในอดีต.."
  },
  Mail_68905_Sender = {
    Text = "อกริปปา"
  },
  Mail_68906_Desc = {
    Text = "ผู้พิทักษ์：\n\nเวลาช่างผ่านไปรวดเร็วจริงๆ ไม่คิดเลยว่าชีวิตที่เคยคิดว่าจะดำเนินไปจนตาย ตอนนี้ฉันแทบจะไม่ระลึกถึงมันอีกแล้ว\nตอนนี้ตัวฉันได้เข้าใจเค้กเล็กๆ ทุกชนิดในโรงอาหารอย่างทะลุปรุโปร่งแล้ว ไม่ว่าจะกดดันพวกพ่อครัวพวกนั้นแค่ไหน พวกเขาก็ไม่สามารถทำอะไรใหม่ๆ ออกมาได้อยู่ดี\nดังนั้น ในปีใหม่นี้ แผนที่อาหารอร่อยของฉันจะต้องขยายให้กว้างขึ้นและไกลขึ้น โดยตั้งเป้าหมายเล็กๆ ไว้ก่อน นั่นคือกินเค้กจากร้านทุกร้านในลอนดีเนี่ยนให้ครบ\nส่วนงานวิ่งเต้นต่อคิวอันทรงเกียรตินั้น ก็ยังคงมอบหมายให้คุณเหมือนเดิม! การได้รับความไว้วางใจจากตัวฉัน คุณก็ไม่จำเป็นต้องดีใจจนเกินไป เพียงแค่ขอบคุณและสรรเสริญนามของผู้ดีเช่นฉันก็พอ\nแต่ถึงอย่างไรก็ตาม พวกพ่อครัวพวกนั้นก็ยังมีความจริงใจอยู่บ้าง จากการที่พวกเขากระซิบกระซาบกันอย่างลับๆ ฉันได้ยินมาว่าพวกเขาเตรียมเค้กขนาดใหญ่สิบชั้นไว้—ฮะ พวกเขายังคงแย่มากในการปกปิดความประหลาดใจ\nแม้ว่าไอเดียจะค่อนข้างซ้ำซาก แต่อาจจะเป็นไปได้ว่าในงานวันเกิดครั้งนี้ ฉันจะเชิญคนเพิ่มขึ้นอีกหน่อย เช่น เพื่อนใหม่ที่ได้เจอตลอดปีที่ผ่านมา\nในฐานะเพื่อนคนแรกของฉันในมิซากะ ฉันอนุญาตให้คุณเป็นคนตัดเค้กชิ้นแรกแทนฉัน\n\nมอร์ฟี่"
  },
  Mail_68906_Name = {
    Text = "เค้กสิบชั้น.."
  },
  Mail_68906_Sender = {
    Text = "เมอร์ฟี่"
  },
  Mail_68907_Desc = {
    Text = "ผู้พิทักษ์ที่รัก：\n\nคุณที่ฉลาดหลักแหลม คงจะทราบข้อมูลนี้จากแฟ้มเอกสารอัศจรรย์ของมิซากะแล้ว——วันนี้ เป็นวันที่ควรจดจำในชีวิตของ「นักสืบผู้โชคดี」\nการเกิด การชนะเกมแบล็คแจ็คครั้งแรก การคว้าชัยในการแข่งม้าครั้งที่หนึ่งร้อย การไขคดีฆาตกรรมในห้องปิดตายครั้งแรก และความพ่ายแพ้ที่นำมาซึ่งความตาย——ทุกอย่างเกิดขึ้นในวันที่ 6 มิถุนายน อันแสนมหัศจรรย์นี้\nดังนั้น คุณอยากเล่นไพ่บริดจ์แบบสองคนกับฉันสักเกมไหม? ทำให้วันนี้กลายเป็นวันที่น่าจดจำยิ่งขึ้น คุณว่าไง?\n\nเลค"
  },
  Mail_68907_Name = {
    Text = "มาเล่นกันสักเกมไหม?"
  },
  Mail_68907_Sender = {
    Text = "ไรเกอร์"
  },
  Mail_68908_Desc = {
    Text = "จดหมายฉบับนี้ไม่ใช่คำทักทาย แต่เป็นคำเตือน——อย่าพยายามควบคุมฉัน อย่าพยายามใส่กุญแจมือให้ฉัน \n ฉันเป็นของตัวเองเท่านั้น \n ฉันไม่เหมือนคนที่หน้าตาเหมือนฉัน ที่ยังคงมีความหวังอันไร้เดียงสาต่อคนอื่นและโลกใบนี้ \n\n ฉันจะฆ่าใครก็ตามที่พยายามเป็น“เจ้านาย”ของฉัน พูดแล้วทำ \n\n H"
  },
  Mail_68908_Name = {
    Text = "ฉันเป็นของ.."
  },
  Mail_68908_Sender = {
    Text = "เฮลอต: ตรวนสีชาด"
  },
  Mail_68909_Desc = {
    Text = "ผู้พิทักษ์：\n\nบางทีฉันอาจจะเคยเล่าให้คุณฟังเกี่ยวกับความชื่นชอบในน้ำของฉัน ถ้าเทียบกับโลกมนุษย์ที่วุ่นวาย โลกใต้น้ำนั้นเงียบสงบและสงบสุขมาก\nฉันเคยลอยตัวอยู่ระหว่างสาหร่ายและปะการัง และเคยมีบทสนทนากับฝูงปลา เมื่ออยู่ไกลจากผิวน้ำมากขึ้น สีสันใต้น้ำก็จะยิ่งลึกซึ้ง และเมื่อถูกผลักดันอย่างนุ่มนวลโดยคลื่นน้ำ มองขึ้นไปยังท้องฟ้าจากก้นทะเล แสงและเงาที่พรำเพริดนั้นสร้างสีสันที่ชวนหลงใหล เป็นภาพทิวทัศน์ที่สวยงามที่สุดในใจฉัน\nคุณรู้ไหม? บางสัตว์ทะเลสามารถจำรูปลักษณ์ของคนได้ เมื่อคุณกลับมาเยือน “เพื่อน” เหล่านี้จะเข้ามาต้อนรับอย่างอบอุ่น เช่น หมึกน้อยแสนฉลาดตัวหนึ่ง และปลาทะเลสีเหลืองอ่อนอีกตัวหนึ่งที่ฉันรู้จัก\nในวันเกิดนี้ ฉันคิดถึงโลกใต้น้ำอีกครั้ง ไม่ทราบว่าคุณยินดีที่จะดำน้ำกับฉันหรือไม่ ฉันหวังเป็นอย่างยิ่งที่จะแบ่งปันความสงบเงียบนี้ รวมถึงเพื่อนๆ ที่มหัศจรรย์ของฉันให้กับคุณ\n\nหนิงเฟย่า"
  },
  Mail_68909_Name = {
    Text = "โลกใต้น้ำ.."
