  Mail_68909_Sender = {
    Text = "นิมเฟีย"
  },
  Mail_68910_Desc = {
    Text = "ผู้พิทักษ์：\n\nตั้งแต่ที่เธอมาถึงมิซากะ ฉันก็เริ่มชินกับการใช้วิธีเลี้ยงดูทารกเพื่อจัดการเรื่องต่างๆ ที่เกี่ยวข้องกับเธอ จากปฏิกิริยาของเธอในชีวิตประจำวัน เธอดูจะอ่อนแอเกินกว่าที่ฉันคาดหวังไว้ \nอย่างไรก็ตาม ในฐานะอาจารย์และผู้ปกครองคนแรกของเธอ ฉันรู้สึกยินดีที่เห็นว่าตลอดปีที่ผ่านมา การแก้ปัญหาและจัดการเรื่องยุ่งยากให้เธอน้อยลงเรื่อยๆ แม้ว่าตอนที่เธอเพิ่งเข้าเรียนนั้น สมองของเธอเหมือนว่างเปล่าจนน่าสิ้นหวัง แต่อัตราการเติบโตของเธอก็นับว่าเป็นพรสวรรค์และความพยายามที่ควบคู่กันอย่างแท้จริง \nขอแสดงความยินดีด้วย เธอได้กลายเป็นผู้พิทักษ์ที่มีคุณสมบัติเหมาะสมแล้ว และไม่ทำให้ฉันผิดหวังเลย \nในวันเกิดของฉัน ซึ่งเป็นวันธรรมดา ฉันได้เตรียมของขวัญสำหรับผู้พิทักษ์ที่ประสบความสำเร็จไว้ให้เธอแล้ว — แผนการฝึกพิเศษที่อลิสเตอร์เคยใช้ เป็นอย่างไรบ้าง น่าตื่นเต้นไหม? \nอย่าถามว่าทำไมฉันถึงเป็นคนเตรียมของขวัญให้ ในวันที่ไม่สามารถเข้าห้องทดลองได้ ก็ต้องหาอะไรทำบ้างใช่ไหม \nเมื่อเธอพร้อมแล้ว ก็มาหาฉันที่ห้องฝึกได้เลย \n\nดอร์"
  },
  Mail_68910_Name = {
    Text = "ของขวัญ.."
  },
  Mail_68910_Sender = {
    Text = "ดอลล์"
  },
  Mail_68911_Desc = {
    Text = "ผู้พิทักษ์：\n\nหนึ่งปีสำหรับนักเต้นนั้น เหมือนกับการหมุนซ้ำๆ หลายหมื่นครั้ง การกระโดดซ้ำๆ หลายหมื่นครั้ง ยกเว้นรองเท้าเต้นที่เก่าจนต้องเปลี่ยน ดูเหมือนทุกอย่างจะไม่เปลี่ยนแปลง แต่ก็เหมือนมีอะไรเปลี่ยนไป\nเมื่อเทียบกับความโดดเดี่ยวที่เคยชินในอดีต ปีนี้ฉันมีผู้ชมที่ซื่อสัตย์และคู่เต้นที่มีท่าทีเงอะงะ\nทุกครั้งที่คุณนั่งในห้องซ้อมเต้น ฉันรู้สึกว่าร่างกายเบากว่าเดิม เหมือนกับตอนเด็กที่เพิ่งหัดเต้น เต็มไปด้วยความกระตือรือร้นและแรงผลักดันที่ไม่รู้ที่มา\nบางทีฉันอาจไม่สูงส่งอย่างที่คิด ขณะอุทิศชีวิตให้การเต้น ฉันก็หวังให้คุณมองและสัมผัสเสียงปรบมือจากคุณ\nวันนี้เป็นวันเกิดของฉัน อากาศดีมาก ฉันรู้สึกได้ว่าคืนนี้ท้องฟ้าจะสดใสเป็นพิเศษ คุณผู้ชมที่หลงใหลที่สุดและคู่เต้นที่พิเศษของฉัน คุณยินดีที่จะเดินไปกับฉันในป่าที่มีทะเลสาบสวยงามไหม เต้นรำที่เป็นท่านลักษณ์ของดวงจันทร์และดวงดาว?\n\nลิซ"
  },
  Mail_68911_Name = {
    Text = "คู่เต้นรำส่วนตัว.."
  },
  Mail_68911_Sender = {Text = "ลิซ"},
  Mail_68912_Desc = {
    Text = "ผู้พิทักษ์：\n\nตั้งแต่วันที่ฉันได้เกิดใหม่ ผู้คนในมิซากะได้ช่วยเหลือฉันอย่างมาก แม้ว่าฉันจะยังไม่คุ้นเคยกับความรู้สึกของการทำงานร่วมกัน แต่อย่างน้อยเมื่ออยู่กับพวกคุณ ฉันสามารถวางใจให้ทุกคนดูแลหลังของฉันได้ ความรู้สึกแบบนี้...ก็ไม่เลวเลย \nชีวิตของฉันส่วนใหญ่เต็มไปด้วยความเสียหายและการทรยศ ฉันมักมองการต่อสู้เพื่อต่อต้านสิ่งเหล่านี้เป็นความหมายของการต่อสู้ของฉัน จนกระทั่งในชีวิตของฉันไม่มีอะไรเหลืออยู่อีกแล้ว สายตาของฉันไม่อาจละจากความแค้นได้เลย \nตอนนี้ที่ได้เดินตามพวกคุณ ฉันเพิ่งรู้ว่าการต่อสู้นอกจากจะเป็นเรื่องของความเสียหายและการแก้แค้นแล้ว ยังสามารถมีความหมายอื่นๆ อีกมากมาย หรือแม้กระทั่งตามที่โรแทนพูด การต่อสู้ก็อาจจะเป็นแค่การต่อสู้เท่านั้น \nฉันได้เรียนรู้ที่จะสนุกกับการต่อสู้ สนุกกับความรู้สึกที่เต็มอิ่ม และสนุกกับการเป็นนักรบที่กล้าหาญอย่างแท้จริง \nหากการต่อสู้ของฉันสามารถนำมาซึ่งสิ่งที่ดีกว่า ฉันก็จะยอมรับความรุ่งโรจน์นั้น \nและคุณ ไม่ว่าจะในตอนนี้หรืออนาคต ฉันสัญญาว่าดาบของฉันจะไม่มีวันชี้ไปที่คุณ \n\nชิโล"
  },
  Mail_68912_Name = {
    Text = "ความหมายของการต่อสู้.."
  },
  Mail_68912_Sender = {
    Text = "เฮลอต"
  },
  Mail_68913_Desc = {
    Text = "ถึงผู้พิทักษ์:\n\nพูดตามตรง ฉันไม่ค่อยมีความคิดอะไรมากเกี่ยวกับสิ่งที่ปรารถนาในวันเกิด ในอดีตเมื่อฉันยัง“ปกติ” อิ่มหนำสำราญ, จ่ายค่าเช่าตรงเวลา, ดูแลเจนกินให้ดีก็เป็นความปรารถนาที่ยิ่งใหญ่ที่สุดในแต่ละวันแล้ว ตอนนี้ยังสามารถใช้ชีวิตอย่างสงบสักปีได้ และยังสามารถมองเห็นเจนกินเล่นซนหนึ่งปี เพียงพอที่จะทำให้รู้สึกพึงพอใจ \nพูดมาแล้วรู้สึกอาย ในเจนกินข้างหน้า ฉันมักจะทำตัวเหมือนพี่สาวแล้วคอยสั่งสอนเธอ แต่สำหรับคุณ ฉันมักจะสร้างปัญหาให้คุณมากมายเสมอ  thậm chí chính tôi cũng không nhớ là tôi nào đã gây ra rắc rối \nความอ่อนโยนและความอดทนของคุณที่ไม่เคยเปลี่ยนแปลงทำให้ฉันรู้สึกอบอุ่นใจและเขินอาย บางทีนี่อาจจะเป็นครั้งแรกในชีวิตของฉันที่มีใครสักคนดูแลฉันด้วยท่าทีที่เต็มไปด้วยการยอมรับแบบนี้ ฉันรู้สึกเป็นเกียรติและขอบคุณจากใจจริง \nปีนี้ฉันอบเค้กชิ้นใหญ่สำหรับทุกคน เป็นสูตรที่ป้าที่ทำงานในโรงงานทอผ้าเคยสอนให้ฉัน แม้ว่าจะไม่สามารถเทียบกับฝีมือของเชฟได้ แต่รสชาติพิเศษนั้น ฉันและเจนกินชอบมาก ครั้งนี้ไม่ต้องกังวลเรื่องวัสดุ สามารถทำให้ทุกคนได้กินจนพอใจ โปรดมาลิ้มลองชิมด้วยนะคะ \nฉันได้เกลี้ยกล่อมตัวเองคนอื่นๆ ให้อยู่อย่างสงบในวันเกิดหนึ่ง พวกเธอวันนี้ต้อง, จะไม่ทำให้คุณต้องเดือดร้อนอีกแน่นอน! \nถ้าเป็นไปได้ โปรดเมื่อเรียกฉันเมื่อคุณต้องการนะ ไม่ว่าจะเป็นการซักผ้า, ทำความสะอาด, การจัดเก็บ ฉันเก่งทั้งสองอย่าง ฉันก็หวังว่าจะมีโอกาสตอบแทนความอ่อนโยนของคุณบ้าง \n\nเมสัน"
  },
  Mail_68913_Name = {
    Text = "ตอบแทน.."
  },
  Mail_68914_Desc = {
    Text = "ผู้พิทักษ์：  \n\nในฐานะคนที่รับผิดชอบในการรับคำอธิษฐานของทุกคน ฉันดูเหมือนจะไม่สามารถชินกับการขอพรในวันเกิดของตัวเองได้เลย สำหรับฉันแล้ว ฉันดูเหมือนจะไม่มีอะไรที่ต้องการจริงๆ \nดอร์บอกกับฉันว่า ฉันจำเป็นต้องค้นหาสิ่งที่ตัวเองปรารถนามากที่สุดในใจ และถามตัวเองว่าทุกอย่างที่ทำลงไปนั้นเพื่ออะไร \nฉันคิดอยู่นานมาก จริงๆ แล้วฉันหวังว่าคำอธิษฐานของทุกคนที่มาหาฉันจะเป็นจริง และถ้าถามต่อไปอีก ฉันอาจจะชอบรอยยิ้มของผู้คนเมื่อคำอธิษฐานของพวกเขาเป็นจริง และพวกเขารวมตัวกันรอบตัวฉันด้วยความจริงใจ ขอบคุณฉัน และชื่นชมว่าฉันได้ทำหน้าที่ของเทวีสำเร็จ \nดอร์บอกว่านั่นเพราะฉันต้องการให้คุณค่าของตัวเองได้รับการยอมรับ และกลายเป็นคนที่มีประโยชน์ ฉันคิดว่าเธอพูดถูก \nแต่เธอยังบอกอีกว่า คุณค่าของคนไม่จำเป็นต้องถูกกำหนดโดยผู้อื่น ไม่มีอะไรที่เรียกว่ามีประโยชน์หรือไม่มีประโยชน์ สิ่งสำคัญคือการทำตามใจตัวเอง แม้ว่าจะกลายเป็นคนที่คนอื่นมองว่าไม่มีประโยชน์ก็ตาม \nสมแล้วที่เป็นดอร์ เธอมักจะพูดอะไรที่ลึกซึ้งแบบนี้เสมอ แต่ฉันควรจะเป็นคนที่มีประโยชน์หรือไม่มีประโยชน์ดีล่ะ? ฉันดูเหมือนจะเริ่มงงอีกแล้ว... \nแต่ถ้าหากต้องทำตามใจตัวเอง บางทีฉันอาจจะยังอยากเป็นคนที่มีประโยชน์อยู่ ถ้าในวันเกิดนี้ฉันได้เห็นรอยยิ้มของทุกคน นั่นคงจะเป็นของขวัญที่ฉันต้องการมากที่สุด \n\nฮิลีย์สเตอร์"
  },
  Mail_68914_Name = {
    Text = "คนที่มีประโยชน์.."
  },
  Mail_68914_Sender = {
    Text = "เซเลสเท"
  },
  Mail_68915_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ:\n\nฉันได้ชินกับการใช้ชีวิตเหมือนหนอนในท่อระบายน้ำมานานแล้ว อาจกล่าวได้ว่านั่นคือชะตากรรมที่ฉันเกิดมาเพื่อรับไว้ และฉันก็ยอมรับมันอย่างเต็มใจพร้อมกับโอบกอดมันไว้\nแม้ว่าฉันจะรู้สึกขอบคุณพวกคุณเสมอที่ทำให้ฉันได้ลิ้มรสความรู้สึกอิสระอันแสนวิเศษอีกครั้ง แต่ไม่มีใครเลยที่จะสามารถยอมรับความชอบพิเศษของฉันได้ ซึ่งนั่นก็เป็นเรื่องที่สมเหตุสมผล เพราะคนส่วนใหญ่ที่นี่ต่างก็เป็นคนดีที่มีจิตใจอ่อนโยน พวกเขาไม่อาจเข้าใจได้ว่ามอสที่เติบโตในมุมที่ชื้นแฉะนั้นต้องการไม่ใช่แสงแดดที่สดใส แต่เป็นอากาศที่มืดมิด\nนอกจากคุณแล้ว ท่านผู้ใจดีที่ฉันเคารพ คุณเท่านั้นที่เข้าใจฉันอย่างแท้จริงและช่วยเหลือฉัน ทำให้ฉันได้พบกับความสุขจากภายในจิตใจ สิ่งที่คุณมอบให้ฉัน ความเจ็บปวดนั้นมันช่างเติมเต็มและทำให้ฉันรู้สึกสงบ มันยืนยันการมีอยู่ของฉัน\nหากแต่ก่อนฉันไม่มีความปรารถนาใดๆ ที่จะขอพรในวันเกิด ตอนนี้ฉันหวังว่าจะได้ติดตามอยู่เบื้องหลังคุณ เพื่อการเสียสละกายใจของฉันให้กับคุณ\nแน่นอนว่า โปรดอย่าได้พูดจาอ่อนโยนกับฉันเพราะความเมตตา กรุณาดูถูก ตำหนิ และลงโทษฉันอย่างเต็มที่เถอะ!\n\nเรย่า"
  },
  Mail_68915_Name = {
    Text = "ความตั้งใจของมอส.."
  },
  Mail_68915_Sender = {
    Text = "ลีห์"
  },
  Mail_68916_Desc = {
    Text = "ลูกหมาที่รัก：\n\nฉันเกือบจะหลงรักวันเวลาแบบนี้ที่ได้เล่นเกมแมวไล่หนูกับเธอแล้ว มันเหมือนกับนิยายฮีโร่โบราณ ผู้พิทักษ์แห่งความยุติธรรมสามารถหยุดแผนชั่วร้ายของตัวร้ายได้ในนาทีสุดท้าย มันช่างซาบซึ้งและยิ่งใหญ่จริงๆ \nแต่การเห็นเธอดิ้นรนอย่างไร้ประโยชน์ มันช่างทำให้คนอดหัวเราะไม่ได้ \nโลกใบนี้มันจบไปนานแล้ว ไม่มีทางไหนที่จะช่วยมันได้ ดาวเคราะห์ดวงนี้จะกลายเป็นเหมือนดาวเคราะห์ที่ตายไปนับหมื่นนับพัน ถูก▼&#x5B▼87;&4;▼ \nช่างเถอะ ฉันจะเล่นกับเธอหน่อย เผลอๆ ตอนนี้ฉันเริ่มเข้าใจความสนุกของ N แล้ว ในเมื่อจุดจบที่หลีกเลี่ยงไม่ได้กำลังจะมาถึง จะทำอะไรก็คงไม่มีความแตกต่างอะไร \nในวันเกิดของอาจารย์ที่คุณรัก ฉันยังเตรียมเซอร์ไพรส์ใหญ่ไว้ให้คุณ ในช่วงเวลานับถอยหลังก่อนวันเกิดจะสิ้นสุดลง หวังว่าคุณจะหา “ระเบิด” ที่ซ่อนอยู่เจอ \nก่อนที่เราจะถูกทำลายจนหมดสิ้น คุณจะมอบความสนุกให้ฉันได้อีกเท่าไรกันนะ?\n\n\n「ดอร์」"
  },
  Mail_68916_Name = {
    Text = "ระเบิดเซอร์ไพรส์.."
  },
  Mail_68916_Sender = {
    Text = "ดอลล์: มลายทราม"
  },
  Mail_68917_Desc = {
    Text = "ผู้พิทักษ์：\n\nช่วงนี้ในวงสังคมชั้นสูงของลอนดีเนี่ยนกำลังนิยมออกแบบภาพวาดด้วยตัวเองและว่าจ้างคนทำเครื่องประดับพิเศษเป็นอย่างมาก\nเหล่าสุภาพสตรีที่อวดอ้างว่าเข้าใจศิลปะมากมายนั้น ต่างก็เปลี่ยนจากการแข่งขันกันเรื่องขนาดของอัญมณี มาเป็นการแข่งขันกันเรื่องความประณีตของแบบแปลน โดยไม่รู้เลยว่าการแอบว่าจ้างจิตรกรชื่อดังนั้นชัดเจนจนแทบจะปิดบังไม่มิด\nด้วยกระแสความนิยมนี้ ในรายการของขวัญวันเกิดของฉันก็เลยเพิ่มเต็มไปด้วยอัญมณีและเครื่องประดับที่แสดงความสง่างามเพียงผิวเผิน มีอยู่เม็ดหนึ่งสีแดงเลือดนกพิราบที่ดูดีมาก แต่ยังขาดแหวนที่จะมาเสริมให้สมบูรณ์\nฉันคิดว่าแทนที่จะไปหาพวกผู้เฒ่าผู้แก่ที่น่าเบื่อ น่าจะขอให้อัศวินของฉันวาดรูปแบบแปลนที่เต็มไปด้วยความตั้งใจให้ฉันเสียมากกว่า จะได้เป็นของขวัญสำหรับฉันอย่างไรบ้าง?\nฉันจะรอคอยผลงานของคุณด้วยความคาดหวัง เชื่อว่ารสนิยมของคุณต้องยอดเยี่ยมแน่นอน\n\nโซเรล"
  },
  Mail_68917_Name = {
    Text = "ออกแบบเครื่องประดับ.."
  },
  Mail_68917_Sender = {
    Text = "โซเรล"
  },
  Mail_68918_Desc = {
    Text = "ผู้พิทักษ์：\n\nก่อนที่ฉันจะพบเธอเป็นครั้งแรก ข้างหลังประตูนับหมื่นบาน ฉันเคยเห็นตัวเธอนับไม่ถ้วน ที่เหมือนกันแต่แตกต่าง\nฉันจำความสุข ความเศร้า ความโกรธ และการตัดสินใจทุกครั้งของเธอได้ รวมถึงภาพที่เธอเดินหน้าต่อไปในโลกที่หลากหลาย\nสำหรับฉัน ในตัวเธอที่มีมากมายเหล่านี้ เธอคือคนที่พิเศษที่สุด ฉันเคยตั้งชื่อและหมายเลขให้กับโลกที่สังเกตเห็นในใจ โลกที่เธออยู่ ฉันเรียกมันว่า \"ความหวัง\" และชื่อนี้เกิดขึ้นในวันที่ฉันพบเธอ\nในวันที่ชื่อว่า \"ความหวัง\" นี้ ฉันคิดว่าเธออาจสนใจมองดูโลกใบอื่นๆ เหมือนการมองผ่านดวงตาแห่งจักรวาล ฉันจะพาเธอไปดูทุกสิ่งที่ฉันเฝ้าดูอย่างเงียบๆ ตรงหน้าประตูเหล่านั้น\nและมองดูตัวเธอผ่านสายตาของฉัน\n\nทาวี"
  },
  Mail_68918_Name = {
    Text = "คุณที่แตกต่าง.."
  },
  Mail_68918_Sender = {
    Text = "ทาวิล"
  },
  Mail_68919_Desc = {
    Text = "แรกเริ่มความเรียบง่ายของมีธากนั้นเหมาะกับใจข้า แต่พอตั้งแต่มิรียำผู้หญิงคนนั้นมาถึง ชีวิตของข้าก็เริ่มไม่มีความสงบ\nข้าไม่ปฏิเสธคนที่ต้องการจะมาหาความมั่นคงขอที่พักพิง ในโลกที่วุ่นวายนี้การหาความปลอบโยนนั้นเป็นธรรมดาของสรรพสิ่ง ไม่มีอะไรผิด\nแต่อยากจะเสริมว่า ข้าไม่ชอบยกย่องตนเองเทียบเท่าพระเจ้าที่สามารถทำทุกอย่างได้ โดยเฉพาะในเมื่อเลมูเรียจมตัวลง ก็ไม่มีเหตุผลต้องไปสร้างพระเจ้าอีกตัวที่จะอยู่เหนือทุกอย่าง\nมิรียำก็น่าจะยังคงติดอยู่กับเงาอดีต จึงได้นำความเชื่อที่งมงายที่ไม่มีเหตุผลมาสู่ปัจจุบัน ทำให้ข้าเดินในวิทยาลัยที่ใดล้วนแต่อยู่ในความสนใจและถูกรบกวนอย่างไม่สิ้นสุด รบกวนเสียจริง\nวันนี้เป็นวันเกิด ตั้งใจว่าจะไม่ไปเข้าร่วมกับกิจกรรมที่เธอเตรียมเอิกเกริก ข้าได้ยินแล้วทำให้หูหนวกแล้ว ปวดหัวจนถ้าไปเข้าร่วมงานนั้นเต็มไปด้วยความรำคาญใจ\nถ้าท่านสนใจ ส่งข้อความมายังที่อยู่ในภายหลังแล้วเดินเล่นเพื่อผ่อนคลายกับข้าหน่อยได้ไหม\nโปรดระวัง อย่าให้ผู้หญิงคนนั้นพบเห็น\n\nทูลู"
  },
  Mail_68919_Name = {
    Text = "หลบความวุ่นวาย.."
