  },
  Mail_68920_Desc = {
    Text = "ฉันหิวโหยทุกวัน แค่ไม่ได้ดื่มเลือดเพียงชั่วขณะก็รู้สึกทรมาน แต่หลังจากได้ลิ้มรสเลือดของคุณ เลือดธรรมดาอื่นๆ ในปากฉันก็เหมือนขี้ผึ้งแข็งที่เคี้ยวยากไปหมด รสชาติอันยอดเยี่ยมของเลือดคุณกลับมาหลอกหลอนและล่อใจฉันในลำคอทุกวัน \nฉันรู้ว่าการดูดคนหนึ่งจนแห้งจะได้เลือดเท่าไร ความอร่อยแบบนั้นเรียกได้ว่าหายไปในพริบตา เพื่อไม่ให้คุณตายเร็วเกินไป ฉันจะพยายามใช้ความอดทนต่อความหิว และรอคอยความอร่อยครั้งต่อไป จนกว่าจะถึงวันที่ได้ลิ้มรสเลือดหอมหวานของคุณอีกครั้ง \nฮะ พระเจ้า ไม่อยากเชื่อเลยว่าฉันทำได้ ฉันสงสัยว่าตัวเองวิวัฒนาการไปแล้วหรือเปล่า ก็ดูสิ ฉันอดทนขนาดนี้ ในวันที่เรียกว่าวันเกิดนี่ ให้ฉันลองชิมเลือดแสนอร่อยของคุณสักนิดได้มั้ย แค่นิดเดียว จะเป็นไรไป? \nฉันใช้เงินที่หามาได้จากสโมสรปลาเทราต์ (Trout Club) ซื้ออาหารเสริมให้คุณแล้ว คราวนี้คุณคงจะไม่ซีดเซียวเพราะโลหิตจางอีกแล้ว \n\nยูวฮะชิที่หิวโหยมานาน"
  },
  Mail_68920_Name = {
    Text = "เลือดที่แสนอร่อย.."
  },
  Mail_68920_Sender = {
    Text = "อูฟฮาช"
  },
  Mail_68921_Desc = {
    Text = "ถึงผู้พิทักษ์ที่เคารพ:\n\n ข้าพเจ้ายินดีมากที่ได้เห็นความก้าวหน้าของคุณในชั้นเรียนฝึกตลอดปีที่ผ่านมา อีกไม่นานคุณจะเก่งกว่าข้าพเจ้าในวัยหนุ่ม และกลายเป็นทหารที่แข็งแกร่ง การได้เป็นครูฝึกของคุณเป็นความภาคภูมิใจอย่างยิ่ง\nปีนี้ในวันเกิด ข้าพเจ้าได้รับรองเท้าบูทสำหรับปีนเขาที่ดีมาก ๆ คุณสนใจไปเดินป่ากับข้าพเจ้าไหม? เราสามารถทดสอบสมรรถภาพทางกายของคุณ และไปชมพระอาทิตย์ขึ้นบนยอดเขา ทิวทัศน์บนภูเขาที่ไกลจากเมืองคงจะสวยงามมาก\nแน่นอน หากมีการปิกนิกแคมป์ปิ้งพร้อมเหล้าแรงเพื่อป้องกันความหนาวเย็น ก็คงจะสมบูรณ์แบบ\n\nเอลวา"
  },
  Mail_68921_Name = {
    Text = "เดินป่าขึ้นเขา.."
  },
  Mail_68921_Sender = {
    Text = "อัลวา"
  },
  Mail_68922_Desc = {
    Text = "คู่หู：\n\nในช่วงปีที่ผ่านมามีเรื่องราวเกิดขึ้นมากมาย บางทีสำหรับเธอแล้ว นี่อาจไม่ใช่ช่วงชีวิตในโรงเรียนที่ดีนัก\nฉันยอมรับว่าตลอดปีที่ผ่านมา การตักเตือนของฉันมักจะกดดันเธอไปบ้าง และการใส่ใจก็ยังขาดความอ่อนโยน การฝึกฝนทุกอย่างดูเหมือนจะเร่งรัดเกินไป ทำให้เธอต้องแบกรับอะไรมากมายในเวลาอันสั้น\nแต่ฉันหวังว่าเธอจะรู้ว่า ในใจของฉัน เธอคือคนสำคัญที่สุดเสมอ นอกจากเป็นผู้พิทักษ์แห่งมิซากะแล้ว เธอคือคู่หูเพียงหนึ่งเดียวของฉัน\nบางทีในวันนี้ ฉันหมายถึงแค่วันเกิดนี้ ฉันอาจจะลองทำตัวตามใจตัวเองสักครั้ง ส่วนเธอก็สามารถลืมความรับผิดชอบทั้งหมดได้ เราไม่ต้องสนใจการบ้านหรือการฝึกฝนใดๆ ไปพักผ่อนให้เต็มที่กันเถอะ\nไปสวนสนุกในเมือง? โรงละคร? ห้างสรรพสินค้าหรือตลาดนัด... อะไรก็ได้ ฉันหวังว่าจะพยายามชดเชยสิ่งที่ขาดหายไปให้เธอ\nเช่นเดียวกัน ฉันหวังว่าวันที่ไม่ต้องคิดอะไรนี้จะมีเธออยู่เคียงข้าง กำหนดเส้นทางทั้งหมดโดยเธอเลยก็ได้\n\nรามอน่า"
  },
  Mail_68922_Name = {
    Text = "วันที่ผ่อนคลาย.."
  },
  Mail_68922_Sender = {
    Text = "ราโมน่า"
  },
  Mail_68923_Desc = {
    Text = "ผู้พิทักษ์ที่รัก：\n\nในช่วงเวลาที่ฉันใช้ชีวิตบนโลกมนุษย์ บริวารที่น่ารักของฉันในอดีตจะจัดงานเลี้ยงใหญ่โตให้ฉันในวันนี้ของทุกปี พวกเขาพยายามทำทุกวิถีทางเพื่อเอาใจฉัน\nแม้ว่าวันนี้จะดูเหมือนเป็นวันธรรมดาที่ไม่มีอะไรเกิดขึ้น แต่รอยยิ้มแปลกๆ เหล่านั้นกลับทำให้มันกลายเป็นวันที่เต็มไปด้วยความสุขอย่างแท้จริง มนุษย์ช่างเก่งในการสร้างความสุขจากความทุกข์หรือเปลี่ยนสิ่งที่ว่างเปล่าให้กลายเป็นบางสิ่งได้อย่างน่าทึ่ง\nแม้แต่ในโรงเรียนที่สร้างสุสานไว้ในบริเวณโรงเรียนแห่งนี้ พวกเธอยังคงสามารถสร้างความสุขได้อย่างแข็งแกร่ง ซึ่งทำให้ฉันประหลาดใจมาก\nเพียงแต่ว่าของขวัญของคนธรรมดาเหล่านั้นมันช่างไร้รสชาติ และงานเลี้ยงวันเกิดที่เรียกว่านั้นก็ดูจืดชืดจนยากจะเชื่อ คนที่สามัญก็ยังคงเป็นส่วนใหญ่อยู่ดี\nมีเพียงเธอเท่านั้น แค่คิดถึงเธอก็ทำให้ฉันรู้สึกสนใจขึ้นมาบ้าง ทำให้ฉันได้ลิ้มรสความสนุกแบบในอดีตอีกครั้ง\nฉันสั่งให้เธอมาที่ห้องของฉันตอนนี้ทันที และเล่นเกมกับฉันจนถึงรุ่งเช้า หากเธอปรนนิบัติฉันดี ฉันอาจจะอนุญาตอย่างไม่เต็มใจให้เธอจูบหลังมือของฉัน\n\nวันดา"
  },
  Mail_68923_Name = {
    Text = "คำสั่ง.."
  },
  Mail_68923_Sender = {
    Text = "วานด้า"
  },
  Mail_68924_Desc = {
    Text = "<Del:คนฝั่งตะวันตก>ผู้พิทักษ์หมี่：\nตอนแรกฉันไม่ได้คิดจะเขียนอะไรแบบนี้อีกแล้ว แต่ไอจิสพูดอยู่ข้างๆ ตลอดเรื่องการรำลึกถึงความสำคัญอะไรพวกนั้น มันบังคับให้ฉันต้องเขียนจดหมายฉบับนี้ถึงเธอจริงๆ \nเอาล่ะ เพื่อไอจิส ฉันก็จะพูดอะไรสักหน่อย ก็คือว่าอยู่ที่นี่มาปีแล้ว ฉันค่อนข้างพอใจกับที่พักและอาหารในโรงเรียนนะ ยกเว้นผ้าปูที่นอนในหอพักที่ลื่นไปหน่อย ทำให้ฉันนอนไม่ค่อยชินเลย พวกเธอไม่คิดเหรอว่าผ้าฝ้ายแบบธรรมดาๆ นอนสบายกว่าเยอะ? \nส่วนที่พอจะติได้อีกอย่างก็คืออาหารในโรงอาหารมันสุขภาพดีเกินไป กินแล้วอิ่มก็จริง แต่รู้สึกไม่มีรสชาติในปากเลย ไม่อร่อยเท่าของกินริมถนนแน่นอน! \nดังนั้นงานวันเกิดปีนี้ฉันไม่ขอรบกวนพวกเชฟแล้ว จะให้ปรมาจารย์ด้านอาหารอย่างฉันพาทุกคนไปยังตรอกลับลับตาทางฝั่งตะวันออก ลองชิมแผงลอยที่ฉันกับบราวน์แนะนำเป็นพิเศษ รับรองว่าพวกเธอจะหลงรักอาหารริมถนนทันที! \nแน่นอน ค่าใช้จ่ายทั้งหมดในวันนี้ คนฝั่งตะวันตกจะเป็นคนจ่าย เธอไม่มีปัญหาใช่ไหม? \n\nเพื่อนเก่าของเธอ เจนกิน และ บราวน์"
  },
  Mail_68924_Name = {
    Text = "อาหารริมทาง.."
  },
  Mail_68924_Sender = {
    Text = "เจนกิน"
  },
  Mail_68925_Desc = {
    Text = "ผู้มีพระคุณ：\n\nนอกจากพี่สาวแล้ว เธอเป็นคนแรกที่สนับสนุนฉันอย่างจริงใจ ขอบคุณคำแนะนำของเธอก่อนหน้านี้ ตอนนี้ฉันได้ปล่อยอัลบั้มหลายชุดร่วมกับค่ายเพลง และเร็วๆ นี้จะจัดคอนเสิร์ตเดี่ยวของตัวเองแล้ว\nฉันอยากให้คอนเสิร์ตครั้งแรกบนดาวเคราะห์ดวงนี้จัดขึ้นในวันเกิดของฉัน เพื่อเป็นการเฉลิมฉลองการเริ่มต้นชีวิตใหม่ของฉันที่นี่\nหวังว่าเธอจะมาฟังฉันร้องเพลงอย่างเต็มที่ที่คอนเสิร์ต ฉันอยากจะเชิญเธอและพี่สาวขึ้นไปบนเวทีในฐานะแขกรับเชิญพิเศษในช่วงสุดท้าย เพื่อร้องเพลงใหม่ของฉันด้วยกัน เธอคิดยังไงบ้าง?\nอ้อ อย่าบอกเรื่องนี้กับพี่สาวของฉันนะ เพราะวันนั้นก็เป็นวันเกิดของเธอเช่นกัน ฉันอยากให้เธอเซอร์ไพรส์\nส่วนความปรารถนาที่ฉันและพี่สาวตกลงกันไว้ว่าจะขอในวันเกิด ฉันหวังว่าจะทำให้เสียงเพลงของฉันเปล่งประกายอีกครั้งบนดาวเคราะห์ดวงนี้\n\nทิงค์เทต"
  },
  Mail_68925_Name = {
    Text = "คอนเสิร์ต.."
  },
  Mail_68925_Sender = {
    Text = "ทิงค์"
  },
  Mail_68926_Desc = {
    Text = "ผู้พิทักษ์ที่รัก：\n\nไม่รู้ตัวเลยว่าอีกปีนึงผ่านไปแล้ว ทุกวันของฉันที่มิซากะเต็มไปด้วยความสุขมาก ๆ ได้เล่นด้วยกัน เรียนด้วยกัน และกินของอร่อย ๆ มากมาย นี่คือช่วงเวลาที่มีความสุขที่สุดในชีวิตของฉัน แม้ว่าบางครั้งตอนออกไปทำภารกิจฉันจะรู้สึกตื่นเต้นบ้าง แต่การได้ต่อสู้ร่วมกับทุกคน ไอจิสไม่เคยกลัวเลย\nขอโทษจริง ๆ ที่ปีนี้ยังคงสร้างปัญหาให้คุณอีกหลายครั้ง ถึงแม้ว่าส่วนใหญ่จะเป็นเพราะเจนกินชอบเล่นสนุก แต่เธอก็แค่อยากให้ทุกคนมีความสุข หวังว่าคุณจะไม่ถือโกรธความสะเพร่าและการกระทำที่อาจล่วงเกินของเรา\nพูดถึงเจนกิน เธอเสนอให้จัดการแข่งขันจับหิ่งห้อยในวันเกิดของฉันปีนี้ เธอเตรียมขวดใสไว้มากมาย โดยบอกว่าจะทำโคมไฟหิ่งห้อยจำนวนมาก และใครที่สามารถทำโคมไฟให้สว่างที่สุด จะได้รับตำแหน่ง \"นักจับแมลงยอดเยี่ยม\"\nถึงแม้ว่าคำว่า \"นักจับแมลงยอดเยี่ยม\" จะฟังดูแปลกไปหน่อย แต่ป่าที่เต็มไปด้วยหิ่งห้อยในฤดูร้อนนั้นสวยงามจริง ๆ หากคุณมีเวลาว่างจากงานที่ยุ่ง ๆ ก็ขอเชิญคุณมาร่วมกับเราเดินเข้าไปในป่า เพื่อชมวิวทิวทัศน์ที่ระยิบระยับเหมือนดวงดาว\n\nไอจิส"
  },
  Mail_68926_Name = {
    Text = "การแข่งขันจับหิ่งห้อย.."
  },
  Mail_68926_Sender = {
    Text = "ไอจิส"
  },
  Mail_68927_Desc = {
    Text = "ผู้พิทักษ์! เมื่อไม่กี่วันก่อน ตอนไปว่ายน้ำในทะเล โอเรียตาได้พบเพื่อนใหม่ที่สามารถปล่อยกระแสไฟฟ้าได้! มันมีรูปร่างกลมๆ แบนๆ เหมือนพิซซ่าขนาดใหญ่!\nโอเรียตาทักทายมัน แต่อยู่ดีๆ ก็รู้สึกชาตามตัว แล้วเพื่อนใหม่ก็หายไปในพริบตา\nหลังจากกลับมา ดอร์บอกว่านั่นคือปลากระเบนไฟฟ้ากำลังปล่อยกระแสไฟฟ้า โอเรียตาไม่ค่อยเข้าใจ แต่รู้สึกว่าเพื่อนใหม่เจ๋งมาก! พอดีวันเกิดของโอเรียตาใกล้ถึงแล้ว ผู้พิทักษ์ช่วยโอเรียตาไปรับเพื่อนใหม่กลับมาเถอะ! แล้วจะได้อยู่กับเพื่อนๆ ของโอเรียตา! ความรู้สึกชาๆ แบบนั้น ผู้พิทักษ์ต้องชอบแน่ๆ!\n\nออรีตา"
  },
  Mail_68927_Name = {
    Text = "เพื่อนใหม่ที่สามารถปล่อยไฟฟ้าได้.."
  },
  Mail_68927_Sender = {
    Text = "ออริตา"
  },
  Mail_68928_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\n\nในวัยเด็ก วันเกิดสำหรับฉันคือคำสั่งที่ไม่มีการละเว้นจากบิดา เป็นการฝึกซ้อมการบรรเลงที่ไม่อาจผ่อนคลายได้แม้แต่น้อย\nห้ามหยิ่ง ห้ามใจร้อน ห้ามเกียจคร้าน นอกจากแม่จะแอบเตรียมเค้กชิ้นเล็กๆ ให้ฉันแล้ว วันนี้สำหรับฉันเป็นเพียงการฟังคำตักเตือนอย่างเข้มงวด เพื่อชี้ให้เห็นถึงข้อบกพร่องต่างๆ ในปีที่ผ่านมา\nจนกระทั่งวันนี้ ฉันไม่ใช่ศิษย์ดนตรีอีกต่อไป และเพราะท่าน ฉันสามารถสัมผัสประตูอันยิ่งใหญ่นั้นและก้าวเข้าสู่หอคอยดนตรีชั้นสูงสุด แต่คำสอนตั้งแต่เด็กได้ทำให้ฉันไม่มีความปรารถนาใดๆ ต่อความสนุกทางโลกอีก\nมีเพียงดนตรีเท่านั้น การบรรเลงเพลงสวดวิญญาณที่กำหนดไว้ให้ท่าน คือเป้าหมายสูงสุดของชีวิตนี้ เป็นช่วงเวลาเดียวที่ฉันรู้สึกว่ามีความหมาย\nหากท่านยินดีมอบช่วงเวลาแห่งราตรีก่อนนอนให้ฉัน ฉันขอสัญญาว่าจะบรรเลงเพลงที่แกะสลักอยู่ในวิญญาณของฉันตลอดทั้งคืน จนกว่าจะรุ่งอรุณ\n\nแฮมลิน"
  },
  Mail_68928_Name = {
    Text = "ความปรารถนาในการบรรเลง.."
  },
  Mail_68928_Sender = {
    Text = "ฮาเมลน์"
  },
  Mail_68929_Desc = {
    Text = "เด็กหนุ่ม: \n\nตั้งแต่มาที่นี่ ตอนแรกคิดว่าจะได้หลุดพ้นจากผู้หญิงบ้าที่โบราณคนนั้นเสียที แต่กฎระเบียบในที่นี่กลับมากกว่าของผู้หญิงคนนั้นอีก ข้าไม่ได้ลิ้มรสความสุขมานานแล้ว! \nดื่มเหล้าอย่างเต็มที่ก็ไม่ได้ จีบสาวก็ไม่ได้ งานเลี้ยงรอบกองไฟก็ไม่ได้ แม้กระทั่งเนื้อย่างที่นี่ยังห่างไกลจากของพวกฟิลิสเตียเสียอีก! ไม่รู้จริงๆ ว่าชีวิตจืดชืดแบบนี้พวกเจ้าทนอยู่กันได้อย่างไร \nแต่คนเก่งจะไม่บ่นเรื่องสภาพแวดล้อม หลังจากที่ข้าใช้ความพยายามอยู่พักใหญ่ ข้าก็ได้กลายเป็นหัวหน้าแก๊งใหญ่ในเมืองของพวกเจ้าอีกครั้ง \nในโอกาสวันเกิดของโกลิอัทผู้ยิ่งใหญ่ ข้าเมตตาเชิญเจ้ามาร่วมงานเลี้ยงที่ลูกน้องของข้าจัดให้ มีเหล้าดี เนื้อดี และสาวงามมากมาย รับรองว่าจะทำให้เด็กน้อยอย่างเจ้าที่ไม่เคยเห็นอะไรเปิดหูเปิดตาแน่นอน \nดูในน้ำใจที่เคยมีให้กันมาก่อน ข้าจะไม่ขอของขวัญจากเจ้า เจ้าแค่เอาความเคารพของเจ้ามา มอบคำอวยพรให้กับการกลับมายิ่งใหญ่อีกครั้งของผู้แข็งแกร่งอย่างข้า \nจงจ้องตาดูให้ดี วันนี้ปีหน้า หรือปีถัดไปไม่ว่าข้าจะอยู่ที่ไหน ข้าจะสร้างเส้นทางใหม่ให้กับตัวเอง \n\nโกลิอัท"
  },
  Mail_68929_Name = {
    Text = "การเดินทาง.."
  },
  Mail_68929_Sender = {
    Text = "โกไลแอท"
  },
  Mail_68930_Desc = {
    Text = "ผู้พิทักษ์： \n\nเดิมทีฉันไม่เคยคิดจะเฉลิมฉลองวันเกิดของร่างกายที่ตื้นเขินนี้ เพียงถือว่าเป็นวันฝึกฝนธรรมดา แต่ไม่นึกว่าพระราชาจะทรงพบข้าในเช้าวันนี้ และมีพระราชดำรัสสั่งให้ข้าห้ามทำสิ่งใดที่เกี่ยวข้องกับพระราชาหรือการฝึกฝนในวันนี้ ต้องใช้วันนี้เพื่อตัวเองทั้งหมด \nตลอดระยะเวลาหลายคืนและวันมา ครั้งแรกที่พระราชาทรงระลึกถึงข้าเช่นนี้ ทำให้ข้ารู้สึกตื่นตระหนกและซาบซึ้งอย่างยิ่ง แต่ข้าได้ทำการเสียสละชีวิตนี้แด่พระราชาไปแล้ว จึงไม่รู้เลยว่าควรไปที่ไหน หรือควรทำอะไร \nหลังจากไตร่ตรองอยู่ครู่หนึ่ง สิ่งเดียวที่พอจะเรียกว่ามีความเสียใจเล็กน้อย ก็คือความรู้สึกผิดต่อเด็กคนนั้น มอร์ฟี่ แม้จะเพื่อการฟื้นฟูประเทศชาติเดิม ข้าก็ไม่เคยรู้สึกเสียใจเลยสักนิด แต่สิ่งที่ข้าเป็นหนี้เธอ ข้าก็รู้ดีว่าไม่มีทางชดเชยหรือทดแทนได้ \nแต่ หากข้ายังมีสิ่งใดที่อยากทำจากใจจริง บางทีอาจเป็นการทำหน้าที่ของแม่อีกครั้งอย่างไม่เกรงกลัวต่อความอาย \nข้าได้เตรียมขนมหวานที่เด็กคนนั้นเคยชอบมาโดยเฉพาะ ก็ถือว่าเป็นการทำให้แม่ที่น่ารังเกียจและไร้คุณสมบัติคนนี้สมหวัง ขอร้องเถอะ ช่วยนำของขวัญชิ้นนี้ไปมอบให้เธอด้วย อย่าบอกเธอว่าเป็นของข้า แค่บอกว่าเธอเตรียมไว้ก็พอ \nหวังว่าจะตอบรับคำขอ ขอบคุณอย่างยิ่ง \n\nมิลียาห์ม"
  },
  Mail_68930_Name = {
    Text = "ชดเชย.."
  },
  Mail_68930_Sender = {
    Text = "มิเรียม"
  },
  Mail_68931_Desc = {
    Text = "อาฮา หลังจากที่ฉันไตร่ตรองอย่างชาญฉลาด ตอนนี้ฉันเข้าใจความหมายของวันเกิดของมนุษย์อย่างถ่องแท้แล้ว สิ่งที่เรียกว่าวันพิเศษเฉพาะของใครคนหนึ่งนั้น ก็เพื่อให้คนได้รับโอกาสในการใช้สิทธิพิเศษที่หายาก ได้รับโอกาสในการครอบครองของมีค่า และมีโอกาสที่จะขอความปรารถนาจากผู้อื่นอย่างมั่นใจ\nไม่ว่าจะเป็นความปรารถนาใดๆ ที่ปกติไม่กล้าพูดหรือไม่กล้าคิด ในวันนี้ก็มีโอกาสที่จะได้รับการเติมเต็ม ฮะ นี่มันวันแห่งการปลดปล่อยที่ตื่นเต้นกว่าเทศกาลใดๆ เสียอีก\nดูเหมือนว่าฉันพลาดโอกาสมากมายในอดีต แต่โชคดีที่ด้วยอายุขัยที่ยาวนานของฉัน ในอนาคตฉันยังมีวันเกิดอีกมากมายนับไม่ถ้วนที่จะขอพร\nดังนั้น การขอให้ทุกคนมาต่อสู้กับฉันอย่างสนุกสนานในวันเกิด ควรจะเป็นความปรารถนาที่สามารถทำให้เป็นจริงได้ง่ายใช่ไหม?\n\nโรแทน"
  },
  Mail_68931_Name = {
    Text = "สิทธิพิเศษของผู้ที่เกิดในวันนี้.."
  },
  Mail_68931_Sender = {
    Text = "โลทัน"
  },
  Mail_68932_Desc = {
    Text = "ผู้พิทักษ์： \n\nเมื่ออายุมากขึ้น วันเกิดก็ค่อยๆ กลายเป็นวันที่มองข้ามไปในปฏิทิน บ่อยครั้งที่เราเผลอคิดถึงมันเมื่อวันเกิดก็ผ่านพ้นไปอย่างเงียบๆ เหมือนสายน้ำ \nในโลกของผู้ใหญ่ การเฉลิมฉลองวันเกิดเป็นเรื่องของเด็กและคนที่ไม่มีอะไรทำ ฉันเองก็กลายเป็นผู้ใหญ่น่าเบื่อคนหนึ่ง ไม่ได้คาดหวังอะไรกับวันเกิดอีกแล้ว \nเคยมีปีหนึ่งฉันเกิดไอเดียแปลกๆ แกะสลักเค้กเป็นรูปปั้นสวยงาม ในปีต่อมา ฉันก็ไม่เคยพลาดการจองเค้กวันเกิดเพราะลืมอีก เพียงแค่หยิบรูปปั้นที่ไม่มีวันเน่าเสียนี้ออกมาจากคลังในวันเกิด เพื่อสัมผัสประสบการณ์การเป่าเทียน แค่นี้ก็ถือว่าวันเกิดผ่านไปแล้ว \nจนกระทั่งมาถึงมิซากะ ฉันถึงได้พบว่าคนยุ่งและคนว่างสามารถอยู่ร่วมกันได้ในคนเดียว และคนที่นี่ไม่เพียงพอใจที่จะเบื่อคนเดียว แต่ยังชวนทุกคนมาเบื่อด้วยกัน \nสองปีที่ผ่านมาในการเข้าร่วมงานวันเกิดที่มิซากะ มีจำนวนครั้งมากกว่าที่ฉันเคยเข้าร่วมมาตลอดชีวิต และตลกกว่านั้นคือฉันกลับพบความสนุกบางอย่างในงานเฉลิมฉลองที่น่าเบื่อนี้ \nบางทีนอกจากธีมเศร้าและจริงจัง การวาดภาพฉากชีวิตประจำวันที่ดูโง่ๆ ก็อาจเต็มไปด้วยความงามทางศิลปะ \nพูดถึงเรื่องนี้ แผนงานสร้างสรรค์สำหรับวันเกิดปีนี้ก็คือการแกะสลักรูปครึ่งตัวของผู้พิทักษ์ที่กำลังยิ้มโง่ๆ เพื่อใช้ประดับเค้กรูปปั้นของฉัน \nอย่าลืมมาที่สตูดิโอของฉันเร็วๆ นี้นะ แบบจำลองมิวส์ของฉัน \n\nซาน"
  },
  Mail_68932_Name = {
    Text = "ความสนุกที่น่าเบื่อ.."
  },
  Mail_68932_Sender = {
    Text = "ซังก้า"
  },
  Mail_68933_Desc = {
    Text = "ถึงผู้รับที่เคารพ：\n\nหลังจากครุ่นคิดอยู่นาน ผมได้เขียนจดหมายฉบับนี้ในโลกที่เงียบงันและไร้ชีวิต ตลอดเวลาที่ผ่านมา ผมแทบจะลืมวันเกิดของตัวเองไปแล้ว และในโลกแบบนี้ การเฉลิมฉลองก็ไม่มีความหมายอะไร \nแต่ นับตั้งแต่ได้พบกับคุณ ผมกลับเริ่มโลภมากขึ้นทุกวัน แม้กระทั่งความโดดเดี่ยวที่เคยชินก็เริ่มทนไม่ไหว \nทุกครั้งที่เป็นแบบนี้ ใจผมจะเกิดอารมณ์แปลกๆ รู้สึกอิจฉาตัวเองในโลกของคุณเล็กน้อย บางทีอาจมีความรู้สึกอิจฉาที่แทบจะมองไม่เห็น คุณดูสิ คนอย่างผมที่เคยคิดว่าตัวเองมีเหตุผล ก็ยังมีวันที่ความคิดต่ำช้าแบบนี้ได้ นี่แสดงให้เห็นว่าความยุติธรรมและความมีเหตุผลของมนุษย์ต่างก็มีขีดจำกัดของมัน \nผมรู้ว่าคุณจะเชิญผมอย่างไร แต่สำหรับกาลเวลาแล้ว การรบกวนที่ไม่จำเป็นควรหลีกเลี่ยง ผมไม่ควรและจะไม่ไปยังโลกของคุณ \nขณะที่เขียนถึงตรงนี้ ผมกำลังมองออกไปยังจักรวาลอย่างไกลโพ้น มองไปยังจุดที่อุโมงค์เปิด หากคุณบังเอิญแหงนมองฟ้าอยู่เช่นกัน เราก็คงจะกำลังมองท้องฟ้าดวงดาวเดียวกัน \nหวังว่าจดหมายฉบับนี้จะแทนตัวผม ข้ามผ่านกาลเวลา ลอยไปยังฝ่ามือของคุณ ผ่านดวงตาและริมฝีปากของคุณ เพื่อพบเจอและพึ่งพาคุณ \nเมื่อคุณโอบกอดกระดาษแผ่นนี้ ผมจะจินตนาการถึงการโอบกอดคุณจากปลายทางนี้ของโลก \n\n「รามอน่า」"
  },
  Mail_68933_Name = {
    Text = "...ร่วมกันเฝ้ามองด้วยความรู้สึกลึกซึ้ง"
  },
  Mail_68933_Sender = {
    Text = "ราโมน่า: วัฏกาล"
  },
  Mail_68934_Desc = {
    Text = "นักโทษตัวน้อยของฉัน:\n\nเธอรู้ไหม เหมือนกับสัตว์แต่ละชนิดมีเมนูอาหารที่แตกต่างกัน มนุษย์แต่ละคนก็มีความต้องการความอบอุ่นที่ไม่เหมือนกัน บางคนแค่ใส่เสื้อผ้าหนึ่งชุดก็เพียงพอที่จะให้ความอบอุ่นแก่ตัวเอง บางคนต้องการมือที่อบอุ่น หรือการกอดที่อบอุ่น ในขณะที่บางคนต้องการอุณหภูมิที่ร้อนระดับเทียนที่กำลังละลาย\nอุณหภูมิที่ร้อนจัดและเหนียวข้นนั้นจะถูกบันทึกไว้บนปลายประสาททุกอณู สะท้อนให้เห็นอย่างชัดเจนถึงเส้นทางที่เทียนหยดลงมาอย่างคดเคี้ยว ความเจ็บปวดเล็กน้อย ความรู้สึกสัมผัสที่ทำให้สั่นสะท้าน จนกระทั่งเผลอร้องออกมา จึงจะสามารถรู้สึกถึงการมีอยู่ของตัวเองได้อย่างเต็มที่\nบางครั้งฉันจะกลายเป็นเทียน สนุกกับความสุขที่ได้สร้างการแกะสลัก และบางครั้งฉันก็หลงใหลในอุณหภูมิของเทียน ปรารถนาความอบอุ่นที่เจ็บปวดและแสนหวานเช่นนั้น\nฤดูหนาวของมิซากะมาถึงแล้ว ช่วงนี้ฉันมักจะรู้สึกหนาวเย็น และความเหงาที่เกิดจากความหนาวเย็น ที่รักของฉัน เธอควรจะรู้ว่าวันนี้คือวันอะไร ความปรารถนาของฉันง่ายมาก เชื่อว่าคนใจดีอย่างเธอจะต้องเต็มใจมอบความอบอุ่นที่จะขจัดความเหงาให้ฉันแน่\n\nพันเดีย"
  },
  Mail_68934_Name = {
    Text = "ความต้องการที่อบอุ่น.."
  },
  Mail_68934_Sender = {
    Text = "แพนเดีย"
  },
  Mail_68935_Desc = {
    Text = "ผู้พิทักษ์：\n\nปีนี้ฉันกับทิงค์เทตได้ทำข้อตกลงกันว่า คำอธิษฐานในวันเกิดของเราจะต้องเกี่ยวกับตัวเองเท่านั้น ห้ามอธิษฐานให้กันและกัน \nถึงแม้ว่าเธอจะเป็นคนเริ่มต้นข้อตกลงนี้เพราะความโกรธ แต่ดูเหมือนว่ามันจะทำให้เธอลำบากไม่น้อย \nพวกเราสองคนผูกพันกันมานานมาก การคิดอย่างเป็นอิสระเหมือนคนปกติจึงเป็นเรื่องยาก แต่การได้เกิดใหม่ในชีวิตที่เต็มไปด้วยความช่วยเหลือและความห่วงใยเช่นนี้ ไม่มีเวลาไหนเหมาะกว่านี้อีกแล้วที่จะเรียนรู้ที่จะเดินด้วยตัวเอง \nหลังจากที่ฉันพิจารณาอย่างรอบคอบ ฉันก็ได้ตัดสินใจว่าคำอธิษฐานของฉันในปีนี้คือ การมีเพื่อนใหม่ห้าคน... เอาเถอะ สามคนก็พอ การเปลี่ยนแปลงตัวเองจำเป็นต้องค่อยๆ ทำทีละเล็กทีละน้อย \nในฐานะเพื่อนคนเดียวในตอนนี้ที่ได้รับความนิยมอย่างมาก คุณพอจะสอนเคล็ดลับในการหาเพื่อนให้ฉันได้ไหม? \n\nฟีนต์"
  },
  Mail_68935_Name = {
    Text = "ความปรารถนาที่จะคบเพื่อน.."
  },
  Mail_68935_Sender = {
    Text = "เฟนท์"
  },
  Mail_68936_Desc = {
    Text = "ผู้พิทักษ์： \n\nทุกปีในวันเกิดเมื่ออธิษฐาน ฉันมักจะขอพรเดิมเสมอ นั่นคือการเปลี่ยนแปลงอย่างสมบูรณ์แบบของสายเลือด จริงๆ แล้วฉันรู้มาตลอดว่า ความยึดมั่นในสายเลือดของฉันอาจดูเหมือนดื้อรั้น น่าขัน หรือแม้กระทั่งน่าสงสารและน่ารังเกียจสำหรับคนอื่นๆ.\nแต่เธอกับฉันไม่เหมือนกัน ไม่ว่าเมื่อไหร่ ฉันรู้ว่าเธอจะสนับสนุนให้ฉันเดินไปบนเส้นทางนี้ต่อไป แม้จะเจอกับอุปสรรค ล้มลง หรือไม่ประสบผลสำเร็จ ในเสียงหัวเราะของคนอื่น เธอคือคนแรกที่คอยห่วงใยฉัน.\nบางทีไม่ว่าจะเป็นเธอหรือใครก็ตามอาจไม่เข้าใจสิ่งที่คนที่ถูกกดขี่และถูกเหยียดหยามมาตั้งแต่เด็กแบกรับไว้ แต่ไม่เป็นไร ความทุกข์ยากบนเส้นทางของการเปลี่ยนแปลงนี้ได้กลายเป็นเนื้อและเลือด รวมถึงอาหารของฉัน ทำให้ฉันสามารถลุกขึ้นและต่อสู้อย่างต่อเนื่อง.\nฉันไม่ใช่ตัวเองที่ไร้พลังเมื่อยังเยาว์อีกต่อไป แม้จะมีบททดสอบมากมายเพียงใด ฉันจะก้าวไปอย่างมั่นคงจนถึงวินาทีสุดท้าย.\nก่อนหน้านั้น ก็ขอให้เธอจับตาดูฉัน และรอความสำเร็จของฉันนะ.\nอ้อ เธอเคยให้เงินฉันห้าสิบหน่วย ฉันบอกว่าจะคืนให้ ตอนนี้ฉันเก็บเงินได้ครบแล้วและยังเหลืออีกสองหน่วย จะถือว่าเป็นการตอบแทนและคืนให้เธอด้วยเลย.\n\nเคคอส"
  },
  Mail_68936_Name = {
    Text = "คืนเงิน.."
  },
  Mail_68936_Sender = {
    Text = "เคคัส"
  },
  Mail_68937_Desc = {
    Text = "ผู้พิทักษ์ที่เคารพ:\n\nสวัสดีค่ะ ยินดีต้อนรับสู่แบบสอบถามการสอบสวนประจำปีของหุ่นยนต์อัตโนมัติ เอริกา ฉันจะรวบรวมประสบการณ์จริงและปัญหาที่ท่านพบในระหว่างการใช้งานเอริกาในปีนี้ ความคิดเห็นของท่านคือทิศทางในการปรับปรุงของเอริกา\nต่อไปนี้ กรุณาให้คะแนนตามคำถามที่เกี่ยวข้องจากต่ำไปสูงในจดหมายตอบกลับ ขอบคุณมากสำหรับคำติชมของท่าน\nระดับความสะดวกในการใช้งาน: 1-5 คะแนน\nความเร็วในการตอบสนองขณะใช้งาน: 1-5 คะแนน\nระดับความเข้าใจในความต้องการ: 1-5 คะแนน\nการดูแลอารมณ์ของผู้ใช้: 1-5 คะแนน\nความถูกต้องในการค้นหาข้อมูล: 1-5 คะแนน\nความเป็นประโยชน์ของวิธีแก้ปัญหาที่เสนอ: 1-5 คะแนน\nสุดท้าย กรุณาระบุปัญหาที่ท่านเคยพบขณะใช้งานเอริกา และส่วนที่ไม่พึงพอใจ ปัญหาเหล่านี้อาจได้รับการแก้ไขในภายหลัง\nเมื่อเสร็จสิ้นแบบสอบถาม จะมีของขวัญที่ระลึกครบรอบปีส่งไปยังห้องของท่าน ในปีหน้าผู้ช่วยที่ใกล้ชิดที่สุดของท่าน เอริกา จะยังคงอยู่เคียงข้างท่าน อีกครั้งขอบคุณสำหรับการใช้งาน แล้วพบกันใหม่\n\nเอริกา"
  },
  Mail_68937_Name = {
    Text = "แบบสอบถามการสอบสวนประจำปี.."
  },
  Mail_68937_Sender = {
    Text = "เอริกา"
  },
  Mail_68938_Desc = {
    Text = "ผู้พิทักษ์： \n\nทุกปีในวันเกิดของฉัน ฉันจะใช้เวลาทั้งวันระลึกถึงเรื่องราวในอดีตอย่างละเอียด และเขียนบันทึกประจำวันเดิมซ้ำอีกครั้ง \nยิ่งห่างจากบ้านเกิดนานเท่าไหร่ ความทรงจำก็ยิ่งเลือนลางมากขึ้น วันคืนที่รอคอยการกลับมาตามแสงสว่าง หรือวันที่แหงนมองพระพักตร์แห่งราชันอย่างเคารพ ตอนนี้แทบจำไม่ได้แล้ว \nแต่ฉันไม่ยอมลืม และจะไม่มีวันลืม แม้การรอคอยจะยาวนานไม่สิ้นสุด หรือต้องเผาผลาญวิญญาณนี้ แสงสว่างนี้ก็จะไม่มืดลง จนกว่าบ้านเกิดจะฟื้นคืนชีพ ในวันนั้น ฉันจะเป็นแสงแรกที่ตอบสนองต่อการเรียก \nฉันเคยจินตนาการถึงการพบกันใหม่นับร้อยแบบ แต่ไม่เคยคิดเลยว่าจะได้เห็นพระราชาและนักบวชอีกครั้งที่นี่ หากพูดตามคำพูดของพวกท่าน หากสถานที่ที่จิตใจสงบคือบ้านเกิด ที่นี่ก็สามารถนับเป็นบ้านเกิดที่สองของฉันได้ และสิ่งที่บันทึกไว้ในสมุดบันทึกของฉันก็เปลี่ยนจากความทรงจำกลายเป็นความทรงจำใหม่ที่สดใสในแต่ละวัน \nไม่จำเป็นต้องมีรางวัลหรือของขวัญใดๆ การได้ติดตามอยู่ข้างกายพระราชาอีกครั้งก็เป็นความสุขที่ยิ่งใหญ่ที่สุดแล้ว \nหากแสงสว่างจากตัวตนนี้ไม่อาจส่องถึงก้นทะเลแห่งบ้านเกิด ก็ขอให้มันตามรอยพระบาทของพระราชา ส่องสว่างแผ่นดินนี้ไปพลางก่อนเถิด \n\nฟาร์โรส"
  },
  Mail_68938_Name = {
    Text = "ติดตามพระมหากษัตริย์ของข้า.."
  },
  Mail_68938_Sender = {
    Text = "ฟารอส"
  },
  Mail_68939_Desc = {
    Text = "ผู้พิทักษ์: \n\nขอแสดงความยินดีให้กับฉัน ยินดีให้กับคุณ ยินดีให้กับมีธาก ยินดีที่เรารอดพ้นจากการไล่ล่าของความหวาดกลัวสีดำมาอีกหนึ่งปี \nวันนี้ไม่ใช่วันเกิดที่ธรรมดา วันนี้เป็นวันครบรอบการมีชีวิตอยู่ของฉัน เป็นวันที่เราจะชื่นชมความมีชีวิตอยู่ของฉัน \nการมีชีวิตอยู่ สองคำที่เรียบง่ายนี้ซ่อนเร้นความยากลำบากมากมาย ความมีชีวิตชีวาที่ร้อนแรงเช่นนี้สามารถเปรียบเทียบได้กับกลิ่นหอมของกาแฟร้อน มาร่วมเข้าร่วมศาสนากาแฟเถอะ ผู้พิทักษ์ ให้เราชื่นชมความตื่นตัว ชื่นชมการมีชีวิตอยู่ในทุกๆ \n\nโน้ตที่ส่งมาพร้อมกับจดหมาย: \nอา วินเคลอร์คนนี้ดื่มกาแฟมากเกินไป ตื่นเต้นและเหนื่อยล้า จนหมดสติหน้าตัก ฉันได้พาเธอไปยังห้องพยาบาลแล้ว ไม่ต้องกังวล \nแต่ก่อนที่เธอจะหมดสติ เธอได้เอากาแฟที่เก็บสะสมไว้และกระดาษจดหมายออกมา เหมือนจะส่งให้คุณ ฉันจึงแนบมากับจดหมายนี้ หวังว่าเมื่อเธอตื่นขึ้นมาจะไม่เสียใจ \nสำหรับวันเกิดของเธอ อาจจะให้เธอได้พักผ่อนสักหน่อยจะเป็นของขวัญที่ดีที่สุด \n——ซิลเวีย"
  },
  Mail_68939_Name = {
    Text = "สรรเสริญชีวิต.."
  },
  Mail_68939_Sender = {
    Text = "วิงเกิล"
  },
  Mail_68940_Desc = {
    Text = "ผู้พิทักษ์: \n\nฮ่าฮ่าฮ่า! หลังจากที่ฉันพยายามอย่างไม่ลดละ แกะข้อความเตือน 12 ข้อไว้ตามมุมต่างๆ ของห้อง และเขียนโน้ตกระดาษถึง 36 แผ่น (อาจจะมากกว่านั้นแต่ฉันหาไม่เจอแล้ว) ในที่สุดฉันก็จำได้สำเร็จว่าวันนี้เป็นวันเกิดของฉัน! \nคาดไม่ถึงใช่ไหม จริงๆ แล้วตัวฉันเองก็เพิ่งจะนึกออกเมื่อเช้านี้ แต่นั่นก็ต้องขอบคุณความพยายามตลอดปีที่ผ่านมาของฉันเอง ฉันไม่อยากพลาดวันดีๆ แบบนี้เด็ดขาด \nครั้งที่แล้วที่ฉันจัดปาร์ตี้กับทุกคน มันสนุกมากเลยนะ โดยเฉพาะตอนเล่นเกมอะไรสักอย่างกับใครบางคน แล้วก็กินขนมหวานชนิดหนึ่ง... เอาเถอะ ยังไงก็สนุก! \nตอนเด็กๆ ทุกวันเกิดแม่จะซื้อหนังสือเรื่องราวการผจญภัยให้ฉันเสมอ เราสองคนจะนอนอ่านด้วยกันทุกคืนก่อนนอน แล้วในฝันก็จะฝันถึงการผจญภัยที่ยอดเยี่ยม ถึงแม้พอตื่นมาแล้วจะลืมไปอย่างรวดเร็ว แต่ความสุขนั้นยังคงอยู่ในใจเสมอ ฉันเชื่อว่าความรู้สึกที่มีค่าจะไม่มีวันถูกลืม \nแถมการเป็นคนขี้ลืมก็มีข้อดีเหมือนกันนะ ถึงแม้ฉันจะจำไม่ได้ว่าครั้งที่แล้วเราทำอะไรกันบ้างในปาร์ตี้ แต่วันนี้ฉันสามารถสัมผัสประสบการณ์ใหม่อีกครั้งได้ทั้งหมดเลย ความสุขจากครั้งที่แล้ว กรุณาแพ็คให้ฉันอีกหนึ่งชุดนะ! \n\nนอร์ดิลาที่เต็มไปด้วยความคาดหวัง"
  },
  Mail_68940_Name = {
    Text = "อีกครั้ง.."
  },
  Mail_68940_Sender = {
    Text = "นอติลา"
