  Mail_79390_Desc = {
    Text = "เรียนผู้พิทักษ์: \n        ขอขอบคุณสำหรับการสนับสนุนและการยอมรับใน「คืนแห่งการลืมเลือน」เพื่อให้ผู้พิทักษ์ที่มหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดีขึ้น เราจึงขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อกรอกแบบสอบถามเสร็จสิ้นสามารถรับได้ ร่วมตอบแบบสอบถามก่อนวันที่ 17 มีนาคม เวลา 9:00 น. โปรดกรอกให้ทันเวลา \n        <SurveyLink:「คลิกเพื่อไปกรอก」>\n        เราจะรับฟังข้อเสนอแนะแต่ละข้อจากผู้พิทักษ์อย่างจริงจัง ความคิดเห็นของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ! \n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
