    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「ฝังลึกในความทรงจำ」สิ้นสุดแล้ว ขณะนี้จะทำการแปลง「รายงานการวินิจฉัย」ที่เหลืออยู่ของผู้พิทักษ์ตามสัดส่วนการแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 กรุณาจำไว้ว่าให้ตรวจสอบรับด้วย."
