  Mail_80091_Desc = {
    Text = "ผู้พิทักษ์：\n\nเมื่อคุณเปิดจดหมายนี้ แสดงว่าฉันได้ฝังสัญญาณในใจของคุณแล้ว.\nฮ่า ไม่ต้องกังวล นี่แค่เพื่อให้วันเกิดของฉันดำเนินไปอย่างราบรื่นด้วยการสะกดจิตเล็กน้อย จะไม่มีผลกระทบกับคุณ.\nต่อจากนี้ คุณจะรู้สึกอยากไปช้อปปิ้งด้วยใจจริง จงเชื่อฟังมันไปยังถนน จากนั้นเลือกของขวัญที่ถูกใจฉันที่สุดจากหน้าต่างร้านค้า ที่จะส่งไปในมือของฉัน.\nฉันรู้ถึงความสงสัยของคุณในขณะนี้ และเข้าใจถึงความเหมาะสมของมัน แต่เจ้าของวันเกิดมักมีสิทธิพิเศษ ใช่ไหม? สิ่งที่ฉันทำแค่อยากให้คุณไม่ลืมวันพิเศษนี้ เพราะคุณคือแขกที่ฉันเฝ้ารอ.\nสุดท้าย ฉันจะรอคอยการมาเยือนของคุณอย่างอดทน —— อย่าลืมของขวัญ.\n\nเคลเมนติน"
  },
  Mail_80091_Name = {
    Text = "“ของขวัญ” ที่เลือกโดยตรง"
  },
  Mail_80091_Sender = {
    Text = "คลีเมนไทน์"
