  Mail_81288_Desc = {
    Text = "เรียนผู้พิทักษ์ที่เคารพ：\n        ขอบคุณสำหรับการสนับสนุนและการยอมรับใน「คืนแห่งการลืมเลือน」เพื่อให้ผู้พิทักษ์ที่มหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดีขึ้น เราขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อกรอกแบบสอบถามเสร็จสิ้นคุณสามารถรับรางวัลได้ แบบสอบถามจะปิดในวันที่ 14 เมษายน เวลา 9:00 น. กรุณาสังเกตให้กรอกให้ทันเวลา.\n        <SurveyLink:「คลิกเพื่อกรอก」>\n        เราจะรับฟังข้อเสนอแนะจากผู้พิทักษ์ทุกคนอย่างจริงจัง ความคิดเห็นของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ！\n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
