  },
  Mail_81326_Desc = {
    Text = "ผู้มีพระคุณ：\n\nวันนี้ สำหรับฉันและโพลักซิส เป็นเทศกาลเดียวในปี ในศาสนจักร เราไม่ถูกอนุญาตให้มุ่งเน้นที่ความหมายของตนเองเกินไป คุณค่าทั้งหมดของเรามีอยู่แค่ในงานนิรันดร์ในการรับใช้ผู้ถือไฟาน ในเบื้องหน้านั้น เทศกาลอื่น ๆ ก็ไร้สาระ\nแต่เมื่อถึงวันเกิด ฉันและโพลักซิสก็ยังคงแอบฉลอง โดยแอบเตรียมของขวัญเล็ก ๆ น้อย ๆ ให้กันและกัน และรอคอยวันนี้ด้วยคำนึงถึง\nเวลาฉลองมักจะเป็นยามค่ำคืน — เป็นอิสระในแต่ละวันที่เรามี มือและความคิดที่เก่งของโพลักซิสมักทำให้ของขวัญของเขาเหนือกว่าฉัน บ้างครั้ง เขาถึงกับถักดอกไม้จากขนนกหล่น\nฉันไม่ค่อยถนัดจัดสิ่งที่ประทับใจ โพลักซิสมักว่าฉันเสียความใส่ใจไปแล้ว แต่สิ่งที่ฉันมีคงดูจนไม่สนุกสำหรับท่าน อย่างไรก็ตาม วันนี้ ฉันมีวิธีที่ดีที่สุดในการแบ่งปันความสุขกับท่าน\nเมื่อท่านได้ยินหน้าต่างถูกเคาะ 3 ครั้งตอนกลางคืน ไม่ต้องกลัว เปิดหน้าต่าง ฉันจะพาท่านไปสัมผัสกับเมฆและสายลมยามค่ำ\n\nคาสเตอร์"
  },
  Mail_81326_Name = {
    Text = "การเดินทางในคืน..."
  },
  Mail_81326_Sender = {
    Text = "คาสเตอร์"
  },
  Mail_84142_Desc = {
    Text = "ผู้พิทักษ์： \n\nก่อนที่จะพบกัน ฉันเขียนจดหมายนี้ลงไป เพื่อเชิญชวนและแนะนำการ 「เดินทางวันเกิด」 ของฉัน.\nจุดหมายแรกของการเดินทางนี้คือแม่น้ำเทมส์ เราจะขึ้นเรือขนของที่ปรับแต่งเป็นร้านอาหารเคลื่อนที่ ในระหว่างการล่องเรือ เราจะเพลิดเพลินกับสับปะรดที่ชุบด้วยน้ำหวานและรัม นี่คือของอร่อยที่จัดเฉพาะในวันเกิดของพนักงาน หวังว่าคุณจะชอบ.\nจุดหมายที่สองของการเดินทางคือจุดชมวิวในท่าเรือ โปรดวางใจ ฉันได้ขออนุญาตจากสมาคมบอลลูนแล้ว เมื่อลูกโป่งขึ้นสูงและมองดูช่องลอนดอนทั้งหมด เราจะเคียงเค้กด้วยกันเพื่อเป็นการเฉลิมฉลอง.\nในอดีต สภาพการเดินทางมีข้อจำกัด เค้กวันเกิดเรียกว่าเป็นโมเดลที่ช่างไม้ทำจากไม้โอ๊คและน้ำตาลไหม้ ดังนั้นฉันก็ไม่รู้ว่ากลิ่นของเค้กเป็นอย่างไร ครั้งนี้ได้ร่วมชิมกับคุณ ฉันคิดว่านอกจากความอร่อยของอาหารแล้ว ฉันยังจะได้รับมากกว่านั้น.\nจุดหมายที่สาม หรือควรเรียกว่าช่วงที่สาม คือแผนที่ดาวต้นแบบ ฉันได้ทำเครื่องหมายตำแหน่งของวัตถุในเวลาที่ฉันเกิดบนแผนที่ทะเล หากคุณไม่กังวล ฉันคิดว่าอยากจะทำเครื่องหมายของคุณด้วย ถ้าแผนที่ทางทะเลที่เป็นเอกลักษณ์นี้ จะเป็นของขวัญที่ควรค่าแก่การรักษา.\nในความเป็นจริง ในขณะที่เขียนจดหมายนี้ ฉันเคยลังเลอยู่บ้าง การกระทำเหล่านี้ไม่ต้องสงสัยเกินขอบเขตปกติ แต่วันนี้เป็นวันที่พิเศษ คุณก็เป็นคนพิเศษสำหรับฉัน สมควรที่ฉันจะแหกกฎ.\nฉะนั้นโปรดอย่าปฏิเสธ และมาที่นัดหมายตามเวลา.\n\nเคอร์เพอร์ซานท์"
  },
