  Mail_84355_Desc = {
    Text = "เรียนผู้พิทักษ์：\nกิจกรรม「ในพายุฝนกระหน่ำ」ได้สิ้นสุดแล้ว ปัจจุบันจะทำการคืนเงินตรากิจกรรมที่เหลืออยู่「ธงสัญญาณ」ให้กับผู้พิทักษ์ตามอัตราส่วนการแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 โปรดจำไว้ด้วยนะครับ."
