  Mail_84410_Desc = {
    Text = "เรียน ผู้พิทักษ์:\n        ขอบคุณสำหรับการสนับสนุนและการยอมรับต่อ「คืนแห่งการลืมเลือน」 เพื่อให้ผู้พิทักษ์ที่มหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดีขึ้น เราจึงขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล โดยสามารถรับได้เมื่อกรอกแบบสอบถามเสร็จสิ้น เวลาสิ้นสุดการกรอกแบบสอบถามคือวันที่ 5 พฤษภาคม เวลา 9:00 น. กรุณาใส่ใจกรอกให้ทันเวลา.\n        <SurveyLink:「คลิกเพื่อกรอก」>\n        เราจะรับฟังคำแนะนำจากผู้พิทักษ์ทุกคนอย่างจริงจัง และข้อเสนอแนะของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อยๆ!\n        ——ขอให้กุญแจเงินนำทางคุณ."
  },
