  Mail_89905_Desc = {
    Text = "เรียน ผู้พิทักษ์ความลับ：\n        ขอขอบคุณสำหรับการสนับสนุนและการยอมรับที่มีต่อ《Eve of Oblivion》 เพื่อมอบประสบการณ์การเล่นเกมที่ดียิ่งขึ้นให้แก่ผู้พิทักษ์ความลับในมหาวิทยาลัยมิซาเกร์ ขอเรียนเชิญท่านกรอกแบบสอบถามสำรวจประสบการณ์ต่อไปนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของท่าน เราได้เตรียม「ซิลเวอร์คอร์」× 200 เป็นรางวัล สามารถรับได้ทันทีเมื่อกรอกแบบสอบถามเสร็จสิ้น แบบสอบถามปิดรับวันที่ 15 มิถุนายน เวลา 9:00 กรุณากรอกให้ทันเวลา\n        <SurveyLink:【คลิกเพื่อไปกรอกแบบสอบถาม】>\n        เราจะรับฟังข้อเสนอแนะของผู้พิทักษ์ความลับทุกท่านอย่างจริงจัง ความคิดเห็นของท่านจะช่วยให้มหาวิทยาลัยมิซาเกร์ดียิ่งขึ้นอย่างแน่นอน！\n        ——ขอให้กุญแจเงินนำทางสู่เส้นทางข้างหน้า"
