    Text = "เรียนผู้พิทักษ์: \n        ขอบคุณสำหรับการสนับสนุนและการรับรู้ต่อ「คืนแห่งการลืมเลือน」เพื่อให้ผู้พิทักษ์ที่มหาวิทยาลัยมิซากะมีประสบการณ์การเล่นเกมที่ดียิ่งขึ้น เราขอเชิญคุณกรอกแบบสอบถามประสบการณ์ด้านล่างนี้ เพื่อเป็นการขอบคุณสำหรับความร่วมมือของคุณ เราได้เตรียม「เงินใจ」× 200 เป็นรางวัล เมื่อกรอกแบบสอบถามเสร็จแล้วสามารถรับได้ แบบสอบถามจะสิ้นสุดในวันที่ 19 มกราคม เวลา 9:00 น. กรุณาใส่ใจกรอกให้ทันเวลา \n        <SurveyLink:「คลิกที่นี่เพื่อกรอก」>\n        เราจะรับฟังข้อเสนอแนะจากผู้พิทักษ์ทุกท่านอย่างจริงจัง และข้อเสนอแนะของคุณจะทำให้มหาวิทยาลัยมิซากะดีขึ้นเรื่อย ๆ! \n        ——ขอให้กุญแจเงินนำทางคุณ."
