  Mail_94425_Desc = {
    Text = "เรียนผู้พิทักษ์: \n กิจกรรม「การยิ่งใหญ่ในการพิชิต」ได้สิ้นสุดลงแล้ว ขณะนี้จะทำการแปลง「คูปองออกแบบชุดแฟนตาซีสไตล์มินิมอล(ฉบับที่ 2)」ที่เหลืออยู่ของผู้พิทักษ์เป็น「คำเชิญของวิญาณไร้รูปร่าง」× 1 โดยอัตราการแลกเปลี่ยน กรุณาตรวจสอบให้ดี."
