  Mail_94503_Desc = {
    Text = "โคมไฟนำทางของฉัน:\n\nตั้งแต่ฉันและคาสเตอร์มาถึงที่นี่ การเอาใจใส่ของท่านต่อเราเหมือนได้รับชีวิตใหม่ ขอบคุณที่เตรียมเค้กวันเกิดอย่างดีให้เรา แม้จะรู้สึกขอโทษที่เราเข้าใจผิดว่าภาพนกสองตัวบนเค้กว่าเป็นผีเสื้อ แต่เราชอบของขวัญนี้มาก นี่เป็นครั้งแรกที่เราได้รับของขวัญวันเกิดจากผู้อื่น\nเรายังได้รับบัตรอวยพรจากชอร์ท ดีนที่ถูกส่งจากโรงเรียน ซองจดหมายสีขาวนั้นมีตราปิดทองที่งดงาม ข้างในเขียนด้วยคำอวยพรที่แสนดี ที่นี้เป็นที่อบอุ่นจริงๆ ชีวิตของเราไม่เคยมีช่วงเวลาที่มีความสุขเช่นนี้มาก่อน\nโปรดมาร่วมฉลองวันเกิดกับฉันและคาสเตอร์ นี่คือพิธีที่เรายังคงรักษาไว้ตั้งแต่เด็ก ในฐานะอานุคุณ เราเตรียมของขวัญแลกเปลี่ยนให้แก่ท่าน เป็นหมวกที่ฉันถักจากขนที่หลุดของคาสเตอร์\nฉันมอบหมวกกระด้างนี้ให้ท่านเพื่อแสดงความเคารพ ฉันยินดีที่จะติดตามท่านตลอดชีวิตของฉัน ดำเนินการต่อวิสัยทัศน์ที่ยิ่งใหญ่ของโรงเรียนนี้ที่กำจัดความชั่วร้ายและความมืดจริงๆ\nเป็นเวลานานที่ไม่เคยทำสิ่งนี้ คาสเตอร์ยังขำเรื่องฝีมือของฉันไม่เหมือนเมื่อเด็ก หวังว่าท่านจะไม่ดูถูก\n\nโพลลักซ์"
  },
  Mail_94503_Name = {
    Text = "หัวเข็มขัดขนนก..."
  },
  Mail_94503_Sender = {
    Text = "โพลลักซ์"
  },
  Mail_95382_Desc = {
    Text = "เจ้าตัวเล็กที่น่ารัก:\n\nเจ้าตัวเล็ก วันนี้คือวันที่ฉันมาถึง\nไม่ใช่ในฐานะลูกไฟที่ไหม้อย่างไม่หยุดยั้ง แต่เป็นวันเกิดของเด็กสาวที่ชื่อว่าไคติกูลา\nตามปกติในทางชิวิตก่อน วันนี้เราจะมีงานเลี้ยงใหญ่เพื่อเพลิดเพลินกับไวน์และเนื้อย่าง\nแน่นอนเสมอว่าจะมีเด็กหนุ่มที่ไม่สนใจกับการแซวว่าฉันอายุมากขึ้นอีกปี ฉันเลยทักทายเขาด้วยกำปั้น\nและตอนนี้ งานเลี้ยงแบบนี้เพิ่มหน้าที่ใหม่คือเพื่อให้เรารำลึกถึงช่วงเวลาที่เราเคยมี\nปีนี้ฉันตั้งใจที่จะเพิ่มกิจกรรมเพิ่มเติม ซึ่งก็คือ--ล่าตามหาเจ้าตัวเล็กของเรา!\nรู้ไหม ฉันรอไม่ไหวที่จับเจ้าตัวเล็กไปงานเลี้ยงของฉัน ใช้การแสดงออกน่ารักอันขี้อายและสับสนของคุณ พร้อมกับกลิ่นหอมละมุนจากภายใน มาเป็นเครื่องประดับในงานเลี้ยงวันเกิดของฉันในปีนี้ ซึ่งจะเป็นของขวัญวันเกิดที่ดีที่สุดตั้งแต่ฉันเกิดมามีมา!\nตอนนี้เริ่มวางแผนหนีแล้วล่าช้า เพราะเมื่อคุณอ่านจดหมายนี้...\nฉัน·มา·ถึง·หน้าประตูบ้าน·คุณ·แล้ว. \nอย่ากลัวเลย เจ้าตัวเล็ก หากสิ่งทุกอย่างเป็นไปตามปกติ คุณจะได้แค่ฟังเรื่องราวที่ดีที่สุดและชิมอาหารที่อร่อยที่สุดที่นี่.\nแน่นอนว่าหากตัวสัตว์เล็กที่จับได้นั้น เกิดสิ่งผิดปกติก็เป็นธรรมดาใช่ไหม.\nตามฉันมาเลย เจ้าตัวเล็ก คืนนี้เวลาที่ดีของคุณ จะต้องใช้ร่วมกับฉัน.\n\nไคติกูลา"
  },
