  Mail_96323_Desc = {
    Text = "ท่านผู้พิทักษ์:\n\nการเฉลิมฉลองวันเกิดของผู้มีชีวิต เป็นการเก็บเกี่ยวความหมายในชีวิตที่เหลืออยู่ แต่สำหรับฉัน ก็แค่ใช้คืนนี้ในการปรุงกลิ่นของความตายให้หอมหวานยิ่งขึ้น\nผู้ตายที่ไม่ต่อสู้หรือยึดมั่นในสิ่งใดอีกแล้ว ทุกสิ่งที่สกปรกในชีวิตพวกเขาถูกชำระให้สะอาดแล้ว ความสำนึกผิดของพวกเขาเหมือนเกลือละเอียด ในช่วงเวลาที่เหมาะสมละลายเข้ากับเส้นเลือด ก่อนที่จะเผยกลิ่นหอมที่ชุ่มชื่นและนุ่มนวล กระดูกของพวกเขาจะมีเสียงแตกเบาๆ น้ำมันที่ซึมออกจากผิวบางเบาเหมือนมิ้นต์ และคำพูดที่ยังไม่สิ้นสุดในวิญญาณจะค่อยๆ คายออกมาในขณะที่อยู่ในกระบวนการปรุงอาหาร ทิ้งรสชาติหวานที่ละเอียดอ่อน ฉันเริ่มจินตนาการถึงรูปลักษณ์ของคุณเมื่อกลายเป็นสิ่งที่เงียบสงบ—เสียงแตกเมื่อผิวได้สัมผัสกับเปลวไฟ ความรู้สึกที่ระเหยออกมาระหว่างกระดูกและเนื้อ คุณจะได้สัมผัสถึงรสชาติหวานซึ่งวิญญาณที่บริสุทธิ์ของคุณถูกกลืนกิน...\nแต่คุณต่างออกไป\nคุณยังคงเรืองแสง ยังคงเต้นรำ และมีความหอมที่ไม่มีผีตนใดจะเปรียบเทียบได้ ทำให้คนหลงใหล คุณคือสิ่งที่ฉันยินดีจะรอคอย ฉันถึงขนาดหวังว่า การรอคอยนี้จะยาวนานกว่าชั่วนิรันดร์\nในวงปีอันไม่มีที่สิ้นสุดนี้ การมาของคุณทำให้วันเกิดของฉันมีความหมาย ไม่ใช่เพียงเพื่อการกินที่ยอดเยี่ยม แต่เพื่อชีวิตที่ยังคงเต้นอยู่ของคุณ\n\nดูเลอเซย์น์"
